INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2cbadaf7-2bff-4bac-86a7-b9e6bcb16420','Absorbing boundary condition','In computational acoustics, an absorbing boundary condition (ABC) is a numerical treatment applied at the edge of a finite mesh that lets outgoing waves leave with minimal artificial reflection, so a truncated grid mimics unbounded free space. Common forms include radiation-type conditions and the perfectly matched layer (PML).','A computer model of sound needs edges. But open air has no edges. This boundary soaks up waves that reach the edge. So they do not bounce back and spoil the result.','It lets a finite simulation grid stand in for open, unbounded space by stopping spurious reflections at the domain edges.','An engineer running a finite-element or FDTD model of a loudspeaker in free field wraps the outer boundary in a PML so exterior radiation is not corrupted by edge echoes.','Computational Method',ARRAY['Perfectly matched layer','Boundary-element analysis','Finite-element method','Radiation condition','Beam tracing']::text[],ARRAY['Assuming an ABC is perfect; residual reflection grows at grazing incidence and low frequency.','Placing the boundary too close to the source so the near field is truncated.','Confusing a numerical absorbing boundary with a physically absorptive surface material.']::text[],ARRAY['Modeling free-field loudspeaker radiation in a finite-element solver.','Simulating exterior sound scattering from a noise barrier.','Truncating a duct or waveguide model without unwanted end reflections.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absorbing boundary condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2cbadaf7-2bff-4bac-86a7-b9e6bcb16420','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2cbadaf7-2bff-4bac-86a7-b9e6bcb16420') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2cbadaf7-2bff-4bac-86a7-b9e6bcb16420');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f83bbb23-aa39-4794-804f-d7dcc4ce7676','Accelerance','Accelerance (also called inertance) is a vibration frequency-response function equal to the ratio of a structure''s complex acceleration to the harmonic force that produces it, at a given frequency. It is the acceleration-form counterpart of receptance (displacement/force) and mobility (velocity/force).','Push a structure with a shaking force and it speeds up and slows down. Accelerance compares that acceleration to the force. It changes with frequency. Peaks in it reveal resonances.','It captures how much acceleration a structure develops per unit applied force versus frequency, which reveals its resonances and mode shapes.','In a modal test with an accelerometer and instrumented hammer, a rigid mass m gives accelerance magnitude 1/m; a 2 kg mass reads 0.5 (m/s^2)/N at all frequencies.','Vibration FRF',ARRAY['Acoustic mobility','Mechanical impedance','Receptance','Modal analysis','Dynamic stiffness']::text[],ARRAY['Confusing accelerance (acceleration/force) with mechanical impedance (force/velocity).','Dropping the j-omega factors when converting between accelerance, mobility, and receptance.','Reporting only magnitude and ignoring the phase of the FRF.']::text[],ARRAY['Measuring a speaker-cabinet panel resonance with an accelerometer.','Building a modal model from hammer-impact FRFs.','Converting an accelerometer FRF to displacement for a fatigue study.']::text[],'advanced','A(w) = a(w)/F(w) = jw*Y(w) = -w^2*H(w)','Accelerance equals complex acceleration divided by applied force; equivalently it is j-omega times the mobility, or minus omega-squared times the receptance.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Accelerance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f83bbb23-aa39-4794-804f-d7dcc4ce7676','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f83bbb23-aa39-4794-804f-d7dcc4ce7676') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f83bbb23-aa39-4794-804f-d7dcc4ce7676');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2e4f01d-e891-42fb-96d2-cce2eaa5a071','Acoustic bandgap','An acoustic bandgap is a frequency band over which a periodic acoustic structure (a phononic crystal or resonant metamaterial) forbids or strongly attenuates wave propagation, so incident sound in that band is reflected rather than transmitted. Gaps arise either from Bragg scattering by the periodic lattice or from local resonances of the unit cell.','Some engineered materials repeat a pattern over and over. Sound in a certain frequency range cannot pass through. That blocked range is the bandgap. Outside it, sound gets through as usual.','It provides a way to block or filter a chosen band of sound using structure rather than bulk mass, enabling compact barriers and acoustic filters.','A designer sizes a sonic-crystal barrier so its Bragg gap covers the noise; in air (c=343 m/s) a 0.1 m lattice period puts the first gap near 343/(2*0.1) = about 1.7 kHz.','Periodic Media',ARRAY['Bragg scattering','Acoustic metamaterial','Acoustic metasurface','Acoustic cloaking','Phononic crystal']::text[],ARRAY['Assuming a Bragg gap and a local-resonance gap form by the same mechanism.','Expecting the gap to hold at every angle of incidence.','Thinking a bandgap blocks all frequencies rather than one specific band.']::text[],ARRAY['Designing a sonic-crystal noise barrier around machinery.','Building a sub-wavelength resonant panel for low-frequency control.','Creating an acoustic filter for an ultrasonic device.']::text[],'advanced','f_gap ~ c/(2a)','For a Bragg-type gap, the center frequency is roughly the sound speed divided by twice the lattice period.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic bandgap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2e4f01d-e891-42fb-96d2-cce2eaa5a071','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2e4f01d-e891-42fb-96d2-cce2eaa5a071') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2e4f01d-e891-42fb-96d2-cce2eaa5a071');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5715a4bb-6b80-44d9-8751-d11e4ca0d0ff','Acoustic cavitation','Acoustic cavitation is the formation, growth, and often violent collapse of gas or vapor bubbles in a liquid driven by an intense sound field, especially ultrasound, when the acoustic pressure lowers the local pressure past a threshold. Inertial (transient) collapse concentrates energy into extreme local temperatures, pressures, micro-shock waves, and reactive species.','Loud ultrasound in a liquid can tear tiny bubbles open. The bubbles then collapse very hard. This makes intense local heat and tiny shock waves. It can clean parts but also cause damage.','It underlies ultrasonic cleaning, sonochemistry, and some medical therapies, and is also a damage and erosion mechanism in propellers, pumps, and high-power sonar.','A technician running an ultrasonic cleaning bath depends on cavitation to scrub parts, and keeps hands and delicate transducers out of the active field to avoid injury and erosion.','Nonlinear Phenomenon',ARRAY['Acoustic shock','Radiation pressure','Acoustic streaming','Sonoluminescence','Blake threshold']::text[],ARRAY['UNSAFE: Placing bare fingers or hands into an active ultrasonic cleaning bath; cavitation plus heat can injure skin.','UNSAFE: Assuming therapeutic or diagnostic ultrasound is harmless at any intensity; inertial cavitation can damage tissue.','Confusing gentle stable (non-inertial) cavitation with violent inertial bubble collapse.','Believing higher frequency always increases cavitation; the pressure threshold actually rises with frequency.']::text[],ARRAY['Cleaning precision parts in an ultrasonic bath.','Assessing bioeffect safety of high-intensity focused ultrasound.','Diagnosing cavitation erosion on a ship propeller.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic cavitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5715a4bb-6b80-44d9-8751-d11e4ca0d0ff','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5715a4bb-6b80-44d9-8751-d11e4ca0d0ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5715a4bb-6b80-44d9-8751-d11e4ca0d0ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c0ed5016-ab46-4c76-9cc5-74f83aba0818','Acoustic cloaking','Acoustic cloaking is the use of engineered materials, typically transformation-acoustics metamaterials, to steer sound waves smoothly around an object so it produces neither an echo nor an acoustic shadow, making it effectively invisible to sound or sonar.','A cloak guides sound waves around an object. The waves rejoin on the far side. It looks as if nothing was there. Doing this over a wide band is very hard.','It aims to hide an object from acoustic detection, or to shield it from incident sound, by rerouting wave energy rather than absorbing it.','Researchers build a ground-plane ''carpet'' cloak from precisely patterned plastic to conceal a bump from sonar in a water tank or in air.','Metamaterial Application',ARRAY['Acoustic metamaterial','Acoustic metasurface','Transformation acoustics','Anechoic coating','Acoustic bandgap']::text[],ARRAY['Expecting broadband, all-angle cloaking; most demonstrations are narrowband and directional.','Confusing cloaking, which reroutes sound, with simple absorption.','Assuming a cloak designed for air works unchanged in water.']::text[],ARRAY['Sonar-stealth research on submerged shapes.','A laboratory metamaterial demonstration.','Concept studies for redirecting noise around an obstacle.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic cloaking');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c0ed5016-ab46-4c76-9cc5-74f83aba0818','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c0ed5016-ab46-4c76-9cc5-74f83aba0818') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c0ed5016-ab46-4c76-9cc5-74f83aba0818');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67b14ff9-5367-46a4-a0c2-8a61381fe1a3','Acoustic impedance matching layer','An acoustic impedance matching layer is an intermediate layer inserted between two media of very different characteristic impedances to maximize sound-energy transmission across their interface. It works best when its impedance is the geometric mean of the two media and its thickness is a quarter wavelength at the design frequency.','Sound reflects strongly when two materials are very different. A matching layer sits between them. It has an in-between stiffness and a quarter-wave thickness. This lets much more sound pass across.','It reduces reflection loss at a mismatched interface, such as between a hard transducer and water or tissue, so more energy is coupled through.','To couple a PZT probe (about 30 MRayl) to water (about 1.5 MRayl), the layer impedance is set near sqrt(30*1.5) = 6.7 MRayl and made a quarter wavelength thick.','Transducer Design',ARRAY['Characteristic acoustic impedance','Quarter-wave transformer','Reflection coefficient','Anechoic coating','Transducer']::text[],ARRAY['Using the arithmetic mean instead of the geometric mean for the target impedance.','Forgetting that quarter-wave matching is frequency-specific and therefore narrowband.','Ignoring attenuation and mismatch losses inside the layer itself.']::text[],ARRAY['Designing a medical ultrasound probe face.','Coupling a sonar transducer efficiently into water.','Building an NDT contact transducer.']::text[],'advanced','Z_m = sqrt(Z1*Z2),  t = lambda_m/4','The matching-layer impedance is the square root of the product of the two media impedances, and its thickness is one quarter of the wavelength inside the layer.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impedance matching layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67b14ff9-5367-46a4-a0c2-8a61381fe1a3','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67b14ff9-5367-46a4-a0c2-8a61381fe1a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67b14ff9-5367-46a4-a0c2-8a61381fe1a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b76cd17-c8b4-419e-97f7-b4ff984468ea','Acoustic levitation','Acoustic levitation is the suspension of small objects or droplets against gravity using the acoustic radiation force of an intense standing or focused sound field. Small dense particles collect near the pressure nodes of the standing wave, spaced half a wavelength apart.','Very loud sound can hold a tiny object in mid-air. The object sits at a quiet point in a standing wave. These points sit half a wavelength apart. Only small light objects can be held.','It allows containerless handling of droplets and particles, useful where contact with a wall would contaminate or disturb the sample.','A 40 kHz levitator in air (c=343 m/s) has a wavelength of about 8.6 mm, so its trapping nodes sit about 4.3 mm apart.','Radiation-Force Application',ARRAY['Radiation pressure','Acoustic trapping','Acoustic tweezers','Acoustic streaming','Standing wave']::text[],ARRAY['Thinking the sound blows the object upward rather than trapping it at a node.','UNSAFE: Operating high-intensity ultrasonic levitators near unprotected ears; intense fields and subharmonics pose a hearing hazard.','Expecting to levitate large or very dense objects; the force scales with intensity and is small.']::text[],ARRAY['Containerless processing of a molten or reactive droplet.','Positioning particles for a spectroscopy measurement.','A tabletop standing-wave levitation demonstration.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic levitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b76cd17-c8b4-419e-97f7-b4ff984468ea','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b76cd17-c8b4-419e-97f7-b4ff984468ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b76cd17-c8b4-419e-97f7-b4ff984468ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf6e3070-8124-46d4-9bf7-0a95d041ab90','Acoustic metamaterial','An acoustic metamaterial is an artificially structured material whose sub-wavelength unit cells, often local resonators, give it effective properties not found in nature, such as negative effective mass density or negative bulk modulus. These allow control of sound below the Bragg limit, including negative refraction and strong low-frequency attenuation.','This is a man-made material built from tiny repeating parts. The parts are smaller than the sound''s wavelength. Together they behave in ways no natural material does. This gives new control over sound.','It engineers effective density and stiffness to bend, focus, or block sound in ways bulk materials cannot, especially at low frequencies.','An engineer stacks membrane or Helmholtz-resonator cells to make a thin panel that blocks low-frequency noise far better than its mass alone would predict.','Engineered Material',ARRAY['Acoustic metasurface','Acoustic bandgap','Acoustic cloaking','Bragg scattering','Negative refraction']::text[],ARRAY['Confusing resonance-based metamaterials with Bragg-based phononic crystals.','Assuming the effective properties hold outside the narrow resonance band.','Expecting the ideal effective behavior once losses and finite size are included.']::text[],ARRAY['Designing a thin low-frequency sound-blocking panel.','Building a flat acoustic lens for focusing.','Research on sub-wavelength sound control.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic metamaterial');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf6e3070-8124-46d4-9bf7-0a95d041ab90','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf6e3070-8124-46d4-9bf7-0a95d041ab90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf6e3070-8124-46d4-9bf7-0a95d041ab90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f41f89a7-77cb-4767-a7c8-3767d98e4998','Acoustic metasurface','An acoustic metasurface is a thin, nearly planar array of sub-wavelength acoustic resonators that imposes an engineered, position-dependent phase (and often amplitude) shift on transmitted or reflected sound. This lets a flat structure steer, focus, or reshape a wavefront, producing anomalous reflection and refraction.','This is a thin sheet covered with tiny sound elements. Each element delays the sound by a set amount. Across the sheet these delays reshape the wave. A flat sheet can then bend or focus sound.','It provides wavefront control from a compact flat surface, replacing bulky curved lenses or reflectors for steering and focusing sound.','A designer patterns coiled-channel cells across a panel to give each spot the phase delay needed to bend an incoming beam to a chosen angle.','Engineered Material',ARRAY['Acoustic metamaterial','Acoustic bandgap','Acoustic cloaking','Acoustic vortex','Diffraction grating']::text[],ARRAY['Confusing a thin metasurface with a bulk metamaterial.','Ignoring the narrow bandwidth of the resonant unit cells.','Forgetting that unwanted diffraction orders can carry energy away.']::text[],ARRAY['Building a flat acoustic lens for ultrasound focusing.','Steering a loudspeaker beam with a passive panel.','Generating an acoustic vortex from a flat plate.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic metasurface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f41f89a7-77cb-4767-a7c8-3767d98e4998','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f41f89a7-77cb-4767-a7c8-3767d98e4998') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f41f89a7-77cb-4767-a7c8-3767d98e4998');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfedee22-3bc1-4968-91d9-4880a6784e18','Acoustic mobility','Mobility (mechanical mobility) is the vibration frequency-response function equal to the ratio of a structure''s complex velocity to the harmonic force that produces it. It is the reciprocal of mechanical impedance and, in structure-borne sound, governs how readily a point responds to and radiates vibration.','Push a structure with a shaking force and a point on it moves. Mobility compares that speed to the force. High mobility means the point moves easily. It is the opposite of mechanical impedance.','It quantifies how easily a structure vibrates at a driving point, which sets how much vibration and radiated sound a force injects.','For a point mass m, mobility is 1/(j*w*m); at 100 Hz a 2 kg mass gives |Y| = 1/(2*pi*100*2) = about 7.96e-4 (m/s)/N.','Vibration FRF',ARRAY['Accelerance','Mechanical impedance','Receptance','Structure-borne sound','Radiation efficiency']::text[],ARRAY['Confusing mobility (velocity/force) with impedance (force/velocity).','Ignoring the complex (magnitude and phase) nature of the ratio.','Assuming a driving-point mobility applies to a distant transfer point.']::text[],ARRAY['Predicting vibration transmission through a machine mount.','Rating a resilient isolator by its mobility.','Comparing panel driving-point response in a modal survey.']::text[],'advanced','Y(w) = v(w)/F(w) = 1/Z_m','Mobility equals complex velocity divided by applied force, and it is the reciprocal of the mechanical impedance.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic mobility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfedee22-3bc1-4968-91d9-4880a6784e18','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfedee22-3bc1-4968-91d9-4880a6784e18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfedee22-3bc1-4968-91d9-4880a6784e18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ba6fe45-713d-4793-9a20-b7c2d2b67163','Acoustic nonlinearity parameter','The acoustic nonlinearity parameter (coefficient of nonlinearity), usually written beta, measures how strongly a finite-amplitude sound wave distorts, generates harmonics, and steepens toward a shock in a medium. It combines the medium''s equation-of-state term B/A with the convective nonlinearity of the flow.','Loud sound does not travel perfectly cleanly. It distorts and grows extra harmonics as it goes. This number says how strongly a medium does that. Bigger means faster distortion.','It sets the rate of harmonic generation and shock formation in a medium, and is used to characterize fluids and biological tissue.','Using beta = 1 + B/(2A): water with B/A about 5 gives beta = 3.5, while air with B/A about 0.4 gives beta = 1.2, so water distorts intense sound more than air.','Nonlinear Phenomenon',ARRAY['B/A parameter','Acoustic shock','Harmonic generation','Radiation pressure','Parametric array']::text[],ARRAY['Confusing beta (which includes the convective term) with the medium term B/A alone.','Assuming air and water distort intense sound at the same rate.','Treating beta as frequency dependent; it is a material property, though distortion grows with amplitude and distance.']::text[],ARRAY['Characterizing tissue for harmonic ultrasound imaging.','Predicting distortion of a high-intensity ultrasound beam.','Designing a parametric loudspeaker array.']::text[],'advanced','beta = 1 + B/(2A)','The coefficient of nonlinearity equals one plus half of the medium''s B-over-A parameter.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic nonlinearity parameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ba6fe45-713d-4793-9a20-b7c2d2b67163','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ba6fe45-713d-4793-9a20-b7c2d2b67163') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ba6fe45-713d-4793-9a20-b7c2d2b67163');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9b1c0236-1b6c-40fd-a9a2-5fb5c4837c67','Acoustic rectification','Acoustic rectification is a nonlinear effect in which an oscillating, zero-mean sound field produces a steady, non-zero (DC) response, such as a constant pressure, a net force, or a steady particle drift. It is the acoustic analog of electrical rectification and includes radiation pressure and acoustic streaming.','A sound wave pushes back and forth with no net average. But in a nonlinear medium it can leave a steady leftover push. That steady part is the rectified response. Radiation pressure is one example.','It explains how alternating sound can create steady forces and flows, which drive levitation, particle trapping, and streaming.','An engineer relies on this steady rectified force when using an intense field to hold a droplet in place or to drive slow fluid streaming in a channel.','Nonlinear Phenomenon',ARRAY['Radiation pressure','Acoustic streaming','Acoustic nonlinearity parameter','Acoustic levitation','Acoustic trapping']::text[],ARRAY['Expecting a linear medium to rectify; the steady response requires nonlinearity.','Confusing the small steady term with the large oscillating pressure.','Assuming the rectified force always points along the wave; it depends on gradients and absorption.']::text[],ARRAY['Explaining why intense sound exerts a steady radiation force.','Driving acoustic streaming in a microfluidic device.','Analyzing DC drift in a high-amplitude standing wave.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic rectification');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9b1c0236-1b6c-40fd-a9a2-5fb5c4837c67','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9b1c0236-1b6c-40fd-a9a2-5fb5c4837c67') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9b1c0236-1b6c-40fd-a9a2-5fb5c4837c67');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27c7661a-f808-4c60-8f9c-43bec049dcf0','Acoustic shock','In physical acoustics, an acoustic shock is a near-discontinuous jump in pressure that forms when a finite-amplitude wave steepens as it travels, because its compressions travel slightly faster than its rarefactions, until the waveform develops a shock front. Sonic booms, blast waves, and the sawtooth of intense ultrasound are examples.','A very loud wave does not keep a smooth shape. Its high-pressure parts catch up to the low-pressure parts. The front then gets very steep, almost a jump. That steep front is a shock.','Understanding shock formation matters wherever intense sound is used, since shocks bring extra loss, heating, and hazard that linear theory misses.','For a 20 kHz plane wave at 1000 Pa in air (rho=1.21, c=343, beta=1.2), the shock-formation distance is rho*c^3/(beta*w*p0) = about 0.32 m.','Nonlinear Phenomenon',ARRAY['Acoustic nonlinearity parameter','Acoustic cavitation','Radiation pressure','Sonic boom','Harmonic generation']::text[],ARRAY['UNSAFE: Exposure to blast or impulsive shock waves can rupture the eardrum and cause permanent hearing loss.','UNSAFE: Assuming high-intensity ultrasound stays sinusoidal; it steepens into shocks that heat tissue strongly.','Thinking a shock needs a supersonic source; finite-amplitude waves steepen on their own.','Confusing this weak-shock physics with the occupational ''acoustic shock'' headset-transient injury.']::text[],ARRAY['Predicting distortion and loss in a high-power ultrasound beam.','Analyzing a sonic boom or blast pressure signature.','Assessing hearing hazard from impulsive noise.']::text[],'advanced','x_shock = 1/(beta*eps*k) = rho0*c0^3/(beta*w*p0)','The plane-wave shock-formation distance equals the fluid density times sound speed cubed, divided by the product of the nonlinearity coefficient, the angular frequency, and the peak pressure.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic shock');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27c7661a-f808-4c60-8f9c-43bec049dcf0','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27c7661a-f808-4c60-8f9c-43bec049dcf0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27c7661a-f808-4c60-8f9c-43bec049dcf0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6606f3f-d472-42f1-bb95-ee23c1347d98','Acoustic trapping','Acoustic trapping is the holding of particles, cells, or droplets at fixed positions in a fluid using the acoustic radiation force of a standing or structured sound field. Depending on their acoustic contrast, objects collect at the pressure nodes or antinodes of the field.','A structured sound field can pin small particles in place. They gather at quiet or loud points of the wave. This lets you sort or hold cells without touching them. It works only for small objects.','It enables contact-free capture, concentration, and sorting of microparticles and cells, common in acoustofluidics and lab-on-a-chip devices.','A technician tunes a half-wavelength resonance in a microchannel so flowing cells are pushed to the center node and collected downstream.','Radiation-Force Application',ARRAY['Acoustic tweezers','Acoustic levitation','Radiation pressure','Acoustic streaming','Standing wave']::text[],ARRAY['Assuming every particle moves to a node; the direction depends on the acoustic contrast factor.','Ignoring acoustic streaming, which competes with trapping for very small particles.','Expecting strong trapping of objects with density and stiffness close to the fluid.']::text[],ARRAY['Concentrating cells in a microfluidic channel.','Sorting particles by size in an acoustofluidic device.','Holding a droplet for optical measurement.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic trapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6606f3f-d472-42f1-bb95-ee23c1347d98','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6606f3f-d472-42f1-bb95-ee23c1347d98') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6606f3f-d472-42f1-bb95-ee23c1347d98');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '08171cb7-3b7d-4486-bd69-0d8a2d98ce06','Acoustic tweezers','Acoustic tweezers are a technique that uses focused or structured acoustic fields, including surface acoustic waves and acoustic vortices, to grip and move individual microparticles or cells with fine, sub-wavelength precision. They are the acoustic counterpart of optical tweezers and work with a wider range of particle sizes.','Acoustic tweezers use sound to pick up and move tiny objects. They can grab a single cell and slide it around. This works without any physical contact. They are like light-based tweezers, but with sound.','They provide gentle, contact-free, precise manipulation of single cells or particles for biology and microassembly.','A researcher patterns interdigital transducers to launch surface acoustic waves that trap and steer single cells across a chip for sorting.','Radiation-Force Application',ARRAY['Acoustic trapping','Acoustic vortex','Radiation pressure','Acoustic levitation','Surface acoustic wave']::text[],ARRAY['Confusing acoustic tweezers with bulk acoustic trapping of many particles at once.','Overlooking heating from the transducer during long manipulation.','Assuming any particle can be trapped regardless of its acoustic contrast.']::text[],ARRAY['Isolating a single rare cell from a sample.','Assembling microparticles into a pattern.','Non-contact micromanipulation in a lab-on-a-chip.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic tweezers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '08171cb7-3b7d-4486-bd69-0d8a2d98ce06','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='08171cb7-3b7d-4486-bd69-0d8a2d98ce06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='08171cb7-3b7d-4486-bd69-0d8a2d98ce06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '361f5e66-2761-4eaa-a0b7-148081ec857b','Acoustic vortex','An acoustic vortex is a sound field that carries orbital angular momentum, with a helical (screw-like) phase front and a central null of zero pressure. Produced by phased arrays, spiral sources, or metasurfaces, it can exert a steady torque on an absorbing particle.','An acoustic vortex is a sound field that spins as it travels. Its phase twists like a screw around a quiet center. That center has almost no pressure. It can make a small absorbing object rotate.','It carries angular momentum that can rotate or trap particles, useful in acoustic tweezers and contactless manipulation.','An engineer drives a ring phased array with a spiral phase pattern to build a vortex beam whose quiet core traps and spins a bead.','Radiation-Force Application',ARRAY['Acoustic tweezers','Acoustic trapping','Radiation pressure','Acoustic metasurface','Orbital angular momentum']::text[],ARRAY['Confusing the vortex phase singularity with a simple focal point.','Assuming the field can spin any particle; steady torque needs absorption or asymmetry.','Ignoring that the central null is where trapping, not maximum pressure, occurs.']::text[],ARRAY['Rotating a microparticle without contact.','Trapping a bead in a vortex core.','Encoding angular momentum in an ultrasound beam.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic vortex');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '361f5e66-2761-4eaa-a0b7-148081ec857b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='361f5e66-2761-4eaa-a0b7-148081ec857b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='361f5e66-2761-4eaa-a0b7-148081ec857b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c518d23-a0ae-449f-a346-d3aa3255be74','Aeolian tone','An aeolian tone is the roughly tonal sound radiated when steady flow past a bluff body, such as a wire or cylinder, sheds vortices alternately from its sides. The shedding, and thus the tone frequency, is set by the Strouhal relation, giving the familiar whistling of wind through wires.','Wind blowing past a wire makes a singing tone. The wind sheds little swirls off each side in turn. This shedding pushes the air at a steady rate. That rate sets the pitch you hear.','It explains flow-induced tonal noise from wires, cables, poles, and struts, and helps predict and control such whistling.','Using St = f*d/U with St about 0.2, a 2 mm wire in a 20 m/s wind sings at f = 0.2*20/0.002 = about 2000 Hz.','Aeroacoustic Source',ARRAY['Aeroacoustics','Airfoil self-noise','Blade-passing frequency','Vortex shedding','Strouhal number']::text[],ARRAY['Treating the Strouhal number as fixed at exactly 0.2 for all shapes and speeds.','Confusing the aeolian tone with an edge tone, which needs a jet and an edge.','Forgetting that the frequency scales with wind speed, so gusts shift the pitch.']::text[],ARRAY['Diagnosing wind whistle from overhead cables.','Predicting tonal noise from a cylindrical strut.','Explaining the hum of a taut wire in the wind.']::text[],'intermediate','f = St*U/d','The tone frequency equals the Strouhal number times the flow speed divided by the body''s cross-stream size.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aeolian tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c518d23-a0ae-449f-a346-d3aa3255be74','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c518d23-a0ae-449f-a346-d3aa3255be74') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c518d23-a0ae-449f-a346-d3aa3255be74');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4281b44-66d4-4661-8be8-45e06ca11244','Aeroacoustics','Aeroacoustics is the branch of acoustics that studies sound generated by turbulent or unsteady fluid flow and its interaction with surfaces. It is founded on Lighthill''s acoustic analogy, which recasts the fluid equations as a wave equation driven by aerodynamic source terms.','Aeroacoustics is the study of sound made by moving air itself. Jets, fans, and wind all create noise as the flow swirls. It also covers how that flow noise grows near surfaces. It builds on Lighthill''s theory.','It provides the framework to predict and reduce flow-generated noise from jets, fans, vehicles, and wind turbines.','An engineer applies the Lighthill analogy to model jet noise, then reshapes a nozzle or adds serrations to cut the radiated sound.','Field of Acoustics',ARRAY['Aeolian tone','Airfoil self-noise','Blade-passing frequency','Jet noise','Vortex sound']::text[],ARRAY['Assuming flow noise needs a vibrating solid; free turbulence alone radiates sound.','Treating the aerodynamic source as an external force rather than a stress from the flow.','Ignoring how nearby edges and surfaces greatly amplify the radiation.']::text[],ARRAY['Predicting jet-engine exhaust noise.','Reducing wind noise on a vehicle mirror.','Designing quieter fan and turbine blades.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aeroacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4281b44-66d4-4661-8be8-45e06ca11244','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4281b44-66d4-4661-8be8-45e06ca11244') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4281b44-66d4-4661-8be8-45e06ca11244');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60a09ef7-2b3e-4d8b-854e-358049ad27cd','Airfoil self-noise','Airfoil self-noise is the sound an airfoil produces from its own boundary layer and wake interacting with its trailing edge, even in smooth incoming flow. It includes turbulent-boundary-layer trailing-edge noise, separation and stall noise, laminar vortex-shedding tones, and blunt trailing-edge tones.','A moving wing makes noise even in smooth air. The thin layer of air on its surface becomes turbulent. When that turbulence sweeps off the back edge, it radiates sound. This is the wing''s own self-noise.','It is a key noise source for wind turbines, fans, and aircraft, and its prediction guides quieter blade and edge design.','A wind-turbine engineer uses trailing-edge self-noise models to add serrated edges that break up the turbulence and lower the broadband swish.','Aeroacoustic Source',ARRAY['Aeroacoustics','Aeolian tone','Blade-passing frequency','Boundary layer','Trailing-edge noise']::text[],ARRAY['Attributing all airfoil noise to inflow turbulence rather than the airfoil''s own boundary layer.','Ignoring the strong role of the trailing edge in the radiation.','Assuming a sharper edge always helps; a too-blunt or too-sharp edge changes the tone.']::text[],ARRAY['Reducing wind-turbine blade swish.','Designing a quiet cooling or HVAC fan.','Assessing broadband noise from an aircraft high-lift device.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Airfoil self-noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60a09ef7-2b3e-4d8b-854e-358049ad27cd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60a09ef7-2b3e-4d8b-854e-358049ad27cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60a09ef7-2b3e-4d8b-854e-358049ad27cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eedb60b2-c1f0-4f87-8a27-1c55ea26d509','Anechoic coating','An anechoic coating is a sound-absorbing surface layer, often rubber with embedded air cavities such as Alberich tiles, applied to a structure like a submarine hull to absorb incident sonar and suppress its echo across a design frequency band.','An anechoic coating is a rubber skin that soaks up sound. It is put on hulls to hide them from sonar. Tiny cavities inside trap and absorb the sound. This cuts the echo the hull sends back.','It reduces a structure''s sonar echo and self-noise by absorbing incident and radiated sound, mainly for underwater stealth.','A naval engineer selects an Alberich-type tiled coating whose resonant cavities are tuned to absorb the threat sonar band at operating depth.','Absorptive Material',ARRAY['Acoustic impedance matching layer','Absorption coefficient','Radiation efficiency','Flow resistivity','Acoustic metamaterial']::text[],ARRAY['Assuming broadband absorption; cavity-resonant coatings are band-limited.','Ignoring how hydrostatic pressure at depth changes the rubber''s properties.','Confusing an anechoic coating, which absorbs, with a cloak, which reroutes sound.']::text[],ARRAY['Treating a submarine hull for sonar stealth.','Lining an underwater test tank to reduce reflections.','Damping a radiating machine surface.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anechoic coating');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eedb60b2-c1f0-4f87-8a27-1c55ea26d509','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eedb60b2-c1f0-4f87-8a27-1c55ea26d509') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eedb60b2-c1f0-4f87-8a27-1c55ea26d509');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '109dea8d-ece4-44c9-8e55-5cb005ac0098','B/A parameter','The B/A parameter is the leading measure of a medium''s acoustic nonlinearity, defined from the ratio of the second- to first-order terms in the Taylor expansion of pressure in density about the ambient state at constant entropy. It rises with a medium''s tendency to distort intense sound; for an ideal gas it equals gamma minus one.','The B/A parameter tells how nonlinear a medium is for sound. It comes from how pressure changes with density. A larger value means intense sound distorts faster. Air is low; water and tissue are higher.','It characterizes a fluid''s nonlinearity for finite-amplitude acoustics and is used to identify and image materials, including biological tissue.','For air, B/A = gamma - 1 = 0.4; pure water is about 5; using beta = 1 + B/(2A) these give coefficients of nonlinearity of 1.2 and 3.5.','Nonlinear Phenomenon',ARRAY['Acoustic nonlinearity parameter','Acoustic shock','Harmonic generation','Radiation pressure','Parametric array']::text[],ARRAY['Confusing B/A (the medium term) with beta, which also adds the convective ''1''.','Assuming air and water share similar nonlinearity; water''s B/A is much larger.','Treating B/A as a small correction; it drives harmonic imaging in tissue.']::text[],ARRAY['Tissue characterization for harmonic ultrasound imaging.','Comparing nonlinearity of fluids in a lab.','Predicting harmonic buildup in a high-intensity beam.']::text[],'advanced','B/A = 2*rho0*c0*(dc/dP)_s','The B-over-A parameter equals twice the ambient density times the sound speed, multiplied by how the sound speed changes with pressure at constant entropy.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='B/A parameter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '109dea8d-ece4-44c9-8e55-5cb005ac0098','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='109dea8d-ece4-44c9-8e55-5cb005ac0098') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='109dea8d-ece4-44c9-8e55-5cb005ac0098');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68a8992e-0b92-4d28-b590-f4faaa994ab9','Beam tracing','Beam tracing is a geometrical-acoustics modeling method that propagates finite beams, bundles of rays that carry area, from a source and tracks their reflections off surfaces. It computes room impulse responses more efficiently and with fewer sampling artifacts than tracing independent rays.','Beam tracing predicts room sound using spreading beams instead of single rays. Each beam covers an area and reflects off walls. This misses fewer surfaces than thin rays. It builds a room''s echo pattern efficiently.','It models sound propagation and reflections in rooms and outdoor scenes for auralization and prediction, balancing speed and accuracy.','An acoustician runs a beam-tracing simulation of an auditorium to estimate early reflections and reverberation before building physical mockups.','Computational Method',ARRAY['Ray tracing','Image-source method','Boundary-element analysis','Absorbing boundary condition','Geometrical acoustics']::text[],ARRAY['Assuming geometrical methods capture low-frequency wave effects like diffraction and modes.','Confusing beam tracing with simple ray tracing that can miss small surfaces.','Overlooking the cost of tracking beam splitting after many reflections.']::text[],ARRAY['Predicting early reflections in a concert hall design.','Auralizing a virtual room for a game or VR.','Modeling outdoor sound around buildings.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beam tracing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68a8992e-0b92-4d28-b590-f4faaa994ab9','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68a8992e-0b92-4d28-b590-f4faaa994ab9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68a8992e-0b92-4d28-b590-f4faaa994ab9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1e14a229-ad5e-4c83-95c7-947bcd179b80','Bending mode','A bending mode is a structural vibration mode in which a beam, plate, or panel deforms by flexure (transverse bending) rather than by stretching or shear. The associated bending (flexural) waves are dispersive, with their wave speed increasing as the square root of frequency.','A bending mode is a way a panel flexes as it vibrates. It curves up and down rather than stretching. These bending waves travel faster at higher frequency. This matters for how panels radiate sound.','Bending waves dominate how panels and plates vibrate and radiate sound, so their modes govern structure-borne noise and coincidence effects.','An engineer computes the flexural wave speed c_B = (D*w^2/rho_s)^(1/4) of a panel to find where it coincides with airborne sound and radiates strongly.','Structural Vibration',ARRAY['Breakup mode','Breathing mode','Coincidence frequency','Radiation efficiency','Modal density']::text[],ARRAY['Assuming bending waves are non-dispersive like sound in air; their speed rises with frequency.','Confusing bending modes with longitudinal or shear modes of the same plate.','Using a single wave speed for a panel that in fact varies with frequency.']::text[],ARRAY['Analyzing panel vibration in a loudspeaker cabinet.','Predicting coincidence dip in a partition''s sound insulation.','Studying flexural resonances of a structural plate.']::text[],'intermediate','c_B = (D*w^2/rho_s)^(1/4)','The bending-wave speed equals the fourth root of the bending stiffness per unit width times angular frequency squared, divided by the mass per unit area.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bending mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1e14a229-ad5e-4c83-95c7-947bcd179b80','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1e14a229-ad5e-4c83-95c7-947bcd179b80') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1e14a229-ad5e-4c83-95c7-947bcd179b80');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d6c0939-46bb-4c9a-af8e-e9316b79ded3','Bifurcation','In nonlinear dynamics, a bifurcation is a qualitative change in a system''s steady behavior as a control parameter passes a critical value. A vibrating reed, string, or aeroacoustic source may jump suddenly to a new amplitude, frequency, or a period-doubled or chaotic regime.','A bifurcation is a sudden change in how a system behaves. You slowly turn one knob, and behavior flips at a threshold. A tone may jump, split, or turn chaotic. Small change, big effect.','It explains threshold-like jumps and route-to-chaos behavior in nonlinear oscillators, instruments, and flow-acoustic systems.','A researcher tracks how a wind-instrument reed suddenly starts oscillating, or period-doubles into a rough sound, as blowing pressure crosses a bifurcation.','Nonlinear Dynamics',ARRAY['Acoustic nonlinearity parameter','Chaos','Period doubling','Limit cycle','Nonlinear oscillator']::text[],ARRAY['Expecting a smooth, gradual change; a bifurcation is an abrupt qualitative switch.','Assuming the system returns along the same path; bifurcations often show hysteresis.','Treating chaotic output as random noise rather than deterministic dynamics.']::text[],ARRAY['Explaining the onset threshold of a woodwind reed.','Modeling multiphonics and rough tones in instruments.','Analyzing route to chaos in a nonlinear vibrating system.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bifurcation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d6c0939-46bb-4c9a-af8e-e9316b79ded3','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d6c0939-46bb-4c9a-af8e-e9316b79ded3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d6c0939-46bb-4c9a-af8e-e9316b79ded3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94c52966-6ecf-40aa-8f09-6b6133a90d25','Biot theory','Biot theory is the theory of poroelasticity that describes sound in a fluid-saturated porous solid by coupling the motion of the elastic frame and the pore fluid. It predicts two compressional waves, a fast and a slow (Biot) wave, plus a shear wave, and underlies modern models of porous sound absorbers.','Biot theory describes sound moving through a wet, spongy material. Both the solid frame and the fluid in the pores move. They drag on each other as sound passes. The theory predicts extra wave types not seen in solids alone.','It provides the physics for sound in porous, fluid-filled media, from acoustic foams and fibrous absorbers to saturated soils and rock.','An acoustician uses a Biot-based (Biot-Allard) model to predict the absorption of a foam from its frame stiffness, porosity, flow resistivity, and tortuosity.','Porous Media Theory',ARRAY['Porous absorber','Flow resistivity','Tortuosity','Slow wave','Poroelasticity']::text[],ARRAY['Ignoring the slow compressional wave that Biot theory uniquely predicts.','Treating a porous absorber as either purely rigid-frame or purely elastic when both matter.','Confusing frame (structural) motion with pore-fluid motion in the coupled model.']::text[],ARRAY['Modeling absorption of an acoustic foam or fibrous panel.','Predicting seismic wave behavior in saturated ground.','Characterizing a porous material''s frame and fluid parameters.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Biot theory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94c52966-6ecf-40aa-8f09-6b6133a90d25','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94c52966-6ecf-40aa-8f09-6b6133a90d25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94c52966-6ecf-40aa-8f09-6b6133a90d25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34ccfdb1-28ab-48a5-a510-099b15d585a3','Blade-passing frequency','The blade-passing frequency (BPF) is the fundamental tonal frequency generated by a rotating bladed machine, equal to the number of blades times the shaft rotation rate. It marks where fans, propellers, pumps, and turbines radiate their strongest tonal noise, along with its harmonics.','A fan''s blades chop the air one after another. Each pass gives a little push. The rate of these pushes sets a clear tone. That tone is the blade-passing frequency.','It identifies and predicts the dominant tonal noise of rotating machinery, guiding blade count and duct design for quieter operation.','Using BPF = B * (RPM/60), a 6-blade fan running at 3000 rpm produces a tone at 6 * 50 = 300 Hz, plus harmonics.','Rotating-Machinery Noise',ARRAY['Aeroacoustics','Airfoil self-noise','Aeolian tone','Tonal noise','Harmonic']::text[],ARRAY['Forgetting to divide RPM by 60 to get revolutions per second.','Multiplying by shaft speed only and omitting the blade count.','Expecting a single tone; strong harmonics of the BPF also appear.']::text[],ARRAY['Diagnosing a fan whine in an HVAC system.','Predicting propeller tonal noise on a drone.','Balancing blade count against tone frequency in a pump.']::text[],'intermediate','BPF = B * (RPM/60)','The blade-passing frequency equals the number of blades times the shaft speed in revolutions per second.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Blade-passing frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34ccfdb1-28ab-48a5-a510-099b15d585a3','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34ccfdb1-28ab-48a5-a510-099b15d585a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34ccfdb1-28ab-48a5-a510-099b15d585a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '479b621e-7563-4397-af26-fcb75295cf35','Boundary-element analysis','Boundary-element analysis (BEM) is a numerical method that solves acoustic radiation and scattering by discretizing only the boundary surfaces of a body and using a boundary-integral form of the Helmholtz equation. It naturally handles exterior, unbounded problems without meshing the surrounding air.','This method predicts sound from an object by meshing only its surface. It does not need to fill the whole surrounding air with a grid. That makes it well suited to open, outdoor-like problems. It solves radiation and scattering.','It efficiently models sound radiated or scattered by a body in open space, since only the surface, not the whole air volume, needs meshing.','An engineer runs a BEM model of a vibrating gearbox surface to predict its radiated sound power and directivity into free space.','Computational Method',ARRAY['Finite-element method','Absorbing boundary condition','Radiation efficiency','Helmholtz equation','Beam tracing']::text[],ARRAY['Forgetting BEM produces dense, fully-populated matrices, so large models grow costly.','Ignoring fictitious (irregular) frequencies unless a CHIEF or Burton-Miller fix is used.','Assuming BEM handles strongly inhomogeneous media as easily as uniform ones.']::text[],ARRAY['Predicting radiated sound power from a machine housing.','Modeling scattering of sound off a rigid body.','Coupling structural vibration to exterior acoustics.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary-element analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '479b621e-7563-4397-af26-fcb75295cf35','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='479b621e-7563-4397-af26-fcb75295cf35') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='479b621e-7563-4397-af26-fcb75295cf35');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4932a8a3-e46e-4183-a57a-d7dc747384ba','Bragg scattering','Bragg scattering is the coherent reflection of waves by a periodic structure when scattered contributions add in phase, which for a lattice of spacing d occurs when 2*d*sin(theta) equals an integer number of wavelengths. In acoustics it produces the Bragg bandgaps of phononic crystals.','When a wave meets a repeating pattern, each layer sends back a little echo. At certain angles and frequencies these echoes line up and add. The wave is then strongly reflected. This is Bragg scattering.','It explains strong, frequency-selective reflection by periodic media and sets where phononic-crystal bandgaps appear.','Using 2*d = lambda at normal incidence, a phononic crystal in water (c=1500 m/s) with 5 mm spacing strongly reflects near f = c/(2*d) = 150 kHz.','Periodic Media',ARRAY['Acoustic bandgap','Acoustic metamaterial','Phononic crystal','Diffraction grating','Scattering']::text[],ARRAY['Confusing the angle convention; Bragg''s angle is measured from the planes, not the normal.','Assuming Bragg reflection is broadband; it is sharply frequency and angle selective.','Mixing up Bragg (periodicity) gaps with local-resonance gaps.']::text[],ARRAY['Designing a phononic-crystal reflector or filter.','Explaining bandgaps in a sonic-crystal barrier.','Analyzing wave reflection in a layered periodic medium.']::text[],'advanced','2*d*sin(theta) = m*lambda','Strong coherent reflection occurs when twice the lattice spacing times the sine of the incidence angle equals a whole number of wavelengths.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bragg scattering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4932a8a3-e46e-4183-a57a-d7dc747384ba','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4932a8a3-e46e-4183-a57a-d7dc747384ba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4932a8a3-e46e-4183-a57a-d7dc747384ba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f8bfd07-82df-4942-a11d-2a6ee092faad','Breakup mode','A breakup mode is a high-frequency structural mode in which a loudspeaker diaphragm or panel no longer moves as a rigid piston but flexes into a pattern of nodal lines and out-of-phase regions. This breakup colors the frequency response and lowers radiation efficiency and off-axis consistency.','At high frequencies a speaker cone stops moving as one solid piece. Parts of it flex in and out of step. This is called breakup. It adds peaks and dips and messes up the sound.','Understanding breakup sets the usable upper frequency of a driver and guides cone material and geometry choices.','A loudspeaker designer measures where a cone breaks up, then adds stiffening or damping to push that breakup above the driver''s crossover point.','Structural Vibration',ARRAY['Bending mode','Breathing mode','Modal density','Radiation efficiency','Pistonic motion']::text[],ARRAY['Assuming a driver stays pistonic across its whole operating band.','Confusing breakup coloration with distortion from the motor and suspension.','Believing a stiffer cone removes breakup; it mainly shifts the frequency, not eliminates it.']::text[],ARRAY['Setting a woofer''s crossover below its cone breakup.','Comparing cone materials for a tweeter''s smoothness.','Diagnosing a response peak from panel flexure.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Breakup mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f8bfd07-82df-4942-a11d-2a6ee092faad','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f8bfd07-82df-4942-a11d-2a6ee092faad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f8bfd07-82df-4942-a11d-2a6ee092faad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4679f111-15a5-4dec-81ea-700a78b53183','Breathing mode','A breathing mode is a vibration mode in which a body expands and contracts uniformly about its center, like a pulsating sphere, so its whole surface moves in phase. Because it displaces net volume, it is a highly efficient, omnidirectional monopole radiator of sound.','In a breathing mode a body swells and shrinks all over at once. Its whole surface moves the same way together. This pushes air out in all directions. It radiates sound very efficiently, like a tiny pulsing ball.','It describes the most efficient, monopole-like radiation from a vibrating body and serves as a reference for radiation efficiency.','An engineer treats a small pulsating source as a breathing sphere to estimate its radiated sound power as an ideal monopole.','Structural Vibration',ARRAY['Bending mode','Breakup mode','Radiation efficiency','Monopole','Pulsating sphere']::text[],ARRAY['Confusing the in-phase breathing mode with higher-order flexural modes.','Assuming all modes radiate equally; the breathing mode radiates far more efficiently.','Mixing up the structural breathing mode with the ''breathing'' of a ported enclosure.']::text[],ARRAY['Modeling a small source as an ideal monopole.','Explaining why a pulsating shell radiates strongly.','Comparing radiation efficiency of different structural modes.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Breathing mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4679f111-15a5-4dec-81ea-700a78b53183','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4679f111-15a5-4dec-81ea-700a78b53183') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4679f111-15a5-4dec-81ea-700a78b53183');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ea4193e-34c2-45f8-8a20-20220fb6a303','Broadband shock-associated noise','A component of supersonic jet noise radiated by an imperfectly expanded (off-design) jet, produced when large turbulent structures in the shear layer convect through the quasi-periodic shock-cell structure of the plume. Its spectrum is broadband with a peak frequency that shifts with observer angle, distinguishing it from discrete screech tones.','A fast jet that is not perfectly expanded forms a train of shock cells. Turbulence flows through these shocks and scatters sound. The result is a broad hiss, not a pure tone. Its pitch changes with your listening angle.','It names and models a major part of supersonic jet noise, separate from turbulent mixing noise and screech, so nozzle and airframe designers can predict and reduce it.','When testing a supersonic nozzle, a technician sees a broad spectral hump; its peak frequency rises toward upstream (forward) angles, following Tam''s shock-noise model, and grows as the jet moves further off its design pressure ratio.','Aeroacoustics',ARRAY['Screech tone','Convective Mach number','Jet mixing noise','Shock cell','Ffowcs Williams-Hawkings equation']::text[],ARRAY['Confusing it with screech tones, which are discrete tones from a resonant feedback loop rather than broadband','Assuming it appears at the design pressure ratio; it needs off-design shock cells to exist','Treating its peak frequency as fixed, when the peak clearly shifts with observation angle']::text[],ARRAY['Measuring flyover noise of military aircraft with supersonic exhaust','Wind-tunnel or anechoic testing of convergent-divergent nozzles','Diagnosing why an off-design rocket or jet plume is broadband rather than tonal']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Broadband shock-associated noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ea4193e-34c2-45f8-8a20-20220fb6a303','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ea4193e-34c2-45f8-8a20-20220fb6a303') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ea4193e-34c2-45f8-8a20-20220fb6a303');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd97c289b-2af2-4d42-82f1-0d1dfe69d9ad','Bubble resonance','The volumetric (breathing-mode) natural frequency at which a small gas bubble in a liquid pulsates, with the compressed gas acting as the spring and the surrounding liquid providing the inertial mass. For an air bubble in water below ultrasonic sizes it is given by the Minnaert relation.','A bubble in water can bounce in size like a mass on a spring. The gas inside is the spring and the water around it is the mass. This gives the bubble a natural pitch. Smaller bubbles ring at higher pitches.','It sets the frequency where a bubble scatters, absorbs, and re-radiates sound most strongly, which underlies underwater sound, the babble of running water, and medical ultrasound contrast agents.','For an air bubble of radius R = 1 mm in water, f0 = (1/(2pi x 0.001)) x sqrt(3 x 1.4 x 101325 / 1000) is about 3.3 kHz; the handy rule f0 x R is roughly 3.3 m.Hz for air in water.','Nonlinear Acoustics',ARRAY['Cavitation threshold','Complex density','Dipole source','Difference-frequency generation','Combustion noise']::text[],ARRAY['Forgetting that resonance frequency rises as the bubble shrinks; small micro-bubbles ring at ultrasonic frequencies','Ignoring surface tension, which raises the frequency of very small (micrometre) bubbles','Using an adiabatic exponent when the bubble is small enough to behave nearly isothermally near resonance']::text[],ARRAY['Explaining the sound of a running stream or a poured drink','Sizing microbubble ultrasound contrast agents in biomedical acoustics','Underwater acoustics of gas leaks, ship wakes, and breaking waves']::text[],'advanced','f0 = (1/(2*pi*R)) * sqrt(3*gamma*p0/rho)','The resonance frequency equals one divided by two pi times the bubble radius, multiplied by the square root of (three times the gas polytropic exponent times the ambient static pressure, divided by the liquid density).','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bubble resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd97c289b-2af2-4d42-82f1-0d1dfe69d9ad','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d97c289b-2af2-4d42-82f1-0d1dfe69d9ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d97c289b-2af2-4d42-82f1-0d1dfe69d9ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17d7638a-5e59-4763-89c2-833a925f2ea6','Cavitation threshold','The acoustic pressure amplitude above which cavitation begins in a liquid, meaning pre-existing nuclei become unstable and grow explosively, then collapse. In the quasi-static limit the Blake threshold gives the tension needed to destabilise a nucleus; the threshold falls as nucleus size increases and as gas content rises.','Push a sound wave hard enough in a liquid and tiny bubbles suddenly grow and violently collapse. The pressure where this starts is the cavitation threshold. Bigger seed bubbles and more dissolved gas lower it. Collapsing bubbles make heat, light, and shock waves.','It marks the safe operating limit for high-intensity ultrasound and the onset condition for cleaning, sonochemistry, and possible tissue damage, so it defines where violent bubble activity begins.','A technician driving an ultrasonic cleaner or medical transducer keeps drive level and the mechanical index within limits; degassing the liquid or removing large nuclei raises the threshold, while dissolved gas and debris lower it.','Nonlinear Acoustics',ARRAY['Bubble resonance','Difference-frequency generation','Complex density','Combustion noise','Dipole source']::text[],ARRAY['UNSAFE: assuming a fixed pressure threshold; real thresholds fall sharply in gassy or dirty water, so intense fields can cavitate far below a clean-water estimate and erode surfaces or tissue','UNSAFE: touching or immersing hands in an active high-intensity ultrasonic field, where transient cavitation can damage skin and tissue','Confusing gentle stable cavitation with violent inertial (transient) cavitation, which produces the damaging collapse','Ignoring frequency dependence; the threshold generally rises with frequency']::text[],ARRAY['Setting drive levels for ultrasonic cleaning baths','Assessing bio-effect safety in diagnostic and therapeutic ultrasound','Sonochemistry and cavitation-erosion testing of materials']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavitation threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17d7638a-5e59-4763-89c2-833a925f2ea6','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17d7638a-5e59-4763-89c2-833a925f2ea6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17d7638a-5e59-4763-89c2-833a925f2ea6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4288ba32-ac68-45dd-9dd5-4672356f9324','Cavity tone','A self-sustained tone generated when flow passes over an open cavity, driven by a feedback loop: shear-layer instabilities convect downstream, impinge on the aft wall, and radiate acoustic pulses upstream that re-excite the shear layer at the leading edge. The discrete frequencies (Rossiter modes) follow a semi-empirical formula.','Air blowing across an open cavity can whistle. Swirls in the shear layer hit the back wall and send sound back to the front. This closes a loop and locks in tones. The buffeting of an open car sunroof is the everyday version.','It predicts the tonal frequencies produced by cavities such as landing-gear bays, sunroofs, and windows, so engineers can anticipate and suppress the resonance.','For U = 100 m/s, L = 0.1 m, M = 0.29, mode n = 2, alpha = 0.25, kappa = 0.57: f2 = (100/0.1) x (2 - 0.25)/(0.29 + 1/0.57) is about 856 Hz.','Aeroacoustics',ARRAY['Edge tone','Broadband shock-associated noise','Convective Mach number','Eigenfrequency','Coiled-space resonator']::text[],ARRAY['Treating alpha and kappa as universal constants rather than empirical fits that vary with geometry and Mach number','Ignoring depth effects; deep cavities can couple to depth (organ-pipe) resonances the basic Rossiter formula omits','Confusing the flow-acoustic Rossiter feedback tone with a purely acoustic standing-wave resonance']::text[],ARRAY['Predicting landing-gear and weapons-bay tones on aircraft','Diagnosing sunroof or side-window buffeting in vehicles','Wind-tunnel study of open-cavity aeroacoustics']::text[],'advanced','f_n = (U/L) * (n - alpha)/(M + 1/kappa),  n = 1,2,3,...','The nth mode frequency equals the freestream speed divided by the cavity length, times the quantity (mode number minus a phase constant), divided by (the Mach number plus the reciprocal of the convection-speed ratio).','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cavity tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4288ba32-ac68-45dd-9dd5-4672356f9324','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4288ba32-ac68-45dd-9dd5-4672356f9324') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4288ba32-ac68-45dd-9dd5-4672356f9324');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '300a89b8-6560-469a-8b6c-475038a0c333','Closed-cell foam','A cellular polymer or elastomer in which the gas-filled cells are sealed and not interconnected, giving very low air permeability and high flow resistivity. Because sound cannot readily pump air through the pore network, closed-cell foam is a poor porous sound absorber but useful for sealing, flotation, and thermal insulation.','This foam has tiny sealed bubbles that do not connect. Air cannot flow through it easily. That makes it bad at soaking up sound but good at blocking air and water. Open-cell foam, with connected pores, absorbs sound much better.','It provides airtight, water-resistant gasketing, buoyancy, and thermal insulation, and can add mass or damping, rather than serving as a fibrous-style acoustic absorber.','A technician chooses open-cell foam or mineral wool for broadband absorption and reserves closed-cell foam for sealing gaps, decoupling gaskets, or vibration pads; treating a room with closed-cell foam gives little absorption.','Acoustic Materials',ARRAY['Flow resistivity','Equivalent-fluid model','Complex bulk modulus','Constrained-layer damping material','Coiled-space resonator']::text[],ARRAY['Assuming any acoustic foam absorbs sound; closed-cell foam is nearly non-absorbing because air cannot move through it','Confusing closed-cell foam panels with open-cell acoustic foam wedges','Expecting good low-frequency absorption from a thin sealed foam layer']::text[],ARRAY['Selecting gasket and seal materials for enclosures','Vibration-isolation pads under equipment','Distinguishing sealing foam from acoustic-treatment foam in a studio build']::text[],'beginner',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Closed-cell foam');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '300a89b8-6560-469a-8b6c-475038a0c333','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='300a89b8-6560-469a-8b6c-475038a0c333') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='300a89b8-6560-469a-8b6c-475038a0c333');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5266415-2ae0-4973-b496-4605c820a520','Coiled-space resonator','An acoustic metamaterial element that folds or coils a long, narrow air channel into a compact footprint, so a physically small unit behaves like a much longer air column. The coiling yields a high effective refractive index and deep sub-wavelength resonances, enabling thin low-frequency absorbers and wavefront-shaping panels.','Imagine winding a long pipe into a tiny box. The sound still travels the full folded length. So a small unit can tune to low, long-wavelength sounds. Engineers use this trick for thin bass absorbers and sound-steering panels.','It packs a long acoustic path into a small space to reach low resonance frequencies and high effective index without a bulky cavity, a core idea in acoustic metamaterials.','A technician can use arrays of coiled channels tuned near a problem frequency to absorb or redirect low-frequency sound in a panel far thinner than a quarter-wavelength.','Acoustic Materials',ARRAY['Coupled-field simulation','Cavity tone','Eigenfrequency','Complex bulk modulus','Closed-cell foam']::text[],ARRAY['Assuming the effective long path removes viscous-thermal losses; narrow coiled channels can dissipate strongly, which is exploited for absorption','Treating it as a broadband solution; single coiled resonators are narrowband and usually arrayed','Ignoring that real performance needs full-wave simulation, not just a folded-length estimate']::text[],ARRAY['Designing thin low-frequency metamaterial absorbers','Acoustic wavefront steering and lensing panels','Compact silencers and duct treatments']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coiled-space resonator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5266415-2ae0-4973-b496-4605c820a520','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5266415-2ae0-4973-b496-4605c820a520') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5266415-2ae0-4973-b496-4605c820a520');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd61db33b-f865-4a09-8ff0-68a3272403ef','Combustion noise','Broadband sound produced by unsteady heat release in a flame or combustor, where fluctuating rates of gas expansion act as a volume (monopole-type) acoustic source. Direct combustion noise radiates from the flame itself, while indirect combustion noise arises when entropy or vorticity non-uniformities accelerate through a downstream nozzle.','A flickering flame heats gas unevenly, so the gas expands in pulses. Those pulses push on the air and make a rumbling roar. This is combustion noise. In engines, hot spots pushed through the exhaust nozzle add more noise.','It explains and quantifies the roar of burners, furnaces, gas-turbine combustors, and rocket engines, guiding combustor design and low-noise burner development.','When a technician measures a gas-turbine or burner rig, combustion noise shows as a broad low-to-mid-frequency hump that scales with heat-release rate and its fluctuation, distinct from mechanical and jet noise.','Aeroacoustics',ARRAY['Dipole source','Curle analogy','Ffowcs Williams-Hawkings equation','Convective Mach number','Bubble resonance']::text[],ARRAY['Modelling the flame as a dipole; unsteady heat release radiates primarily as a monopole (volume) source','Ignoring indirect (entropy) noise generated as hot spots accelerate through the turbine or nozzle','Confusing stable combustion noise with a thermoacoustic instability (a growing tonal oscillation)']::text[],ARRAY['Characterising gas-turbine combustor noise','Domestic and industrial burner noise assessment','Separating combustion, jet, and mechanical noise on an engine test bed']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Combustion noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd61db33b-f865-4a09-8ff0-68a3272403ef','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d61db33b-f865-4a09-8ff0-68a3272403ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d61db33b-f865-4a09-8ff0-68a3272403ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76b9320c-c0b4-49ac-af97-ce2a2ca4d57f','Complex bulk modulus','The frequency-dependent complex quantity describing the dynamic compressibility of the fluid within a porous or lossy medium, whose imaginary part represents thermal (and related) energy losses during compression. In equivalent-fluid models it pairs with a complex effective density to give the material''s complex wavenumber and characteristic impedance.','Squeeze the air inside a porous absorber and it does not push back perfectly in step. Some energy turns to heat at the pore walls. A complex bulk modulus captures both the springiness and this loss. It changes with frequency.','It encodes the thermal-loss part of sound absorption in porous media, letting a rigid-frame absorber be modelled as a simple effective fluid.','Combined with complex density, a technician computes the material sound speed c = sqrt(K/rho) and characteristic impedance Zc = sqrt(K*rho) (both complex) to predict a porous absorber''s absorption versus frequency.','Acoustic Materials',ARRAY['Complex density','Equivalent-fluid model','Flow resistivity','Closed-cell foam','Coiled-space resonator']::text[],ARRAY['Treating the bulk modulus as real; the imaginary part is what produces thermal absorption','Using the adiabatic value at all frequencies; behaviour shifts from adiabatic at high frequency to isothermal at low frequency in the pores','Forgetting that it is defined for the pore fluid within a rigid frame, not the bulk solid material']::text[],ARRAY['Modelling mineral-wool or foam absorbers with the Johnson-Champoux-Allard model','Predicting transfer impedance of porous layers','Fitting measured surface impedance to extract material parameters']::text[],'advanced','c_tilde = sqrt(K_tilde/rho_tilde);  Z_c = sqrt(K_tilde*rho_tilde);  k = omega*sqrt(rho_tilde/K_tilde)','The complex sound speed equals the square root of the complex bulk modulus divided by the complex effective density; characteristic impedance is the square root of their product; and the complex wavenumber is angular frequency times the square root of density over bulk modulus.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex bulk modulus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76b9320c-c0b4-49ac-af97-ce2a2ca4d57f','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76b9320c-c0b4-49ac-af97-ce2a2ca4d57f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76b9320c-c0b4-49ac-af97-ce2a2ca4d57f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9794279f-9ad4-46a1-8894-88fd6a886a9e','Complex density','The frequency-dependent complex effective density used in equivalent-fluid models of porous media, whose real part reflects the inertia of the pore fluid (including tortuosity) and whose imaginary part represents viscous drag losses at the pore walls. It pairs with the complex bulk modulus to describe wave propagation and dissipation in the absorber.','Air moving inside tiny twisted pores feels heavier and drags on the walls. A complex effective density captures this extra inertia and friction. Its real part is the added mass and its imaginary part is the loss. It varies with frequency.','It encodes the viscous-loss and tortuosity part of sound absorption in porous media, completing the equivalent-fluid description alongside the complex bulk modulus.','With the complex bulk modulus, a technician forms the complex wavenumber and characteristic impedance to predict how a fibrous or foam layer absorbs and reflects sound across frequency.','Acoustic Materials',ARRAY['Complex bulk modulus','Equivalent-fluid model','Flow resistivity','Closed-cell foam','Bubble resonance']::text[],ARRAY['Using the static air density; the effective density is inflated by tortuosity and made complex by viscous drag','Ignoring the imaginary part, which represents the viscous dissipation that gives absorption','Applying it to a flexible-frame material without allowing for frame motion (the Biot poroelastic case)']::text[],ARRAY['Johnson-Champoux-Allard modelling of porous absorbers','Extracting tortuosity and flow resistivity from impedance-tube data','Simulating duct liners and silencer fill']::text[],'advanced','Z_c = sqrt(K_tilde*rho_tilde);  k = omega*sqrt(rho_tilde/K_tilde)','Characteristic impedance equals the square root of the complex bulk modulus times the complex effective density, and the complex wavenumber equals angular frequency times the square root of the complex density divided by the complex bulk modulus.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9794279f-9ad4-46a1-8894-88fd6a886a9e','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9794279f-9ad4-46a1-8894-88fd6a886a9e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9794279f-9ad4-46a1-8894-88fd6a886a9e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a943b26b-c974-4190-83cf-82e06bff4ce7','Constrained-layer damping material','A damping treatment in which a viscoelastic layer is sandwiched between the vibrating base structure and a stiff outer constraining layer. When the structure bends, the viscoelastic core is forced into shear, dissipating vibrational energy far more effectively than an unconstrained (free-layer) coating of the same material.','Glue a soft rubbery layer to a vibrating panel, then cap it with a stiff sheet. When the panel flexes, the soft middle is sheared back and forth. That shearing turns vibration into heat. It damps ringing far better than a plain soft coating.','It suppresses resonant vibration and structure-borne noise in panels and enclosures by converting bending energy into heat through shear in a confined viscoelastic layer.','A technician bonds constrained-layer damping tiles or tape to a resonant chassis, duct, or panel; the added stiff face sheet is what makes the viscoelastic core shear and greatly raises the loss factor.','Vibro-Acoustics',ARRAY['Damping ratio','Damping-controlled region','Critical damping','Dynamic stiffness','Driving-point mobility']::text[],ARRAY['Omitting the stiff constraining layer, which reduces the treatment to a much weaker free-layer damper','Assuming performance is frequency- and temperature-independent; viscoelastic loss peaks over a limited range','Adding excessive mass expecting more damping, when shear strain in the core drives the loss']::text[],ARRAY['Damping resonant metal panels in equipment enclosures','Reducing structure-borne noise in vehicle and appliance bodies','Treating HVAC ductwork and machine covers for ring-down']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Constrained-layer damping material');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a943b26b-c974-4190-83cf-82e06bff4ce7','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a943b26b-c974-4190-83cf-82e06bff4ce7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a943b26b-c974-4190-83cf-82e06bff4ce7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf87563f-f3b2-45fd-aa38-e1c8f783d51f','Convective Mach number','A similarity parameter for compressible shear layers and jets defined from the speed of the large convecting turbulent structures relative to the ambient sound speed. For a two-stream mixing layer it is (U1 - U2)/(a1 + a2); it governs shear-layer growth rate and the efficiency of acoustic radiation.','Turbulent swirls in a fast shear layer travel at their own speed. Compare that speed to the speed of sound and you get the convective Mach number. When it is high, the flow mixes less and radiates sound differently. It is a key aeroacoustic yardstick.','It collapses compressibility effects on mixing-layer growth and jet-noise radiation onto a single parameter, letting engineers compare flows across speeds and conditions.','For two streams with U1 = 300 m/s, U2 = 0, and equal sound speeds a1 = a2 = 340 m/s, Mc = 300/(340 + 340) is about 0.44, indicating moderate compressibility of the shear layer.','Aeroacoustics',ARRAY['Broadband shock-associated noise','Cavity tone','Jet mixing noise','Ffowcs Williams-Hawkings equation','Combustion noise']::text[],ARRAY['Confusing it with the jet or freestream Mach number; it uses the eddy convection speed, not the mean flow speed','Using the wrong reference sound speed when the two streams differ in temperature or gas','Assuming shear-layer growth is unaffected by it; growth rate drops markedly as Mc rises']::text[],ARRAY['Correlating supersonic jet noise with convective Mach number','Predicting compressible mixing-layer spreading rates','Scaling aeroacoustic wind-tunnel data across speeds']::text[],'advanced','M_c = (U1 - U2)/(a1 + a2)','The convective Mach number equals the velocity difference between the two streams divided by the sum of their sound speeds.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Convective Mach number');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf87563f-f3b2-45fd-aa38-e1c8f783d51f','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf87563f-f3b2-45fd-aa38-e1c8f783d51f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf87563f-f3b2-45fd-aa38-e1c8f783d51f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77d7bfc0-0506-4a2d-826e-729fdcffb5a9','Coupled-field simulation','A multiphysics numerical simulation in which two or more interacting physical fields, such as structural vibration and the surrounding acoustic fluid, are solved together with their mutual coupling at shared interfaces. Vibro-acoustic FEM/BEM and fluid-structure interaction are common examples relevant to radiated sound.','Some problems mix physics that push on each other. A vibrating panel drives the air, and the air pushes back. A coupled-field simulation solves both at once and links them at the shared surface. This captures effects a single-physics model would miss.','It predicts how structures and fluids exchange energy, so engineers can compute radiated sound, transmission loss, and vibration response that depend on two-way coupling.','A technician uses a coupled structural-acoustic FEM/BEM model to predict how a loudspeaker cabinet or machine panel radiates sound, including the fluid loading that a vacuum (uncoupled) model would ignore.','Numerical Methods',ARRAY['Finite-element analysis','Discontinuous Galerkin method','Finite-difference method','Energy finite-element analysis','Driving-point mobility']::text[],ARRAY['Assuming coupling is negligible; heavy fluids (water) or light stiff panels can make fluid loading dominant','Mismatching meshes or time steps between the fields, causing spurious energy at the interface','Confusing one-way (sequential) coupling with true two-way coupling']::text[],ARRAY['Vibro-acoustic prediction of enclosure and panel radiation','Underwater structure and sonar dome modelling with strong fluid loading','Fluid-structure interaction in ducts and thin-walled machinery']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coupled-field simulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77d7bfc0-0506-4a2d-826e-729fdcffb5a9','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77d7bfc0-0506-4a2d-826e-729fdcffb5a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77d7bfc0-0506-4a2d-826e-729fdcffb5a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfe583b0-daa4-45b6-912d-a2329563727b','Courant condition','A necessary stability condition for explicit time-marching schemes of hyperbolic (wave) equations, requiring that the numerical domain of dependence contain the physical one. It is expressed through the Courant (CFL) number, which must not exceed a scheme-dependent maximum, limiting the time step relative to the grid spacing and wave speed.','When you simulate waves step by step, the time step cannot be too big. Information must not skip past grid points in one step. The Courant condition sets that speed limit. Break it and the simulation blows up.','It tells the analyst the largest stable time step for an explicit acoustic or wave solver, preventing numerical instability while keeping computation efficient.','For a 1-D acoustic FDTD run with c = 343 m/s and grid dx = 0.01 m, a Courant number of 1 gives dt <= dx/c = 0.01/343, about 29 microseconds per step.','Numerical Methods',ARRAY['Finite-difference method','Discontinuous Galerkin method','Finite-element analysis','Coupled-field simulation','Eigenfrequency']::text[],ARRAY['Assuming C_max is always 1; it drops in multiple dimensions and varies by scheme','Thinking the condition guarantees accuracy; it only bounds stability, not error','Forgetting to use the largest wave speed in the domain when setting the time step']::text[],ARRAY['Choosing time steps for FDTD room-acoustics simulation','Stability tuning of explicit CFD and computational aeroacoustics solvers','Physical-modelling sound synthesis on a grid']::text[],'advanced','C = c*dt/dx <= C_max','The Courant number equals the wave speed times the time step divided by the grid spacing, and it must be less than or equal to a scheme-dependent maximum (often one in one dimension).','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Courant condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfe583b0-daa4-45b6-912d-a2329563727b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfe583b0-daa4-45b6-912d-a2329563727b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfe583b0-daa4-45b6-912d-a2329563727b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3edeff9e-5515-4afe-919f-5e7253184d2e','Critical damping','The exact amount of viscous damping in a single-degree-of-freedom system that returns it to equilibrium in the shortest time without oscillating. It marks the boundary between underdamped (oscillatory) and overdamped (sluggish) behaviour, and equals twice the square root of the product of stiffness and mass.','Damping decides how a vibrating system settles. Too little and it wobbles many times. Too much and it crawls back slowly. Critical damping is the sweet spot: fastest return with no overshoot. It just barely avoids oscillation.','It provides the reference damping level used to classify and design vibration behaviour, and to normalise damping into the damping ratio.','For a mass m = 2 kg on a spring of stiffness k = 800 N/m, critical damping cc = 2*sqrt(k*m) = 2*sqrt(1600) = 80 N.s/m; any damping below this leaves the system oscillatory.','Vibro-Acoustics',ARRAY['Damping ratio','Damping-controlled region','Constrained-layer damping material','Eigenfrequency','Dynamic stiffness']::text[],ARRAY['Believing critically damped is the fastest possible return; it is fastest without overshoot, but a small overshoot can settle sooner','Confusing critical damping (a coefficient) with the damping ratio (a dimensionless number)','Assuming more damping is always better, ignoring the overdamped sluggish response']::text[],ARRAY['Designing shock mounts and instrument suspensions','Tuning meter-movement and sensor response to avoid overshoot','Setting isolator damping in vibration control']::text[],'intermediate','c_c = 2*sqrt(k*m) = 2*m*omega_n','Critical damping equals two times the square root of stiffness times mass, which is also two times the mass times the undamped natural angular frequency.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3edeff9e-5515-4afe-919f-5e7253184d2e','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3edeff9e-5515-4afe-919f-5e7253184d2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3edeff9e-5515-4afe-919f-5e7253184d2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8665081-4cab-4e4c-be01-21c1df379c0f','Curle analogy','An extension of Lighthill''s acoustic analogy that incorporates the effect of stationary solid boundaries on aerodynamically generated sound. It shows that fluctuating forces the surface exerts on the fluid radiate as a dipole distribution, which dominates the volume (Lighthill quadrupole) sound at low Mach number.','Lighthill explained sound made by free turbulence. Curle added solid surfaces to the picture. Pressure wobbling on a surface acts like a dipole loudspeaker. At low speeds this surface dipole is louder than free-turbulence sound.','It provides the theoretical basis for predicting sound from turbulence interacting with rigid bodies, such as struts, cylinders, and blades, by linking surface pressure fluctuations to radiated sound.','A technician predicting flow noise from a strut or cylinder uses the Curle result: measured or computed unsteady surface forces give the dipole sound, which at low Mach number exceeds any quadrupole contribution.','Aeroacoustics',ARRAY['Dipole source','Ffowcs Williams-Hawkings equation','Combustion noise','Convective Mach number','Edge tone']::text[],ARRAY['Assuming the surface adds a monopole; a rigid stationary surface contributes a dipole (force) source','Neglecting the surface dipole at low Mach number, where it dominates over the quadrupole','Applying it to moving surfaces, which require the more general Ffowcs Williams-Hawkings equation']::text[],ARRAY['Predicting aeolian tones from cylinders and wires','Airframe and strut self-noise estimation','Fan and blade interaction-noise modelling at low Mach number']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Curle analogy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8665081-4cab-4e4c-be01-21c1df379c0f','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8665081-4cab-4e4c-be01-21c1df379c0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8665081-4cab-4e4c-be01-21c1df379c0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d4c0991-e255-405e-a4c5-d8ab1330ade9','Damping ratio','A dimensionless measure of damping in a single-degree-of-freedom system, equal to the actual viscous damping divided by the critical damping. Values below one are underdamped (oscillatory), one is critically damped, and above one is overdamped; it is directly related to the quality factor and loss factor.','The damping ratio is a simple number that says how damped a system is. Below one it rings before settling. At one it settles fast with no wobble. Above one it returns slowly. It compares real damping to critical damping.','It normalises damping into a single dimensionless figure that predicts overshoot, decay rate, and resonance sharpness across systems of any size.','With damping c = 8 N.s/m and critical damping cc = 80 N.s/m, zeta = c/cc = 0.1 (underdamped); this also gives quality factor Q = 1/(2*zeta) = 5 and loss factor eta = 2*zeta = 0.2.','Vibro-Acoustics',ARRAY['Critical damping','Damping-controlled region','Constrained-layer damping material','Eigenfrequency','Dynamic stiffness']::text[],ARRAY['Mixing up damping ratio (dimensionless) with the damping coefficient (units N.s/m)','Applying the Q = 1/(2*zeta) shortcut at heavy damping, where light-damping approximations break down','Reading a resonance peak''s sharpness without accounting for it being set by the damping ratio']::text[],ARRAY['Extracting damping from a measured resonance peak or decay','Specifying isolator and mount performance','Comparing loss factor, Q, and damping ratio in modal analysis']::text[],'intermediate','zeta = c/c_c = c/(2*sqrt(k*m));  Q = 1/(2*zeta);  eta = 2*zeta','The damping ratio equals the viscous damping divided by the critical damping, which is the damping divided by twice the square root of stiffness times mass; the quality factor is one over twice the damping ratio, and the loss factor is twice the damping ratio.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Damping ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d4c0991-e255-405e-a4c5-d8ab1330ade9','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d4c0991-e255-405e-a4c5-d8ab1330ade9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d4c0991-e255-405e-a4c5-d8ab1330ade9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3bc2cab6-d6ea-4521-a4c5-d3604464d5b2','Damping-controlled region','The frequency band of a driven single-degree-of-freedom system, centred on resonance, where the response amplitude is governed mainly by damping rather than by stiffness or mass. Below resonance the response is stiffness-controlled; above resonance it is mass-controlled; at resonance the stiffness and inertia reactances cancel and damping alone limits the peak.','Drive a spring-mass system and its response changes with frequency. Well below its natural frequency, stiffness rules. Well above, mass rules. Right at resonance, only damping holds the peak down. That band is the damping-controlled region.','It identifies where added damping actually reduces vibration response, so effort is spent where it helps rather than where stiffness or mass dominates.','A technician facing a resonant peak knows that near resonance only damping cuts the amplitude, so a constrained-layer or lossy treatment is effective there, while stiffening or mass changes shift rather than damp the peak.','Vibro-Acoustics',ARRAY['Damping ratio','Critical damping','Constrained-layer damping material','Eigenfrequency','Driving-point mobility']::text[],ARRAY['Adding stiffness or mass to reduce a resonant peak; near resonance only damping limits amplitude','Assuming damping helps everywhere; away from resonance the response is set by stiffness or mass','Confusing the resonance frequency itself with the finite band around it that damping controls']::text[],ARRAY['Deciding whether to damp, stiffen, or add mass to fix a resonance','Interpreting frequency-response-function regions in modal testing','Isolation design across stiffness-, damping-, and mass-controlled bands']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Damping-controlled region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3bc2cab6-d6ea-4521-a4c5-d3604464d5b2','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3bc2cab6-d6ea-4521-a4c5-d3604464d5b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3bc2cab6-d6ea-4521-a4c5-d3604464d5b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8407f25d-cce0-45e5-9b81-fee0b75ab64c','Difference-frequency generation','A nonlinear acoustic process in which two collimated primary waves at closely spaced high frequencies interact within the medium''s finite nonlinearity to generate a difference-frequency wave. Distributed along the primary beam, this is the mechanism of the parametric acoustic array, yielding a highly directional low-frequency beam from a small aperture.','Send two strong high-pitched beams together through air or water. The medium is slightly nonlinear, so they mix. This creates a new tone at the difference of their pitches. The low tone comes out as a tight, narrow beam.','It lets a small transducer radiate a very directional low-frequency (audible or sonar) beam, avoiding the wide spreading a small source would normally give at low frequency.','A technician using a parametric loudspeaker or sonar drives two ultrasonic primaries (for example 40 and 41 kHz) so the medium''s nonlinearity produces a directional 1 kHz beam along the primary column.','Nonlinear Acoustics',ARRAY['Bubble resonance','Cavitation threshold','Dipole source','Convective Mach number','Combustion noise']::text[],ARRAY['Expecting the difference tone at the source face; it builds up gradually along the primary beam','Assuming it is efficient; conversion to the difference frequency is inherently weak','Ignoring high drive levels needed, which can invoke further nonlinearity, shock formation, or (in liquids) cavitation']::text[],ARRAY['Parametric (''audio spotlight'') directional loudspeakers','Parametric sonar for narrow-beam low-frequency sounding','Nonlinear-acoustics laboratory demonstrations']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Difference-frequency generation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8407f25d-cce0-45e5-9b81-fee0b75ab64c','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8407f25d-cce0-45e5-9b81-fee0b75ab64c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8407f25d-cce0-45e5-9b81-fee0b75ab64c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44f3eb49-1c36-4efd-a5f5-ab9afe9417f1','Dipole source','An elementary acoustic source equivalent to two closely spaced monopoles of equal strength in antiphase, or physically to a fluctuating force applied to the fluid. It radiates with a figure-of-eight (cosine) directivity and, for a given source strength, is far less efficient than a monopole at low frequency, with radiated power scaling more steeply with frequency.','Picture two tiny loudspeakers side by side, one pushing while the other pulls. Their sound cancels to the sides and adds front and back. That is a dipole. An oscillating force on the air makes the same pattern. It radiates a figure-eight shape.','It models sound from unsteady forces, such as vibrating surfaces, struts, and rigid bodies in flow, and is a building block of aeroacoustic and radiation theory.','A technician recognises an unbaffled small loudspeaker or a bare vibrating panel edge as an acoustic dipole, explaining its weak, direction-dependent low-frequency output and the deep side nulls.','Physical Acoustics',ARRAY['Curle analogy','Ffowcs Williams-Hawkings equation','Combustion noise','Edge tone','Driving-point mobility']::text[],ARRAY['Expecting omnidirectional radiation; a dipole has strong nulls perpendicular to its axis','Assuming it radiates as efficiently as a monopole at low frequency; it is much weaker','Confusing the two-monopole model with a single simple source']::text[],ARRAY['Explaining unbaffled loudspeaker dipole roll-off and side nulls','Modelling flow-induced surface forces as dipoles in aeroacoustics','Teaching elementary source directivity in acoustics']::text[],'intermediate','p(r,theta) proportional to cos(theta);  W_dipole proportional to omega^4','The far-field dipole pressure varies as the cosine of the angle from its axis, giving a figure-of-eight pattern, and its radiated power rises with the fourth power of frequency for a fixed dipole strength.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dipole source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44f3eb49-1c36-4efd-a5f5-ab9afe9417f1','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44f3eb49-1c36-4efd-a5f5-ab9afe9417f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44f3eb49-1c36-4efd-a5f5-ab9afe9417f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b640b40-6c16-49e0-b095-b4962ca2de2d','Discontinuous Galerkin method','A high-order finite-element method that represents the solution by piecewise polynomials which are allowed to be discontinuous across element interfaces, with inter-element coupling supplied through numerical fluxes as in finite-volume schemes. Its low numerical dispersion and dissipation and local, parallel-friendly structure make it well suited to computational aeroacoustics and wave propagation.','This method splits a domain into elements and fits a smooth polynomial in each. Neighbouring pieces need not match at the borders. They talk through flux terms at the interfaces. This gives accurate, low-error wave simulations that parallelise well.','It provides accurate high-order solutions of wave and flow equations on complex meshes, combining finite-element geometric flexibility with finite-volume conservation and stability.','A technician running computational aeroacoustics can use a discontinuous Galerkin solver to propagate sound over long distances with little numerical dispersion, on unstructured meshes around complex geometry.','Numerical Methods',ARRAY['Finite-element analysis','Finite-difference method','Coupled-field simulation','Courant condition','Energy finite-element analysis']::text[],ARRAY['Assuming it is unconditionally stable; explicit time stepping still obeys a Courant-type limit','Ignoring the numerical-flux choice, which affects accuracy and stability','Expecting cheap low-order accuracy; its strength is high-order convergence, at higher per-element cost']::text[],ARRAY['High-fidelity computational aeroacoustics propagation','Wave simulation on unstructured meshes around complex bodies','Scalable parallel solvers for large acoustic domains']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Discontinuous Galerkin method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b640b40-6c16-49e0-b095-b4962ca2de2d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b640b40-6c16-49e0-b095-b4962ca2de2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b640b40-6c16-49e0-b095-b4962ca2de2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d2953d1-6116-4391-9334-33ea659a38bd','Driving-point mobility','The frequency-dependent complex ratio of the velocity to the applied force at the very point of excitation on a structure. It characterises how readily a structure moves where it is driven, sets the vibrational power a source injects, and for an infinite thin plate is real and independent of frequency.','Push a structure at one spot and it moves. Mobility is how much velocity you get per unit force at that same spot. High mobility means the point moves easily. It controls how much vibration a source can pump in.','It quantifies a structure''s local response and the power a vibration source delivers, guiding source-structure matching and isolation design.','For an infinite thin plate, driving-point mobility is Y = 1/(8*sqrt(B*m_area)), real and flat with frequency; a technician uses measured mobility to estimate injected power, P = (1/2)*Re(Y)*|F|^2.','Vibro-Acoustics',ARRAY['Dynamic stiffness','Damping-controlled region','Eigenfrequency','Effective modal mass','Constrained-layer damping material']::text[],ARRAY['Confusing mobility (velocity/force) with its inverse, mechanical impedance (force/velocity)','Measuring velocity at a point other than the drive point and calling it driving-point mobility','Assuming a finite plate has the flat infinite-plate mobility, ignoring its resonant peaks and dips']::text[],ARRAY['Estimating vibrational power injected into a panel by a machine','Impact-hammer or shaker mobility measurements','Matching sources and isolators in structure-borne noise control']::text[],'advanced','Y(omega) = v(omega)/F(omega);  Y_plate = 1/(8*sqrt(B*m_area))','Mobility is the complex velocity divided by the complex force at the drive point; for an infinite thin plate it equals one divided by eight times the square root of the bending stiffness times the mass per unit area.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Driving-point mobility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d2953d1-6116-4391-9334-33ea659a38bd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d2953d1-6116-4391-9334-33ea659a38bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d2953d1-6116-4391-9334-33ea659a38bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb49faaf-a199-4033-9ea9-8c8d1e2860fc','Dynamic stiffness','The frequency-dependent complex ratio of dynamic force to dynamic displacement of a resilient element. For materials used under floating floors, ISO 9052-1 defines an apparent dynamic stiffness per unit area, measured from the vertical resonance of a standard mass on the sample, which sets the floor''s mass-spring isolation frequency.','Dynamic stiffness says how hard a springy material pushes back when vibrated, per unit squeeze. A softer material has lower dynamic stiffness. Under a floating floor, lower stiffness means better isolation. A standard test finds it from a resonance.','It rates resilient underlays and isolators for impact and structure-borne noise control, because a lower dynamic stiffness gives a lower resonance and better isolation above it.','Per ISO 9052-1, a technician measures the resonance fr of a standard load on the sample; with load mass per area m'' = 20 kg/m^2 and fr = 100 Hz, s'' = 4*pi^2*m''*fr^2 is about 7.9 MN/m^3.','Vibro-Acoustics',ARRAY['Critical damping','Damping ratio','Driving-point mobility','Constrained-layer damping material','Eigenfrequency']::text[],ARRAY['Confusing static stiffness with dynamic stiffness; they differ for many resilient materials','Ignoring the airflow-resistivity contribution that ISO 9052-1 accounts for in some materials','Assuming lower stiffness always helps, without checking that the isolation frequency lands below the range of interest']::text[],ARRAY['Selecting resilient underlays for floating floors','Rating vibration-isolation pads and mounts','Predicting impact-noise improvement of floor build-ups']::text[],'advanced','s'' = 4*pi^2*m''*f_r^2;  f_r = (1/(2*pi))*sqrt(s''/m'')','The apparent dynamic stiffness per unit area equals four pi squared times the load mass per unit area times the resonance frequency squared; equivalently the resonance frequency is one over two pi times the square root of the stiffness per area divided by the mass per area.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic stiffness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb49faaf-a199-4033-9ea9-8c8d1e2860fc','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb49faaf-a199-4033-9ea9-8c8d1e2860fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb49faaf-a199-4033-9ea9-8c8d1e2860fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7cb40bab-0140-4bc2-8354-a9d5cb2763cd','Edge tone','A self-sustained oscillation produced when a thin planar jet issuing from a slit strikes a sharp wedge or edge placed downstream. A feedback loop between the jet''s instability waves and the pressure field generated at the edge locks the jet into oscillation, radiating tones that jump between stages as jet speed or gap changes.','Blow a flat sheet of air at a sharp edge just downstream. The jet wavers, hits the edge, and sends a signal back that keeps it wavering. This locks in a tone. It is the driving mechanism behind flutes and organ flue pipes.','It explains the sound-generating mechanism of flue musical instruments and many aeroacoustic whistles, and is the free-jet cousin of the cavity tone.','A technician tuning or diagnosing a flue organ pipe or a whistle recognises the edge-tone feedback; increasing jet speed or shortening the jet-to-edge gap raises frequency and can trigger a jump to a higher stage.','Aeroacoustics',ARRAY['Cavity tone','Dipole source','Curle analogy','Convective Mach number','Combustion noise']::text[],ARRAY['Treating the frequency as a single value; edge tones stage-jump discontinuously with speed and gap','Assuming a fixed jet-to-edge distance sets frequency linearly; the feedback timing is what matters','Confusing the free-jet edge tone with the wall-bounded cavity (Rossiter) tone']::text[],ARRAY['Physics of flute and flue-organ-pipe sound production','Aeroacoustic whistle and edge-tone experiments','Diagnosing unwanted whistling at slots and sharp edges']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Edge tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7cb40bab-0140-4bc2-8354-a9d5cb2763cd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7cb40bab-0140-4bc2-8354-a9d5cb2763cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7cb40bab-0140-4bc2-8354-a9d5cb2763cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6edf0f8a-7751-4b14-aa97-3fb382b7bdcd','Effective modal mass','A property of each vibration mode indicating how much of the structure''s total mass is dynamically active in that mode for a given base-excitation direction, computed from the mode''s participation factor and generalised mass. Summed over all modes in a direction, the effective modal masses recover the structure''s total mass in that direction.','Not every mode moves much of a structure''s mass. Effective modal mass says how much mass each mode really shakes in a chosen direction. Big values mark the modes that matter most. Add them all up and you get the total mass.','It ranks which modes dominate the response to base motion, so analysts know how many modes to include and which resonances truly matter.','Running a modal analysis, a technician checks that the summed effective modal mass reaches most of the total mass (often a 90 percent target) before trusting a truncated modal model for shock or vibration response.','Vibro-Acoustics',ARRAY['Eigenfrequency','Driving-point mobility','Damping-controlled region','Dynamic stiffness','Finite-element analysis']::text[],ARRAY['Confusing effective modal mass with generalised (modal) mass, which depends on mode-shape scaling','Judging a mode important by frequency alone rather than by its effective mass','Truncating a modal model before the summed effective mass captures enough of the total']::text[],ARRAY['Deciding how many modes to keep in a reduced FE model','Qualifying structures for random-vibration and shock loads','Interpreting modal-analysis mass-participation tables']::text[],'advanced','m_eff,i = (phi_i^T * M * r)^2 / (phi_i^T * M * phi_i)','The effective modal mass of mode i equals the square of the modal participation factor (the mode shape transpose times the mass matrix times the direction vector), divided by the generalised (modal) mass.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective modal mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6edf0f8a-7751-4b14-aa97-3fb382b7bdcd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6edf0f8a-7751-4b14-aa97-3fb382b7bdcd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6edf0f8a-7751-4b14-aa97-3fb382b7bdcd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa86be86-c03d-4a78-b6df-47b7dbd150ef','Eigenfrequency','A natural frequency at which a linear system freely vibrates in a characteristic mode shape (eigenvector) with no external forcing. Found from the eigenvalue problem for the stiffness and mass matrices, eigenfrequencies are where a lightly damped structure or acoustic cavity resonates most strongly.','Every structure or air cavity has favourite frequencies where it likes to vibrate on its own. These are its eigenfrequencies. Each comes with a shape of motion. Drive it near one and it resonates strongly.','It identifies the resonances of a structure or cavity, which govern where response, radiation, and potential failure peak.','For a spring-mass system with k = 800 N/m and m = 2 kg, the eigenfrequency is fn = (1/(2*pi))*sqrt(k/m) = (1/(2*pi))*sqrt(400), about 3.2 Hz; multi-degree systems solve det(K - omega^2*M) = 0.','Vibro-Acoustics',ARRAY['Effective modal mass','Damping-controlled region','Dynamic stiffness','Driving-point mobility','Finite-element analysis']::text[],ARRAY['Confusing eigenfrequency (undamped natural frequency) with damped natural frequency, which is slightly lower','Ignoring that boundary conditions and added mass shift eigenfrequencies','Assuming an eigenfrequency exists in isolation, forgetting its associated mode shape']::text[],ARRAY['Modal analysis of panels, enclosures, and structures','Predicting room and cavity acoustic resonances','Avoiding resonance by tuning mounts and structures']::text[],'intermediate','det(K - omega^2*M) = 0;  f_n = (1/(2*pi))*sqrt(k/m)  (single DOF)','Eigenfrequencies come from setting the determinant of the stiffness matrix minus the frequency squared times the mass matrix to zero; for one degree of freedom the natural frequency is one over two pi times the square root of stiffness over mass.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eigenfrequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa86be86-c03d-4a78-b6df-47b7dbd150ef','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa86be86-c03d-4a78-b6df-47b7dbd150ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa86be86-c03d-4a78-b6df-47b7dbd150ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8513374-e24e-473b-9db8-f7f9752228e4','Energy finite-element analysis','A high-frequency vibro-acoustic modelling technique that solves for the time- and space-averaged vibrational energy density over a finite-element mesh, using an energy-balance (diffusion-like) governing equation rather than the full displacement field. It bridges detailed finite-element analysis at low frequency and statistical energy analysis at high frequency.','At high frequencies a structure has too many modes to track one by one. This method follows how vibration energy flows and spreads instead. It solves for energy on a mesh, much like heat spreading. That gives smooth high-frequency estimates.','It predicts high-frequency vibration and noise energy distribution with spatial detail that statistical energy analysis lacks, while avoiding the impractical mesh density full FEA would need.','For a complex panel structure vibrating in the kilohertz range, a technician uses energy FEA to map where vibrational energy concentrates, informing where to add damping, without meshing every wavelength for a modal solution.','Numerical Methods',ARRAY['Finite-element analysis','Coupled-field simulation','Damping-controlled region','Driving-point mobility','Discontinuous Galerkin method']::text[],ARRAY['Expecting detailed mode shapes; it yields smoothed energy distributions, not the field itself','Applying it at low frequency, where modal FEA is appropriate and its assumptions fail','Confusing it with statistical energy analysis, which uses lumped subsystems rather than a mesh']::text[],ARRAY['High-frequency structure-borne energy mapping','Bridging FEA and SEA in mid-to-high frequency vibro-acoustics','Locating energy hotspots to target damping treatment']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Energy finite-element analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8513374-e24e-473b-9db8-f7f9752228e4','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8513374-e24e-473b-9db8-f7f9752228e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8513374-e24e-473b-9db8-f7f9752228e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c163711d-f2a7-4cac-82eb-99d44feb7947','Equivalent-fluid model','A modelling approach that treats a rigid-framed porous absorber as if it were a homogeneous fluid characterised by a complex effective density and a complex bulk modulus. From these, a complex characteristic impedance and wavenumber are obtained, so standard fluid wave equations predict the absorber''s reflection and absorption.','A porous absorber is really a solid skeleton full of air in tiny pores. The equivalent-fluid model pretends it is just one special fluid instead. That fluid has complex density and stiffness that include the losses. Then simple wave math predicts absorption.','It simplifies porous-material acoustics to a fluid problem, enabling fast prediction of absorption and impedance for design and simulation.','A technician specifying acoustic treatment uses an equivalent-fluid model (such as Delany-Bazley or Johnson-Champoux-Allard) with flow resistivity and other parameters to predict a layer''s absorption coefficient versus frequency and backing depth.','Acoustic Materials',ARRAY['Complex bulk modulus','Complex density','Flow resistivity','Closed-cell foam','Coiled-space resonator']::text[],ARRAY['Applying it to limp or elastic-frame materials where the skeleton moves, which needs poroelastic (Biot) theory','Using empirical models like Delany-Bazley outside their valid flow-resistivity and frequency range','Forgetting that backing air gap and mounting strongly change the predicted absorption']::text[],ARRAY['Predicting absorption of mineral wool and foam layers','Impedance-tube data fitting to extract material parameters','Duct-liner and silencer acoustic design']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent-fluid model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c163711d-f2a7-4cac-82eb-99d44feb7947','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c163711d-f2a7-4cac-82eb-99d44feb7947') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c163711d-f2a7-4cac-82eb-99d44feb7947');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8c362bc-d761-449b-8207-fa416434dd85','Ffowcs Williams–Hawkings equation','An exact reformulation of the continuity and Navier-Stokes equations that extends Lighthill''s and Curle''s acoustic analogies to surfaces in arbitrary motion. It expresses radiated sound as three source terms: a monopole (thickness) term from surface displacement, a dipole (loading) term from surface forces, and a quadrupole (volume) term from the Lighthill turbulence stresses.','This equation predicts sound from surfaces that move, like spinning rotor blades. It splits the sound into three parts. One part comes from the blade pushing air aside. Another comes from forces on the blade, and a third from nearby turbulence.','It is the foundation of modern rotating-machinery and rotor/propeller noise prediction, letting surface and flow data on a moving body be turned into far-field sound.','A technician predicting helicopter-rotor, propeller, or fan noise feeds computed blade-surface pressures and motion into an FW-H solver, which returns the far-field acoustic signature from the thickness and loading terms.','Aeroacoustics',ARRAY['Curle analogy','Dipole source','Combustion noise','Convective Mach number','Broadband shock-associated noise']::text[],ARRAY['Assuming it is an approximation; it is an exact rearrangement of the governing equations','Dropping the quadrupole term when flow is transonic or supersonic, where it becomes important','Ignoring retarded-time and Doppler effects from the surface motion when evaluating the integrals']::text[],ARRAY['Helicopter-rotor and propeller noise prediction','Wind-turbine and fan aeroacoustics','Coupling CFD surface data to far-field acoustic solvers']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ffowcs Williams–Hawkings equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8c362bc-d761-449b-8207-fa416434dd85','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8c362bc-d761-449b-8207-fa416434dd85') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8c362bc-d761-449b-8207-fa416434dd85');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '17ce4f08-8f8d-474d-a99d-1e0729e1adbd','Finite-difference method','A numerical technique that solves differential equations by replacing derivatives with difference quotients evaluated on a structured grid of points. In acoustics the finite-difference time-domain (FDTD) form marches the wave equation forward in time on a regular mesh and is widely used for room-acoustics and wave-propagation modelling.','This method puts a grid of points over the problem and approximates slopes using nearby point values. Step by step in time, it updates the sound field on the grid. It is simple to code for regular shapes. Room-acoustics simulations often use this approach.','It provides a straightforward, grid-based way to simulate wave propagation and sound fields, especially efficient on regular geometries.','A technician modelling a room with FDTD sets a grid fine enough to resolve the highest frequency and picks a time step within the Courant limit, then excites a source and records the impulse response at receiver points.','Numerical Methods',ARRAY['Finite-element analysis','Discontinuous Galerkin method','Courant condition','Coupled-field simulation','Energy finite-element analysis']::text[],ARRAY['Violating the Courant stability limit, causing the simulation to diverge','Using too coarse a grid, which produces numerical dispersion that detunes high frequencies','Handling curved or irregular boundaries poorly, since regular grids fit them awkwardly (staircasing)']::text[],ARRAY['FDTD room-acoustics impulse-response simulation','Physical-modelling sound synthesis','Wave-propagation and duct-acoustics modelling on grids']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite-difference method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '17ce4f08-8f8d-474d-a99d-1e0729e1adbd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='17ce4f08-8f8d-474d-a99d-1e0729e1adbd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='17ce4f08-8f8d-474d-a99d-1e0729e1adbd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c9d2c64-e529-4d70-9753-07bde546c667','Finite-element analysis','A numerical method that divides a domain into small elements, approximates the unknown field within each by shape functions, and assembles element equations into a global system solved for nodal values. In acoustics and vibration it solves the Helmholtz and structural-dynamics equations, and is most efficient at low-to-mid frequencies where elements resolve the wavelength.','This method chops a shape into many small pieces called elements. It approximates the answer inside each piece with simple functions. Then it links them and solves the whole system. It handles complex geometry well at lower frequencies.','It predicts vibration modes, acoustic fields, and structural response in geometrically complex parts, forming the backbone of engineering simulation.','A technician meshes a cabinet or cavity with several elements per wavelength (a common guide is at least six per wavelength), applies boundary conditions, and solves for eigenfrequencies, mode shapes, or the forced response.','Numerical Methods',ARRAY['Discontinuous Galerkin method','Finite-difference method','Coupled-field simulation','Energy finite-element analysis','Eigenfrequency']::text[],ARRAY['Meshing too coarsely for the frequency of interest, so short wavelengths are poorly resolved','Pushing standard FEA to high frequencies where mode counts explode and SEA or energy methods suit better','Neglecting fluid loading by solving a structure in vacuum when the surrounding fluid matters']::text[],ARRAY['Modal and forced-response analysis of structures','Interior acoustic-cavity and enclosure modelling','Low-to-mid frequency vibro-acoustic design']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite-element analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c9d2c64-e529-4d70-9753-07bde546c667','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c9d2c64-e529-4d70-9753-07bde546c667') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c9d2c64-e529-4d70-9753-07bde546c667');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cb5d6509-b2b6-43a5-83ce-32a542366aba','Flow resistivity','Flow resistivity (airflow resistivity, sigma) measures how strongly a porous material resists steady air passing through it, expressed per unit thickness. It equals the static pressure drop across a sample divided by the product of the linear airflow velocity and the sample thickness. ISO 9053-1 defines its static measurement; the SI unit is Pa*s/m^2.','Flow resistivity shows how hard it is to push slow air through a porous material. Tighter, denser materials resist more. It is quoted per unit thickness. Good sound absorbers sit in a middle range, not too open and not too dense.','It is a core input describing how absorbing foams and fibres dissipate sound energy inside their pores.','Measured per ISO 9053. Example: pressure drop 5 Pa, airflow velocity 0.01 m/s, thickness 0.05 m gives sigma = 5 / (0.01 x 0.05) = 10000 Pa*s/m^2.','Material acoustics',ARRAY['Johnson-Champoux-Allard model','Labyrinthine metamaterial','Loss factor','Gradient-index acoustic material']::text[],ARRAY['Confusing flow resistivity (per unit thickness, Pa*s/m^2) with total flow resistance (Pa*s/m)','Assuming higher resistivity is always better; too high reflects sound instead of absorbing it','Thinking it uses high-speed airflow, when ISO 9053 uses a low, steady flow']::text[],ARRAY['Specifying acoustic foam or mineral wool for a studio wall treatment','Feeding measured sigma into a porous-absorber prediction model','Comparing absorber batches for laboratory quality control']::text[],'advanced','sigma = dP / (v * d)','Flow resistivity equals the static pressure drop across the sample divided by the product of the linear airflow velocity and the sample thickness.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flow resistivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cb5d6509-b2b6-43a5-83ce-32a542366aba','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cb5d6509-b2b6-43a5-83ce-32a542366aba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cb5d6509-b2b6-43a5-83ce-32a542366aba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94d75969-b8b1-437e-816c-caabac973621','Flow separation noise','Flow separation noise is aerodynamic sound produced when a boundary layer detaches from a surface, forming unsteady turbulent eddies and pressure fluctuations that radiate as sound. It typically arises at sharp edges, bluff bodies, or diffusers where the flow can no longer follow the surface contour.','When fast air peels away from a surface, it makes swirling eddies. Those swirls create pressure changes we hear as noise. It often happens at sharp edges or sudden shape changes. Smoothing the shape can reduce it.','Naming this mechanism helps engineers locate and cut noise from ducts, vents, diffusers, and vehicle bodies.','A technician chamfers or streamlines a duct transition where separation is suspected, then rechecks the spectrum for a drop in broadband level.','Aeroacoustics',ARRAY['Flow-induced noise','Leading-edge noise','Jet noise','Mixing noise']::text[],ARRAY['Confusing it with jet noise, which comes from free turbulent mixing, not surface detachment','Assuming it is tonal; separation noise is usually broadband','Thinking faster flow always helps; higher speed usually raises separation noise']::text[],ARRAY['HVAC diffuser noise complaints','Wind noise around a vehicle mirror or A-pillar','Airflow noise in a wind-tunnel test section']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flow separation noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94d75969-b8b1-437e-816c-caabac973621','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94d75969-b8b1-437e-816c-caabac973621') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94d75969-b8b1-437e-816c-caabac973621');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7577efcb-8909-46ee-9ead-ed7bba324d09','Flow-induced noise','Flow-induced noise is any sound generated by unsteady fluid motion, including turbulence, vortex shedding, flow separation, and the interaction of flow with surfaces or resonators. It is the broad category covering both aeroacoustic and hydroacoustic sources.','Flow-induced noise is sound made by moving air or water. Turbulence, swirling vortices, and flow hitting edges all count. It is a broad family, not one single source. Engineers study it to make quieter fans, ducts, and vehicles.','The umbrella term groups the mechanisms engineers must control in fans, valves, ducts, vehicles, and pipes.','A technician tracing duct noise first decides whether the source is flow-induced (airflow) or structure-borne (fan vibration) before choosing a fix.','Aeroacoustics',ARRAY['Flow separation noise','Jet noise','Leading-edge noise','Lighthill analogy','Hydrodynamic pressure fluctuation']::text[],ARRAY['Assuming all fan noise is flow-induced; some is structure-borne vibration','Treating it as one mechanism rather than a whole category','Ignoring flow-surface interaction, which often dominates over free turbulence']::text[],ARRAY['Diagnosing HVAC system noise','Designing a quiet computer cooling fan','Assessing control-valve noise in a piping system']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flow-induced noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7577efcb-8909-46ee-9ead-ed7bba324d09','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7577efcb-8909-46ee-9ead-ed7bba324d09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7577efcb-8909-46ee-9ead-ed7bba324d09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e99e8aa4-4233-4dd8-a329-6a91eebfc77d','Fluid–structure interaction','Fluid-structure interaction (FSI) is the two-way coupling in which a fluid''s pressure loads a flexible structure, the structure deforms or vibrates, and that motion in turn alters the fluid flow and sound field. In acoustics it governs how panels, shells, and membranes radiate and respond in air or water.','Fluid-structure interaction is a two-way push between a fluid and a solid. The fluid pushes on the surface, and the surface moves. That movement then changes the fluid again. It matters for panels vibrating in air or hulls in water.','It explains coupled problems such as panel radiation, hull sonar signatures, and duct-wall interaction that single-domain models miss.','A technician modelling a submerged panel uses coupled FSI simulation because heavy water loading strongly lowers the panel''s resonance frequencies.','Vibro-acoustics',ARRAY['Mechanical impedance','Modal mass','Hydrodynamic pressure fluctuation','Hybrid acoustic simulation']::text[],ARRAY['Ignoring fluid loading; in water it can shift natural frequencies substantially','Assuming coupling is one-way, from fluid to structure only','Confusing FSI with simple added-mass, which is only its low-frequency limit']::text[],ARRAY['Underwater sonar dome design','Aircraft panel vibration and cabin noise','Large loudspeaker cabinet wall analysis']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fluid–structure interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e99e8aa4-4233-4dd8-a329-6a91eebfc77d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e99e8aa4-4233-4dd8-a329-6a91eebfc77d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e99e8aa4-4233-4dd8-a329-6a91eebfc77d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1aa599f-69a2-49de-aa16-dcba1de07425','Geometrical-acoustics simulation','Geometrical-acoustics simulation models sound propagation as rays or particles that travel in straight lines and reflect off surfaces, valid when wavelengths are small compared with room and object dimensions. Ray tracing and the image-source method are the main techniques for room and outdoor sound prediction.','This method treats sound like rays of light that bounce off walls. It works well at high frequencies with short wavelengths. It ignores wave effects such as diffraction. Engineers use it to predict room reverberation and echoes.','It gives fast, high-frequency predictions of reverberation, echoes, and coverage without solving the full wave equation.','An acoustician builds a room model, assigns surface absorption, and ray-traces to estimate reverberation time before construction.','Acoustic simulation',ARRAY['Image-source method','Hybrid acoustic simulation','Mesh convergence']::text[],ARRAY['Trusting it at low frequencies, where diffraction and room modes dominate','Forgetting it ignores wave interference and diffraction','Assuming more rays overcome the accuracy limits set by the geometric assumption']::text[],ARRAY['Predicting reverberation time in an auditorium design','Auralizing a concert hall','Outdoor sound propagation over terrain']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Geometrical-acoustics simulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1aa599f-69a2-49de-aa16-dcba1de07425','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1aa599f-69a2-49de-aa16-dcba1de07425') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1aa599f-69a2-49de-aa16-dcba1de07425');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b707425c-4d69-45b1-9949-ad3869c0518b','Gradient-index acoustic material','A gradient-index (GRIN) acoustic material has a spatially varying effective sound speed or refractive index, produced by grading a structure''s local geometry or density. The gradient bends sound along curved paths, enabling flat acoustic lenses, beam steering, and focusing.','A gradient-index material slowly changes how fast sound travels across it. This gradual change bends sound along curved paths. It lets a flat plate act like a lens. Engineers use it to focus or steer sound.','It provides refraction-based control of sound, allowing compact flat lenses and beam-steering without bulky curved shapes.','A technician arranges graded unit cells so sound converges at a target point, then checks the focal gain with a scanning microphone.','Acoustic metamaterials',ARRAY['Labyrinthine metamaterial','Locally resonant metamaterial','Geometrical-acoustics simulation']::text[],ARRAY['Confusing GRIN grading with a uniform metamaterial slab','Assuming the index gradient works at all frequencies; unit-cell size sets a limit','Expecting perfect focusing; losses and discretization blur the focus']::text[],ARRAY['Designing a flat acoustic lens for ultrasound','Steering a loudspeaker beam','Underwater sound-focusing research']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gradient-index acoustic material');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b707425c-4d69-45b1-9949-ad3869c0518b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b707425c-4d69-45b1-9949-ad3869c0518b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b707425c-4d69-45b1-9949-ad3869c0518b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4294651a-9a7f-4503-9584-21c4767e1b5d','Harmonic generation','Harmonic generation is a nonlinear effect in which a finite-amplitude sound wave progressively transfers energy from its fundamental frequency into integer multiples (harmonics) as it propagates. It occurs because the medium''s response is not perfectly linear, so the waveform distorts and steepens with distance.','A very loud pure tone does not stay pure as it travels. The medium distorts the wave and adds higher tones. These extra tones are whole-number multiples of the original. This is a nonlinear effect, strongest at high amplitude.','It explains waveform distortion, harmonic buildup, and eventual shock formation in high-amplitude and ultrasonic sound fields.','A technician driving a high-intensity ultrasound source measures second-harmonic growth to gauge the nonlinearity and beam distortion.','Nonlinear acoustics',ARRAY['Inertial cavitation','Minnaert resonance','Mach number','Jet noise']::text[],ARRAY['Assuming air is always linear; loud sound really does generate harmonics','UNSAFE: Assuming harmonics are harmless; in high-intensity ultrasound, harmonic steepening builds shocks that raise local heating and cavitation risk','Confusing medium harmonic generation with a loudspeaker''s electronic distortion']::text[],ARRAY['High-intensity ultrasound field characterization','Measuring the nonlinearity parameter B/A of a fluid','Parametric-array and sonar design']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic generation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4294651a-9a7f-4503-9584-21c4767e1b5d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4294651a-9a7f-4503-9584-21c4767e1b5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4294651a-9a7f-4503-9584-21c4767e1b5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '557e0a73-e2f8-4df0-8d3d-8916e0ea20ad','Helmholtz instability','The Helmholtz instability, more fully the Kelvin-Helmholtz instability, arises when two fluid layers move at different velocities across a shear interface, causing small perturbations to grow into rolling vortices. In aeroacoustics it seeds the turbulence and vortex structures of shear layers and jets that generate sound.','When two streams of fluid slide past each other, the boundary is unstable. Small ripples grow into rolling waves and vortices. This is the Kelvin-Helmholtz instability. It starts the turbulence in jets that makes noise.','It explains the origin of the shear-layer vortices that drive jet and mixing noise.','A technician studying jet noise treats the shear-layer instability as the source of the vortices whose merging radiates low-frequency sound.','Aeroacoustics',ARRAY['Jet noise','Mixing noise','Flow-induced noise','Lighthill analogy']::text[],ARRAY['Calling it a Helmholtz-resonator effect; it is a shear-flow instability, not a cavity resonance','Assuming it needs a density difference; a velocity difference alone suffices','Treating the growing vortices as pure noise rather than organized flow structures']::text[],ARRAY['Explaining jet-exhaust noise generation','Modelling mixing-layer growth','Cavity-tone onset over an open sunroof']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Helmholtz instability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '557e0a73-e2f8-4df0-8d3d-8916e0ea20ad','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='557e0a73-e2f8-4df0-8d3d-8916e0ea20ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='557e0a73-e2f8-4df0-8d3d-8916e0ea20ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa29f69f-d1df-4ed5-a6b5-98bea2de8867','Hybrid acoustic simulation','Hybrid acoustic simulation combines two or more modelling methods, typically wave-based methods at low frequencies and geometrical (ray or image-source) methods at high frequencies, to cover the full audible range efficiently. Each method is applied where it is most accurate and affordable.','Hybrid simulation mixes two methods in one model. Wave methods handle low frequencies well but cost a lot. Ray methods handle high frequencies cheaply. Combining them covers the whole range accurately.','It gives accurate broadband room predictions by using each technique inside its valid frequency range.','An acoustician runs a wave solver below a crossover frequency and ray tracing above it, then blends the results into one impulse response.','Acoustic simulation',ARRAY['Geometrical-acoustics simulation','Image-source method','Mesh convergence','Fluid-structure interaction']::text[],ARRAY['Setting the crossover frequency arbitrarily instead of near the Schroeder frequency','Assuming the two methods blend seamlessly without careful matching','Believing hybrid always beats a single method for every problem']::text[],ARRAY['Full-band auralization of a concert hall','Vehicle-cabin acoustic modelling','Combining finite-element and ray methods for one room']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hybrid acoustic simulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa29f69f-d1df-4ed5-a6b5-98bea2de8867','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa29f69f-d1df-4ed5-a6b5-98bea2de8867') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa29f69f-d1df-4ed5-a6b5-98bea2de8867');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1f5f1a8-c37b-4764-97cc-0a5b1e96929a','Hydrodynamic pressure fluctuation','Hydrodynamic pressure fluctuations are the near-field, non-propagating pressure variations carried by turbulent flow past a sensor or surface; they convect with the flow rather than radiating as sound. They dominate the pseudo-sound picked up by microphones and hydrophones in flow and must be separated from true acoustic pressure.','Moving turbulence carries its own pressure bumps along with it. These bumps ride with the flow and do not travel as sound. Microphones in wind can pick them up as pseudo-sound. Engineers must separate them from real sound.','The concept distinguishes convecting flow pressure (pseudo-sound) from radiating acoustic pressure in measurements.','A technician fits a windscreen or nose cone to a flow microphone to reject hydrodynamic pressure and keep the true acoustic signal.','Aeroacoustics',ARRAY['Flow-induced noise','Lighthill analogy','Fluid-structure interaction','Flow separation noise']::text[],ARRAY['Mistaking wind-induced pseudo-sound for genuine acoustic noise','Assuming a bare microphone in flow reads only sound','Thinking these fluctuations radiate efficiently to the far field; mostly they do not']::text[],ARRAY['Outdoor sound measurement in wind','Wind-tunnel microphone measurements','Hydrophone turbulence rejection near a moving hull']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydrodynamic pressure fluctuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1f5f1a8-c37b-4764-97cc-0a5b1e96929a','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1f5f1a8-c37b-4764-97cc-0a5b1e96929a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1f5f1a8-c37b-4764-97cc-0a5b1e96929a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4edab9eb-a09b-4499-8ea7-8de3933af30d','Image-source method','The image-source method predicts specular reflections by replacing each reflecting surface with a mirror-image copy of the source placed symmetrically behind it. Summing the direct source and its images reproduces the geometrical reflection pattern, giving arrival times and levels for room impulse responses.','The image-source method treats each wall like a mirror. It places a copy of the source behind the wall. The mirrored copies stand in for reflections. Adding them up predicts the echoes in a room.','It gives exact specular reflection paths for simple room shapes, used in room modelling and auralization.','For a rectangular room, a technician mirrors the source across each wall to compute early-reflection times feeding an impulse response.','Acoustic simulation',ARRAY['Geometrical-acoustics simulation','Hybrid acoustic simulation','Mesh convergence']::text[],ARRAY['Applying it to complex geometries, where the image count explodes and many images are invalid','Forgetting to test each image for visibility before including it','Assuming it captures diffraction and scattering; it gives only specular reflections']::text[],ARRAY['Computing early reflections in a shoebox room','Validating a ray tracer','Small-room studio reflection analysis']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Image-source method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4edab9eb-a09b-4499-8ea7-8de3933af30d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4edab9eb-a09b-4499-8ea7-8de3933af30d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4edab9eb-a09b-4499-8ea7-8de3933af30d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf2a9ad1-e8e1-428a-979d-2425e77319ef','Inertance','Acoustic inertance (acoustic mass) is the property of a fluid element in a duct or opening that opposes changes in volume velocity, defined as the ratio of sound pressure to the resulting in-phase volume acceleration. For a short open passage it equals the fluid density times the effective length divided by the cross-sectional area.','Inertance is the acoustic version of mass. It is the air in a neck resisting changes in flow. A longer, narrower neck has more inertance. It pairs with springiness to set resonance, as in a Helmholtz resonator.','It models the mass-like reactance of ducts and openings in lumped-element acoustic circuits and resonators.','For a port of area 0.001 m^2 and effective length 0.05 m in air (rho = 1.21 kg/m^3): M_a = 1.21 x 0.05 / 0.001 = 60.5 kg/m^4.','Vibro-acoustics',ARRAY['Mechanical impedance','Minnaert resonance','Mechanical mobility','Loss factor']::text[],ARRAY['Forgetting end corrections, which increase the effective length of a short neck','Confusing acoustic inertance (kg/m^4) with mechanical mass (kg)','Ignoring it at low frequencies, where it dominates a port''s impedance']::text[],ARRAY['Tuning a bass-reflex loudspeaker port','Designing a Helmholtz absorber','Modelling a muffler element']::text[],'advanced','M_a = rho * l_eff / S','Acoustic inertance equals fluid density times the effective length of the passage divided by its cross-sectional area.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inertance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf2a9ad1-e8e1-428a-979d-2425e77319ef','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf2a9ad1-e8e1-428a-979d-2425e77319ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf2a9ad1-e8e1-428a-979d-2425e77319ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c451e26-83bf-406c-b387-e455cfc93c4f','Inertial cavitation','Inertial (transient) cavitation is the violent growth and rapid collapse of gas or vapour bubbles driven by a high-amplitude sound field, in which the surrounding liquid''s inertia implodes the bubble. The collapse concentrates energy into extreme local temperatures, pressures, shock waves, and sometimes light emission (sonoluminescence).','A strong sound field in liquid can grow tiny bubbles then crush them. The liquid rushes in and the bubble implodes violently. This releases intense heat, pressure, and shock waves in a tiny spot. It can damage nearby surfaces and living tissue.','The concept explains the erosive, chemical, and biological effects of high-intensity ultrasound and underwater sound.','A technician keeps ultrasound below the inertial-cavitation threshold when cleaning delicate parts to avoid pitting the surface.','Nonlinear acoustics',ARRAY['Minnaert resonance','Harmonic generation','Hydrodynamic pressure fluctuation']::text[],ARRAY['Confusing it with stable (non-inertial) cavitation, where bubbles oscillate without collapsing','UNSAFE: Assuming high-intensity ultrasound in liquid is harmless; collapse can erode metal and injure tissue','UNSAFE: Ignoring the mechanical index in diagnostic ultrasound, which bounds cavitation risk to patients','Believing cavitation needs boiling heat; sound-driven cavitation occurs at room temperature']::text[],ARRAY['Ultrasonic cleaning bath damaging or pitting parts','Diagnostic ultrasound safety limits and mechanical index','Sonochemistry reactor design']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inertial cavitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c451e26-83bf-406c-b387-e455cfc93c4f','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c451e26-83bf-406c-b387-e455cfc93c4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c451e26-83bf-406c-b387-e455cfc93c4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6c407fa-8a99-4fa9-8c0f-152e6fda5f8c','Jet noise','Jet noise is the broadband aerodynamic sound radiated by the turbulent mixing of a high-speed jet with the surrounding fluid. For subsonic jets, Lighthill''s acoustic analogy predicts that radiated acoustic power scales roughly with the eighth power of the jet exit velocity.','A fast jet of air mixes with still air and makes turbulence. That turbulence radiates strong broadband noise. Lighthill showed the power rises steeply with jet speed. Doubling the speed can raise power more than two hundredfold.','It explains why exhaust and engine jets are so loud and why even small speed reductions help greatly.','Using P proportional to U^8, halving the jet velocity cuts radiated power by 2^8 = 256, about 24 dB, which guides nozzle design.','Aeroacoustics',ARRAY['Lighthill analogy','Lighthill stress tensor','Mixing noise','Mach number','Helmholtz instability']::text[],ARRAY['Applying the eighth-power law to supersonic jets, where shock-associated noise adds','Assuming it is tonal; subsonic jet noise is broadband','Forgetting the strong velocity dependence when comparing quiet-nozzle designs']::text[],ARRAY['Aircraft engine-exhaust noise','High-pressure air blow-off silencing','Rocket-launch acoustic loads']::text[],'advanced','P ~ rho0 * U^8 * D^2 / c0^5','The radiated acoustic power of a subsonic jet is proportional to ambient fluid density times jet velocity to the eighth power times a characteristic area, divided by the fifth power of the speed of sound.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Jet noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6c407fa-8a99-4fa9-8c0f-152e6fda5f8c','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6c407fa-8a99-4fa9-8c0f-152e6fda5f8c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6c407fa-8a99-4fa9-8c0f-152e6fda5f8c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b36607c5-3802-45ab-8e52-1e2ee6f4e756','Johnson–Champoux–Allard model','The Johnson-Champoux-Allard (JCA) model is a semi-phenomenological equivalent-fluid model that predicts the frequency-dependent effective density and effective bulk modulus of a rigid-frame porous material. It uses five macroscopic parameters: open porosity, static airflow resistivity, high-frequency tortuosity, and the viscous and thermal characteristic lengths.','The JCA model predicts how a porous absorber behaves across frequency. It treats the material as an equivalent fluid. It needs five measurable properties of the material. Engineers use it to predict sound absorption of foams and fibres.','It lets engineers predict the absorption and surface impedance of porous absorbers from measurable physical parameters.','A technician measures the five parameters, feeds them to the JCA model, and predicts the absorption curve before building a treatment.','Material acoustics',ARRAY['Flow resistivity','Loss factor','Labyrinthine metamaterial','Gradient-index acoustic material']::text[],ARRAY['Counting it as six parameters; porosity is shared, so JCA needs five macroscopic parameters','Confusing it with the later JCAL model, which adds a static thermal permeability','Assuming it models the solid frame; JCA assumes a motionless (rigid) skeleton']::text[],ARRAY['Predicting foam absorption for a studio','Characterizing mineral wool in an impedance tube','Feeding a room model with measured absorber data']::text[],'advanced','{phi, sigma, alpha_inf, Lambda, Lambda_prime} -> rho_eff(w), K_eff(w)','From five macroscopic parameters (porosity, airflow resistivity, high-frequency tortuosity, viscous characteristic length, thermal characteristic length), the model computes the frequency-dependent effective dynamic density and effective dynamic bulk modulus of the equivalent fluid.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Johnson–Champoux–Allard model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b36607c5-3802-45ab-8e52-1e2ee6f4e756','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b36607c5-3802-45ab-8e52-1e2ee6f4e756') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b36607c5-3802-45ab-8e52-1e2ee6f4e756');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ed71d787-c9eb-470d-863c-a92c96834835','Labyrinthine metamaterial','A labyrinthine (space-coiling) acoustic metamaterial folds narrow channels into a maze-like path so that sound travels a long effective distance within a small unit cell. This raises the effective refractive index and slows the wave, enabling thin, deeply sub-wavelength control such as high-index lenses and compact absorbers.','A labyrinthine metamaterial coils sound through a maze of narrow channels. The long twisty path makes sound act as if it moves slower. This packs strong effects into a thin panel. Engineers use it for compact lenses and absorbers.','It achieves a very high effective index in a compact cell for thin lenses, cloaks, and absorbers.','A technician stacks coiled unit cells to build a thin panel that bends or delays sound far more than its physical thickness suggests.','Acoustic metamaterials',ARRAY['Gradient-index acoustic material','Locally resonant metamaterial','Johnson-Champoux-Allard model']::text[],ARRAY['Assuming the high effective index holds at all frequencies; unit-cell size limits it','Ignoring viscous losses inside the narrow coiled channels','Confusing space-coiling with locally resonant designs; the mechanisms differ']::text[],ARRAY['Designing a thin flat sound lens','Building a compact low-frequency absorber','Laboratory metamaterial research']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Labyrinthine metamaterial');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ed71d787-c9eb-470d-863c-a92c96834835','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ed71d787-c9eb-470d-863c-a92c96834835') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ed71d787-c9eb-470d-863c-a92c96834835');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74c59abc-69bc-499c-8924-22d0981d6400','Leading-edge noise','Leading-edge noise is the broadband sound produced when incoming turbulence strikes the front edge of a body such as an aerofoil or fan blade, causing unsteady surface pressures that radiate efficiently. It is distinct from trailing-edge noise, which arises from the boundary-layer turbulence leaving the rear edge.','Leading-edge noise happens when turbulent air hits the front of a blade or wing. The impacts make unsteady pressures that radiate sound. It differs from trailing-edge noise at the back. It matters for fans and wind turbines in turbulent air.','Naming this source helps engineers cut fan, turbine, and rotor noise caused by incoming turbulence.','A technician adds a serrated or wavy leading edge to a fan blade to break up turbulence interaction and lower the radiated noise.','Aeroacoustics',ARRAY['Flow-induced noise','Flow separation noise','Jet noise','Helmholtz instability']::text[],ARRAY['Confusing it with trailing-edge noise, a different mechanism at the rear edge','Assuming smooth inflow; real inflow turbulence drives this source','Thinking it is tonal; it is usually broadband']::text[],ARRAY['Wind-turbine blade noise in turbulent wind','Cooling-fan noise behind a grille','Rotor-stator interaction in a duct']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Leading-edge noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74c59abc-69bc-499c-8924-22d0981d6400','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74c59abc-69bc-499c-8924-22d0981d6400') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74c59abc-69bc-499c-8924-22d0981d6400');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '96649950-fcd1-4fd2-bbe9-cbccd513b533','Lighthill analogy','Lighthill''s acoustic analogy recasts the exact equations of fluid motion into an inhomogeneous wave equation whose source term is a quadrupole distribution, so that turbulence in a small region is treated as an equivalent acoustic source radiating into an ideal, uniform medium at rest. It is the foundation of modern aeroacoustics.','Lighthill rewrote the flow equations to look like a wave equation with a source. The messy turbulence becomes an equivalent sound source. That source radiates into calm, uniform air. This idea launched modern aeroacoustics.','It lets engineers predict sound from turbulent flow without directly solving the full nonlinear flow-acoustic problem.','A technician computes the turbulent flow, forms Lighthill''s source term, and integrates it to estimate the radiated jet noise.','Aeroacoustics',ARRAY['Lighthill stress tensor','Jet noise','Mixing noise','Flow-induced noise']::text[],ARRAY['Thinking the rearrangement is approximate; it is exact, and approximations enter only in modelling the source','Treating the source as a real added force rather than an equivalent representation','Ignoring that solid boundaries need extensions like the Ffowcs Williams-Hawkings equation']::text[],ARRAY['Predicting jet-exhaust noise','Computational aeroacoustics of fans','Benchmarking turbulence-noise models']::text[],'advanced','d^2(rho'')/dt^2 - c0^2 * laplacian(rho'') = d^2(T_ij)/dx_i dx_j','The second time derivative of the density fluctuation minus the sound speed squared times its Laplacian equals the double spatial divergence of the Lighthill stress tensor.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lighthill analogy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '96649950-fcd1-4fd2-bbe9-cbccd513b533','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='96649950-fcd1-4fd2-bbe9-cbccd513b533') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='96649950-fcd1-4fd2-bbe9-cbccd513b533');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0250389e-74cc-48eb-bfeb-1ce191c02ad7','Lighthill stress tensor','The Lighthill stress tensor is the source term of Lighthill''s acoustic analogy, representing the difference between the real turbulent flow and an ideal linear acoustic medium. It combines the Reynolds stress, the excess of pressure over its linear acoustic value, and the viscous stress.','The Lighthill stress tensor is the sound-source term in Lighthill''s equation. It measures how the real flow differs from calm air. It includes turbulence momentum, extra pressure, and viscous effects. In jets the turbulence part dominates.','It packages all aeroacoustic source effects into one term that drives the wave equation.','A technician often evaluates T_ij approximately as rho*u_i*u_j from a flow simulation because the Reynolds-stress term dominates for high-speed jets.','Aeroacoustics',ARRAY['Lighthill analogy','Jet noise','Mixing noise','Flow-induced noise']::text[],ARRAY['Dropping the Reynolds-stress term rho*u_i*u_j, which usually dominates jet noise','Confusing it with an ordinary mechanical stress tensor','Ignoring the pressure-density and viscous terms even when they matter near solid surfaces']::text[],ARRAY['Computing jet-noise sources from CFD','Teaching aeroacoustic theory','Developing acoustic-analogy solvers']::text[],'advanced','T_ij = rho*u_i*u_j + (p'' - c0^2*rho'')*delta_ij - tau_ij','The Lighthill stress tensor equals density times the product of velocity components, plus the excess of pressure over sound-speed-squared times density fluctuation on the diagonal, minus the viscous stress tensor.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lighthill stress tensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0250389e-74cc-48eb-bfeb-1ce191c02ad7','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0250389e-74cc-48eb-bfeb-1ce191c02ad7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0250389e-74cc-48eb-bfeb-1ce191c02ad7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5a52f84-980d-4337-99d6-41b9adad4667','Locally resonant metamaterial','A locally resonant acoustic metamaterial contains sub-wavelength resonators (such as mass-spring or membrane units) that vibrate strongly near their resonance, producing effective properties including negative effective mass density or modulus within narrow band gaps. This lets thin structures block low-frequency sound far below the limit set by mass alone.','This metamaterial hides tiny resonators inside a thin panel. Near their resonance they push back hard on the sound. That creates a band where sound cannot pass. It blocks low frequencies without needing heavy mass.','It provides deep sub-wavelength band gaps to stop low-frequency sound and vibration that ordinary mass barriers cannot.','A technician tunes membrane-mass cells to a target low frequency, blocking it with a thin light panel instead of a heavy wall.','Acoustic metamaterials',ARRAY['Labyrinthine metamaterial','Gradient-index acoustic material','Modal mass','Loss factor']::text[],ARRAY['Expecting broadband blocking; local resonance gives only narrow band gaps','Confusing it with Bragg/phononic band gaps set by periodicity, not resonance','Ignoring damping, which broadens but weakens the resonant dip']::text[],ARRAY['Thin low-frequency sound barrier','Vibration-isolation panel','Laboratory negative-effective-mass demonstration']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Locally resonant metamaterial');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5a52f84-980d-4337-99d6-41b9adad4667','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5a52f84-980d-4337-99d6-41b9adad4667') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5a52f84-980d-4337-99d6-41b9adad4667');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0be5983-9c5b-4b7d-b5d9-6db262471079','Loss factor','The damping loss factor (eta) is a dimensionless measure of internal energy dissipation in a material or structure, equal to the fraction of stored vibrational energy dissipated per radian of oscillation. For light damping it relates to other measures by eta = 1/Q = 2*zeta = tan(delta).','The loss factor shows how quickly a vibrating material loses energy to heat. A higher value means faster damping. It is a plain number with no units. Engineers use it to compare damping treatments.','It quantifies damping so engineers can predict decay rates, resonance sharpness, and structure-borne sound.','If a panel has quality factor Q = 50, its loss factor is eta = 1/Q = 0.02, indicating light damping and a sharp resonance.','Vibro-acoustics',ARRAY['Modal damping','Mechanical impedance','Modal mass','Locally resonant metamaterial']::text[],ARRAY['Confusing loss factor eta with damping ratio zeta; eta = 2*zeta for light damping','Assuming the simple relations hold at heavy damping; they are small-damping approximations','Forgetting it is frequency-dependent for real viscoelastic materials']::text[],ARRAY['Rating constrained-layer damping treatments','Predicting panel resonance decay','Providing inputs for statistical energy analysis (SEA)']::text[],'intermediate','eta = 1/Q = 2*zeta = D / (2*pi*U)','The loss factor equals the reciprocal of the quality factor, equals twice the damping ratio, and equals the energy dissipated per cycle divided by two pi times the peak stored energy.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loss factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0be5983-9c5b-4b7d-b5d9-6db262471079','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0be5983-9c5b-4b7d-b5d9-6db262471079') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0be5983-9c5b-4b7d-b5d9-6db262471079');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8233c430-b64f-4a64-b7c0-5bb8dcf28ba2','Mach number','The Mach number (M) is the dimensionless ratio of a flow or object speed to the local speed of sound in the surrounding medium. It classifies flow regimes as subsonic (M<1), transonic (near 1), and supersonic (M>1), and governs compressibility and shock formation.','The Mach number compares speed to the speed of sound. A value below one is slower than sound. A value above one is faster, and shock waves form. It is just a ratio, with no units.','It tells engineers whether compressibility, shocks, and supersonic noise mechanisms are important.','An object at 170 m/s in air (c ~ 340 m/s) has M = 170 / 340 = 0.5, firmly subsonic, so no shock noise is expected.','Aeroacoustics',ARRAY['Jet noise','Lighthill analogy','Mixing noise','Helmholtz instability']::text[],ARRAY['Using a fixed sound speed; c changes with temperature and medium','Assuming shocks form at any speed; they require M >= 1','Confusing Mach number with velocity; it is a dimensionless ratio']::text[],ARRAY['Classifying a jet as subsonic or supersonic','Predicting shock-associated noise','Selecting a wind-tunnel test regime']::text[],'beginner','M = U / c','The Mach number equals the flow or object speed divided by the local speed of sound in the medium.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mach number');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8233c430-b64f-4a64-b7c0-5bb8dcf28ba2','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8233c430-b64f-4a64-b7c0-5bb8dcf28ba2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8233c430-b64f-4a64-b7c0-5bb8dcf28ba2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '154b1111-fb62-4e00-a8e4-dc152ff5c7bd','Mechanical admittance','Mechanical admittance is the complex frequency-domain ratio of a structure''s velocity response to the applied force, the reciprocal of mechanical impedance. It is identical to mechanical mobility and describes how readily a point on a structure moves when force is applied.','Mechanical admittance shows how easily a structure moves when pushed. It is velocity divided by force. It is the opposite of mechanical impedance. A high value means the point moves easily.','It quantifies how readily a structure responds to force, used in vibration and structure-borne sound analysis.','If a shaker applies 10 N and a point moves at 0.05 m/s, its mechanical admittance is 0.05 / 10 = 0.005 (m/s)/N.','Vibro-acoustics',ARRAY['Mechanical impedance','Mechanical mobility','Modal mass','Loss factor']::text[],ARRAY['Confusing admittance (velocity/force) with compliance (displacement/force)','Forgetting it is complex and frequency-dependent, not a single number','Treating it as identical to electrical admittance without care over the analogy']::text[],ARRAY['Interpreting frequency-response measurements of a panel','Matching a shaker to a structure','Modal-test data analysis']::text[],'intermediate','Y = v / F = 1 / Z_m','Mechanical admittance equals the velocity response divided by the applied force, which is the reciprocal of mechanical impedance.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical admittance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '154b1111-fb62-4e00-a8e4-dc152ff5c7bd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='154b1111-fb62-4e00-a8e4-dc152ff5c7bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='154b1111-fb62-4e00-a8e4-dc152ff5c7bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6c708466-af65-4c04-8e19-cee0a61c951d','Mechanical impedance','Mechanical impedance is the complex frequency-domain ratio of an applied force to the resulting velocity at the point of application. A large magnitude means the structure resists motion strongly; it is the reciprocal of mechanical mobility.','Mechanical impedance shows how hard it is to make a structure move. It is force divided by the resulting velocity. A high value means the point barely moves. It is the opposite of mobility.','It characterizes how a structure resists vibration and how force couples into structure-borne sound.','If 20 N produces 0.1 m/s at a point, its mechanical impedance magnitude is 20 / 0.1 = 200 N*s/m.','Vibro-acoustics',ARRAY['Mechanical admittance','Mechanical mobility','Modal mass','Inertance']::text[],ARRAY['Confusing mechanical impedance with acoustic impedance; different quantities and units','Using force over displacement; impedance uses force over velocity','Ignoring its complex, frequency-dependent nature']::text[],ARRAY['Vibration-isolation design','Drive-point measurements on machinery','Matching source and receiver structures']::text[],'intermediate','Z_m = F / v','Mechanical impedance equals the applied force divided by the resulting velocity at the same point.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6c708466-af65-4c04-8e19-cee0a61c951d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6c708466-af65-4c04-8e19-cee0a61c951d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6c708466-af65-4c04-8e19-cee0a61c951d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c8b45db-e6f6-4559-aaf4-322e84ac5d58','Mechanical mobility','Mechanical mobility is the complex frequency-domain ratio of velocity to applied force at a point on a structure, the reciprocal of mechanical impedance. It is synonymous with mechanical admittance and is the standard quantity reported in structural vibration measurements.','Mobility shows how easily a structure moves when a force is applied. It is velocity divided by force. It is the same as mechanical admittance. Engineers measure it to study vibration.','It is the standard measured quantity describing a structure''s velocity response per unit force.','A drive-point mobility of 0.004 (m/s)/N means 5 N of force produces 0.02 m/s of velocity at that point.','Vibro-acoustics',ARRAY['Mechanical admittance','Mechanical impedance','Modal mass','Loss factor']::text[],ARRAY['Thinking mobility and admittance differ; in mechanics they are the same quantity','Confusing drive-point mobility with transfer mobility (different points)','Forgetting it is complex and frequency-dependent']::text[],ARRAY['Structural mobility measurement','Predicting power flow between connected structures','Instrument-body vibration studies']::text[],'intermediate','M = v / F = 1 / Z_m','Mechanical mobility equals velocity divided by the applied force, the reciprocal of mechanical impedance.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical mobility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c8b45db-e6f6-4559-aaf4-322e84ac5d58','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c8b45db-e6f6-4559-aaf4-322e84ac5d58') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c8b45db-e6f6-4559-aaf4-322e84ac5d58');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d8b9de0-af65-407a-8f4c-457e0d92c68c','Mesh convergence','Mesh convergence is the process of refining the spatial discretization of a numerical acoustic or vibration model until the computed results stop changing significantly, confirming the mesh resolves the physics. In acoustics it typically requires several elements per wavelength at the highest frequency of interest.','In simulations, space is broken into a mesh of small cells. If the mesh is too coarse, results are wrong. Engineers refine it and re-run until answers stop changing. That stable point shows the mesh is fine enough.','It verifies that a simulation''s discretization error is small enough for the results to be trusted.','A technician halves the element size and re-runs; when a resonance frequency shifts by less than a set tolerance, the mesh is deemed converged.','Acoustic simulation',ARRAY['Hybrid acoustic simulation','Geometrical-acoustics simulation','Image-source method','Fluid-structure interaction']::text[],ARRAY['Using too few elements per wavelength, causing numerical dispersion errors','Assuming a fine mesh alone guarantees accuracy; boundary conditions also matter','Stopping refinement before the results actually stabilize']::text[],ARRAY['Finite-element room-mode analysis','Loudspeaker radiation simulation','Validating a vibro-acoustic model']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mesh convergence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d8b9de0-af65-407a-8f4c-457e0d92c68c','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d8b9de0-af65-407a-8f4c-457e0d92c68c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d8b9de0-af65-407a-8f4c-457e0d92c68c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29ac825d-dac8-433f-a031-901402cde668','Minnaert resonance','Minnaert resonance is the natural volumetric (''breathing'') oscillation of a gas bubble in a liquid, in which the gas acts as the spring and the surrounding liquid as the mass. Its frequency, given by the Minnaert formula, falls as bubble radius increases and explains the ringing tone of bubbly water.','A bubble in water can pulse in and out like a tiny balloon. The gas acts as a spring and the water as the mass. This sets a natural pitch. Bigger bubbles ring at lower pitches, giving the babble of a brook.','It predicts the resonant frequency and acoustic activity of bubbles, central to cavitation, bubbly media, and underwater sound.','For an air bubble of radius 1 mm in water (gamma=1.4, p0=101.3 kPa, rho=1000 kg/m^3): f0 = (1/(2*pi*0.001)) * sqrt(3*1.4*101325/1000) ~ 3.3 kHz.','Nonlinear acoustics',ARRAY['Inertial cavitation','Harmonic generation','Inertance']::text[],ARRAY['Using the gas density instead of the liquid density for rho','Forgetting surface tension, which matters for very small bubbles','Assuming isothermal behaviour; the standard form uses the adiabatic/polytropic exponent']::text[],ARRAY['Explaining the sound of running water','Sizing bubbles from their acoustic emission','Cavitation and sonoluminescence studies']::text[],'advanced','f0 = (1 / (2*pi*R)) * sqrt(3*gamma*p0 / rho)','The Minnaert resonance frequency equals one over two pi times the bubble radius, times the square root of three times the gas polytropic exponent times ambient pressure divided by the liquid density.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Minnaert resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29ac825d-dac8-433f-a031-901402cde668','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29ac825d-dac8-433f-a031-901402cde668') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29ac825d-dac8-433f-a031-901402cde668');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '80a6a62e-b555-4bda-9633-1efb2223d227','Mixing noise','Mixing noise is the broadband component of jet noise generated by the turbulent mixing of the jet with the surrounding fluid, as distinct from shock-associated (broadband shock) or screech components. It is the dominant source for subsonic and moderately supersonic jets.','Mixing noise is the roar from a jet blending with still air. Turbulent eddies of many sizes make broadband sound. It is separate from shock-related jet tones. It dominates for subsonic jets.','The term separates turbulence-mixing sound from shock-related components in jet-noise analysis.','A technician analysing engine noise attributes the smooth broadband hump to mixing noise and any sharp tones to shock or screech.','Aeroacoustics',ARRAY['Jet noise','Lighthill analogy','Lighthill stress tensor','Helmholtz instability','Mach number']::text[],ARRAY['Confusing mixing noise with shock-associated noise, a different mechanism','Assuming it is tonal; it is broadband','Applying subsonic scaling to strongly supersonic jets, where shock noise is added']::text[],ARRAY['Aircraft jet-noise breakdown by source','Nozzle design to reduce mixing noise','Distinguishing components in an exhaust spectrum']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mixing noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '80a6a62e-b555-4bda-9633-1efb2223d227','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='80a6a62e-b555-4bda-9633-1efb2223d227') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='80a6a62e-b555-4bda-9633-1efb2223d227');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95085d0e-73aa-4623-91eb-b2cbda4790ff','Modal damping','Modal damping is the damping associated with an individual vibration mode, expressed as a modal damping ratio (zeta_n) or a modal loss factor, describing how quickly that mode''s free response decays. It lets multi-degree-of-freedom systems be analysed one mode at a time.','Each vibration mode of a structure fades at its own rate. Modal damping measures that fade for one mode. A higher value means the mode dies out faster. It lets engineers treat each mode separately.','It reduces a complex structural response to a set of independent single-mode oscillators, each with its own damping.','A modal test finds a mode with damping ratio zeta = 0.01; its half-power bandwidth is about 2*zeta*f_n, so a 100 Hz mode is roughly 2 Hz wide.','Vibro-acoustics',ARRAY['Modal mass','Loss factor','Mechanical impedance','Mechanical admittance']::text[],ARRAY['Assuming all modes share one damping value; each mode can differ','Confusing damping ratio zeta with loss factor eta; eta = 2*zeta','Neglecting that heavy damping couples modes, breaking modal separation']::text[],ARRAY['Modal testing of a panel','Tuning a damping treatment per mode','Building a reduced-order vibration model']::text[],'advanced','zeta_n = c_n / (2*sqrt(k_n*m_n)) = eta_n / 2','The modal damping ratio equals the modal damping coefficient divided by twice the square root of modal stiffness times modal mass, and equals half the modal loss factor.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal damping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95085d0e-73aa-4623-91eb-b2cbda4790ff','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95085d0e-73aa-4623-91eb-b2cbda4790ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95085d0e-73aa-4623-91eb-b2cbda4790ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4a24f578-d008-460d-a5be-f0b6f03015d3','Modal mass','Modal mass (generalized mass) is the effective mass of a structure as it participates in a particular vibration mode, obtained by weighting the physical mass distribution with the squared mode shape. Together with modal stiffness it sets the natural frequency of that mode.','Modal mass is the effective mass that a single vibration mode feels. It depends on the mode''s shape, not just total weight. With modal stiffness it fixes the mode''s natural frequency. Its value also depends on how the mode shape is scaled.','It lets each mode be modelled as a simple mass-spring oscillator with a defined natural frequency.','For a mode with modal stiffness k_n and modal mass m_n, the natural frequency is f_n = (1/(2*pi)) * sqrt(k_n / m_n).','Vibro-acoustics',ARRAY['Modal damping','Mechanical impedance','Mechanical mobility','Loss factor']::text[],ARRAY['Treating modal mass as the total physical mass; it is mode-shape weighted','Forgetting it depends on mode-shape normalization; mass-normalized modes give modal mass 1','Confusing modal mass with the effective/participating mass used in base excitation']::text[],ARRAY['Building a modal model of a structure','Computing natural frequencies from finite-element results','Tuned-mass-damper design']::text[],'advanced','m_n = integral( phi_n(x)^2 * rho(x) ) dV ,  omega_n = sqrt(k_n / m_n)','The modal mass of a mode equals the volume integral of its mode shape squared times the local mass density; the modal natural angular frequency is the square root of modal stiffness divided by modal mass.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal mass');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4a24f578-d008-460d-a5be-f0b6f03015d3','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4a24f578-d008-460d-a5be-f0b6f03015d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4a24f578-d008-460d-a5be-f0b6f03015d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2325b524-6fcf-46ba-8a76-f260531edecc','Modal overlap','Modal overlap is the ratio of a resonance''s average half-power bandwidth to the average frequency spacing between adjacent modes. When this ratio exceeds one, individual resonances merge into a smooth response, marking the transition from modal to statistical (diffuse-field) behaviour.','Modes are the natural resonances of a room or a panel. Each resonance has some width. As frequency rises, resonances crowd together and start to overlap. When they blur into one smooth response, the modal overlap is high.','It tells an analyst whether a structure or space behaves as separate resonances or as a statistical, diffuse system at a given frequency.','With modal density n(f) and loss factor eta, modal bandwidth is f*eta. At f=1000 Hz, eta=0.05, bandwidth = 50 Hz; if modes sit 25 Hz apart (n=0.04/Hz), M = 0.04 x 50 = 2, so modes overlap.','Structural Acoustics',ARRAY['Normal mode','Modal stiffness','Model-order reduction','Operational deflection shape']::text[],ARRAY['Confusing modal overlap with modal density; density counts modes, overlap compares their width to their spacing.','Assuming high overlap means more modes rather than wider, merging resonances.','Treating a room as diffuse below its Schroeder frequency, where overlap is still below one.']::text[],ARRAY['Deciding the frequency above which a room can be treated statistically for reverberation.','Choosing between finite-element and statistical energy analysis for a panel.','Explaining why low-frequency room response shows isolated peaks but high frequencies smooth out.']::text[],'advanced','M = n(f) * (f * eta)','Modal overlap equals the modal density times the average half-power bandwidth of one mode.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal overlap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2325b524-6fcf-46ba-8a76-f260531edecc','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2325b524-6fcf-46ba-8a76-f260531edecc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2325b524-6fcf-46ba-8a76-f260531edecc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '29cfc27f-dd94-4710-a266-eda4ad082fe9','Modal participation factor','The modal participation factor is the mass-weighted projection of an applied load direction onto a given mode shape, normalised by that mode''s modal mass. It quantifies how strongly a particular excitation drives each individual mode of a multi-degree-of-freedom system.','A structure vibrates as a mix of its modes. Some modes respond strongly to a given push, others barely move. The participation factor scores how much each mode joins in. Engineers use it to find the modes that matter for a load.','It ranks which modes dominate the response to a specific excitation, so analysts can keep the important modes and ignore the rest.','For a mode where the mass-weighted load projection is 2.0 kg and the modal mass is 4.0 kg, the participation factor is 2.0 / 4.0 = 0.5. A near-zero value means the load hardly excites that mode.','Structural Dynamics',ARRAY['Normal mode','Modal stiffness','Model-order reduction','Operational deflection shape']::text[],ARRAY['Confusing participation factor with effective modal mass; the latter is its square times modal mass.','Assuming a high-frequency mode cannot participate, when the load direction, not frequency, sets participation.','Forgetting that participation depends on the excitation direction, not on the mode alone.']::text[],ARRAY['Selecting dominant modes for an earthquake or base-shake response analysis.','Deciding how many modes to retain in a truncated modal model.','Diagnosing which structural mode a rotating machine excites.']::text[],'advanced','Gamma_n = (phi_n^T * M * r) / (phi_n^T * M * phi_n)','The participation factor is the mass-weighted projection of the load direction onto a mode, divided by that mode''s modal mass.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal participation factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '29cfc27f-dd94-4710-a266-eda4ad082fe9','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='29cfc27f-dd94-4710-a266-eda4ad082fe9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='29cfc27f-dd94-4710-a266-eda4ad082fe9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fad25fb2-e106-43e1-8521-9a01b91604ba','Modal stiffness','Modal (generalised) stiffness is the effective stiffness of a single mode in modal coordinates, equal to the modal mass multiplied by the square of the mode''s natural angular frequency. It appears on the diagonal of the stiffness matrix after transformation to the mode-shape basis.','When a structure is described mode by mode, each mode acts like a simple spring-mass system. The modal stiffness is that mode''s spring value. It ties the mode''s mass to how fast it naturally vibrates. Stiffer modes resonate at higher frequencies.','It lets a complex structure be analysed as a set of independent single-degree-of-freedom oscillators, one per mode.','For a mode with modal mass 2 kg and natural frequency 100 Hz, the angular frequency is 2*pi*100 = 628 rad/s, so modal stiffness = 2 * 628^2 = 7.9 x 10^5 N/m.','Structural Dynamics',ARRAY['Normal mode','Modal participation factor','Modal overlap','Overdamping']::text[],ARRAY['Confusing modal stiffness with the physical stiffness of a single spring in the structure.','Assuming modal stiffness has fixed units independent of how the mode shape was normalised.','Forgetting that modal mass and modal stiffness both scale with the chosen mode-shape scaling.']::text[],ARRAY['Building a reduced modal model of a loudspeaker cabinet panel.','Predicting a mode''s response amplitude from an applied modal force.','Checking a finite-element eigenvalue solution for consistency.']::text[],'advanced','k_n = omega_n^2 * m_n','Modal stiffness equals the modal mass times the square of the mode''s natural angular frequency.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal stiffness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fad25fb2-e106-43e1-8521-9a01b91604ba','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fad25fb2-e106-43e1-8521-9a01b91604ba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fad25fb2-e106-43e1-8521-9a01b91604ba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4543b440-7518-408c-9645-74838ea583e3','Model-order reduction','Model-order reduction is a family of techniques that replace a large numerical model with a much smaller one that preserves the input-output behaviour of interest over a chosen frequency range. In vibro-acoustics, common methods include modal truncation, Guyan (static) condensation, and Craig-Bampton component-mode synthesis.','A detailed computer model of a structure can have millions of unknowns. That is slow to solve. Model-order reduction shrinks it to a small model that still gives the right answers. It keeps the behaviour that matters and drops the rest. This makes big simulations practical.','It cuts computational cost so large structural-acoustic models can be simulated, optimised, or run in real time.','An engineer reduces a million-degree-of-freedom cabinet model to its first fifty modes, checks that the retained modes cover the audio band of interest, then couples the small model to an acoustic domain.','Numerical Methods',ARRAY['Normal mode','Modal participation factor','Multiphysics simulation','Modal stiffness']::text[],ARRAY['Truncating too few modes, so the response is wrong near the top of the analysis band.','Assuming reduction is lossless, when accuracy is only guaranteed over the target range.','Ignoring residual (static) flexibility, which matters for point loads and interfaces.']::text[],ARRAY['Speeding up a finite-element vibration model for design optimisation.','Coupling a structural substructure into a larger assembly model.','Enabling real-time simulation of a structure for control design.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Model-order reduction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4543b440-7518-408c-9645-74838ea583e3','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4543b440-7518-408c-9645-74838ea583e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4543b440-7518-408c-9645-74838ea583e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b5c5f94-cdb2-4b16-ab91-27e618478b87','Monopole source','A monopole is an idealised point source whose surface pulsates uniformly, radiating sound equally in all directions when its size is much smaller than a wavelength (ka << 1). Its strength is the source''s volume velocity, and its far-field pressure is proportional to frequency and source strength and inversely proportional to distance.','Picture a tiny pulsing ball that pushes air out and in evenly. It sends sound out equally in every direction. This ideal source is called a monopole. Real small sources, like a subwoofer at low frequency, act nearly like one.','It is the basic building block for describing and modelling more complex sound sources and radiation.','For a monopole of strength Q=1e-4 m^3/s at 100 Hz in air (rho=1.21, c=343), k=1.83 /m, the pressure at 1 m is |p| = 1.21*343*1.83*1e-4 / (4*pi*1) = 0.0060 Pa, about 50 dB SPL.','Radiation Sources',ARRAY['Quadrupole source','Nonlinear acoustics','Point impedance','Normal mode']::text[],ARRAY['Assuming a monopole radiates with a directional pattern; it is omnidirectional.','Confusing source strength (volume velocity) with radiated power.','Using the far-field formula in the near field where kr is small.']::text[],ARRAY['Modelling a small loudspeaker or vent at low frequency.','Explaining why subwoofer placement affects room excitation.','Deriving radiation from a vibrating panel as a sum of monopoles.']::text[],'intermediate','|p(r)| = (rho0 * c * k * Q) / (4 * pi * r)','Far-field monopole pressure equals fluid density times sound speed times wavenumber times source strength, divided by four pi times distance.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Monopole source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b5c5f94-cdb2-4b16-ab91-27e618478b87','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b5c5f94-cdb2-4b16-ab91-27e618478b87') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b5c5f94-cdb2-4b16-ab91-27e618478b87');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1301950c-96c4-4a02-bc41-294278eaceec','Multiphysics simulation','Multiphysics simulation solves two or more coupled physical phenomena together in one numerical model, exchanging quantities at shared boundaries or throughout the domain. In acoustics it commonly couples structural vibration, fluid acoustics, thermal, and electromagnetic or piezoelectric fields, for example in transducer or vibro-acoustic problems.','Real devices obey several physics at once. A speaker moves, heats up, and pushes air. Multiphysics simulation models these effects together in one solve. It captures how each field affects the others. That is more realistic than solving each alone.','It captures the two-way coupling between physical domains that single-physics models miss, giving more accurate device predictions.','An engineer couples the moving cone (structural), the surrounding air (acoustic), and the voice-coil drive (electromagnetic) to predict a loudspeaker''s frequency response before building a prototype.','Numerical Methods',ARRAY['Model-order reduction','Perfectly matched layer','Poroelastic model','Monopole source']::text[],ARRAY['Assuming weak (one-way) coupling is always adequate when strong two-way coupling is present.','Neglecting mesh compatibility at the interface between physics domains.','Overlooking thermal or damping effects that only appear when domains are coupled.']::text[],ARRAY['Designing a MEMS microphone with coupled fluid and structural fields.','Predicting transducer behaviour including voice-coil heating.','Modelling sound transmission through a vibrating, porous-lined panel.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multiphysics simulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1301950c-96c4-4a02-bc41-294278eaceec','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1301950c-96c4-4a02-bc41-294278eaceec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1301950c-96c4-4a02-bc41-294278eaceec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2448ea3e-9856-430e-91f0-7b098a7cb000','Negative bulk modulus','Negative effective bulk modulus is a metamaterial property in which, over a narrow frequency band near a local resonance (such as an array of Helmholtz resonators), the medium''s volume responds out of phase with applied pressure. In that band the effective bulk modulus is negative, and combined with positive density it forbids propagating waves.','Squeeze a normal material and its pressure goes up. This special material is built to act backward for a moment. It happens near a certain resonance. Its stiffness to squeezing turns negative. In that narrow band, sound cannot pass. Engineers design this metamaterial effect.','It provides a route to acoustic band gaps, cloaking, and negative-index behaviour that natural materials cannot offer.','A technician meets it in ultrasonic metamaterial panels built from Helmholtz-resonator arrays, used to block a chosen narrow frequency band without a thick, dense barrier.','Acoustic Metamaterials',ARRAY['Negative effective mass density','Phononic bandgap','Phononic crystal','Nonlinear resonance']::text[],ARRAY['Believing a real static bulk modulus can be negative; the effect is dynamic and band-limited.','Confusing negative modulus (from Helmholtz-type resonance) with negative mass density (from mass resonance).','Assuming the effect is broadband rather than confined near resonance.']::text[],ARRAY['Designing a thin panel to block a specific ultrasonic tone.','Explaining double-negative metamaterials with negative index.','Comparing local-resonance metamaterials with periodic phononic crystals.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Negative bulk modulus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2448ea3e-9856-430e-91f0-7b098a7cb000','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2448ea3e-9856-430e-91f0-7b098a7cb000') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2448ea3e-9856-430e-91f0-7b098a7cb000');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af0a27c0-8dfa-4ef5-8bb9-4a983cc7cd59','Negative effective mass density','Negative effective mass density is a metamaterial property in which an internal mass-spring resonator makes the composite accelerate opposite to an applied dynamic force over a narrow band just above the internal resonance. The effective density, defined through the averaged force-acceleration relation, becomes negative and blocks wave propagation there.','Push most things and they move the way you push. Some engineered materials hide a weight on an internal spring. Near a resonance, that weight makes the whole unit lurch backward. Then its effective mass acts negative and sound cannot pass.','It supplies one of the two negative parameters needed for band gaps, negative refraction, and sub-wavelength sound control.','Using the mass-in-mass model m_eff = m1 + m2*w0^2/(w0^2 - w^2), just above the internal resonance w0 the second term is large and negative, so m_eff < 0 in that narrow band.','Acoustic Metamaterials',ARRAY['Negative bulk modulus','Phononic bandgap','Phononic crystal','Normal mode']::text[],ARRAY['Thinking the total physical mass changes; only the dynamic effective mass goes negative.','Confusing this with negative bulk modulus, which comes from a different resonance type.','Assuming the negative band is wide rather than a narrow slice above resonance.']::text[],ARRAY['Explaining membrane-type sound-blocking metamaterials at low frequency.','Designing locally resonant panels for narrowband isolation.','Teaching how sub-wavelength band gaps differ from Bragg gaps.']::text[],'advanced','m_eff(omega) = m1 + m2 * omega0^2 / (omega0^2 - omega^2)','Effective mass equals the outer mass plus a resonance term that turns negative just above the internal resonance frequency.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Negative effective mass density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af0a27c0-8dfa-4ef5-8bb9-4a983cc7cd59','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af0a27c0-8dfa-4ef5-8bb9-4a983cc7cd59') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af0a27c0-8dfa-4ef5-8bb9-4a983cc7cd59');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8187651-97b5-48e4-b023-fd441175a897','Nonlinear absorption','Nonlinear absorption is amplitude-dependent energy loss that arises when a finite-amplitude wave distorts and, in the extreme, forms shocks. Because energy dissipates rapidly at the steep shock fronts, the effective attenuation of an intense wave exceeds the small-signal (linear) absorption predicted for the same frequency.','Quiet sound loses energy at a fixed rate. Very loud sound is different. A loud wave steepens and can form shock fronts. Those sharp fronts burn off energy fast. So intense sound is absorbed more strongly than linear theory predicts.','It explains and quantifies the extra loss and waveform limiting that occur at high sound intensities, beyond ordinary absorption.','A technician working with high-intensity ultrasound accounts for extra shock-related loss so that predicted focal energy in tissue is not overestimated.','Nonlinear Acoustics',ARRAY['Nonlinear acoustics','Nonlinear propagation','Parameter of nonlinearity','Nonlinear resonance']::text[],ARRAY['Applying small-signal absorption coefficients to intense, shocked waves.','Assuming absorption is independent of amplitude, which fails once distortion is strong.','UNSAFE: underestimating focal heating in high-intensity ultrasound by ignoring shock-enhanced absorption, risking unintended tissue burns or overexposure.']::text[],ARRAY['Predicting attenuation of high-intensity focused ultrasound in tissue.','Explaining saturation of a loud acoustic beam.','Modelling energy loss in a shocked sawtooth wave.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8187651-97b5-48e4-b023-fd441175a897','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8187651-97b5-48e4-b023-fd441175a897') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8187651-97b5-48e4-b023-fd441175a897');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42c9b553-0d06-42fd-b5e0-a131ec65289b','Nonlinear acoustics','Nonlinear acoustics is the study of finite-amplitude sound where the governing equations cannot be linearised, so pressure and particle velocity no longer combine additively. Consequences include waveform distortion, harmonic and difference-frequency generation, amplitude-dependent sound speed, and shock formation.','For quiet sound, waves simply add up and keep their shape. Loud sound breaks that rule. The wave changes shape as it travels and grows new frequencies. It can even steepen into a shock. This behaviour is called nonlinear acoustics.','It describes how intense sound behaves, underpinning medical ultrasound, sonar, and parametric audio arrays.','A technician recognises that a loud primary tone will spawn harmonics and, for two tones, a difference frequency, so the received spectrum is not a simple copy of the source.','Nonlinear Acoustics',ARRAY['Nonlinear propagation','Parameter of nonlinearity','Parametric acoustic array','Nonlinear absorption']::text[],ARRAY['Assuming superposition holds at high amplitude, when it does not.','Ignoring generated harmonics and difference tones in intense fields.','UNSAFE: assuming linear exposure limits apply to high-intensity ultrasound or cavitating fields, which can cause burns or tissue damage.']::text[],ARRAY['Explaining harmonic imaging in diagnostic ultrasound.','Understanding self-demodulation in a parametric loudspeaker.','Analysing sonic-boom and high-intensity sound propagation.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42c9b553-0d06-42fd-b5e0-a131ec65289b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42c9b553-0d06-42fd-b5e0-a131ec65289b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42c9b553-0d06-42fd-b5e0-a131ec65289b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5854a572-1955-48fd-91ca-b4f90c519221','Nonlinear propagation','Nonlinear propagation is the cumulative distortion of a finite-amplitude wave as it travels, because compressions move slightly faster than rarefactions. The waveform steepens with distance and, absent enough absorption, forms a shock at a characteristic shock-formation distance governed by the medium''s nonlinearity, the frequency, and the source amplitude.','A loud wave does not keep its shape as it moves. Its peaks travel a touch faster than its troughs. Over distance the front steepens. Eventually it can snap into a shock. How soon depends on loudness, frequency, and the medium.','It predicts where and how an intense wave distorts and shocks, which is central to ultrasound, sonar, and blast acoustics.','In water (beta=3.5) at 1 MHz with 1 MPa source pressure, particle velocity u=p/(rho*c)=0.67 m/s, Mach ~4.4e-4, k=4189/m, giving shock-formation distance x = 1/(beta*k*eps) ~ 0.15 m.','Nonlinear Acoustics',ARRAY['Nonlinear acoustics','Parameter of nonlinearity','Nonlinear absorption','Parametric acoustic array']::text[],ARRAY['Assuming a loud wave keeps a pure sinusoidal shape as it travels.','Ignoring that shock-formation distance shrinks with higher frequency and amplitude.','UNSAFE: mispredicting the focal shock zone in high-intensity focused ultrasound, risking excess heating or cavitation damage.']::text[],ARRAY['Estimating shock distance for a high-intensity ultrasound beam.','Explaining sonic-boom waveform steepening in air.','Designing a parametric array where distortion builds the audible signal.']::text[],'advanced','x_shock = 1 / (beta * k * eps) = rho0 * c0^3 / (beta * omega * p0)','Plane-wave shock forms at a distance set inversely by the nonlinearity coefficient, the wavenumber, and the acoustic Mach number.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5854a572-1955-48fd-91ca-b4f90c519221','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5854a572-1955-48fd-91ca-b4f90c519221') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5854a572-1955-48fd-91ca-b4f90c519221');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09d14de5-e725-45b3-9487-55613e23d024','Nonlinear resonance','Nonlinear resonance occurs when a resonator''s stiffness or restoring force depends on amplitude, so its resonance frequency shifts as the drive level changes (as in a Duffing oscillator). The response curve bends, and over a range of drive frequencies the system can jump abruptly between high- and low-amplitude states.','A simple resonator peaks at one fixed frequency. A nonlinear one is different. Its peak frequency slides as you drive it harder. The response curve leans over and can jump suddenly. This bending and jumping is nonlinear resonance.','It explains amplitude-dependent tuning, hysteresis, and jump phenomena seen in strongly driven mechanical and acoustic resonators.','A technician driving a loudspeaker suspension hard notices the resonance peak shifts and the response curve leans, a sign of nonlinear (Duffing-like) stiffness rather than a fixed linear resonance.','Nonlinear Acoustics',ARRAY['Nonlinear acoustics','Normal mode','Overdamping','Negative effective mass density']::text[],ARRAY['Assuming the resonance frequency is fixed regardless of drive level.','Overlooking hysteresis and jump behaviour when sweeping frequency up versus down.','Fitting a linear model to a clearly bent, amplitude-dependent response.']::text[],ARRAY['Characterising a loudspeaker suspension at high excursion.','Explaining rattle and jump behaviour in strongly driven panels.','Modelling amplitude-dependent tuning of a resonant absorber.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlinear resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09d14de5-e725-45b3-9487-55613e23d024','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09d14de5-e725-45b3-9487-55613e23d024') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09d14de5-e725-45b3-9487-55613e23d024');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1590b39a-8594-46fe-b628-5b9935760919','Normal mode','A normal mode is a natural pattern of vibration in which every part of a system oscillates sinusoidally at one common (natural) frequency with fixed relative amplitudes. For a rigid rectangular room, the acoustic modal frequencies follow the eigenvalue relation set by the sound speed and the three room dimensions.','Every room or structure has natural ways it likes to vibrate. Each way has one frequency and a fixed shape. These are its normal modes. In a room they create standing waves and boomy or dead spots at certain low frequencies.','Normal modes form the basis set from which any free or forced response of a linear system can be built.','For a 5 x 4 x 3 m room (c=343), the (1,0,0) axial mode is f = (343/2)*(1/5) = 34.3 Hz, a frequency where standing-wave peaks and nulls appear.','Room Acoustics',ARRAY['Modal overlap','Modal stiffness','Modal participation factor','Operational deflection shape']::text[],ARRAY['Confusing a normal (natural) mode with a forced operational deflection shape.','Assuming modes exist only in rooms, not in panels, strings, and structures.','Using the rigid-wall formula for rooms with strongly absorbing boundaries.']::text[],ARRAY['Predicting low-frequency room resonances for studio treatment.','Explaining uneven bass response and listening-position nulls.','Setting the modal basis for a structural vibration analysis.']::text[],'intermediate','f_lmn = (c/2) * sqrt((l/Lx)^2 + (m/Ly)^2 + (n/Lz)^2)','Each rectangular-room mode frequency comes from the sound speed and the integer mode counts along the three room dimensions.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Normal mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1590b39a-8594-46fe-b628-5b9935760919','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1590b39a-8594-46fe-b628-5b9935760919') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1590b39a-8594-46fe-b628-5b9935760919');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a424d967-5dec-49dc-a7e5-7bf895dd42e1','Numerical dispersion','Numerical dispersion is an artefact of discretised wave solvers in which the simulated wave speed depends on frequency, grid resolution, and propagation direction, even when the true medium is non-dispersive. It causes waveforms to spread and phase errors to accumulate over distance, worsening for short wavelengths relative to the grid.','In real air, all sound travels at nearly the same speed. A computer grid can get this slightly wrong. Different frequencies then move at slightly wrong speeds in the model. The wave spreads out and phases drift. This false effect is numerical dispersion.','Recognising it guides mesh and time-step choices so simulated waves keep the correct speed and shape.','An engineer uses at least ten to twenty grid points per shortest wavelength in a finite-difference acoustic model to keep numerical dispersion errors acceptably small over the simulated distance.','Numerical Methods',ARRAY['Numerical dissipation','Multiphysics simulation','Perfectly matched layer','Model-order reduction']::text[],ARRAY['Confusing numerical dispersion (phase-speed error) with numerical dissipation (amplitude loss).','Using too few grid points per wavelength and blaming physics for the spreading.','Ignoring that the error depends on propagation direction on a grid.']::text[],ARRAY['Setting mesh density for a finite-difference time-domain acoustic model.','Explaining pulse broadening in a long-range wave simulation.','Comparing solver schemes for room-acoustic wave modelling.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Numerical dispersion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a424d967-5dec-49dc-a7e5-7bf895dd42e1','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a424d967-5dec-49dc-a7e5-7bf895dd42e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a424d967-5dec-49dc-a7e5-7bf895dd42e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c5308e52-61f0-470e-b381-0f1854529854','Numerical dissipation','Numerical dissipation is artificial damping introduced by a discretisation scheme, causing simulated wave amplitudes to decay faster than the true physics dictates. It often arises from upwind or low-order time-integration schemes and can be deliberately added to stabilise a solver at the cost of amplitude accuracy.','A computer scheme can quietly drain energy from a simulated wave. The wave then fades faster than it really should. This false damping is numerical dissipation. Sometimes it is added on purpose to keep the solver stable.','Understanding it lets analysts balance solver stability against unwanted loss of wave energy in a simulation.','An engineer choosing a time-integration scheme accepts a little numerical dissipation to suppress spurious high-frequency oscillations, while checking that real resonances are not over-damped.','Numerical Methods',ARRAY['Numerical dispersion','Multiphysics simulation','Perfectly matched layer','Overdamping']::text[],ARRAY['Mistaking numerical dissipation for real material damping in results.','Using a highly dissipative scheme and under-predicting resonance amplitudes.','Assuming a stable scheme is automatically an accurate one.']::text[],ARRAY['Selecting a stable time-marching scheme for transient acoustics.','Explaining why simulated resonance peaks are lower than measured.','Tuning artificial viscosity in a shock-capturing solver.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Numerical dissipation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c5308e52-61f0-470e-b381-0f1854529854','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c5308e52-61f0-470e-b381-0f1854529854') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c5308e52-61f0-470e-b381-0f1854529854');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '25c5a007-a700-43e2-b99e-368cad32411c','Open-cell foam','Open-cell foam is a porous material whose pores are interconnected, allowing air to flow through the sample. Its acoustic behaviour is governed by parameters such as porosity, airflow resistivity, and tortuosity, making it an effective dissipative sound absorber, unlike closed-cell foam whose sealed cells block airflow.','Open-cell foam has tiny pores that connect together. Air can move right through it. As sound pushes air through the maze of pores, friction turns sound into heat. That makes it a good absorber. Closed-cell foam, with sealed pockets, does not absorb well.','It absorbs airborne sound by viscous and thermal losses as air moves through its connected pore network.','A studio technician selects open-cell foam and confirms its airflow resistivity (per ISO 9053) sits in the absorptive range, rather than using sealed closed-cell foam that reflects rather than absorbs.','Acoustic Materials',ARRAY['Porosity','Poroelastic model','Nonlinear absorption','Point impedance']::text[],ARRAY['Assuming any foam absorbs sound; closed-cell foam largely does not.','Believing thicker foam always helps at low frequency without checking airflow resistivity.','Ignoring that very high airflow resistivity reflects sound rather than absorbing it.']::text[],ARRAY['Choosing absorptive panels for a control room or vocal booth.','Lining a duct or enclosure to reduce airborne noise.','Measuring absorption of a foam sample in an impedance tube.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open-cell foam');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '25c5a007-a700-43e2-b99e-368cad32411c','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='25c5a007-a700-43e2-b99e-368cad32411c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='25c5a007-a700-43e2-b99e-368cad32411c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d44c167-22e0-4d20-8524-e4b124cc1734','Operational deflection shape','An operational deflection shape (ODS) is the vibration pattern a structure actually exhibits at a specific frequency or moment under its real operating loads. Unlike a normal mode, it is a forced response that generally combines contributions from several modes and depends on the excitation.','A running machine flexes in some pattern you can measure. That live pattern is the operational deflection shape. It is not a pure natural mode. It is a blend of modes shaped by the real forces acting at that moment.','It shows how a structure really moves in service, helping locate excessive motion and troubleshoot noise and vibration.','A technician measures vibration at many points on a running pump, animates the ODS at the running speed, and sees where the casing flexes most to target a fix.','Structural Dynamics',ARRAY['Normal mode','Modal participation factor','Modal overlap','Modal stiffness']::text[],ARRAY['Treating an ODS as a mode shape; an ODS is a forced, excitation-dependent response.','Assuming an ODS at a resonance equals that single mode, ignoring nearby modes.','Comparing ODS amplitudes without keeping a consistent phase reference.']::text[],ARRAY['Troubleshooting a vibrating machine at its running speed.','Locating panel regions that radiate the most noise.','Guiding where to add stiffening or damping on a structure.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Operational deflection shape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d44c167-22e0-4d20-8524-e4b124cc1734','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d44c167-22e0-4d20-8524-e4b124cc1734') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d44c167-22e0-4d20-8524-e4b124cc1734');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45b80e16-868d-4d43-8dd7-8e891c133cc9','Overdamping','Overdamping is the condition of a second-order system whose damping ratio exceeds unity, so a disturbed system returns to equilibrium without oscillating. It corresponds to a damping coefficient greater than the critical value, giving two real, distinct decay rates rather than an oscillatory response.','Give a resonator a push and normally it wobbles as it settles. Add enough damping and it stops wobbling. It just eases back to rest with no bounce. That heavily damped case is called overdamping.','It defines the regime where a system settles without ringing, important for suspensions, dampers, and controlled decay.','For m=1 kg and k=100 N/m, critical damping is c_crit = 2*sqrt(k*m) = 20 N.s/m; a damping coefficient of 30 gives zeta = 30/20 = 1.5 > 1, so the system is overdamped.','Vibration',ARRAY['Normal mode','Nonlinear resonance','Numerical dissipation','Modal stiffness']::text[],ARRAY['Confusing overdamping with critical damping; critical is the fastest non-oscillatory return at zeta = 1.','Assuming more damping always means faster settling, when heavy overdamping is sluggish.','Expecting an overdamped system to overshoot or ring.']::text[],ARRAY['Specifying a shock mount that must not oscillate after a bump.','Explaining why a heavily damped meter needle creeps to rest.','Distinguishing under-, critically, and over-damped transient responses.']::text[],'beginner','zeta = c / (2 * sqrt(k * m)) > 1','A system is overdamped when its damping ratio, the actual damping over the critical damping, exceeds one.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Overdamping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45b80e16-868d-4d43-8dd7-8e891c133cc9','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45b80e16-868d-4d43-8dd7-8e891c133cc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45b80e16-868d-4d43-8dd7-8e891c133cc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5f8c830f-1ab9-4cbd-b67d-7f6cbdba9abf','Parameter of nonlinearity','The parameter of nonlinearity, B/A, is the ratio of the second- to first-order coefficients in the Taylor expansion of pressure in terms of density perturbation for a given medium. The related coefficient of nonlinearity beta equals 1 + B/(2A) and governs the rate of finite-amplitude waveform distortion.','Every fluid bends the pressure-density relation a little when squeezed hard. The number B/A measures how much it bends. A larger B/A means loud sound distorts faster. Water has a bigger B/A than air, so it distorts more readily.','It characterises a medium''s intrinsic nonlinearity and is used in tissue characterisation and finite-amplitude modelling.','For water B/A is about 5.0, so beta = 1 + 5.0/2 = 3.5; for air, treated as an ideal gas, B/A = gamma - 1 = 0.4, giving beta = 1.2.','Nonlinear Acoustics',ARRAY['Nonlinear acoustics','Nonlinear propagation','Nonlinear absorption','Parametric acoustic array']::text[],ARRAY['Confusing B/A with beta; beta = 1 + B/(2A), not B/A itself.','Assuming air and water distort similarly, when their B/A and beta differ markedly.','UNSAFE: neglecting the medium''s high beta when estimating focal pressures in ultrasound, leading to under-predicted heating or cavitation.']::text[],ARRAY['Characterising biological tissue by its B/A value.','Estimating harmonic growth of a finite-amplitude beam.','Comparing nonlinear distortion in air versus water.']::text[],'advanced','beta = 1 + B/(2A);  p'' = A*(rho''/rho0) + (B/2)*(rho''/rho0)^2 + ...','The coefficient of nonlinearity equals one plus half the ratio of the second to the first Taylor coefficient of pressure versus density.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parameter of nonlinearity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5f8c830f-1ab9-4cbd-b67d-7f6cbdba9abf','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5f8c830f-1ab9-4cbd-b67d-7f6cbdba9abf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5f8c830f-1ab9-4cbd-b67d-7f6cbdba9abf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '89bb928d-7e0d-472a-8c40-429d7fac8574','Parametric acoustic array','A parametric acoustic array is a highly directional sound source that exploits nonlinear interaction of two collimated high-frequency (primary) beams in a fluid. Their nonlinear mixing generates a difference-frequency wave along the beam, forming a virtual end-fire array that radiates the low difference frequency with a narrow beamwidth. The concept was introduced by Westervelt in 1963.','Send two strong high-frequency beams into water or air together. Where they overlap, the nonlinear medium mixes them. This creates a new tone at their difference frequency. Because it is born along a thin beam, the low tone comes out remarkably narrow and directional.','It produces a very narrow low-frequency beam from a small source, used in sonar and directional audio.','A sonar engineer drives two primaries near 200 kHz whose difference is 10 kHz; the 10 kHz beam radiates far more directionally than a conventional 10 kHz transducer of the same aperture.','Nonlinear Acoustics',ARRAY['Parametric interaction','Parametric loudspeaker','Nonlinear acoustics','Nonlinear propagation']::text[],ARRAY['Assuming the difference frequency comes from a linear transducer rather than nonlinear mixing.','Expecting high efficiency; parametric conversion is inherently low-efficiency.','UNSAFE: exposing personnel to the intense inaudible high-frequency primary beams, which can cause ultrasonic overexposure, without proper limits.']::text[],ARRAY['Building narrow-beam sub-bottom profiling sonar.','Explaining how directional audio spotlights work.','Analysing self-demodulation of a modulated ultrasonic beam.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parametric acoustic array');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '89bb928d-7e0d-472a-8c40-429d7fac8574','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='89bb928d-7e0d-472a-8c40-429d7fac8574') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='89bb928d-7e0d-472a-8c40-429d7fac8574');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72a8d7ac-7f09-446a-8026-3efd8f4f2de5','Parametric interaction','Parametric interaction is the nonlinear coupling between acoustic waves in which two or more waves mix through the medium''s nonlinearity to generate new frequencies, notably sum and difference frequencies and harmonics. It is the physical mechanism underlying parametric arrays and loudspeakers.','When two strong sound waves share a nonlinear medium, they do not just add up. They mix and breed new tones. You get their sum and difference frequencies plus harmonics. This mixing is called parametric interaction.','It is the basic nonlinear mixing process that lets one frequency band generate another, enabling parametric sources.','An engineer notes that two intense primaries at f1 and f2 produce a usable difference frequency f1 - f2 through parametric interaction, which the array then radiates directionally.','Nonlinear Acoustics',ARRAY['Parametric acoustic array','Parametric loudspeaker','Nonlinear acoustics','Parameter of nonlinearity']::text[],ARRAY['Confusing parametric interaction (nonlinear mixing) with linear superposition.','Assuming only difference frequencies appear, ignoring sum frequencies and harmonics.','Believing weak, low-amplitude waves interact strongly, when the effect grows with intensity.']::text[],ARRAY['Explaining difference-tone generation in a parametric array.','Analysing intermodulation from two intense ultrasonic beams.','Teaching the mechanism behind directional audio.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parametric interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72a8d7ac-7f09-446a-8026-3efd8f4f2de5','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72a8d7ac-7f09-446a-8026-3efd8f4f2de5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72a8d7ac-7f09-446a-8026-3efd8f4f2de5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8c6e980-426c-4a39-8402-939de646bcb1','Parametric loudspeaker','A parametric loudspeaker is a directional audio device that emits an amplitude-modulated ultrasonic carrier which self-demodulates through nonlinear propagation in air, recovering the audible signal along a narrow beam. It applies the parametric-array principle to airborne audio; the commercial ''Audio Spotlight'' is a trademark of Holosonics.','This speaker sends out a beam of inaudible ultrasound carrying your audio. As the intense beam travels through air, nonlinear effects unwrap the audio from it. The sound appears along a tight beam, like a spotlight. Only listeners in the beam hear it clearly.','It delivers highly directional sound so audio can be aimed at a listening zone with little spill elsewhere.','An installer aims a parametric loudspeaker at a museum exhibit so visitors there hear narration, while people a few metres to the side hear very little.','Nonlinear Acoustics',ARRAY['Parametric acoustic array','Parametric interaction','Nonlinear propagation','Nonlinear acoustics']::text[],ARRAY['Assuming a conventional cone speaker can be this directional at audio frequencies.','Expecting high output and low distortion; efficiency and fidelity are limited by the nonlinear process.','UNSAFE: running the ultrasonic carrier at excessive levels near people without regard to ultrasound exposure guidance.']::text[],ARRAY['Providing localised audio at a museum or retail display.','Delivering directional announcements without wide spill.','Demonstrating self-demodulation of a modulated ultrasonic beam.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Parametric loudspeaker');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8c6e980-426c-4a39-8402-939de646bcb1','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8c6e980-426c-4a39-8402-939de646bcb1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8c6e980-426c-4a39-8402-939de646bcb1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4ca75a35-29cc-4403-a5be-a7785d41d1e4','Perfectly matched layer','A perfectly matched layer (PML) is an artificial absorbing region added at the boundary of a wave-simulation domain that is impedance-matched to the interior, so waves enter without reflection and are then exponentially attenuated. Introduced by Berenger in 1994 for electromagnetics, it is widely used to emulate open (unbounded) domains in acoustic finite-element and finite-difference models.','A computer model of open space must stop somewhere. A hard edge would echo waves back and spoil results. A perfectly matched layer is a special border that lets waves in without reflection, then soaks them up. It fakes open, boundless space.','It lets a finite computational grid mimic an infinite, non-reflecting domain for outgoing waves.','An engineer wraps a loudspeaker radiation model in a PML so outgoing sound leaves the mesh without artificial echoes contaminating the near-field solution.','Numerical Methods',ARRAY['Multiphysics simulation','Numerical dispersion','Numerical dissipation','Monopole source']::text[],ARRAY['Confusing a PML with a simple lossy layer; a plain absorber reflects at its interface.','Making the PML too thin or too steeply graded, causing residual reflections.','Assuming a PML absorbs equally well at grazing incidence without careful formulation.']::text[],ARRAY['Modelling free-field radiation from a source on a finite mesh.','Simulating scattering without domain-edge echoes.','Truncating a waveguide model to emulate an open end.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Perfectly matched layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4ca75a35-29cc-4403-a5be-a7785d41d1e4','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4ca75a35-29cc-4403-a5be-a7785d41d1e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4ca75a35-29cc-4403-a5be-a7785d41d1e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec2eda12-b464-49a1-9203-188bca4c088c','Phonon tracing','Phonon tracing is a geometric room-acoustics simulation method in which discrete energy particles (''phonons''), each carrying a frequency-dependent energy spectrum, are traced from source to receiver while accumulating frequency-dependent reflection and absorption. The collected phonon spectra build an impulse response for auralisation and visualisation.','This method shoots many tiny energy packets from a sound source into a room model. Each packet carries a spectrum and bounces off surfaces, losing energy by frequency. Packets that reach the listener are gathered up. Together they build the room''s sound and can be drawn as a map.','It provides frequency-dependent room-acoustic simulation for auralisation and for visualising how sound energy spreads.','An acoustician traces phonons through a virtual concert-hall model to compute a listener''s impulse response and to display where reflected energy concentrates on the walls.','Room Acoustics',ARRAY['Normal mode','Multiphysics simulation','Numerical dispersion','Operational deflection shape']::text[],ARRAY['Confusing acoustic phonon tracing (a room-acoustics analogy) with solid-state lattice phonons.','Assuming it captures wave effects like diffraction as accurately as a wave solver.','Using too few phonons, giving a noisy, unreliable impulse response.']::text[],ARRAY['Auralising a room design before construction.','Visualising reflected-energy distribution on surfaces.','Comparing geometric and wave-based room-acoustic predictions.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phonon tracing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec2eda12-b464-49a1-9203-188bca4c088c','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec2eda12-b464-49a1-9203-188bca4c088c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec2eda12-b464-49a1-9203-188bca4c088c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3f4adaf0-62ce-4c0f-b74f-a26989f1d82b','Phononic bandgap','A phononic bandgap is a frequency range within which elastic or acoustic waves cannot propagate through a periodic or locally resonant medium, because no real wave solutions (Bloch modes) exist there. Gaps arise from Bragg scattering in periodic structures or from local resonances in metamaterials.','Some engineered materials have a frequency band where sound simply cannot pass. Inside that band, waves are blocked and reflected. This forbidden band is a phononic bandgap. It comes from a regular pattern or from tiny built-in resonators.','It enables frequency-selective blocking, filtering, and guiding of sound and vibration.','A designer sizes a periodic array so its Bragg bandgap covers a troublesome machine tone, blocking that frequency without a thick, heavy barrier.','Acoustic Metamaterials',ARRAY['Phononic crystal','Negative bulk modulus','Negative effective mass density','Modal overlap']::text[],ARRAY['Assuming a bandgap blocks all frequencies rather than a specific band.','Confusing Bragg gaps (from periodicity) with resonance gaps (from local resonators).','Expecting a fixed gap when temperature or geometry changes shift it.']::text[],ARRAY['Designing a vibration isolator for a specific frequency band.','Creating an acoustic filter or mirror.','Explaining why a periodic structure reflects one band strongly.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phononic bandgap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3f4adaf0-62ce-4c0f-b74f-a26989f1d82b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3f4adaf0-62ce-4c0f-b74f-a26989f1d82b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3f4adaf0-62ce-4c0f-b74f-a26989f1d82b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c82aec99-9ace-471f-af15-de21e4e70f7e','Phononic crystal','A phononic crystal is a composite material with a periodic spatial variation in elastic properties (density and stiffness) that controls the propagation of acoustic or elastic waves. Its periodicity produces Bragg-scattering bandgaps at wavelengths comparable to twice the lattice spacing, analogous to photonic crystals for light.','A phononic crystal is a material built as a repeating pattern of two or more solids. The regular pattern steers and blocks sound waves. At certain frequencies it reflects them strongly. It works for sound much as a photonic crystal works for light.','It gives engineers a periodic structure to filter, guide, or block sound and vibration by design.','An engineer chooses a lattice spacing so the Bragg gap (near wavelength = twice the spacing) blocks a target ultrasonic frequency, then arranges the periodic inclusions accordingly.','Acoustic Metamaterials',ARRAY['Phononic bandgap','Negative bulk modulus','Negative effective mass density','Normal mode']::text[],ARRAY['Confusing a phononic crystal (periodic, Bragg-based) with a resonant metamaterial (sub-wavelength).','Assuming its gap sits far below the frequency set by lattice spacing.','Believing a single inclusion, not the periodic array, creates the gap.']::text[],ARRAY['Designing an ultrasonic filter or waveguide.','Creating a vibration-blocking periodic panel.','Teaching wave physics by analogy with photonic crystals.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phononic crystal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c82aec99-9ace-471f-af15-de21e4e70f7e','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c82aec99-9ace-471f-af15-de21e4e70f7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c82aec99-9ace-471f-af15-de21e4e70f7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd21e730-34af-41ac-a2d5-a8ba7f7a1da9','Point impedance','Point (driving-point) impedance is the complex ratio of the harmonic force applied at a point on a structure to the resulting velocity at that same point. It characterises how strongly a structure resists being driven at that location and governs how much power a source can inject there.','Push a structure at one spot with a shaking force and it moves at some speed. Point impedance is the force divided by that speed at the same spot. A high value means the spot is hard to drive. It tells you how easily a source feeds power in.','It quantifies how a structure resists a point drive, setting how much vibrational power a source injects there.','If a shaker applies 10 N and the drive point moves at 0.02 m/s, the point impedance magnitude is 10 / 0.02 = 500 N.s/m at that frequency.','Structural Acoustics',ARRAY['Normal mode','Modal stiffness','Monopole source','Operational deflection shape']::text[],ARRAY['Confusing structural (mechanical) point impedance with acoustic impedance (pressure over volume velocity).','Ignoring the phase of the complex ratio and using magnitude alone.','Assuming point impedance is frequency-independent, when it varies with frequency and near resonances.']::text[],ARRAY['Matching a shaker or actuator to a structure for efficient power input.','Predicting power injected into a panel by a vibration source.','Comparing drive-point mobility across candidate mounting locations.']::text[],'advanced','Z = F / v','Driving-point impedance is the applied harmonic force divided by the resulting velocity at the same point.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Point impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd21e730-34af-41ac-a2d5-a8ba7f7a1da9','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd21e730-34af-41ac-a2d5-a8ba7f7a1da9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd21e730-34af-41ac-a2d5-a8ba7f7a1da9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3a9fd86-1833-4372-bdd1-e4a1a7abae18','Poroelastic model','A poroelastic model describes sound in a fluid-saturated porous material by treating the elastic solid frame and the pore fluid as two coupled, interacting phases, following Biot''s theory. It predicts multiple coupled wave types, including two compressional waves and a shear wave, and is the standard framework for materials such as acoustic foams and fibrous absorbers.','A sound-absorbing foam is a springy solid frame full of air. A poroelastic model lets both the frame and the trapped air move. It tracks how they push on each other. This follows Biot''s theory and predicts absorption better than a rigid model.','It accurately predicts absorption and transmission in porous media where both the frame and the fluid move.','An acoustician uses a Biot poroelastic model, with measured porosity, airflow resistivity, and tortuosity, to predict a foam liner''s absorption instead of assuming a rigid, motionless frame.','Acoustic Materials',ARRAY['Porosity','Open-cell foam','Multiphysics simulation','Point impedance']::text[],ARRAY['Assuming a rigid frame when the skeleton actually vibrates and matters.','Confusing the two Biot compressional waves or ignoring the slow wave.','Using a poroelastic model without the required measured material parameters.']::text[],ARRAY['Predicting absorption of a foam or fibrous liner in a vehicle.','Modelling sound transmission through a porous-cored panel.','Characterising a porous absorber from measured Biot parameters.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Poroelastic model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3a9fd86-1833-4372-bdd1-e4a1a7abae18','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3a9fd86-1833-4372-bdd1-e4a1a7abae18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3a9fd86-1833-4372-bdd1-e4a1a7abae18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd2e56d0d-419b-498a-aa47-ede2f8c34a00','Porosity','Porosity is the ratio of the connected pore (fluid) volume to the total bulk volume of a porous material. In acoustics it is one of the key non-acoustical parameters, alongside airflow resistivity and tortuosity, that determine a porous absorber''s behaviour; typical acoustic foams and fibrous materials have porosity above 0.9.','Porosity is how much of a material is empty pore space filled with air. It is the air volume divided by the whole volume. Good sound absorbers are mostly open air inside, often over ninety percent. That open space lets sound in to be absorbed.','It is a fundamental material parameter that helps predict how a porous absorber interacts with sound.','A foam block of 1000 cm^3 that contains 950 cm^3 of connected air has porosity = 950 / 1000 = 0.95, typical of an effective acoustic foam.','Acoustic Materials',ARRAY['Open-cell foam','Poroelastic model','Point impedance','Nonlinear absorption']::text[],ARRAY['Counting sealed, closed pores as open porosity; only connected pores count acoustically.','Assuming higher porosity alone guarantees better absorption, ignoring airflow resistivity.','Confusing porosity with density or with airflow resistivity.']::text[],ARRAY['Characterising an absorber alongside airflow resistivity and tortuosity.','Feeding porosity into a Biot or empirical absorption model.','Comparing candidate foams for a lining application.']::text[],'intermediate','phi = V_pore / V_total','Porosity is the connected pore (air) volume divided by the total bulk volume of the sample.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Porosity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd2e56d0d-419b-498a-aa47-ede2f8c34a00','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d2e56d0d-419b-498a-aa47-ede2f8c34a00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d2e56d0d-419b-498a-aa47-ede2f8c34a00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fefd065a-670c-4a85-9b9c-a2bd54612d5a','Quadrupole source','A quadrupole is an idealised source formed by two closely spaced dipoles of opposite phase, radiating inefficiently with a four-lobed directivity. Its radiated power scales with the sixth power of frequency; in Lighthill''s aeroacoustic analogy, free turbulence radiates as a quadrupole, giving the classic eighth-power dependence of jet acoustic power on flow speed.','A quadrupole is a weak, complex sound source made from two opposed dipoles. It radiates poorly and in a four-lobed pattern. Turbulent flow, like a jet, acts as a quadrupole. That is why jet noise power rises steeply with jet speed.','It models the very inefficient radiation of turbulence and other stress-type sources in aeroacoustics.','Because turbulent (quadrupole) acoustic power scales as U^8, doubling jet exhaust speed raises radiated power by 2^8 = 256 times, about 24 dB, a key jet-noise result.','Radiation Sources',ARRAY['Monopole source','Nonlinear acoustics','Point impedance','Multiphysics simulation']::text[],ARRAY['Assuming a quadrupole radiates as efficiently as a monopole; it is far weaker.','Confusing the quadrupole four-lobe pattern with a dipole''s two lobes.','Misremembering the jet-noise law; free-turbulence power follows the eighth power of speed.']::text[],ARRAY['Explaining why jet-engine noise grows steeply with exhaust speed.','Modelling turbulence-generated sound in aeroacoustics.','Contrasting monopole, dipole, and quadrupole radiation efficiency.']::text[],'advanced','P_rad ~ omega^6;  (Lighthill) P_ac ~ rho0 * U^8 * L^2 / c0^5','Quadrupole radiated power rises with the sixth power of frequency; turbulent (Lighthill) sources scale with the eighth power of flow speed.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quadrupole source');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fefd065a-670c-4a85-9b9c-a2bd54612d5a','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fefd065a-670c-4a85-9b9c-a2bd54612d5a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fefd065a-670c-4a85-9b9c-a2bd54612d5a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7914b9a6-6163-445a-bd69-dfea9b4e7a4b','Radiation efficiency','The radiation efficiency of a vibrating surface is the ratio of the sound power it actually radiates to the power a rigid piston of equal area and equal mean-square normal velocity would radiate into the same medium. It is defined as sigma = W_rad / (rho0 * c * S * <v^2>), where <v^2> is the space- and time-averaged mean-square normal surface velocity.','This number tells how well a shaking surface turns its motion into sound. A value near one means it radiates sound easily. A small value means most of the motion makes little sound. Large, fast-moving panels tend to radiate best.','It lets engineers compare how effectively different vibrating structures convert their motion into airborne sound power.','For a 1 m^2 panel with <v^2> = 1e-4 m^2/s^2 radiating 2e-5 W in air (rho0*c = 415 Pa.s/m): sigma = 2e-5 / (415 * 1 * 1e-4) = 4.8e-4.','Vibro-acoustics',ARRAY['Radiation ratio','Structural acoustics','Structural wave impedance','Statistical energy analysis']::text[],ARRAY['Assuming sigma can never exceed one; near the coincidence frequency it can slightly exceed unity','Confusing radiation efficiency with the mechanical or energy efficiency of a source','Using peak velocity instead of the space- and time-averaged mean-square velocity','Forgetting that sigma is strongly frequency dependent and small below the critical frequency']::text[],ARRAY['Predicting how much noise a machine panel radiates','Comparing loudspeaker cone or diaphragm designs','Ranking which surface of an enclosure radiates most sound','Estimating structure-borne sound from a plate']::text[],'advanced','sigma = W_rad / (rho0 * c * S * <v^2>)','Radiation efficiency equals the radiated sound power divided by the product of air''s characteristic impedance, the radiating area, and the space- and time-averaged mean-square normal velocity.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation efficiency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7914b9a6-6163-445a-bd69-dfea9b4e7a4b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7914b9a6-6163-445a-bd69-dfea9b4e7a4b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7914b9a6-6163-445a-bd69-dfea9b4e7a4b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b7e0caf-d7dd-40fa-a2ec-21af2270851b','Radiation ratio','Radiation ratio is an alternative name for radiation efficiency: the ratio of the sound power radiated by a vibrating surface to rho0*c*S*<v^2>, the power a same-area piston with equal mean-square normal velocity would radiate. The term is common in European and ISO-influenced structural-acoustics literature.','Radiation ratio is just another name for radiation efficiency. It compares the real radiated sound to an ideal piston. A value near one means strong radiation. The quantity has no units.','It provides a single dimensionless figure for how effectively a structure radiates sound, used identically to radiation efficiency.','For a panel radiating 2e-5 W with area 1 m^2 and <v^2> = 1e-4 m^2/s^2 in air: radiation ratio = 2e-5 / (415 * 1 * 1e-4) = 4.8e-4.','Vibro-acoustics',ARRAY['Radiation efficiency','Structural acoustics','Structural wave impedance','Statistical energy analysis']::text[],ARRAY['Assuming ''radiation ratio'' names a different quantity from radiation efficiency; they are identical','Expecting only values at or below one, when it can exceed one near coincidence','Using un-averaged surface velocity in the denominator','Ignoring its strong dependence on frequency']::text[],ARRAY['Reading structural-acoustics texts that use the ISO-style term','Comparing panel radiation across designs','Feeding radiation data into vibro-acoustic models','Assessing machine casing noise']::text[],'advanced','sigma = W_rad / (rho0 * c * S * <v^2>)','The radiation ratio equals the radiated sound power divided by air''s characteristic impedance times the radiating area times the space- and time-averaged mean-square normal velocity.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b7e0caf-d7dd-40fa-a2ec-21af2270851b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b7e0caf-d7dd-40fa-a2ec-21af2270851b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b7e0caf-d7dd-40fa-a2ec-21af2270851b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7714de1d-d820-4e4c-ac8c-2455cf4c06ea','Ray tracing','Ray tracing is a geometrical-acoustics technique that represents sound as rays travelling in straight lines and reflecting from surfaces according to the law of reflection, summing many rays to estimate energy decay, impulse responses, and reverberation. It is valid where wavelengths are small compared with the reflecting surfaces.','Ray tracing follows sound like beams of light bouncing around a room. Each ray reflects off walls and loses some energy. Adding many rays predicts echoes and reverberation time. It works best at high frequencies.','It gives fast, approximate predictions of room acoustics and outdoor sound propagation without solving the full wave equation.','An acoustician launches thousands of rays from a source, counts the energy reaching a receiver over time, and reads the reverberation time from the resulting decay curve.','Computational acoustics',ARRAY['Spatial discretization','Reduced-order model','Statistical energy analysis','Spectral-element method']::text[],ARRAY['Trusting ray tracing at low frequencies, where wave effects dominate','Ignoring diffraction, which simple rays do not capture','Using too few rays, giving a noisy or unreliable decay estimate','Confusing ray tracing with the image-source method']::text[],ARRAY['Concert hall and auditorium design','Environmental noise mapping','Auralization of virtual spaces','Predicting reverberation in large rooms']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ray tracing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7714de1d-d820-4e4c-ac8c-2455cf4c06ea','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7714de1d-d820-4e4c-ac8c-2455cf4c06ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7714de1d-d820-4e4c-ac8c-2455cf4c06ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e50ad32d-7945-489c-ab72-c30ab4d72057','Receptance','Receptance, also called dynamic compliance, is the frequency-response function giving the ratio of displacement response to an applied harmonic force, alpha(omega) = X(omega)/F(omega). For a single-degree-of-freedom system it equals 1 / (k - omega^2*m + j*omega*c).','Receptance shows how far a structure moves for a given push at each frequency. A large value means the structure moves a lot. It rises sharply at resonances. Engineers measure it to find natural frequencies.','It characterises how a structure responds to force versus frequency, forming the basis of modal testing and substructure coupling.','For a mass-spring system with k = 1e6 N/m and m = 1 kg, the static (zero-frequency) receptance is alpha = 1/k = 1e-6 m/N, i.e. one micrometre per newton.','Structural dynamics',ARRAY['Structural wave impedance','Reduced-order model','Rigid-body mode','Structural loss factor']::text[],ARRAY['Confusing receptance (displacement/force) with mobility (velocity/force) or accelerance (acceleration/force)','Forgetting receptance is complex, carrying phase as well as magnitude','Ignoring damping, which would make resonance peaks infinite','Assuming it is dimensionless rather than metres per newton']::text[],ARRAY['Measuring frequency-response functions in a modal test','Coupling substructures via their receptances','Identifying resonances of a component','Comparing receptance to mobility data']::text[],'advanced','alpha(omega) = X(omega)/F(omega) = 1 / (k - omega^2*m + j*omega*c)','Receptance equals the displacement amplitude divided by the force amplitude; for one mode it equals one over stiffness minus mass times angular frequency squared plus a damping term.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Receptance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e50ad32d-7945-489c-ab72-c30ab4d72057','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e50ad32d-7945-489c-ab72-c30ab4d72057') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e50ad32d-7945-489c-ab72-c30ab4d72057');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a1028c33-61f9-4749-a72b-c4b34a495436','Reduced-order model','A reduced-order model (ROM) approximates a large dynamic model using far fewer degrees of freedom, usually by projecting the system onto a small set of dominant modes or basis vectors while preserving the response of interest over a chosen frequency band.','A reduced-order model shrinks a huge simulation into a small one. It keeps only the motions that matter most. This makes it run much faster. Engineers use it for quick design studies.','It cuts computational cost while retaining accuracy within the frequency band the analyst cares about.','An analyst keeps the first 30 modes of a 100,000-degree-of-freedom finite-element model, computing the vibration response in seconds rather than hours.','Computational acoustics',ARRAY['Spatial discretization','Receptance','Spectral-element method','Rigid-body mode']::text[],ARRAY['Truncating too few modes, so the response near the band edges is wrong','Assuming a model reduced for one band stays valid at all frequencies','Forgetting residual or static correction for the truncated modes','Confusing model-order reduction with simply coarsening the mesh']::text[],ARRAY['Condensing a finite-element model for fast analysis','Real-time or hardware-in-the-loop simulation','Control-system design','Iterative design optimisation loops']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reduced-order model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a1028c33-61f9-4749-a72b-c4b34a495436','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a1028c33-61f9-4749-a72b-c4b34a495436') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a1028c33-61f9-4749-a72b-c4b34a495436');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '230d3067-57c3-4124-a80a-d1192e1dac5d','Reynolds number','The Reynolds number is a dimensionless ratio of inertial to viscous forces in a flow, Re = rho*U*L/mu = U*L/nu. It governs the transition from laminar to turbulent flow and sets dynamic similarity between geometrically similar flows.','The Reynolds number compares a flow''s push to its stickiness. Low values mean smooth, orderly flow. High values mean turbulent, messy flow. It helps predict when flow noise begins.','It predicts flow regime and lets small-scale tests represent full-scale flows, which is central to flow-induced noise.','Air at U = 10 m/s over a cylinder of L = 0.05 m with nu = 1.5e-5 m^2/s gives Re = 10*0.05/1.5e-5 = 3.3e4, a turbulent wake that sheds vortices.','Fluid dynamics',ARRAY['Strouhal number','Screech tone','Shock-associated noise','Rotor–stator interaction']::text[],ARRAY['Forgetting that Re depends on the chosen characteristic length','Mixing dynamic and kinematic viscosity in the formula','Assuming a single universal transition value for all geometries','Confusing the Reynolds number with the Mach number']::text[],ARRAY['Predicting the onset of vortex shedding','Scaling wind-tunnel model tests to full size','Estimating turbulent flow noise in ducts','Judging whether a flow is laminar or turbulent']::text[],'intermediate','Re = rho*U*L/mu = U*L/nu','The Reynolds number equals fluid density times flow speed times a characteristic length, divided by the dynamic viscosity; equivalently, speed times length divided by the kinematic viscosity.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reynolds number');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '230d3067-57c3-4124-a80a-d1192e1dac5d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='230d3067-57c3-4124-a80a-d1192e1dac5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='230d3067-57c3-4124-a80a-d1192e1dac5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd773fedf-6bdc-4a7f-a526-9542cbe927bf','Rigid-body mode','A rigid-body mode is a zero- or near-zero-frequency mode in which a structure translates or rotates as a whole without elastic deformation. A fully unconstrained body has up to six rigid-body modes: three translations and three rotations.','A rigid-body mode is motion where the whole object moves together. It does not bend or stretch. A free object has up to six of these. They sit at zero frequency.','It represents the free motion of an unconstrained structure, which must be identified before flexible modes in dynamic analysis.','In a free-free modal test, an engineer expects six near-zero-frequency rigid-body modes to appear before the first true bending or flexible mode.','Structural dynamics',ARRAY['Receptance','Reduced-order model','Spatial discretization','Structural acoustics']::text[],ARRAY['Mistaking a low-frequency flexible mode for a rigid-body mode','Forgetting that a fully free body has six rigid-body modes','Not removing rigid-body modes before a static solution, leaving a singular stiffness matrix','Assuming rigid-body modes radiate sound efficiently']::text[],ARRAY['Free-free finite-element analysis','Suspension and mount design','Interpreting modal test data','Launch-vehicle and payload dynamics']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rigid-body mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd773fedf-6bdc-4a7f-a526-9542cbe927bf','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d773fedf-6bdc-4a7f-a526-9542cbe927bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d773fedf-6bdc-4a7f-a526-9542cbe927bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec47a563-8264-4825-a79e-894b0c47136c','Rotor–stator interaction','Rotor-stator interaction is the aerodynamic and acoustic coupling between a rotating blade row and a stationary vane row in turbomachinery. The periodic wakes and potential fields generate tonal noise at the blade-passing frequency and its harmonics, whose circumferential spinning-mode orders follow the Tyler-Sofrin relation m = n*B - k*V.','In a fan or jet engine, spinning blades pass fixed vanes. Their wakes strike the vanes and make strong tones. These tones occur at the blade-passing rate. The sound pattern spins around the duct.','It explains the dominant tonal noise of ducted fans and compressors and guides blade and vane count choices to control it.','With B = 22 blades and V = 26 vanes, the first harmonic (n=1, k=1) gives m = 22 - 26 = -4, a low-order spinning mode that may cut on and propagate as loud tonal noise.','Aeroacoustics',ARRAY['Screech tone','Shock-associated noise','Strouhal number','Reynolds number']::text[],ARRAY['Assuming every blade-passing tone propagates; many spinning modes stay cut off below their cut-on frequency','Ignoring vane count when choosing blade count, which can allow loud low-order modes','Confusing the blade-passing frequency with the shaft rotation frequency','Treating rotor and stator noise as independent sources']::text[],ARRAY['Aircraft engine fan noise','Selecting blade and vane counts','HVAC and cooling fan tonal noise','Turbocharger and compressor whine']::text[],'advanced','m = n*B - k*V','The circumferential spinning-mode order equals the harmonic number times the blade count minus any integer times the vane count.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rotor–stator interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec47a563-8264-4825-a79e-894b0c47136c','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec47a563-8264-4825-a79e-894b0c47136c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec47a563-8264-4825-a79e-894b0c47136c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7c2128e-317d-46d7-8812-b55f9965a24c','SEA','SEA is the standard abbreviation for Statistical Energy Analysis, a method that models high-frequency vibro-acoustic systems as coupled subsystems exchanging vibrational energy. It uses power balance with damping loss factors, coupling loss factors, and modal densities rather than detailed mode shapes.','SEA is short for Statistical Energy Analysis. It treats a structure as boxes of vibration energy. Energy flows between boxes that are joined. It works best at high frequencies with many modes.','It predicts noise and vibration where modal density is high and detailed deterministic methods are impractical or too costly.','A car-body analyst splits the vehicle into panels and air cavities, then solves the energy balance to predict interior noise above roughly 400 Hz.','Vibro-acoustics',ARRAY['Statistical energy analysis','Radiation efficiency','Structural loss factor','Reduced-order model']::text[],ARRAY['Applying SEA at low frequencies with too few modes per frequency band','Guessing coupling loss factors instead of deriving or measuring them','Forgetting the consistency relation between coupling loss factors','Expecting SEA to give detailed local mode shapes']::text[],ARRAY['Automotive NVH prediction','Spacecraft launch vibration analysis','Ship and offshore structure noise','High-frequency sound transmission in buildings']::text[],'advanced','n_i * eta_ij = n_j * eta_ji','The consistency relation states that each subsystem''s modal density times its coupling loss factor toward another equals the reverse product, ensuring reciprocity of energy exchange.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SEA');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7c2128e-317d-46d7-8812-b55f9965a24c','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7c2128e-317d-46d7-8812-b55f9965a24c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7c2128e-317d-46d7-8812-b55f9965a24c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2bece1dd-97bb-44f5-a989-33f9c283a93b','Sawtooth wave formation','In nonlinear acoustics, sawtooth wave formation is the fully developed stage in which an initially sinusoidal finite-amplitude plane wave, after steepening into shocks, takes on a repeating sawtooth profile. Its amplitude then decays in an ''old-age'' regime as the shocks dissipate energy faster than ordinary absorption.','A very loud pure tone slowly changes shape as it travels. Its front steepens into a shock. Eventually the wave looks like a sawtooth. Then it fades as the shocks lose energy.','It describes the saturated, energy-limited stage that intense sound reaches before it weakens, setting practical limits on high-amplitude sound.','Beyond the shock-formation distance, a technician driving an intense sinusoidal source sees harmonics fill the spectrum until the waveform becomes a sawtooth.','Nonlinear acoustics',ARRAY['Shock formation','Sum-frequency generation','Subharmonic generation','Shock-associated noise']::text[],ARRAY['UNSAFE: assuming an intense single-tone ultrasonic or sonar source is harmless, when nonlinear steepening builds strong harmonics that raise real exposure','Thinking the waveform stays sinusoidal at very high amplitude','Ignoring that sawtooth decay is faster than linear absorption predicts','Confusing a sawtooth from a tone with an N-wave from a blast']::text[],ARRAY['High-intensity ultrasound propagation','Loudspeaker and horn distortion at high sound levels','Parametric array behaviour','Sonic-boom and blast waveform evolution']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sawtooth wave formation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2bece1dd-97bb-44f5-a989-33f9c283a93b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2bece1dd-97bb-44f5-a989-33f9c283a93b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2bece1dd-97bb-44f5-a989-33f9c283a93b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea8c2a9e-e978-463e-bf38-1b0969f95bc7','Screech tone','Screech is an intense discrete-frequency tone radiated by imperfectly expanded supersonic jets. It arises from a feedback loop in which turbulent structures passing the quasi-periodic shock cells radiate sound upstream that re-excites the jet shear layer near the nozzle.','Some supersonic jets make a loud whistle called screech. It comes from a feedback loop at the nozzle. Shock cells and turbulence drive it. It can fatigue nearby metal parts.','Understanding screech explains a strong tonal part of supersonic jet noise and guides ways to suppress damaging tones.','An engineer spots a sharp tone in an underexpanded jet spectrum, links its frequency to the shock-cell spacing, and fits nozzle tabs to break the feedback loop.','Aeroacoustics',ARRAY['Shock-associated noise','Shock formation','Rotor–stator interaction','Strouhal number']::text[],ARRAY['UNSAFE: standing close to a screeching jet or exhaust, where the tone can reach hearing-damaging levels and cause sonic fatigue of structures','Confusing screech (a discrete tone) with broadband shock-associated noise','Assuming screech occurs in perfectly (ideally) expanded jets','Thinking screech frequency is independent of the jet pressure ratio']::text[],ARRAY['Military jet and afterburner exhaust','Rocket plume acoustics','Supersonic wind-tunnel operation','Nozzle design for noise suppression']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Screech tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea8c2a9e-e978-463e-bf38-1b0969f95bc7','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea8c2a9e-e978-463e-bf38-1b0969f95bc7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea8c2a9e-e978-463e-bf38-1b0969f95bc7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45dcef13-d464-4f84-abf4-f43a2a0b1069','Shock formation','Shock formation is the nonlinear process by which a finite-amplitude compressive wave steepens, because higher-pressure parts of the waveform travel faster than lower-pressure parts, until a near-discontinuous front (a shock) develops. For an initially sinusoidal plane wave the shock first appears at the distance x_bar = 1/(beta*epsilon*k).','In a very loud wave, the high-pressure part moves faster than the low-pressure part. The wave front gets steeper as it travels. At some distance it becomes a sharp shock. This is shock formation.','It sets the distance at which intense sound becomes shocked, which matters for exposure, absorption, and waveform prediction.','For air (beta = 1.2), a 20 kHz tone at p0 = 1000 Pa: x_bar = rho0*c0^3 / (beta*omega*p0) = 4.88e7 / (1.2 * 1.26e5 * 1000) = 0.32 m.','Nonlinear acoustics',ARRAY['Sawtooth wave formation','Shock-associated noise','Sum-frequency generation','Screech tone']::text[],ARRAY['UNSAFE: underestimating exposure from intense ultrasound or blast because shock steepening concentrates energy into a sharp high-pressure front','Assuming linear acoustics at high amplitude, so waves supposedly never steepen','Confusing the shock-formation distance with the absorption length','Assuming the nonlinearity coefficient beta is the same for air and water']::text[],ARRAY['Sonic-boom propagation','Medical and industrial high-intensity focused ultrasound','Blast-wave analysis','High-sound-level horn and compression-driver output']::text[],'advanced','x_bar = 1/(beta*epsilon*k) = rho0*c0^3 / (beta*omega*p0)','The shock-formation distance equals one over the product of the nonlinearity coefficient, the acoustic Mach number, and the wavenumber; equivalently, air density times sound speed cubed divided by the nonlinearity coefficient, angular frequency, and source pressure amplitude.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shock formation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45dcef13-d464-4f84-abf4-f43a2a0b1069','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45dcef13-d464-4f84-abf4-f43a2a0b1069') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45dcef13-d464-4f84-abf4-f43a2a0b1069');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9c28fad-1da8-4b7a-b4ef-123b0a4c65b0','Shock-associated noise','Shock-associated noise is sound generated when turbulent eddies convect through the quasi-periodic shock-cell structure of an imperfectly expanded supersonic jet. It comprises broadband shock-associated noise and discrete screech tones, and is distinct from the jet''s turbulent mixing noise.','A supersonic jet that is not perfectly expanded forms a repeating pattern of shock waves. Turbulence passing through them makes noise. Part is a broadband hiss and part is a screech whistle. Together this is shock-associated noise.','It names a dominant supersonic-jet noise source, letting engineers separate and target it apart from mixing noise.','An analyst sees a broadband hump above the mixing-noise floor in a jet spectrum and links its peak frequency to the shock-cell spacing and the observer angle.','Aeroacoustics',ARRAY['Screech tone','Shock formation','Rotor–stator interaction','Strouhal number']::text[],ARRAY['UNSAFE: neglecting hearing protection near supersonic exhaust, where shock-associated noise adds very high sound levels','Assuming it occurs in perfectly (ideally) expanded on-design jets','Confusing broadband shock-associated noise with turbulent mixing noise','Ignoring its strong dependence on observer angle']::text[],ARRAY['Supersonic aircraft noise certification','Launch-vehicle liftoff acoustics','Jet-noise suppression research','Supersonic wind-tunnel testing']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shock-associated noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9c28fad-1da8-4b7a-b4ef-123b0a4c65b0','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9c28fad-1da8-4b7a-b4ef-123b0a4c65b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9c28fad-1da8-4b7a-b4ef-123b0a4c65b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd317f93e-c4c5-4c19-baf3-cbff606a0b75','Sonic crystal','A sonic crystal is a periodic arrangement of acoustic scatterers, such as rigid cylinders in air, whose Bragg scattering produces frequency band gaps that strongly attenuate sound at wavelengths comparable to the lattice spacing. The first band gap centres near f = c/(2a) for lattice constant a.','A sonic crystal is a regular grid of objects that block sound. Waves scatter off the pattern and cancel out. This stops certain frequencies from passing. Rows of posts can act as a barrier.','It provides passive, frequency-selective sound attenuation and wave steering, often while still allowing airflow through the array.','Cylinders spaced a = 0.1 m in air (c = 343 m/s) give a first Bragg band gap near f = 343/(2*0.1) = 1715 Hz.','Acoustic metamaterials',ARRAY['Space-coiling metamaterial','Subwavelength resonator','Structural acoustics']::text[],ARRAY['Expecting attenuation well below the first Bragg gap, where the crystal is nearly transparent','Confusing Bragg band gaps with the local-resonance gaps of metamaterials','Assuming a single row of scatterers behaves like a full periodic crystal','Ignoring the strong angle and frequency dependence of the gap']::text[],ARRAY['Tree-array and post-array noise barriers','Sound-guiding and filtering structures','Outdoor noise control that still allows airflow','Acoustic-sculpture demonstrations']::text[],'advanced','f_Bragg = c / (2*a)','The centre frequency of the first Bragg band gap equals the speed of sound divided by twice the lattice constant.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic crystal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd317f93e-c4c5-4c19-baf3-cbff606a0b75','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d317f93e-c4c5-4c19-baf3-cbff606a0b75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d317f93e-c4c5-4c19-baf3-cbff606a0b75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '05e69739-f297-4ced-a208-3b72a67a6322','Sonoluminescence','Sonoluminescence is the emission of short light flashes from gas bubbles in a liquid driven by intense ultrasound. During inertial (transient) cavitation the bubble collapses violently, compressing and heating its contents enough to emit light.','Strong ultrasound can make tiny bubbles in a liquid flash with light. The sound squeezes each bubble until it collapses hard. The trapped gas becomes extremely hot. That heat makes a quick flash.','It is a striking marker of the extreme temperatures and pressures reached inside collapsing cavitation bubbles.','A researcher traps a single bubble in a resonant flask and drives it near 25 kHz to produce steady single-bubble sonoluminescence flashes.','Cavitation',ARRAY['Stable cavitation','Subharmonic generation','Shock formation']::text[],ARRAY['UNSAFE: treating sonoluminescence apparatus as harmless, when high-intensity ultrasound and inertial cavitation can damage tissue and hearing','Thinking stable cavitation causes the flashes, when it requires inertial (collapse) cavitation','Confusing the emitted light with a phosphorescent or chemical glow','Assuming the exact light-emission mechanism is fully settled']::text[],ARRAY['Single-bubble physics demonstrations','Sonochemistry and cavitation research','Probing bubble-collapse conditions','Cautionary context for ultrasound dosimetry']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonoluminescence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '05e69739-f297-4ced-a208-3b72a67a6322','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='05e69739-f297-4ced-a208-3b72a67a6322') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='05e69739-f297-4ced-a208-3b72a67a6322');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd4ccffd4-e78d-4fe1-ac49-e4bc1062a3ab','Space-coiling metamaterial','A space-coiling metamaterial folds its sound-propagation channels into a compact, coiled path so that the acoustic path length greatly exceeds the unit-cell size. This yields a high effective refractive index and a slow effective sound speed at subwavelength scale.','This material coils narrow channels inside a small block. Sound must travel the long, winding path. So it slows down and bends strongly. The block acts much larger than it looks.','It achieves extreme effective index, slow sound, and wavefront control in thin, subwavelength devices.','A designer uses coiled channels to build a thin flat lens or phase plate that steers an audio beam in a chosen direction.','Acoustic metamaterials',ARRAY['Sonic crystal','Subwavelength resonator','Structural acoustics']::text[],ARRAY['Assuming the coiled path changes the true sound speed of air, when only the effective device-scale speed changes','Ignoring viscothermal losses inside the narrow coiled channels','Confusing a high effective index with amplification of sound','Expecting broadband performance from a resonant coiled design']::text[],ARRAY['Thin flat acoustic lenses','Compact wavefront-shaping metasurfaces','Slow-sound absorber designs','Acoustic-cloaking demonstrations']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Space-coiling metamaterial');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd4ccffd4-e78d-4fe1-ac49-e4bc1062a3ab','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d4ccffd4-e78d-4fe1-ac49-e4bc1062a3ab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d4ccffd4-e78d-4fe1-ac49-e4bc1062a3ab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff53d8eb-73d0-42b9-9c3b-5307f1760a4b','Spatial discretization','Spatial discretization is the division of a continuous domain into a mesh or grid of discrete points or elements so that a wave or vibration problem can be solved numerically. Accuracy requires enough points per wavelength to keep numerical dispersion error small.','Computers cannot handle a smooth space directly. So they split it into a grid of small pieces. Each piece holds one value. Using enough small pieces per wavelength keeps the answer accurate.','It converts continuous field equations into a finite system of equations a computer can actually solve.','For a 2 kHz sound in air (wavelength approx 0.17 m), using at least six elements per wavelength requires element size <= 0.17/6 = 0.029 m.','Computational acoustics',ARRAY['Temporal discretization','Spectral-element method','Reduced-order model','Ray tracing']::text[],ARRAY['Using too few elements per wavelength, causing numerical dispersion error','Assuming a mesh fine enough at low frequency also works at high frequency','Ignoring how element order changes the points-per-wavelength requirement','Confusing spatial with temporal discretization']::text[],ARRAY['Meshing for finite-element or boundary-element acoustics','Setting up finite-difference time-domain grids','Checking numerical convergence','Judging the high-frequency limit of a model']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial discretization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff53d8eb-73d0-42b9-9c3b-5307f1760a4b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff53d8eb-73d0-42b9-9c3b-5307f1760a4b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff53d8eb-73d0-42b9-9c3b-5307f1760a4b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '360e2a45-32b1-4fb3-a352-d99b27d24b92','Spectral-element method','The spectral-element method is a high-order finite-element technique that uses high-degree polynomial basis functions, typically Lagrange polynomials on Gauss-Lobatto-Legendre nodes, within each element. This gives low numerical dispersion and rapid convergence for wave-propagation problems.','This method is a finite-element method that uses smooth high-order shapes inside each cell. That lets waves travel accurately with fewer cells. It converges quickly. It suits large wave problems.','It enables accurate, efficient simulation of waves travelling over many wavelengths, where low-order elements would need very fine meshes.','A seismic or room-acoustics modeller uses spectral elements to propagate waves across a large domain with fewer points per wavelength than linear elements require.','Computational acoustics',ARRAY['Spatial discretization','Temporal discretization','Reduced-order model','Ray tracing']::text[],ARRAY['Confusing the spectral-element method with global spectral (Fourier) methods','Assuming high order removes any need for a resolution criterion','Ignoring the diagonal mass matrix that Gauss-Lobatto-Legendre nodes provide','Expecting it to resolve sharp discontinuities without special treatment']::text[],ARRAY['Seismic wave simulation','Large-scale room-acoustic modelling','Ultrasonic non-destructive evaluation','Computational aeroacoustics']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral-element method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '360e2a45-32b1-4fb3-a352-d99b27d24b92','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='360e2a45-32b1-4fb3-a352-d99b27d24b92') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='360e2a45-32b1-4fb3-a352-d99b27d24b92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f262f45-3398-4318-8ef0-1148e69f6074','Stable cavitation','Stable (non-inertial) cavitation is the sustained, repetitive oscillation of a gas or vapour bubble about its equilibrium radius under an acoustic field, without the violent collapse that characterises inertial cavitation. It can drive microstreaming and emit subharmonic acoustic signals.','In stable cavitation a bubble pulses gently in and out for many cycles. It does not collapse hard. It stirs the nearby liquid. It often gives off a half-frequency tone.','It describes the milder cavitation regime exploited in gentle ultrasonic processing and in diagnostic monitoring.','A technician keeps ultrasound intensity low enough that bubbles oscillate stably, using the resulting microstreaming for cleaning without violent collapse.','Cavitation',ARRAY['Sonoluminescence','Subharmonic generation','Shock formation']::text[],ARRAY['UNSAFE: assuming stable cavitation is always safe, when raising drive pressure can tip bubbles into damaging inertial collapse','Thinking stable cavitation produces no acoustic emissions, when it emits subharmonics','Confusing stable (non-inertial) with inertial (transient) cavitation','Assuming a single fixed threshold independent of frequency and bubble size']::text[],ARRAY['Ultrasonic cleaning baths','Sonophoresis and gentle sonoprocessing','Contrast-agent microbubble imaging','Acoustic cavitation monitoring']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stable cavitation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f262f45-3398-4318-8ef0-1148e69f6074','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f262f45-3398-4318-8ef0-1148e69f6074') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f262f45-3398-4318-8ef0-1148e69f6074');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6417c2bb-6998-4268-88b4-96965b8cafc8','Statistical energy analysis','Statistical Energy Analysis (SEA) predicts high-frequency vibro-acoustic behaviour by dividing a system into subsystems, each described by its total vibrational energy, and solving a power balance. The balance is governed by damping loss factors, coupling loss factors, and modal densities rather than detailed mode shapes.','This method predicts noise when a structure has many modes. It divides the system into connected parts. Each part stores vibration energy. Energy flow between parts follows a simple balance.','It gives efficient noise-and-vibration predictions in the high-frequency range where deterministic modelling is impractical.','For two coupled plates with eta_12 = 0.01, E_1 = 1e-3 J, eta_21 = 0.005, E_2 = 2e-4 J at 1 kHz: P_12 = omega*(eta_12*E_1 - eta_21*E_2) = 6283*(1e-5 - 1e-6) = 0.057 W.','Vibro-acoustics',ARRAY['SEA','Radiation efficiency','Structural loss factor','Reduced-order model']::text[],ARRAY['Applying SEA below the frequency where subsystems have enough modes per band','Assuming weak coupling when subsystems are in fact strongly coupled','Neglecting the consistency (reciprocity) relation between coupling loss factors','Expecting local, deterministic responses from an energy-averaged method']::text[],ARRAY['Automotive interior noise prediction','Spacecraft and launch-vehicle vibration','Ship structural noise','High-frequency building sound transmission']::text[],'advanced','P_ij = omega * (eta_ij*E_i - eta_ji*E_j),  with  n_i*eta_ij = n_j*eta_ji','The net power flowing from one subsystem to another equals angular frequency times the difference of their coupling-loss-factor-weighted energies; the modal-density-weighted coupling factors are reciprocal.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Statistical energy analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6417c2bb-6998-4268-88b4-96965b8cafc8','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6417c2bb-6998-4268-88b4-96965b8cafc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6417c2bb-6998-4268-88b4-96965b8cafc8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51ca1338-465b-4f4a-b7bd-6c68514123f1','Strouhal number','The Strouhal number is a dimensionless frequency, St = f*L/U, relating a characteristic oscillation frequency such as vortex shedding to the flow speed and a characteristic length. For a circular cylinder, St is about 0.2 over a wide range of Reynolds numbers.','The Strouhal number links a flow''s shaking frequency to its speed and size. It tells the pitch of flow-made sound. For a cylinder it is about 0.2. That predicts wind-made tones.','It predicts the frequency of flow-induced oscillations and tones, central to aeroacoustic and flow-induced-vibration problems.','For a cylinder of D = 0.02 m in a U = 15 m/s flow with St = 0.2, the shedding frequency is f = St*U/D = 0.2*15/0.02 = 150 Hz.','Aeroacoustics',ARRAY['Reynolds number','Screech tone','Rotor–stator interaction','Shock-associated noise']::text[],ARRAY['Assuming St = 0.2 for all shapes and all Reynolds numbers','Mixing up which length scale to use for L','Confusing the Strouhal number with the reduced frequency used in some fields','Ignoring that St varies through the transition range']::text[],ARRAY['Predicting Aeolian (wind) tones on wires and cables','Cooling-fan and cable whistling','Vortex-shedding flow meters','Wind noise on structures']::text[],'intermediate','St = f*L/U','The Strouhal number equals the characteristic frequency times a characteristic length, divided by the flow speed.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Strouhal number');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51ca1338-465b-4f4a-b7bd-6c68514123f1','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51ca1338-465b-4f4a-b7bd-6c68514123f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51ca1338-465b-4f4a-b7bd-6c68514123f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cfc8145-1cc0-47c1-85d7-00fce73503e8','Structural acoustics','Structural acoustics is the study of the coupled interaction between vibrating elastic structures and a surrounding fluid. It covers how structures radiate, scatter, and respond to sound, and how fluid loading modifies their vibration.','Structural acoustics studies how shaking solids and the surrounding air or water affect each other. It covers how a panel makes sound. It also covers how sound shakes a panel. The two are linked.','It unifies vibration and sound so engineers can predict and control structure-borne and radiated noise.','An engineer models a ship hull''s plate vibration together with the surrounding water loading to predict its radiated underwater sound.','Vibro-acoustics',ARRAY['Radiation efficiency','Structural wave impedance','Structural loss factor','Statistical energy analysis']::text[],ARRAY['Ignoring fluid loading, which is important for heavy fluids such as water','Treating the structure and fluid as uncoupled at all frequencies','Confusing structural acoustics with room acoustics','Assuming in-vacuo modes equal the fluid-loaded modes']::text[],ARRAY['Sonar dome and transducer housing design','Aircraft cabin noise','Underwater radiated noise of vessels','Machine casing and enclosure noise']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Structural acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cfc8145-1cc0-47c1-85d7-00fce73503e8','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cfc8145-1cc0-47c1-85d7-00fce73503e8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cfc8145-1cc0-47c1-85d7-00fce73503e8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13390219-66ed-404d-a38f-e64783220cbb','Structural loss factor','The structural (material) loss factor eta is a dimensionless measure of damping equal to the energy dissipated per radian of oscillation divided by the peak stored energy. It relates to the quality factor by eta = 1/Q and appears in the complex modulus E(1 + j*eta).','The loss factor tells how fast a vibrating structure loses energy to heat. A high value means quick damping. A low value means long ringing. It equals one over the quality factor.','It quantifies damping for design of damping treatments and as an input to vibro-acoustic and SEA models.','A resonance at f_n = 100 Hz with a -3 dB (half-power) bandwidth of 2 Hz has a loss factor eta = 2/100 = 0.02.','Structural dynamics',ARRAY['Structural acoustics','Statistical energy analysis','Receptance','Structural wave impedance']::text[],ARRAY['Confusing loss factor eta with damping ratio zeta; eta is about twice zeta only for light damping','Assuming loss factor stays constant with frequency and temperature','Lumping material, joint, and radiation damping into one number carelessly','Reading loss factor directly as percent of critical damping']::text[],ARRAY['Designing viscoelastic damping treatments','Half-power bandwidth measurements','Providing damping inputs to SEA models','Specifying damping of viscoelastic materials']::text[],'intermediate','eta = D / (2*pi*E_stored) = 1/Q = delta_f / f_n','The loss factor equals the energy lost each cycle divided by two pi times the peak stored energy; it also equals the half-power bandwidth divided by the resonance frequency.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Structural loss factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13390219-66ed-404d-a38f-e64783220cbb','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13390219-66ed-404d-a38f-e64783220cbb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13390219-66ed-404d-a38f-e64783220cbb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da1b380a-5abc-4dd8-95fa-1afb71eaa56f','Structural wave impedance','Structural wave impedance is the ratio of applied force to the resulting velocity at the drive point of a structure carrying elastic waves. For an infinite thin plate the point-force impedance is real and frequency-independent, Z = 8*sqrt(B*m''''), where B is the bending stiffness and m'''' is the mass per unit area.','This impedance tells how hard it is to shake a structure at one point. It is force divided by the speed it moves. For a large flat plate it stays the same at all frequencies. That value sets how much power enters the plate.','It determines how much vibrational power a source drives into a structure and is central to structure-borne sound and SEA coupling.','For a 3 mm steel plate (E = 2e11 Pa, nu = 0.3): B = 494 N.m and m'''' = 23.6 kg/m^2, so Z = 8*sqrt(494*23.6) = 863 N.s/m.','Structural dynamics',ARRAY['Structural acoustics','Radiation efficiency','Receptance','Structural loss factor']::text[],ARRAY['Assuming the infinite-plate impedance applies right at edges or near finite-plate resonances','Confusing mechanical (structural) impedance with acoustic impedance','Forgetting the infinite-plate point impedance is real (purely resistive)','Using mass per unit area and bending stiffness in inconsistent units']::text[],ARRAY['Estimating vibrational power injected into a plate','Coupling machinery sources to supporting structures','Providing coupling data for SEA','Structure-borne sound analysis']::text[],'advanced','Z = F/v ;  Z_plate,inf = 8*sqrt(B*m'''')','Structural wave impedance equals drive-point force divided by velocity; for an infinite thin plate it equals eight times the square root of the bending stiffness times the mass per unit area.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Structural wave impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da1b380a-5abc-4dd8-95fa-1afb71eaa56f','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da1b380a-5abc-4dd8-95fa-1afb71eaa56f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da1b380a-5abc-4dd8-95fa-1afb71eaa56f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e915e779-02fb-4f84-81a9-f55dfe3cb6c3','Subharmonic generation','Subharmonic generation is the appearance of spectral components at frequencies below the drive frequency, typically at half the drive (f/2), produced by nonlinear systems such as oscillating cavitation bubbles or parametrically driven resonators.','A driven nonlinear system can create tones below the drive frequency. The most common is half the drive frequency. Cavitation bubbles often do this. It signals nonlinear behaviour.','It serves as a diagnostic signature of nonlinearity, notably of the onset of cavitation.','An operator monitors the f/2 subharmonic in an ultrasonic bath to detect when cavitation begins.','Nonlinear acoustics',ARRAY['Stable cavitation','Sonoluminescence','Sum-frequency generation','Sawtooth wave formation']::text[],ARRAY['Confusing subharmonics (below the drive) with harmonics (integer multiples above it)','Assuming linear systems can generate subharmonics; they cannot','Overlooking that an f/2 line can indicate cavitation in an ultrasonic system','Mistaking measurement aliasing for a true subharmonic']::text[],ARRAY['Detecting cavitation onset','Ultrasound contrast-agent imaging','Parametrically driven oscillators','Nonlinear structural vibration']::text[],'advanced','f_sub = f_drive / 2','The most common subharmonic appears at half the drive frequency.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subharmonic generation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e915e779-02fb-4f84-81a9-f55dfe3cb6c3','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e915e779-02fb-4f84-81a9-f55dfe3cb6c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e915e779-02fb-4f84-81a9-f55dfe3cb6c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99b42c29-05e1-409e-a51a-f0af30a79684','Subwavelength resonator','A subwavelength resonator is an acoustic element, such as a Helmholtz resonator or a thin membrane, whose resonant wavelength is much larger than its physical size. This enables strong, localised interaction with sound and underlies locally resonant acoustic metamaterials.','This is a small part that resonates at a low frequency. Its wavelength is much bigger than the part itself. Near resonance it grabs sound strongly. Many together make a metamaterial.','It lets thin, compact devices control low-frequency sound below the size limit of ordinary porous absorbers.','A designer tunes a Helmholtz resonator far smaller than the wavelength to absorb a stubborn low-frequency room mode.','Acoustic metamaterials',ARRAY['Sonic crystal','Space-coiling metamaterial','Structural acoustics']::text[],ARRAY['Confusing local-resonance band gaps with the Bragg gaps of sonic crystals','Expecting broadband absorption from a single tuned resonator','Ignoring viscothermal losses that limit narrow-neck performance','Assuming a device must be about a wavelength in size to work']::text[],ARRAY['Low-frequency room treatment','Thin metasurface sound absorbers','Duct and HVAC silencers','Membrane-type barriers']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subwavelength resonator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99b42c29-05e1-409e-a51a-f0af30a79684','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99b42c29-05e1-409e-a51a-f0af30a79684') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99b42c29-05e1-409e-a51a-f0af30a79684');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5a1cbf38-6117-47d5-a45b-1c794d4f923b','Sum-frequency generation','Sum-frequency generation is a nonlinear acoustic process in which two waves of frequencies f1 and f2 interact through the medium''s quadratic nonlinearity to produce energy at the sum frequency f1 + f2 (alongside the difference frequency f1 - f2).','When two loud tones travel together in a nonlinear medium, they mix. New tones appear at the sum and difference of the two frequencies. This is sum-frequency generation. It underlies the parametric array.','It explains frequency mixing in intense sound fields and is the basis of parametric sound sources.','Two ultrasonic beams at 40 kHz and 41 kHz mix to give a 1 kHz difference tone (a parametric array) and an 81 kHz sum tone.','Nonlinear acoustics',ARRAY['Subharmonic generation','Sawtooth wave formation','Shock formation']::text[],ARRAY['Assuming a linear medium can mix two tones; it cannot','Confusing sum-frequency mixing with harmonic generation of a single tone','Forgetting that the difference frequency is generated alongside the sum','Expecting strong output at low amplitudes, where nonlinearity is weak']::text[],ARRAY['Parametric loudspeakers and sonar','Nonlinear material characterisation','Intermodulation in high-level sound systems','Harmonic and nonlinear imaging']::text[],'advanced','f_sum = f1 + f2  (and f_diff = f1 - f2)','The generated sum frequency equals the sum of the two interacting wave frequencies; the difference frequency equals their difference.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sum-frequency generation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5a1cbf38-6117-47d5-a45b-1c794d4f923b','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5a1cbf38-6117-47d5-a45b-1c794d4f923b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5a1cbf38-6117-47d5-a45b-1c794d4f923b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c59b69ee-3677-44de-8237-e5280a2e5dc9','Temporal discretization','Temporal discretization is the division of continuous time into finite steps for a time-domain numerical solution. Explicit schemes require the time step to satisfy a stability limit such as the Courant-Friedrichs-Lewy (CFL) condition, delta_t <= delta_x/c.','Time-domain solvers cannot use smooth time. They march forward in small steps. Each step must be short enough to stay stable. The CFL rule links the time step to grid size and wave speed.','It makes time-dependent wave and vibration problems solvable while keeping the numerical scheme stable.','For finite-difference time-domain modelling in air (c = 343 m/s) with grid spacing delta_x = 0.01 m, the 1-D stability limit is delta_t <= 0.01/343 = 2.9e-5 s.','Computational acoustics',ARRAY['Spatial discretization','Spectral-element method','Reduced-order model','Ray tracing']::text[],ARRAY['Choosing a time step that violates the CFL limit, causing the solution to blow up','Assuming the 1-D CFL limit holds unchanged in two or three dimensions','Confusing stability with accuracy; a stable step can still be inaccurate','Overlooking that implicit schemes relax but do not remove the step limit']::text[],ARRAY['Finite-difference time-domain room simulation','Time-domain finite-element analysis','Transient shock and impact modelling','Explicit structural dynamics']::text[],'intermediate','delta_t <= C * delta_x / c   (CFL, with C <= 1 for basic explicit schemes)','The time step must be no larger than a stability (Courant) number times the grid spacing divided by the wave speed.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal discretization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c59b69ee-3677-44de-8237-e5280a2e5dc9','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c59b69ee-3677-44de-8237-e5280a2e5dc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c59b69ee-3677-44de-8237-e5280a2e5dc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5405282-6a01-4320-9f5f-d1a0043b71cd','Thermal characteristic length','In the Johnson-Champoux-Allard model of rigid-frame porous absorbers, the thermal characteristic length Lambda'' is a geometric pore parameter equal to twice the ratio of pore volume to pore-wall surface area. It governs thermal-exchange losses at medium-to-high frequencies.','This length describes the size of the open spaces inside a porous absorber. It equals twice the pore volume divided by the pore surface area. It sets the heat-related sound losses. Bigger pores give a larger value.','It captures how heat exchanges between the pore air and the solid frame, one of the parameters that sets a porous material''s sound absorption.','For a pore geometry with pore volume 1e-9 m^3 and wall area 2e-5 m^2: Lambda'' = 2*1e-9/2e-5 = 1e-4 m = 100 micrometres.','Material acoustics',ARRAY['Viscous characteristic length','Flow resistivity','Porosity','Sound absorption coefficient']::text[],ARRAY['Confusing the thermal characteristic length Lambda'' with the viscous characteristic length Lambda','Assuming Lambda'' always equals twice Lambda; that is only a default, not a physical rule','Treating it as a directly ruler-measurable dimension rather than a weighted average','Ignoring it at low frequencies, where it has little effect']::text[],ARRAY['Fitting the JCA model to impedance-tube data','Simulating porous sound absorbers','Characterising foams and fibrous materials','Optimising absorber designs']::text[],'advanced','Lambda'' = 2 * V_pore / S_pore','The thermal characteristic length equals two times the total pore (fluid) volume divided by the total pore-wall surface area.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal characteristic length');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5405282-6a01-4320-9f5f-d1a0043b71cd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5405282-6a01-4320-9f5f-d1a0043b71cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5405282-6a01-4320-9f5f-d1a0043b71cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f55d46e-6735-4e66-b4b4-1681638f27ef','Thermoacoustic instability','Thermoacoustic instability is a self-excited oscillation in which unsteady heat release couples with acoustic pressure waves in a confined system such as a combustor. By the Rayleigh criterion the oscillation grows when heat is added in phase with the pressure fluctuation.','In some burners, heat and sound feed each other. When heat is released as pressure peaks, the sound grows. This can become a loud, damaging oscillation. It is called thermoacoustic instability.','Understanding it lets engineers predict and prevent damaging combustion-driven oscillations.','A combustion engineer checks whether the flame''s heat release is in phase with the chamber pressure; if so, they add damping or shift the flame to break the feedback loop.','Thermoacoustics',ARRAY['Combustion noise','Rayleigh criterion','Standing wave','Screech tone']::text[],ARRAY['UNSAFE: dismissing combustor ''rumble'' as harmless, when thermoacoustic oscillations can grow to structurally damaging levels','Confusing the Rayleigh criterion''s phase condition with mere loudness','Assuming more damping always cures it without addressing the heat-release phase','Treating the flame and the acoustics as independent']::text[],ARRAY['Gas-turbine combustor development','Rocket-engine combustion stability','Domestic boiler and burner noise','Rijke-tube demonstrations']::text[],'advanced','integral over cycle of p''(t)*q''(t) dt > 0   (Rayleigh criterion for growth)','Oscillations grow when, over one cycle, the time integral of the pressure fluctuation multiplied by the heat-release fluctuation is positive.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermoacoustic instability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f55d46e-6735-4e66-b4b4-1681638f27ef','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f55d46e-6735-4e66-b4b4-1681638f27ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f55d46e-6735-4e66-b4b4-1681638f27ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66783489-80fc-42c5-8ac8-4aa4f4d2f379','Topological acoustics','Topological acoustics applies the mathematics of topological band theory to classical sound and elastic waves, engineering structured media whose band structure carries topological invariants. These designs support edge or interface modes that are robust against defects and back-scattering, mirroring quantum topological insulators.','This field borrows ideas from quantum physics for sound. Engineers build patterned materials that guide sound along edges. These guided paths keep working even with small flaws. The sound resists bouncing backward.','It exists to create acoustic waveguides and devices whose wave paths are protected by the structure''s topology, so defects and bends do not scatter the sound.','A researcher designs a lattice of resonators so a sound mode travels along its boundary and stays confined even when the path turns sharp corners.','Emerging Acoustics',ARRAY['Wave-based method','Vibroacoustics','Transfer-matrix method','Torsional wave']::text[],ARRAY['Assuming topological protection removes all loss; it suppresses back-scattering, not material absorption.','Believing edge modes appear at any frequency, when they exist only inside a topological band gap.','Confusing the topological invariant of the medium with the geometry of a single resonator.']::text[],ARRAY['Designing a robust acoustic waveguide that tolerates fabrication defects.','Demonstrating one-way sound transport in a metamaterial lattice.','Exploring vibration isolation using protected interface modes.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Topological acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66783489-80fc-42c5-8ac8-4aa4f4d2f379','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66783489-80fc-42c5-8ac8-4aa4f4d2f379') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66783489-80fc-42c5-8ac8-4aa4f4d2f379');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea3721a1-9ab3-4171-ad34-746158684871','Torsional mode','A torsional mode is a natural vibration mode of a shaft, bar, or structure in which cross-sections rotate (twist) about the member''s axis rather than translate. For a uniform circular shaft the modal frequencies form a harmonic series set by the torsional wave speed and the boundary conditions.','A torsional mode is a twisting vibration. The parts of a rod rotate back and forth around its length. Each mode has its own natural frequency. The frequencies depend on the material and the length.','Identifying torsional modes lets engineers predict twisting resonances in shafts and structures so they can be avoided or damped.','For a 1 m free-free steel shaft with torsional wave speed about 3170 m/s, the first torsional mode is f = c/(2L) = 3170/2 = 1585 Hz.','Structural Vibration',ARRAY['Torsional wave','Underdamping','Vibroacoustics','Vibroacoustic coupling']::text[],ARRAY['Confusing a torsional (twisting) mode with a bending or longitudinal mode.','Using the longitudinal bar speed instead of the shear-based torsional speed to find the frequency.','Forgetting that boundary conditions (free, fixed) shift the modal frequencies.']::text[],ARRAY['Diagnosing a twisting resonance in a rotating drive shaft.','Analysing vibration of a loudspeaker or motor spindle.','Predicting resonances of a metal bar used as a sound source.']::text[],'advanced','f_n = n * c_t / (2*L),  c_t = sqrt(G/rho)','The nth torsional natural frequency equals n times the torsional wave speed divided by twice the length; the torsional wave speed is the square root of the shear modulus divided by density.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Torsional mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea3721a1-9ab3-4171-ad34-746158684871','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea3721a1-9ab3-4171-ad34-746158684871') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea3721a1-9ab3-4171-ad34-746158684871');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73e0cc39-321a-4553-ba08-03286c37dac3','Torsional wave','A torsional wave is an elastic wave travelling along a bar or shaft in which the disturbance is a rotational (twisting) displacement of cross-sections about the axis. In a uniform circular rod it propagates non-dispersively at the shear (torsional) wave speed, the square root of shear modulus over density.','A torsional wave is a twist that travels along a rod. As it passes, each slice of the rod rotates a little. In a round rod its speed does not depend on frequency. That speed is set by the material stiffness in shear.','Understanding torsional waves lets engineers predict how twisting disturbances travel in shafts and rods, which matters for drivelines and ultrasonic devices.','For steel with shear modulus 79 GPa and density 7850 kg/m^3, the torsional wave speed is sqrt(79e9/7850) about 3170 m/s.','Structural Vibration',ARRAY['Torsional mode','Vibroacoustics','Transfer mobility','Wave steepening']::text[],ARRAY['Assuming a torsional wave travels at the longitudinal bar speed; it uses the shear modulus, so it is slower.','Treating a circular-rod torsional wave as dispersive when it is essentially non-dispersive.','Confusing torsional (twist) motion with flexural (bending) motion.']::text[],ARRAY['Modelling twist propagation in a rotating shaft.','Designing torsional ultrasonic transducers or horns.','Analysing wave speeds in a solid rod for material testing.']::text[],'advanced','c_t = sqrt(G/rho)','The torsional wave speed in a circular rod equals the square root of the shear modulus divided by the density.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Torsional wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73e0cc39-321a-4553-ba08-03286c37dac3','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73e0cc39-321a-4553-ba08-03286c37dac3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73e0cc39-321a-4553-ba08-03286c37dac3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42a9f112-afd1-46e5-afb4-ed0e0e7812c8','Tortuosity','Tortuosity (high-frequency limit, alpha-infinity) is a dimensionless parameter of a porous material describing how much the fluid''s microscopic flow path is bent and lengthened relative to a straight line through the frame. It is one of the visco-inertial parameters of the Johnson-Koplik-Dashen model and is always greater than or equal to one.','Tortuosity says how twisty the air paths are inside a porous absorber. A value of one means straight channels. Larger values mean the air must weave around the fibres. It helps predict how the material absorbs high-frequency sound.','It captures the inertial effect of a winding pore network, and is a required input to porous-absorber models used for sound absorption prediction.','For an open foam, picture the sound path winding through the pores instead of crossing straight through. That winding path is longer than the straight-line thickness. When the mean path is about 1.02x the direct distance, the tortuosity is alpha ~ (1.02)^2 = 1.04.','Material Acoustics',ARRAY['Viscous characteristic length','Transfer-matrix method','Vibroacoustics','Wave-based method']::text[],ARRAY['Thinking tortuosity can be below one; the winding path makes it at least one.','Confusing tortuosity with porosity or with airflow resistivity.','Assuming tortuosity alone sets absorption; the characteristic lengths and resistivity also matter.']::text[],ARRAY['Fitting a Johnson-Champoux-Allard model to a measured absorber.','Comparing high-frequency absorption of two foams.','Characterising a new porous material for acoustic panels.']::text[],'advanced','alpha_inf = phi * F   (F = formation factor = sigma_0/sigma_eff)','The high-frequency tortuosity equals the open porosity times the electrical formation factor, where the formation factor is the ratio of the saturating fluid conductivity to the effective conductivity of the saturated sample.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tortuosity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42a9f112-afd1-46e5-afb4-ed0e0e7812c8','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42a9f112-afd1-46e5-afb4-ed0e0e7812c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42a9f112-afd1-46e5-afb4-ed0e0e7812c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b54a5c9-5ab2-4bf2-a96b-eea377edcb6e','Trailing-edge noise','Trailing-edge noise is broadband aeroacoustic sound produced when the turbulent boundary layer over an airfoil convects past its sharp trailing edge, which scatters the near-field turbulent pressure into efficient far-field sound. For a large chord in subsonic flow the radiated acoustic power scales roughly with the fifth power of flow speed.','Trailing-edge noise is the swishing sound from the back edge of a blade or wing. Turbulent air flows over the surface and reaches the sharp edge. The edge turns that nearby turbulence into radiated sound. Faster flow makes it much louder.','It explains a dominant broadband noise source for fans, wind turbines, and airfoils, guiding quieter edge designs such as serrations.','Because power scales as U^5, doubling the flow speed raises the level by about 10*log10(2^5) = 15 dB.','Aeroacoustics',ARRAY['Turbulent boundary-layer noise','Vortex shedding','Turbulent pressure spectrum','Wind-induced microphone noise']::text[],ARRAY['Confusing broadband trailing-edge noise with tonal vortex-shedding (bluff-body) noise.','Applying the small-airfoil dipole U^6 law when the large-chord U^5 edge law is appropriate.','Assuming a razor-sharp edge is silent; the edge is precisely what scatters the turbulence to sound.']::text[],ARRAY['Explaining wind-turbine blade broadband noise.','Reducing cooling-fan noise with serrated trailing edges.','Predicting airfoil self-noise in a design study.']::text[],'advanced','I_TE  proportional to  U^5   (large chord, subsonic; ~ M^5)','For a chord large compared with the wavelength, the radiated trailing-edge acoustic intensity is proportional to the fifth power of the flow speed.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Trailing-edge noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b54a5c9-5ab2-4bf2-a96b-eea377edcb6e','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b54a5c9-5ab2-4bf2-a96b-eea377edcb6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b54a5c9-5ab2-4bf2-a96b-eea377edcb6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a170fc67-aeab-4eb0-80c2-c970d3a08dd2','Transfer mobility','Transfer (cross) mobility is a frequency-response function equal to the complex velocity response at one point of a structure divided by the harmonic force applied at a different point. It is a component of the mobility matrix and, by reciprocity, the transfer mobility between two points is symmetric.','Transfer mobility links a push at one spot to the motion at another spot. You divide the measured velocity by the applied force. It changes with frequency. It tells how vibration spreads through a structure.','It quantifies how a force at one location drives motion elsewhere, which is essential for predicting vibration transmission and structure-borne sound.','If a 2 N force at point A drives 0.01 m/s velocity at point B, the transfer mobility is 0.01/2 = 0.005 (m/s)/N at that frequency.','Structural Vibration',ARRAY['Vibroacoustics','Vibroacoustic coupling','Transfer-matrix method','Torsional mode']::text[],ARRAY['Confusing transfer (point-to-point) mobility with driving-point mobility at a single location.','Forgetting mobility is complex and frequency dependent, not a single scalar.','Ignoring reciprocity, which requires transfer mobility to be symmetric between the two points.']::text[],ARRAY['Measuring vibration paths from a machine mount to a panel.','Building a mobility model of a structure for transmission analysis.','Locating structure-borne noise routes in a chassis.']::text[],'advanced','Y_ij(omega) = v_i(omega) / F_j(omega),  i != j','Transfer mobility is the complex velocity at response point i divided by the harmonic force applied at excitation point j, with the two points different.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer mobility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a170fc67-aeab-4eb0-80c2-c970d3a08dd2','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a170fc67-aeab-4eb0-80c2-c970d3a08dd2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a170fc67-aeab-4eb0-80c2-c970d3a08dd2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7cf6c4ff-6e25-4866-8967-16b66dad6cd8','Transfer-matrix method','The transfer-matrix method models a layered or one-dimensional acoustic system by representing each layer or element as a matrix that relates the acoustic state variables (such as pressure and particle velocity) at its two faces. Cascading the layer matrices gives an overall transfer matrix from which absorption, transmission loss, or muffler performance is computed.','This method breaks a layered system into simple blocks. Each block gets a small matrix. You multiply the matrices in order to model the whole stack. It quickly predicts absorption or transmission of the layers.','It gives a fast, exact one-dimensional way to predict the acoustic behaviour of multilayer absorbers, partitions, and duct/muffler elements.','An engineer cascades matrices for an air gap, a porous layer, and a facing to compute a multilayer panel''s normal-incidence absorption.','Modelling Method',ARRAY['Transmission-line matrix','Wave-based method','Tortuosity','Viscous characteristic length']::text[],ARRAY['Confusing the analytical transfer-matrix method with the numerical transmission-line matrix (TLM) method.','Applying the plane-wave one-dimensional model where oblique incidence or higher modes matter.','Ordering the layer matrices incorrectly when cascading them.']::text[],ARRAY['Predicting transmission loss of a multilayer wall.','Designing a layered porous absorber with an air gap.','Modelling a reactive muffler element chain.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer-matrix method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7cf6c4ff-6e25-4866-8967-16b66dad6cd8','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7cf6c4ff-6e25-4866-8967-16b66dad6cd8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7cf6c4ff-6e25-4866-8967-16b66dad6cd8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8dacad6c-c623-4041-a5a2-62f6737e98ff','Transmission-line matrix','The transmission-line matrix (TLM) method is a time-domain numerical technique that models wave propagation by discretising space into a mesh of interconnected transmission lines whose junctions scatter and connect voltage/pressure pulses. Originally developed for electromagnetics, it is applied to acoustics because voltage and current map onto sound pressure and volume velocity.','TLM is a computer method for simulating waves in time. Space becomes a grid of tiny connected lines. Pulses scatter at each junction and pass to neighbours. It can model how sound spreads through a space.','It provides a stable time-domain scheme for simulating acoustic wave propagation and scattering in complex geometries using a network analogue.','A modeller meshes a small enclosure into a TLM grid and injects a pulse to compute its impulse response.','Modelling Method',ARRAY['Transfer-matrix method','Wave-based method','Vibroacoustics','Topological acoustics']::text[],ARRAY['Confusing the numerical TLM with the analytical transfer-matrix method despite the similar names.','Choosing too coarse a mesh, so high frequencies are poorly resolved.','Ignoring numerical dispersion introduced by the discrete grid.']::text[],ARRAY['Simulating an enclosure''s impulse response in the time domain.','Modelling acoustic scattering around an obstacle.','Teaching wave propagation with a network analogue.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transmission-line matrix');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8dacad6c-c623-4041-a5a2-62f6737e98ff','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8dacad6c-c623-4041-a5a2-62f6737e98ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8dacad6c-c623-4041-a5a2-62f6737e98ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7da3d2f0-a474-4cfe-aad5-cb82286a6527','Turbulent boundary-layer noise','Turbulent boundary-layer noise is sound and structural excitation arising from the fluctuating wall pressures beneath a turbulent boundary layer flowing over a surface. These random pressures both radiate weakly as sound and drive the surface into vibration, an important source of interior noise in vehicles and aircraft.','When fast air flows over a surface it forms a turbulent layer. That layer presses on the wall with random, shifting pressure. This shakes the panel and makes noise. It is a big source of cabin noise in cars and planes.','It identifies the flow-driven pressure field that excites panels, so engineers can predict and control flow-induced interior noise.','A technician measures wall-pressure spectra on a fuselage panel to estimate how the turbulent boundary layer drives cabin noise.','Aeroacoustics',ARRAY['Turbulent pressure spectrum','Trailing-edge noise','Wind-induced microphone noise','Vibroacoustic coupling']::text[],ARRAY['Treating the wall-pressure field as pure sound; most of it is a non-radiating convected (hydrodynamic) pressure.','Ignoring that the panel acts as a wavenumber filter of the pressure field.','Confusing boundary-layer excitation with tonal vortex-shedding sources.']::text[],ARRAY['Predicting cabin noise from fuselage flow.','Measuring wall-pressure spectra in a wind tunnel.','Designing panels to resist flow-induced vibration.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Turbulent boundary-layer noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7da3d2f0-a474-4cfe-aad5-cb82286a6527','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7da3d2f0-a474-4cfe-aad5-cb82286a6527') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7da3d2f0-a474-4cfe-aad5-cb82286a6527');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fc35a038-cbc3-4072-8ded-26f9d3b60c53','Turbulent pressure spectrum','The turbulent (wall) pressure spectrum describes the distribution of fluctuating surface pressure beneath a turbulent boundary layer as a function of frequency and, in the wavenumber-frequency form, of streamwise and spanwise wavenumber. Separable empirical models such as the Corcos model represent its convective ridge, where energy peaks at the convective wavenumber.','This spectrum shows how the random wall pressure spreads across frequencies and wave patterns. Most energy travels with the flow at a convective speed. The Corcos model is a common way to describe it. Engineers use it to predict panel excitation.','It provides the statistical input needed to predict how a turbulent boundary layer excites a structure and radiates flow noise.','The convective ridge sits at wavenumber k_c = omega/U_c; for omega = 6280 rad/s and convection speed 60 m/s, k_c is about 105 rad/m.','Aeroacoustics',ARRAY['Turbulent boundary-layer noise','Trailing-edge noise','Vibroacoustic coupling','Wind-noise susceptibility']::text[],ARRAY['Using only the frequency spectrum and ignoring the wavenumber content that a panel filters.','Assuming the acoustic wavenumber dominates when the convective ridge carries most energy.','Applying the Corcos model outside the flat-plate, zero-pressure-gradient conditions it fits.']::text[],ARRAY['Feeding a Corcos spectrum into a panel-response model.','Interpreting wall-pressure measurements from a boundary layer.','Estimating flow-induced noise on a submerged hull.']::text[],'advanced','k_c = omega / U_c','The convective wavenumber, where the wall-pressure spectrum peaks, equals the angular frequency divided by the eddy convection speed.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Turbulent pressure spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fc35a038-cbc3-4072-8ded-26f9d3b60c53','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fc35a038-cbc3-4072-8ded-26f9d3b60c53') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fc35a038-cbc3-4072-8ded-26f9d3b60c53');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c462e51-e7b0-45b2-b35a-db287d253be7','Underdamping','Underdamping is the condition of a second-order oscillatory system whose damping ratio is less than one, so a disturbance decays through oscillations rather than returning monotonically to rest. The system oscillates at a damped natural frequency slightly below its undamped natural frequency.','An underdamped system rings before it settles. It swings past rest several times with shrinking swings. The damping is weak, below the critical amount. Most audio resonators behave this way.','It describes the common ringing behaviour of lightly damped resonators, letting engineers relate decay rate and damped frequency to the damping ratio.','For a damping ratio 0.05 and undamped frequency 100 rad/s, the damped frequency is 100*sqrt(1-0.05^2) about 99.9 rad/s.','Vibration Fundamentals',ARRAY['Torsional mode','Vibroacoustics','Torsional wave','Transfer mobility']::text[],ARRAY['Confusing underdamping (ringing) with critical or overdamping (no oscillation).','Assuming the damped frequency equals the undamped one for light damping without checking.','Reading the decay envelope as the oscillation frequency.']::text[],ARRAY['Analysing the ring-down of a loudspeaker cone or panel.','Tuning a resonator''s decay time.','Interpreting a decaying impulse response.']::text[],'intermediate','omega_d = omega_n * sqrt(1 - zeta^2),  zeta < 1','The damped natural frequency equals the undamped natural frequency times the square root of one minus the damping ratio squared, valid when the damping ratio is below one.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Underdamping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c462e51-e7b0-45b2-b35a-db287d253be7','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c462e51-e7b0-45b2-b35a-db287d253be7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c462e51-e7b0-45b2-b35a-db287d253be7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ec02ef7-303e-46c2-95ae-aba1c676401a','Vibroacoustic coupling','Vibroacoustic coupling is the two-way interaction between a vibrating structure and an adjacent acoustic fluid, in which structural motion radiates and drives sound while the acoustic pressure loads and reacts back on the structure. The strength of the coupling depends on the match between structural and acoustic mode shapes and frequencies.','Vibroacoustic coupling is the give-and-take between a vibrating surface and the air. The surface pushes the air and makes sound. The air pressure also pushes back on the surface. Each affects the other.','It captures the mutual loading between structure and fluid, which must be modelled to predict sound radiation and transmission accurately.','An engineer includes fluid loading when a panel radiates into a small cavity, because the cavity pressure noticeably changes the panel''s response.','Vibroacoustics',ARRAY['Vibroacoustics','Transfer mobility','Wave-based method','Turbulent boundary-layer noise']::text[],ARRAY['Treating the structure and fluid separately when strong coupling makes them interact.','Assuming coupling is always weak; in light fluids it is weak, but in water or small cavities it is strong.','Ignoring the modal frequency and shape match that governs coupling strength.']::text[],ARRAY['Modelling a loudspeaker cone radiating into a sealed box.','Predicting sound transmission through a partition into a room.','Analysing a plate submerged in water.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibroacoustic coupling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ec02ef7-303e-46c2-95ae-aba1c676401a','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ec02ef7-303e-46c2-95ae-aba1c676401a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ec02ef7-303e-46c2-95ae-aba1c676401a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2339854-4461-4e24-87ef-ebc9c74ddfb0','Vibroacoustics','Vibroacoustics is the branch of acoustics concerned with the coupled behaviour of structural vibration and the sound it radiates, transmits, or receives. It combines structural dynamics and acoustics to predict noise from vibrating machinery, panels, and enclosures.','Vibroacoustics studies how vibrating structures make and carry sound. It joins two subjects: how things vibrate and how they radiate noise. Engineers use it to make machines and panels quieter.','It provides the framework for predicting and controlling structure-borne sound and radiated noise from vibrating systems.','A technician uses vibroacoustic analysis to trace a rattling panel''s radiated noise back to a machine''s vibration.','Vibroacoustics',ARRAY['Vibroacoustic coupling','Transfer mobility','Wave-based method','Torsional mode']::text[],ARRAY['Assuming vibroacoustics is only about airborne sound; structure-borne paths are central.','Neglecting fluid loading when it materially changes the structural response.','Treating radiation efficiency as constant across frequency.']::text[],ARRAY['Reducing radiated noise from a machine housing.','Modelling sound transmission through a vehicle floor.','Predicting panel noise in an appliance.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibroacoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2339854-4461-4e24-87ef-ebc9c74ddfb0','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2339854-4461-4e24-87ef-ebc9c74ddfb0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2339854-4461-4e24-87ef-ebc9c74ddfb0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '00c09fa7-52cc-42cd-99b9-969a3eb7e7bd','Viscous characteristic length','The viscous characteristic length (Lambda) is a geometric parameter of a porous material representing an effective pore radius weighted toward the narrow, high-velocity constrictions where viscous losses dominate at high frequency. It is defined by a ratio of a volume integral to a surface integral of the squared microscopic velocity field and appears in the Johnson-Koplik-Dashen model.','This length is an effective pore size for viscous losses. It leans toward the tight channels where air moves fastest. Those spots cause most of the friction loss. It helps models predict high-frequency absorption.','It quantifies the pore geometry controlling viscous drag at high frequency, a required input to accurate porous-absorber models.','A characterisation lab fits Lambda together with tortuosity and resistivity to match a foam''s measured surface impedance.','Material Acoustics',ARRAY['Tortuosity','Transfer-matrix method','Vibroacoustics','Wave-based method']::text[],ARRAY['Confusing the viscous characteristic length with the thermal characteristic length (Lambda-prime), which is usually larger.','Treating Lambda as a simple average pore radius rather than a velocity-weighted one.','Assuming Lambda alone sets absorption without tortuosity and resistivity.']::text[],ARRAY['Fitting a Johnson-Champoux-Allard model to impedance-tube data.','Comparing viscous behaviour of two foams.','Building a material database for absorber design.']::text[],'advanced','Lambda = 2 * ( integral_V |v|^2 dV ) / ( integral_S |v|^2 dS )','The viscous characteristic length equals twice the volume integral of the squared microscopic velocity divided by the surface integral of the squared velocity over the pore walls.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Viscous characteristic length');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '00c09fa7-52cc-42cd-99b9-969a3eb7e7bd','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='00c09fa7-52cc-42cd-99b9-969a3eb7e7bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='00c09fa7-52cc-42cd-99b9-969a3eb7e7bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d198e41-68f2-4c6c-a275-5a31006aa79d','Vortex shedding','Vortex shedding is the periodic detachment of vortices from alternate sides of a bluff body in a flow, forming a Karman vortex street and producing a fluctuating side force. The shedding occurs at a frequency set by the Strouhal number, and can radiate a tonal Aeolian sound.','When air flows past a rod, swirls peel off each side in turn. They alternate in a steady rhythm. This pushes the rod sideways and can whistle. The pitch depends on flow speed and rod size.','It explains the tonal whistling and oscillating loads from bluff bodies in flow, needed to predict Aeolian tones and flow-induced vibration.','For a 10 mm cylinder in a 10 m/s flow with Strouhal number 0.2, the shedding frequency is f = 0.2*10/0.01 = 200 Hz.','Aeroacoustics',ARRAY['Trailing-edge noise','Turbulent boundary-layer noise','Wind-induced microphone noise','Underdamping']::text[],ARRAY['Confusing tonal vortex-shedding noise with broadband trailing-edge noise.','Assuming the Strouhal number is exactly 0.2 for all bodies and Reynolds numbers.','Ignoring lock-in, where structural resonance captures the shedding frequency.']::text[],ARRAY['Predicting the whistle from a cable or antenna in wind.','Explaining Aeolian tones from wires.','Assessing flow-induced vibration of a cylinder.']::text[],'intermediate','f = St * U / d','The vortex-shedding frequency equals the Strouhal number times the flow speed divided by the body''s cross-stream dimension.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vortex shedding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d198e41-68f2-4c6c-a275-5a31006aa79d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d198e41-68f2-4c6c-a275-5a31006aa79d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d198e41-68f2-4c6c-a275-5a31006aa79d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eaddb4a3-c57a-49ef-ba6c-0e041e84d4c2','Wave steepening','Wave steepening is the progressive nonlinear distortion of a finite-amplitude sound wave in which higher-pressure (higher local sound speed and particle velocity) parts advance faster than lower-pressure parts, so the waveform''s leading front becomes ever steeper and tends toward a shock. In a lossless fluid a shock forms at a finite distance set by the amplitude, frequency, and coefficient of nonlinearity.','A loud wave changes shape as it travels. The high-pressure part moves a bit faster than the low-pressure part. So the front edge gets steeper and steeper. Eventually it can turn into a shock.','It explains why intense sound distorts and forms shocks, which matters for high-power ultrasound, sonic booms, and harmonic generation.','For an intense 20 kHz plane wave in air at 1000 Pa (beta about 1.2), the shock forms at x = rho*c^3/(beta*omega*p0) about 0.32 m.','Nonlinear Acoustics',ARRAY['Weakly nonlinear acoustics','Torsional wave','Turbulent pressure spectrum','Vibroacoustics']::text[],ARRAY['Assuming sound always travels linearly; at high amplitude it steepens and distorts.','Thinking the steepening distance is fixed; it shrinks with higher amplitude and frequency.','UNSAFE: assuming high-intensity ultrasound or shock fields are harmless to hands, eyes, or hearing; focused fields can cause burns, cavitation damage, and injury, so follow exposure limits and shielding.']::text[],ARRAY['Predicting harmonic generation in a high-power ultrasound beam.','Explaining distortion of intense finite-amplitude waves.','Analysing shock formation ahead of a loud transient.']::text[],'advanced','x_bar = 1 / (beta * epsilon * k) = rho_0 * c_0^3 / (beta * omega * p_0),  epsilon = u_0/c_0','The plane-wave shock-formation distance equals the reference density times the small-signal sound speed cubed, divided by the product of the coefficient of nonlinearity, the angular frequency, and the pressure amplitude.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave steepening');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eaddb4a3-c57a-49ef-ba6c-0e041e84d4c2','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eaddb4a3-c57a-49ef-ba6c-0e041e84d4c2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eaddb4a3-c57a-49ef-ba6c-0e041e84d4c2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0347d585-4604-4644-ac16-14dbd0bb6bb5','Wave-based method','A wave-based method is a deterministic prediction technique for steady-state vibro-acoustic problems that expands the field in exact solutions of the governing wave equation (Trefftz functions) rather than in element-based shape functions. Because the basis functions satisfy the field equation, the approach is efficient in the low- and mid-frequency range where element counts would otherwise be large.','A wave-based method solves sound and vibration using exact wave shapes. It does not chop the space into many tiny elements. That makes it efficient for low and middle frequencies. It suits enclosed vibro-acoustic problems.','It fills the mid-frequency gap between element methods and statistical methods, giving accurate deterministic results with fewer unknowns.','An analyst uses a wave-based model of a cavity to predict its coupled response up to mid frequencies without a fine mesh.','Modelling Method',ARRAY['Transfer-matrix method','Transmission-line matrix','Vibroacoustics','Topological acoustics']::text[],ARRAY['Confusing the wave-based method with wave field synthesis or with ray methods.','Applying it to arbitrary irregular geometries without the required convex subdomain decomposition.','Assuming it replaces finite elements at all frequencies; it targets low to mid frequencies.']::text[],ARRAY['Predicting coupled cavity-structure response at mid frequencies.','Modelling an enclosure where finite-element meshes become too large.','Comparing deterministic mid-frequency methods.']::text[],'advanced',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave-based method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0347d585-4604-4644-ac16-14dbd0bb6bb5','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0347d585-4604-4644-ac16-14dbd0bb6bb5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0347d585-4604-4644-ac16-14dbd0bb6bb5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '78ca69ab-fca2-42f5-8332-350100bda730','Weakly nonlinear acoustics','Weakly nonlinear acoustics treats finite-amplitude sound whose nonlinear effects are small but cumulative, retaining second-order terms so that phenomena like harmonic generation and gradual waveform distortion appear. The nonlinearity is characterised by the coefficient of nonlinearity beta, and model equations such as the Burgers and KZK equations describe the slow evolution.','This is the study of fairly loud sound where small nonlinear effects build up. The wave slowly grows extra harmonics and changes shape. A single number, beta, sets how strong the effect is. Special equations track the slow change.','It provides the tractable framework for modelling moderate-amplitude distortion, harmonic growth, and beam nonlinearity before full shocks dominate.','The coefficient of nonlinearity is beta = 1 + B/(2A); for air (B/A about 0.4) beta is about 1.2, while for water (B/A about 5) beta is about 3.5.','Nonlinear Acoustics',ARRAY['Wave steepening','Torsional wave','Turbulent pressure spectrum','Vibroacoustics']::text[],ARRAY['Assuming linear superposition holds at high amplitude, when harmonics are generated.','Confusing the parameter B/A with the coefficient of nonlinearity beta, which is 1 + B/(2A).','Applying weakly nonlinear theory once a strong shock has already formed.']::text[],ARRAY['Modelling harmonic generation in a focused ultrasound beam.','Predicting distortion of a moderately intense wave.','Deriving the Burgers equation for a lossy nonlinear wave.']::text[],'advanced','beta = 1 + B/(2A)','The coefficient of nonlinearity equals one plus half the ratio of the fluid''s second-order parameter B to its first-order parameter A.','d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Weakly nonlinear acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '78ca69ab-fca2-42f5-8332-350100bda730','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='78ca69ab-fca2-42f5-8332-350100bda730') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='78ca69ab-fca2-42f5-8332-350100bda730');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f587bf4d-138a-45f2-be17-9b5cb5b1f59d','Wind-induced microphone noise','Wind-induced microphone noise is unwanted low-frequency output produced when turbulent airflow, rather than a propagating sound wave, creates fluctuating pressures directly at a microphone''s diaphragm. It is a non-acoustic, near-field pressure effect, usually strongest at low frequencies, and is reduced with windscreens and blimps.','Wind noise is the rumble a mic makes in a breeze. It is not real sound arriving at the mic. It comes from turbulent air pushing on the diaphragm. Foam or fur windshields cut it down.','Understanding it lets technicians distinguish flow-induced rumble from true sound and choose the right wind protection.','For outdoor recording a technician fits a foam windscreen or furry blimp to lower wind-induced low-frequency noise.','Measurement Practice',ARRAY['Wind-noise susceptibility','Turbulent boundary-layer noise','Turbulent pressure spectrum','Vortex shedding']::text[],ARRAY['Treating wind noise as real acoustic signal instead of a flow artefact.','Relying on a low-cut filter alone when a windscreen is needed at the source.','Assuming an indoor pop filter gives outdoor wind protection.']::text[],ARRAY['Recording dialogue outdoors on a breezy day.','Making outdoor sound-level measurements in wind.','Choosing a blimp and fur cover for a boom microphone.']::text[],'beginner',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind-induced microphone noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f587bf4d-138a-45f2-be17-9b5cb5b1f59d','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f587bf4d-138a-45f2-be17-9b5cb5b1f59d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f587bf4d-138a-45f2-be17-9b5cb5b1f59d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6b66309-8ca1-4514-aa71-fedf8892caa8','Wind-noise susceptibility','Wind-noise susceptibility is a measure of how much unwanted output a microphone (with or without a windscreen) produces for a given airflow condition, allowing microphones and wind-protection systems to be compared. It is characterised by measuring the flow-induced output under controlled wind or turbulence and is a key selection criterion for outdoor and measurement microphones.','Wind-noise susceptibility says how easily a mic picks up wind rumble. A low value means the mic stays quieter in a breeze. It lets you compare mics and windshields fairly. It matters most for outdoor use.','It provides a comparative figure of merit for a microphone''s resistance to flow-induced noise, guiding equipment choice and windscreen design.','A technician compares the rated wind-induced noise level of two measurement microphones before choosing one for outdoor monitoring.','Measurement Practice',ARRAY['Wind-induced microphone noise','Turbulent pressure spectrum','Turbulent boundary-layer noise','Vortex shedding']::text[],ARRAY['Confusing wind-noise susceptibility with acoustic self-noise, which is measured in still air.','Comparing figures taken under different wind speeds or windscreen conditions.','Assuming a smaller diaphragm is always less susceptible without checking measured data.']::text[],ARRAY['Selecting a measurement microphone for outdoor noise monitoring.','Rating windscreen performance across products.','Specifying microphones for a windy installation.']::text[],'intermediate',NULL,NULL,'d289abb3-d751-4a49-8df7-ea686bcc1986' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind-noise susceptibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6b66309-8ca1-4514-aa71-fedf8892caa8','d289abb3-d751-4a49-8df7-ea686bcc1986',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6b66309-8ca1-4514-aa71-fedf8892caa8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6b66309-8ca1-4514-aa71-fedf8892caa8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e6ed413-8da7-4c17-96bc-95c0ffe3151e','Absorber thickness versus frequency','A porous absorber works best where its physical thickness is a meaningful fraction of the wavelength, so thicker material absorbs progressively lower frequencies. As a working guide, a porous layer becomes strongly effective at and above the frequency whose quarter-wavelength equals the layer thickness.','Thick soft panels soak up low sounds. Thin panels only catch high sounds. Low sounds have long waves. So you need deeper material to trap them well.','It explains why a fixed thickness of absorbing material sets a lower frequency limit on useful absorption.','For a porous panel about 0.10 m thick, the quarter-wavelength rule f = c/(4t) gives roughly 343/(4x0.10) = 858 Hz as the point of strong absorption, so lows below that need more depth or an air gap.','Absorption',ARRAY['Air-gap effects behind absorbers','Diaphragmatic absorption','Boundary impedance','Acoustic resonance']::text[],ARRAY['Expecting a thin foam panel to absorb bass frequencies.','Treating the quarter-wavelength point as a hard cutoff rather than a gradual roll-off.','Ignoring that mounting distance from the wall shifts the effective low-frequency limit.']::text[],ARRAY['Choosing panel depth to control low-mid buildup in a control room.','Deciding whether 25 mm foam will tame a room''s bass problem.','Specifying absorber depth for broadband treatment in a studio.']::text[],'intermediate','f = c / (4 t)','The lower frequency of strong porous absorption is the speed of sound divided by four times the material thickness.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absorber thickness versus frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e6ed413-8da7-4c17-96bc-95c0ffe3151e','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e6ed413-8da7-4c17-96bc-95c0ffe3151e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e6ed413-8da7-4c17-96bc-95c0ffe3151e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68d75fd0-d509-4c58-8ccc-4284e010e564','Acoustic resonance','Acoustic resonance is the tendency of an air-filled cavity or system to vibrate with large amplitude at particular natural frequencies, where energy stored in air compliance and air-mass inertia exchanges efficiently. At these frequencies even small driving forces produce strong sound pressure.','Every air space has favorite pitches. Push it at one of those pitches and it rings loudly. Rooms, pipes, and boxes all do this. It builds up sound at set frequencies.','It describes how enclosed air stores and releases sound energy at natural frequencies, which underlies room modes and cavity absorbers.','A technician links a boomy note in a small room to an acoustic resonance and adds a tuned absorber to damp that frequency.','Acoustic Behavior',ARRAY['Axial modes','Coupled resonances','Diaphragmatic absorption','Closed-pipe modes']::text[],ARRAY['Confusing acoustic resonance in air with electrical resonance in a circuit.','Assuming resonance means only one frequency, when a cavity has many.','Thinking resonance always causes problems, when it is also used deliberately in absorbers.']::text[],ARRAY['Diagnosing a boomy note in a home studio.','Designing a Helmholtz absorber tuned to a room problem.','Understanding why a duct or pipe colors sound.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68d75fd0-d509-4c58-8ccc-4284e010e564','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68d75fd0-d509-4c58-8ccc-4284e010e564') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68d75fd0-d509-4c58-8ccc-4284e010e564');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a057ee22-9f52-4e16-9152-0492e8dae41a','Air-gap effects behind absorbers','Mounting a porous absorber with an air gap between it and a rigid wall improves low-frequency absorption, because the gap places more of the absorber''s depth near the region of high particle velocity in the standing-wave field. The spaced mounting behaves acoustically like a thicker absorber.','Leave a space behind a soft panel and it grabs lower sounds. At the hard wall the air barely moves. Away from it the air moves fastest. The panel does most work where air moves.','It lets a thin absorber reach lower frequencies without using extra material, by exploiting the standing-wave velocity distribution near a wall.','A technician mounts 50 mm panels on 100 mm standoffs so they absorb usefully well below the frequency they would manage flush to the wall.','Absorption',ARRAY['Absorber thickness versus frequency','Boundary impedance','Diaphragmatic absorption','Diffuse-field assumptions']::text[],ARRAY['Thinking the panel must touch the wall to work.','Assuming the air gap adds absorption at all frequencies equally.','Expecting an arbitrarily large gap to keep improving results without limit.']::text[],ARRAY['Extending bass absorption from thin panels in a small room.','Deciding standoff depth when hanging cloud absorbers.','Retrofitting extra low-frequency control without adding thick traps.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-gap effects behind absorbers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a057ee22-9f52-4e16-9152-0492e8dae41a','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a057ee22-9f52-4e16-9152-0492e8dae41a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a057ee22-9f52-4e16-9152-0492e8dae41a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73e43865-1e3b-4a2c-b2d0-e2dbd4935cbc','Angle of incidence','The angle of incidence is the angle between an incoming sound ray and the line normal (perpendicular) to a surface at the point of contact. It governs how sound reflects, scatters, and is absorbed at a boundary.','Draw a line straight out from a wall. The angle of incidence is how much the incoming sound tilts from that line. A head-on hit is zero. A glancing hit is large.','It provides the reference angle for describing reflection, absorption, and scattering at a surface.','A technician aims a speaker so its first reflection meets a side wall at an angle of incidence that sends the bounce away from the listener.','Geometric Acoustics',ARRAY['Angle of reflection','Early reflections','Boundary impedance','Aperture diffraction']::text[],ARRAY['Measuring the angle from the surface instead of from the normal.','Assuming absorption is the same at all angles of incidence.','Confusing angle of incidence with the angle of reflection, though they are equal.']::text[],ARRAY['Planning speaker aiming and first-reflection points.','Predicting how a wall panel will redirect sound.','Interpreting absorption data measured at normal versus random incidence.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angle of incidence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73e43865-1e3b-4a2c-b2d0-e2dbd4935cbc','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73e43865-1e3b-4a2c-b2d0-e2dbd4935cbc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73e43865-1e3b-4a2c-b2d0-e2dbd4935cbc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0cf0e6fb-da8d-46aa-928b-a7a4bed375c5','Angle of reflection','For specular reflection from a flat, acoustically hard surface large compared to the wavelength, the angle of reflection equals the angle of incidence, both measured from the surface normal and lying in the same plane. This is the acoustic law of reflection.','Sound bounces off a smooth wall like light off a mirror. The bounce leaves at the same angle it arrived. Both angles are measured from a line square to the wall.','It predicts where a smooth surface will send a reflected sound ray, which drives reflection mapping and room geometry design.','Using the mirror rule, a technician finds a side-wall reflection point by locating where incidence and reflection angles are equal between speaker and listener.','Geometric Acoustics',ARRAY['Angle of incidence','Early reflections','Desk reflection','Diffuser design']::text[],ARRAY['Applying the equal-angle rule to surfaces small compared with the wavelength.','Forgetting that rough or shaped surfaces scatter instead of reflecting cleanly.','Measuring reflection angle from the surface rather than the normal.']::text[],ARRAY['Locating first-reflection points with the mirror method.','Designing angled walls to steer reflections in a control room.','Explaining why a hard flat wall creates a distinct echo.']::text[],'beginner','theta_r = theta_i','The angle of reflection equals the angle of incidence, each measured from the surface normal.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angle of reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0cf0e6fb-da8d-46aa-928b-a7a4bed375c5','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0cf0e6fb-da8d-46aa-928b-a7a4bed375c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0cf0e6fb-da8d-46aa-928b-a7a4bed375c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'df6f87b7-405b-4797-9899-bf7e031775f1','Aperture diffraction','Aperture diffraction is the spreading of sound as it passes through an opening, causing the wave to bend around the edges rather than travel in a straight beam. The effect is strong when the wavelength is comparable to or larger than the opening''s size.','Sound passing through a doorway spreads out on the other side. It does not stay a narrow beam. This bending is strongest for low, long-wavelength sounds through small gaps.','It explains how openings, gaps, and edges redirect and spread sound, affecting leakage and coverage.','A technician expects low bass to leak and spread widely through a partly open door, while high frequencies stay more contained.','Wave Behavior',ARRAY['Angle of incidence','Boundary impedance','Diffuser design','Early reflections']::text[],ARRAY['Assuming all frequencies diffract through an opening by the same amount.','Thinking a small gap blocks sound like a solid wall.','Confusing diffraction (bending at edges) with refraction (bending in a medium).']::text[],ARRAY['Predicting sound leakage through a doorway or gap.','Understanding coverage behind an obstacle or barrier.','Explaining why bass escapes an isolation booth more easily than treble.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aperture diffraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'df6f87b7-405b-4797-9899-bf7e031775f1','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='df6f87b7-405b-4797-9899-bf7e031775f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='df6f87b7-405b-4797-9899-bf7e031775f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94fb0ca8-e161-4b41-91a6-23a18689d571','Articulation loss of consonants','Articulation loss of consonants (%ALcons) is a percentage measure of speech intelligibility that estimates how many consonants a listener fails to recognize in a reverberant space. Peutz''s engineering formula relates it to reverberation time, listener distance, room volume, and source directivity; lower percentages mean clearer speech.','Speech clarity often fails on consonants first. This score is the percent of consonants a listener misses. A small percent means clear speech. Long reverb and far seats make it worse.','It gives sound-system designers a way to predict and specify speech clarity in reverberant rooms before installation.','For a room with RT = 1.5 s, volume V = 3000 m^3, directivity Q = 2, at distance D = 8 m, %ALcons = 200 x 8^2 x 1.5^2 / (3000 x 2) = 4.8%, which is good intelligibility; beyond about 3.16 times the critical distance the value caps near 9 x RT.','Speech Intelligibility',ARRAY['Speech transmission index','Clarity metrics','Definition metrics','Center time']::text[],ARRAY['Treating %ALcons as a general audio-quality score rather than a speech metric.','Ignoring the distance cap that applies far from the source.','Forgetting that background noise, not just reverberation, degrades intelligibility.']::text[],ARRAY['Predicting speech clarity in a reverberant church or gymnasium.','Specifying loudspeaker directivity to hit an intelligibility target.','Cross-checking a measured STI value against an ALcons estimate.']::text[],'advanced','%ALcons = 200 * D^2 * RT^2 / (V * Q)   (D <= 3.16*Dc);  %ALcons ~= 9 * RT   (D > 3.16*Dc)','Percentage articulation loss equals two hundred times listener distance squared times reverberation time squared, divided by room volume times source directivity; beyond about 3.16 times the critical distance it levels off near nine times the reverberation time.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Articulation loss of consonants');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94fb0ca8-e161-4b41-91a6-23a18689d571','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94fb0ca8-e161-4b41-91a6-23a18689d571') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94fb0ca8-e161-4b41-91a6-23a18689d571');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a97fb11-c521-449b-980f-6ac40a22e4b3','Atmospheric sound bending','Atmospheric sound bending is the refraction of sound as it travels through air whose temperature or wind speed varies with height, changing the local speed of sound and curving the propagation path. Sound bends toward regions where its speed is lower.','Outdoors the air is not the same everywhere. Temperature and wind change with height. This bends sound up or down as it travels. That is why distant sound carries farther at night.','It explains why outdoor sound propagation curves and why coverage changes with weather, wind, and time of day.','At an outdoor event, a technician expects sound to bend downward and carry far at night, when cooler air near the ground slows sound closer to the surface.','Propagation',ARRAY['Aperture diffraction','Angle of incidence','Conservation of acoustic energy']::text[],ARRAY['Confusing refraction (bending through the medium) with diffraction (bending at edges).','Assuming outdoor coverage is constant regardless of weather.','Ignoring wind gradients, which bend sound differently upwind and downwind.']::text[],ARRAY['Planning coverage for an outdoor concert across a day-night change.','Explaining why a distant train is heard clearly some nights.','Assessing noise complaints that vary with wind direction.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Atmospheric sound bending');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a97fb11-c521-449b-980f-6ac40a22e4b3','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a97fb11-c521-449b-980f-6ac40a22e4b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a97fb11-c521-449b-980f-6ac40a22e4b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5a89fe4c-8fbb-4782-884d-b07afe8a56f3','Axial modes','Axial modes are room resonances formed by sound reflecting between one opposing pair of parallel surfaces, so they involve only one room dimension. They are the strongest standing-wave modes and dominate low-frequency response in small rectangular rooms.','Sound bounces between two facing walls and builds a standing wave. That resonance is an axial mode. It uses only one room dimension. These are the strongest and most audible room modes.','It identifies the dominant low-frequency resonances of a room, which a designer must space out and control.','For a 5 m room dimension, the first axial mode is f = c/(2L) x 1 = 343/(2x5) = 34.3 Hz, with harmonics at 68.6 Hz, 102.9 Hz, and so on.','Room Modes',ARRAY['Acoustic resonance','Closed-pipe modes','Coupled resonances','Diaphragmatic absorption']::text[],ARRAY['Confusing axial modes with weaker tangential and oblique modes.','Assuming only the fundamental matters, ignoring the mode''s harmonic series.','Thinking absorption alone fixes modes without addressing room dimensions.']::text[],ARRAY['Calculating low-frequency resonances for a rectangular studio.','Choosing room dimension ratios to spread modes evenly.','Placing bass traps to control the strongest standing waves.']::text[],'intermediate','f = (c / 2) * (n / L)','An axial mode frequency equals half the speed of sound times the mode number divided by the room dimension between the two parallel surfaces.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Axial modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5a89fe4c-8fbb-4782-884d-b07afe8a56f3','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5a89fe4c-8fbb-4782-884d-b07afe8a56f3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5a89fe4c-8fbb-4782-884d-b07afe8a56f3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e651a82-7580-451d-bc66-9ac16ffea9c7','Bandwidth versus Q','For a resonant system, the quality factor Q is the ratio of the center (resonant) frequency to the bandwidth measured between the half-power (-3 dB) points. High Q means a narrow, sharply tuned resonance; low Q means a broad, heavily damped one.','Q tells you how sharp a resonance is. High Q is narrow and rings a long time. Low Q is broad and dies fast. It is the center frequency divided by the bandwidth.','It quantifies how sharply tuned or damped a resonance, filter, or room mode is, linking frequency selectivity to decay.','A room mode centered at 100 Hz with a -3 dB bandwidth of 5 Hz has Q = 100/5 = 20, a high-Q resonance that rings audibly and needs damping.','Resonance',ARRAY['Acoustic resonance','Axial modes','Diaphragmatic absorption','Energy decay curve']::text[],ARRAY['Measuring bandwidth at the wrong points instead of the -3 dB half-power points.','Assuming higher Q is always better, when room modes want lower Q.','Confusing the acoustic Q of a resonance with a loudspeaker directivity factor Q.']::text[],ARRAY['Describing how sharply a room mode rings.','Setting an equalizer band''s width to match a resonance.','Comparing a lightly damped versus heavily damped absorber.']::text[],'intermediate','Q = f0 / BW','The quality factor equals the resonant center frequency divided by the bandwidth between the two half-power points.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bandwidth versus Q');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e651a82-7580-451d-bc66-9ac16ffea9c7','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e651a82-7580-451d-bc66-9ac16ffea9c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e651a82-7580-451d-bc66-9ac16ffea9c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb4d7e92-cf9d-4642-973f-a0ca1008e8ea','Boundary impedance','Boundary (surface) impedance is the complex ratio of sound pressure to the normal particle velocity at a surface, describing how that surface responds to an incident sound wave. It determines the surface''s reflection factor and absorption coefficient.','A surface pushes back on sound hitting it. Boundary impedance measures that push compared with how fast the air moves. It sets how much sound reflects or is absorbed. Hard walls have very high impedance.','It links a material''s acoustic behavior to how much sound it reflects or absorbs, forming the boundary condition in room-acoustic models.','A technician uses measured surface impedance in an impedance tube to derive a material''s absorption coefficient before specifying treatment.','Boundary Behavior',ARRAY['Angle of incidence','Air-gap effects behind absorbers','Absorber thickness versus frequency','Diffuse-field assumptions']::text[],ARRAY['Confusing surface impedance with the characteristic impedance of air.','Ignoring that impedance is complex and frequency dependent.','Assuming impedance is independent of the angle of incidence.']::text[],ARRAY['Deriving absorption coefficients from impedance-tube measurements.','Setting boundary conditions in a room acoustic simulation.','Comparing how different wall finishes reflect sound.']::text[],'advanced','Z_s = p / u_n','Surface impedance equals the sound pressure at the boundary divided by the particle velocity component normal to the surface.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb4d7e92-cf9d-4642-973f-a0ca1008e8ea','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb4d7e92-cf9d-4642-973f-a0ca1008e8ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb4d7e92-cf9d-4642-973f-a0ca1008e8ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87c22787-f183-451e-9c6a-76f21fd57d3c','C50','C50 is an early-to-late sound energy ratio, in decibels, comparing the impulse-response energy arriving within the first 50 ms to the energy arriving afterward. Standardized as a clarity measure for speech, higher C50 indicates clearer, more intelligible speech.','C50 compares early sound to late sound in a room. The split point is 50 milliseconds. It is tuned for speech. A higher number means clearer talking.','It rates a room''s suitability for speech by weighing useful early energy against blurring late reverberation.','From a measured impulse response, a technician integrates energy before and after 50 ms; a C50 of about +2 dB or higher usually signals good speech clarity.','Clarity Metrics',ARRAY['C80','Definition','Center time','Clarity metrics']::text[],ARRAY['Using the 50 ms speech split when C80 (80 ms) is the music measure.','Reporting C50 without stating the frequency band or averaging.','Assuming a single number captures clarity across all frequencies.']::text[],ARRAY['Assessing speech clarity in a lecture hall or conference room.','Comparing before-and-after treatment for a meeting space.','Tuning a distributed speech-reinforcement system.']::text[],'advanced','C50 = 10 * log10( INT_0^50ms p^2(t) dt / INT_50ms^inf p^2(t) dt )  [dB]','C50 is ten times the base-ten logarithm of the impulse-response energy in the first fifty milliseconds divided by the energy after fifty milliseconds.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='C50');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87c22787-f183-451e-9c6a-76f21fd57d3c','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87c22787-f183-451e-9c6a-76f21fd57d3c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87c22787-f183-451e-9c6a-76f21fd57d3c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aece7da0-70a5-459f-8cdd-0dc5a727610b','C80','C80 (clarity) is the ratio in decibels of the impulse-response energy arriving in the first 80 ms to the energy arriving after 80 ms. Standardized as a music clarity measure, it balances definition against reverberant fullness.','C80 compares early sound to late sound for music. The split point is 80 milliseconds. High values sound clear and defined. Low values sound full but muddy.','It rates how clear or blended music sounds in a hall, trading off detail against reverberant warmth.','From an impulse response, a technician splits energy at 80 ms; concert halls typically target C80 in roughly the -2 to +2 dB range for balanced music clarity.','Clarity Metrics',ARRAY['C50','Definition','Center time','Clarity metrics']::text[],ARRAY['Using the 80 ms music split for a speech assessment instead of C50.','Ignoring that ideal C80 depends on the type of music.','Quoting a single figure without frequency-band detail.']::text[],ARRAY['Evaluating clarity in a concert hall design.','Comparing seats or halls for musical definition.','Balancing clarity against reverberance during hall tuning.']::text[],'advanced','C80 = 10 * log10( INT_0^80ms p^2(t) dt / INT_80ms^inf p^2(t) dt )  [dB]','C80 is ten times the base-ten logarithm of the impulse-response energy in the first eighty milliseconds divided by the energy after eighty milliseconds.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='C80');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aece7da0-70a5-459f-8cdd-0dc5a727610b','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aece7da0-70a5-459f-8cdd-0dc5a727610b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aece7da0-70a5-459f-8cdd-0dc5a727610b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce5ef2b0-15b5-4fd7-9cf1-39528f9433cc','Ceiling-bounce cancellation','Ceiling-bounce cancellation is comb filtering caused when sound reflected from the ceiling arrives at a microphone or listener delayed relative to the direct sound, so certain frequencies partially cancel. The notches fall at frequencies where the path-length difference equals an odd number of half-wavelengths.','Sound reaches you directly and also bounces off the ceiling. The two arrive slightly apart in time. At some pitches they fight and cancel. This carves dips in the frequency response.','It explains a common source of uneven frequency response and hollow coloration in rooms with reflective ceilings.','A technician who hears a hollow tone lowers a boundary microphone or treats the ceiling to remove the delayed reflection causing the cancellation.','Reflections',ARRAY['Early reflections','Desk reflection','Angle of reflection','Echo criterion']::text[],ARRAY['Blaming equipment when the notches come from a reflection path.','Assuming equalization can fully fix position-dependent comb filtering.','Overlooking the ceiling while treating only side walls.']::text[],ARRAY['Diagnosing hollow coloration on a stage microphone.','Deciding whether to treat the ceiling above a mix position.','Explaining response dips that move as the listener moves.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ceiling-bounce cancellation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce5ef2b0-15b5-4fd7-9cf1-39528f9433cc','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce5ef2b0-15b5-4fd7-9cf1-39528f9433cc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce5ef2b0-15b5-4fd7-9cf1-39528f9433cc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '50f0393c-4253-49c5-aa92-52429688dd6d','Center time','Center time (Ts) is the time of the centre of gravity of the squared impulse response, giving the average arrival time of sound energy without an abrupt early-late split. Lower center time indicates greater clarity; higher values indicate more reverberance.','Center time is the balance point of a room''s energy over time. It is like the average moment at which sound energy arrives. A small value means clear sound. A large value means more reverberant sound.','It summarizes clarity and reverberance in one figure without needing an arbitrary early-late boundary.','From a measured impulse response, a technician computes Ts; small speech rooms often show center times well under about 100 ms, while reverberant halls run higher.','Clarity Metrics',ARRAY['C50','C80','Definition','Energy decay curve']::text[],ARRAY['Confusing center time with reverberation time; they measure different things.','Expecting a fixed early-late split, when center time deliberately avoids one.','Reporting center time without a frequency band.']::text[],ARRAY['Characterizing clarity where a fixed split feels arbitrary.','Comparing rooms with a single continuous clarity figure.','Feeding measured parameters into an acoustic report.']::text[],'advanced','Ts = INT_0^inf t * p^2(t) dt / INT_0^inf p^2(t) dt','Center time is the energy-weighted average arrival time: the integral of time times squared pressure divided by the integral of squared pressure.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Center time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '50f0393c-4253-49c5-aa92-52429688dd6d','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='50f0393c-4253-49c5-aa92-52429688dd6d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='50f0393c-4253-49c5-aa92-52429688dd6d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf9e18ff-900f-4fa7-bb8e-e22200ec7e0c','Clarity metrics','Clarity metrics are a family of room-acoustic parameters, such as C50, C80, Definition (D50), and center time, that quantify how well early sound stands out from later reverberation. They express, in different ways, the balance between detail and reverberant blur.','Clarity metrics are numbers that rate how clear a room sounds. They compare early sound to late reverberation. Different metrics suit speech or music. Higher clarity means more detail.','They give designers standardized, comparable numbers for how clearly a space conveys speech or musical detail.','A technician reports C50 for speech and C80 for music from the same impulse response to describe a multipurpose hall''s clarity.','Clarity Metrics',ARRAY['C50','C80','Definition','Center time']::text[],ARRAY['Treating one clarity number as universally ideal for all uses.','Mixing up speech-oriented and music-oriented metrics.','Ignoring frequency dependence by quoting a single broadband value.']::text[],ARRAY['Writing an acoustic report for a multipurpose auditorium.','Choosing which metric to specify for speech versus music.','Comparing measured clarity across different halls.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clarity metrics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf9e18ff-900f-4fa7-bb8e-e22200ec7e0c','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf9e18ff-900f-4fa7-bb8e-e22200ec7e0c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf9e18ff-900f-4fa7-bb8e-e22200ec7e0c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '88103232-1f60-4a87-820e-99c2fb6c8742','Closed-pipe modes','Closed-pipe modes are the resonances of an air column closed at one end and open at the other, which support only odd harmonics whose quarter-wavelength multiples fit the pipe length. A pressure antinode forms at the closed end and a pressure node at the open end.','A tube closed at one end rings at set pitches. Only odd harmonics appear. The closed end is a pressure peak. The open end is a pressure low. This is the quarter-wave family of resonances.','It models resonances in stopped pipes, ports, and necks, and contrasts with the full-harmonic behavior of open or doubly closed columns.','For a stopped pipe 0.5 m long, the fundamental is f = c/(4L) = 343/(4x0.5) = 171.5 Hz, with resonances only at odd multiples (515, 858 Hz).','Room Modes',ARRAY['Axial modes','Acoustic resonance','Coupled resonances','Diaphragmatic absorption']::text[],ARRAY['Applying the open-pipe half-wave formula to a closed pipe.','Expecting even harmonics, which a one-end-closed pipe suppresses.','Placing the pressure node and antinode at the wrong ends.']::text[],ARRAY['Analyzing resonance of a port or duct closed at one end.','Explaining odd-harmonic coloration in a stopped tube.','Relating pipe resonance concepts to room axial modes.']::text[],'intermediate','f_n = (2n - 1) * c / (4 L)','Closed-pipe resonances occur at odd multiples of the speed of sound divided by four times the pipe length.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Closed-pipe modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '88103232-1f60-4a87-820e-99c2fb6c8742','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='88103232-1f60-4a87-820e-99c2fb6c8742') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='88103232-1f60-4a87-820e-99c2fb6c8742');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '179802e8-a2a7-496c-875f-6908305b4114','Conservation of acoustic energy','Conservation of acoustic energy states that sound energy striking a surface is partitioned into reflected, absorbed, and transmitted portions whose fractions sum to one. It is the energy-balance basis for absorption coefficients and statistical room-acoustics models.','Sound energy is not destroyed at a wall. It splits three ways: some bounces back, some is soaked up, some passes through. The three shares always add up to the whole.','It provides the accounting rule that defines absorption and transmission coefficients and underlies statistical reverberation theory.','If a wall reflects 0.7 and transmits 0.1 of incident energy, conservation requires that it absorbs 0.2, so its absorption coefficient is 0.2.','Energy Principles',ARRAY['Boundary impedance','Energy decay curve','Diffuse-field assumptions','Absorber thickness versus frequency']::text[],ARRAY['Confusing absorbed energy with transmitted energy.','Forgetting that absorption converts sound energy mostly into heat.','Assuming a good absorber must also be a good sound blocker.']::text[],ARRAY['Explaining why absorption coefficients cannot exceed one physically.','Separating absorption from transmission in isolation design.','Setting up an energy balance for a reverberation calculation.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Conservation of acoustic energy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '179802e8-a2a7-496c-875f-6908305b4114','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='179802e8-a2a7-496c-875f-6908305b4114') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='179802e8-a2a7-496c-875f-6908305b4114');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '863742da-9b6f-4cc5-bda5-fd28023ad35d','Coupled resonances','Coupled resonances occur when two or more resonant systems, such as adjoining rooms linked by an opening or a room and a resonant absorber, exchange energy and interact. The coupling shifts frequencies and can produce a combined decay with more than one slope.','Two ringing systems joined together affect each other. Energy passes between them. This can shift their pitches. It can also make the sound decay in two stages instead of one.','It describes how connected spaces or resonators interact, which shapes decay behavior and can be exploited or must be managed.','A technician analyzing a room coupled to a reverberant stairwell expects a double-sloped decay and measures each slope separately.','Resonance',ARRAY['Acoustic resonance','Axial modes','Energy decay curve','Diaphragmatic absorption']::text[],ARRAY['Fitting a single decay slope to a clearly double-sloped coupled decay.','Ignoring the aperture size, which controls coupling strength.','Assuming coupled spaces behave like one simple room.']::text[],ARRAY['Measuring reverberation in a room open to an adjoining space.','Designing coupled reverberation chambers in a concert hall.','Diagnosing an unexpected two-stage decay in a survey.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coupled resonances');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '863742da-9b6f-4cc5-bda5-fd28023ad35d','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='863742da-9b6f-4cc5-bda5-fd28023ad35d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='863742da-9b6f-4cc5-bda5-fd28023ad35d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a559470-5b76-4f60-8a96-6ee22edb0ebf','Definition','Definition (Deutlichkeit, D50) is the fraction of total impulse-response energy that arrives within the first 50 ms, usually expressed as a percentage. Standardized as a speech clarity measure, higher definition means the early, intelligible energy dominates.','Definition is the share of sound energy that arrives early. The window is the first 50 milliseconds. It is written as a percent. A high percent means clear, easy-to-follow speech.','It rates speech clarity as a simple fraction of early energy, closely related to the C50 clarity measure.','From an impulse response, a technician computes D50; a value near 50% or higher generally indicates good speech definition, and D50 relates directly to C50.','Clarity Metrics',ARRAY['Definition metrics','C50','Center time','Clarity metrics']::text[],ARRAY['Confusing Definition (a fraction) with C50 (a decibel ratio), though they are linked.','Using the 50 ms speech window for music assessment.','Quoting a broadband figure and ignoring frequency bands.']::text[],ARRAY['Rating speech clarity in a classroom.','Reporting D50 alongside C50 in an acoustic survey.','Comparing definition before and after adding absorption.']::text[],'advanced','D50 = INT_0^50ms p^2(t) dt / INT_0^inf p^2(t) dt','Definition is the impulse-response energy in the first fifty milliseconds divided by the total energy, often given as a percentage.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Definition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a559470-5b76-4f60-8a96-6ee22edb0ebf','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a559470-5b76-4f60-8a96-6ee22edb0ebf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a559470-5b76-4f60-8a96-6ee22edb0ebf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0da44900-a165-442a-aabf-ce25d5155201','Definition metrics','Definition metrics are room-acoustic measures, chiefly Definition (D50), that express clarity as the proportion of early sound energy relative to the total. They complement the decibel-based clarity ratios by giving an intuitive percentage of useful early energy.','Definition metrics rate clarity as a percentage of early sound. They show how much energy arrives soon versus late. They are close cousins of the clarity ratios. Higher means clearer.','They provide percentage-based clarity figures that are easy to interpret alongside decibel clarity measures.','A technician reports D50 as a percentage next to C50 in decibels so a client can read clarity in familiar terms.','Clarity Metrics',ARRAY['Definition','Clarity metrics','C50','Center time']::text[],ARRAY['Treating definition metrics and clarity ratios as unrelated.','Reading a percentage as a decibel value or vice versa.','Ignoring the frequency dependence of the numbers.']::text[],ARRAY['Presenting clarity results in percentage form for a client.','Comparing D50 with C50 in a room analysis.','Documenting speech clarity in an acoustic report.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Definition metrics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0da44900-a165-442a-aabf-ce25d5155201','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0da44900-a165-442a-aabf-ce25d5155201') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0da44900-a165-442a-aabf-ce25d5155201');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7271adf7-27a7-416c-b254-d0e8bc4762ac','Desk reflection','Desk (console) reflection is comb filtering caused when sound from the monitors bounces off the mixing desk or work surface and combines with the direct sound at the engineer''s ears. The delayed reflection creates response notches, typically in the low-mid range.','Sound from the speakers bounces off the desk. It reaches your ears just after the direct sound. The two mix and cancel at some pitches. This dips the response, often in the low mids.','It explains a common coloration at the mix position and motivates desk angling or reflection control.','A technician who measures a low-mid notch at the mix seat angles the console, lowers the meter bridge, or adds absorption to weaken the desk reflection.','Reflections',ARRAY['Ceiling-bounce cancellation','Early reflections','Angle of reflection','Echo criterion']::text[],ARRAY['Trying to equalize away a position-dependent comb-filter notch.','Overlooking the desk while treating only walls and ceiling.','Assuming the reflection is harmless because it is short.']::text[],ARRAY['Diagnosing a low-mid dip at the mixing position.','Deciding console angle and meter-bridge height in a control room.','Explaining why response changes with small head movements.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Desk reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7271adf7-27a7-416c-b254-d0e8bc4762ac','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7271adf7-27a7-416c-b254-d0e8bc4762ac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7271adf7-27a7-416c-b254-d0e8bc4762ac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8be05419-0876-45d9-8bf4-ac674b2a3ba3','Diaphragmatic absorption','Diaphragmatic (panel/membrane) absorption uses a limp or flexible panel over a sealed air cavity that resonates as a mass-spring system, absorbing sound most strongly near its resonance frequency. It targets low frequencies that porous absorbers handle poorly.','A flexible panel over a sealed air space acts like a spring and weight. It vibrates best at one low pitch. That vibration turns sound into heat. It catches bass that soft foam misses.','It provides tuned low-frequency absorption where a panel''s mass and the trapped air''s springiness set the resonance.','For a panel of surface mass m = 5 kg/m^2 over a d = 0.05 m sealed cavity, resonance f0 = 60/sqrt(m*d) = 60/sqrt(0.25) = 120 Hz, so it best absorbs around 120 Hz.','Absorption',ARRAY['Acoustic resonance','Air-gap effects behind absorbers','Bandwidth versus Q','Boundary impedance']::text[],ARRAY['Leaving the cavity unsealed, which spoils the mass-spring resonance.','Confusing membrane (panel) absorbers with Helmholtz (cavity-neck) absorbers.','Expecting broadband absorption from a sharply tuned panel.']::text[],ARRAY['Building a tuned bass trap for a specific room mode.','Adding low-frequency control where thick porous traps will not fit.','Estimating the resonance of a panel absorber design.']::text[],'advanced','f0 ~= 60 / sqrt(m * d)','The panel absorber''s resonance frequency is about sixty divided by the square root of the panel surface mass times the air-gap depth.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diaphragmatic absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8be05419-0876-45d9-8bf4-ac674b2a3ba3','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8be05419-0876-45d9-8bf4-ac674b2a3ba3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8be05419-0876-45d9-8bf4-ac674b2a3ba3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37da7ea2-e2bf-434a-a6e8-4bc3a353b525','Diffuse-field assumptions','Diffuse-field assumptions treat the reverberant sound field as statistically uniform: energy density is the same everywhere and sound arrives equally from all directions with random phase. These idealizations underpin statistical reverberation formulas such as Sabine''s and Eyring''s.','The theory pretends late reverberant sound is the same all over the room. It comes equally from every direction. Energy is even everywhere. Real rooms only approach this ideal.','It provides the simplifying framework that makes statistical reverberation and absorption formulas tractable.','A technician applying Sabine''s equation assumes a diffuse field, and knows the estimate degrades in rooms that are very absorptive or oddly shaped.','Sound Fields',ARRAY['Energy decay curve','Conservation of acoustic energy','Boundary impedance','Clarity metrics']::text[],ARRAY['Assuming a real room is perfectly diffuse when it is not.','Applying Sabine''s formula in rooms with very high absorption.','Ignoring that strong modes at low frequencies break the diffuse-field model.']::text[],ARRAY['Justifying use of Sabine or Eyring reverberation formulas.','Explaining why reverberation predictions err in dead or coupled rooms.','Interpreting reverberation-chamber absorption measurements.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse-field assumptions');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37da7ea2-e2bf-434a-a6e8-4bc3a353b525','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37da7ea2-e2bf-434a-a6e8-4bc3a353b525') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37da7ea2-e2bf-434a-a6e8-4bc3a353b525');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8842768e-3c6a-451b-9b28-0fe6c7ee4e53','Diffuser design','Diffuser design is the engineering of surfaces that scatter incident sound over a wide range of directions rather than reflecting it specularly. Number-theoretic designs, such as Schroeder quadratic-residue and primitive-root diffusers, use wells of varied depth to spread reflected energy evenly.','A diffuser scatters sound in many directions instead of one. It uses a pattern of wells at different depths. Schroeder based these depths on number sequences. This spreads reflections and reduces echoes.','It creates even, spacious scattering to control strong reflections without deadening the room through absorption.','A technician places a quadratic-residue diffuser on the rear wall to break up a slap echo while keeping the room''s liveliness.','Diffusion',ARRAY['Diffusion coefficient','Early reflections','Echo criterion','Angle of reflection']::text[],ARRAY['Confusing scattering (diffusion) with absorption; a diffuser preserves energy.','Placing a diffuser too close to the listener to develop its scattered field.','Assuming any bumpy surface diffuses well across all frequencies.']::text[],ARRAY['Treating a rear wall to eliminate slap echo in a studio.','Adding spaciousness to a room without over-damping it.','Designing well depths for a target frequency range.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuser design');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8842768e-3c6a-451b-9b28-0fe6c7ee4e53','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8842768e-3c6a-451b-9b28-0fe6c7ee4e53') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8842768e-3c6a-451b-9b28-0fe6c7ee4e53');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2418d9e5-17e0-47a7-a5a3-b0390811f7d6','Diffusion coefficient','The diffusion coefficient is a standardized measure, from 0 to 1, of how uniformly a surface scatters reflected sound across directions, computed from the autocorrelation of its polar reflection response. It is distinct from the scattering coefficient, which measures only the non-specular energy fraction.','This number rates how evenly a surface spreads reflected sound. Zero means one strong direction. One means smooth, even spreading. It comes from the surface''s directional reflection pattern.','It gives designers a comparable quality figure for how uniformly a diffuser scatters, standardized for product comparison.','A technician compares two diffuser products by their published directional diffusion coefficients across frequency bands before choosing one.','Diffusion',ARRAY['Diffuser design','Early reflections','Angle of reflection','Clarity metrics']::text[],ARRAY['Confusing the diffusion coefficient with the scattering coefficient.','Assuming a single number describes performance at every frequency.','Reading a higher coefficient as better absorption, which it is not.']::text[],ARRAY['Comparing commercial diffuser performance data.','Specifying diffusion quality for a room treatment plan.','Evaluating a prototype diffuser in a measurement lab.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffusion coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2418d9e5-17e0-47a7-a5a3-b0390811f7d6','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2418d9e5-17e0-47a7-a5a3-b0390811f7d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2418d9e5-17e0-47a7-a5a3-b0390811f7d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '964b3198-16c9-4a64-a018-3dff93a0aaa7','Early reflections','Early reflections are the first strong reflected sounds that reach a listener shortly after the direct sound, conventionally within roughly the first 50 to 80 ms. They fuse with the direct sound and influence clarity, loudness, timbre, and perceived source width.','Early reflections are the first bounces to reach you after the direct sound. They arrive within a few tens of milliseconds. Your ear blends them with the direct sound. They shape clarity and coloration.','They strongly affect perceived clarity, image, and coloration, so managing them is central to room and studio design.','A technician treats or diffuses side-wall early-reflection points at the mix position to sharpen stereo imaging and reduce comb filtering.','Reflections',ARRAY['Early decay time','Desk reflection','Ceiling-bounce cancellation','Echo criterion']::text[],ARRAY['Confusing early reflections with late reverberation or discrete echoes.','Assuming all early reflections are harmful; some add useful width.','Treating only the walls and ignoring floor, ceiling, and desk reflections.']::text[],ARRAY['Finding and treating first-reflection points in a control room.','Improving stereo imaging at the mix position.','Balancing early energy for clarity in a performance space.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Early reflections');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '964b3198-16c9-4a64-a018-3dff93a0aaa7','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='964b3198-16c9-4a64-a018-3dff93a0aaa7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='964b3198-16c9-4a64-a018-3dff93a0aaa7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab09720d-5240-4a13-952c-a2238d7e80af','Echo criterion','An echo criterion is a rule for predicting when a delayed reflection is heard as a distinct echo rather than fusing with the direct sound. It depends on the reflection''s delay and level relative to the direct sound, with longer delays and higher levels making an echo audible.','A late, loud reflection can be heard as a separate echo. An echo criterion predicts when that happens. It weighs how late and how loud the reflection is. Short, quiet reflections just blend in.','It helps designers judge whether a reflection will be perceived as a disturbing echo and needs treatment.','A technician checking an auditorium for echoes flags a rear-wall reflection that is both strongly delayed and loud enough to exceed an echo-audibility criterion.','Reflections',ARRAY['Early reflections','Ceiling-bounce cancellation','Diffuser design','Center time']::text[],ARRAY['Assuming any reflection is an echo, ignoring the delay-and-level threshold.','Overlooking that many short reflections fuse via the precedence effect.','Applying a single fixed delay threshold to both speech and music.']::text[],ARRAY['Assessing echo risk from a rear wall in an auditorium.','Deciding whether a long reflection needs diffusion or absorption.','Explaining why a distant hard surface causes a slap echo.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Echo criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab09720d-5240-4a13-952c-a2238d7e80af','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab09720d-5240-4a13-952c-a2238d7e80af') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab09720d-5240-4a13-952c-a2238d7e80af');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '76e39443-595d-41f8-bfe9-913c7d0badc5','Electrical resonance','Electrical resonance is the condition in a circuit containing inductance and capacitance where their reactances cancel, so the circuit responds most strongly at a particular resonant frequency. It is the electrical analogue of acoustic and mechanical resonance.','A circuit with a coil and a capacitor has a favorite frequency. At that pitch their opposing effects cancel out. The circuit then responds most strongly. It is the electrical version of a ringing resonance.','It underlies tuning, filtering, and analogies used to model acoustic resonators, appearing in crossovers and analog audio circuits.','For an inductor L = 10 mH and capacitor C = 1 uF, resonance f0 = 1/(2*pi*sqrt(L*C)) = 1/(2*pi*sqrt(1e-8)) = about 1592 Hz.','Resonance',ARRAY['Acoustic resonance','Bandwidth versus Q','Coupled resonances']::text[],ARRAY['Confusing electrical resonance in a circuit with acoustic resonance in air.','Forgetting that resistance damps the resonance and lowers its Q.','Mixing up series and parallel resonant behavior.']::text[],ARRAY['Analyzing a loudspeaker crossover network.','Using an electrical analogy to model an acoustic resonator.','Designing a tuned filter in analog audio gear.']::text[],'intermediate','f0 = 1 / (2 * pi * sqrt(L * C))','The resonant frequency equals one divided by two pi times the square root of the inductance multiplied by the capacitance.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '76e39443-595d-41f8-bfe9-913c7d0badc5','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='76e39443-595d-41f8-bfe9-913c7d0badc5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='76e39443-595d-41f8-bfe9-913c7d0badc5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b296b6b-cf19-4b86-89dd-4b6085f9e852','Energy decay curve','The energy decay curve (EDC) is the smoothed decay of remaining sound energy versus time, obtained by Schroeder''s backward integration of the squared impulse response. Its slope is used to derive reverberation time and related decay parameters.','The energy decay curve shows how a room''s sound energy fades over time. It comes from integrating the impulse response backward. Its slope gives the reverberation time. It is smoother than the raw decay.','It provides a smooth, repeatable decay from which reverberation time and early decay time are measured.','A technician fits a straight line to the energy decay curve between -5 and -35 dB and extrapolates to find T30, the reverberation time.','Reverberation',ARRAY['Reverberation time','Early decay time','Diffuse-field assumptions','Center time']::text[],ARRAY['Reading reverberation time from the noisy raw decay instead of the integrated curve.','Integrating over a range corrupted by background noise.','Assuming the decay is always a single straight line.']::text[],ARRAY['Deriving T30 and early decay time from a measurement.','Detecting double-sloped decay in coupled spaces.','Producing decay parameters for an acoustic report.']::text[],'advanced','EDC(t) = INT_t^inf p^2(tau) d(tau)','The energy decay curve at a time is the integral of the squared impulse response from that time to infinity (Schroeder backward integration).','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Energy decay curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b296b6b-cf19-4b86-89dd-4b6085f9e852','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b296b6b-cf19-4b86-89dd-4b6085f9e852') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b296b6b-cf19-4b86-89dd-4b6085f9e852');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3321fe9e-29a6-4adb-afca-4dacb94dc9d0','Eyring absorption','Eyring absorption is the treatment of room absorption used in the Eyring reverberation model, in which the mean absorption coefficient enters through the term −ln(1−ᾱ) rather than ᾱ itself. This accounts for sound decaying in discrete reflections off surfaces of average absorption ᾱ, and it remains accurate when average absorption is high.','When sound hits a wall, part of it is soaked up each time. Eyring absorption tracks that loss reflection by reflection. It works better than the older method in rooms with lots of soft, absorbing surfaces.','It gives a physically sound way to fold surface absorption into reverberation prediction, correcting the Sabine assumption that breaks down in fairly dead rooms.','For a room with mean absorption ᾱ = 0.4, an engineer uses −ln(1−0.4) = 0.51 in the Eyring term instead of 0.4, predicting a shorter, more realistic reverberation time.','Reverberation',ARRAY['Eyring equation','Absorption coefficient','Sabine equation','Reverberation time','Mean free path']::text[],ARRAY['Using Sabine absorption in a heavily treated room, which overestimates reverberation time.','Forgetting that −ln(1−ᾱ) only approximates ᾱ when absorption is small.','Assuming the average coefficient can equal or exceed 1.']::text[],ARRAY['Predicting reverberation in a well-damped control room.','Comparing Sabine and Eyring results for a studio live room.','Modeling a space where absorptive treatment covers most surfaces.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eyring absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3321fe9e-29a6-4adb-afca-4dacb94dc9d0','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3321fe9e-29a6-4adb-afca-4dacb94dc9d0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3321fe9e-29a6-4adb-afca-4dacb94dc9d0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '266a0f7c-bd5b-4209-9b9d-7a8b99319a98','Eyring equation','The Eyring (Eyring–Norris) equation predicts reverberation time as T60 = 0.161·V / (−S·ln(1−ᾱ) + 4mV), where V is room volume, S is total surface area, ᾱ is the mean absorption coefficient, and 4mV is the air-absorption term. It replaces Sabine''s ᾱ with −ln(1−ᾱ) to stay accurate for high average absorption.','This formula estimates how long sound keeps echoing in a room. It uses room size, surface area, and how absorbent the surfaces are. It stays accurate even when a room is quite dead, where the older Sabine formula fails.','It provides a reverberation-time prediction that stays valid as average surface absorption rises, where Sabine''s linear form overpredicts the decay time.','For V = 200 m³, S = 220 m², ᾱ = 0.30, ignoring air loss: T60 = 0.161·200 / (−220·ln(0.70)) = 32.2 / 78.4 ≈ 0.41 s.','Reverberation',ARRAY['Sabine equation','Eyring absorption','Reverberation time','Absorption coefficient','Air absorption']::text[],ARRAY['Confusing the Eyring and Sabine constants; both use 0.161 in metric units.','Dropping the 4mV air-absorption term at high frequencies where it matters.','Applying either equation to a strongly non-diffuse or coupled space.']::text[],ARRAY['Predicting reverberation time when designing a lecture hall.','Comparing predicted RT60 against a measured decay.','Estimating added absorption needed to hit a target RT60.']::text[],'advanced','T60 = 0.161·V / ( −S·ln(1 − ᾱ) + 4mV )','Reverberation time equals 0.161 times room volume, divided by the sum of the negative total surface area times the natural log of one minus mean absorption, plus four times the air attenuation constant times volume.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eyring equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '266a0f7c-bd5b-4209-9b9d-7a8b99319a98','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='266a0f7c-bd5b-4209-9b9d-7a8b99319a98') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='266a0f7c-bd5b-4209-9b9d-7a8b99319a98');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf7e4a9f-7e77-4565-a227-49e5f60446c9','Fibrous absorber','A fibrous absorber is a porous sound absorber made of tangled fibres such as mineral wool, glass fibre, or polyester, in which airflow through the interconnected pores converts acoustic energy to heat by viscous and thermal losses. Its absorption rises with thickness and is greatest at mid and high frequencies.','This is a soft, fluffy panel made of packed fibres. Sound waves push air through the tiny gaps and lose energy as heat. Thicker material soaks up more sound, especially higher notes.','It absorbs mid- and high-frequency sound to control reverberation, echoes, and reflections in a room.','A technician mounts 100 mm mineral-wool panels with an air gap behind them to extend absorption toward lower frequencies in a vocal booth.','Absorption',ARRAY['Porous absorption','Absorption coefficient','Flow resistivity','Panel absorbers']::text[],ARRAY['UNSAFE: Handling loose glass or mineral fibre without gloves and a mask, risking skin and lung irritation.','Expecting a thin fibrous panel to absorb bass; low frequencies need great thickness.','Compressing the material, which changes its flow resistivity and reduces performance.']::text[],ARRAY['Treating first-reflection points in a mixing room.','Filling a partition cavity to raise sound insulation.','Lining a duct or plenum to reduce airborne noise.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fibrous absorber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf7e4a9f-7e77-4565-a227-49e5f60446c9','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf7e4a9f-7e77-4565-a227-49e5f60446c9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf7e4a9f-7e77-4565-a227-49e5f60446c9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e004e44-1c96-4c8c-9ab2-4dfa8d1310a3','Floor-bounce cancellation','Floor-bounce cancellation is a comb-filter dip in the response at a listening position caused by interference between the direct sound and a reflection from the floor. A deep notch occurs when the extra path length of the reflection equals half a wavelength, producing destructive interference.','Sound reaches your ears twice: straight from the source and bounced off the floor. When the bounce arrives just out of step, the two cancel. This carves a dip in the sound at certain frequencies.','It explains a common frequency-response dip in measurements and mixing rooms so it can be predicted and reduced.','If the floor reflection travels 0.5 m farther than the direct path, the first cancellation is near f = 343/(2·0.5) ≈ 343 Hz; absorbing or repositioning fills the dip.','Reflections',ARRAY['Front-wall cancellation','Listener-boundary interference response','Comb filtering','Early reflections']::text[],ARRAY['Blaming the speaker for a dip actually caused by the floor reflection.','Assuming the notch is fixed; it moves as source or listener height changes.','Treating only the wall while ignoring the floor and ceiling bounces.']::text[],ARRAY['A midrange suck-out heard at a seated mixing position.','Ground-plane measurements exploiting the floor reflection deliberately.','Diagnosing a response dip during loudspeaker setup.']::text[],'intermediate','f_null = (2k − 1)·c / (2·Δr),  k = 1, 2, 3, …','The cancellation frequencies equal odd multiples of the speed of sound divided by twice the path-length difference between the reflected and direct sound.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Floor-bounce cancellation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e004e44-1c96-4c8c-9ab2-4dfa8d1310a3','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e004e44-1c96-4c8c-9ab2-4dfa8d1310a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e004e44-1c96-4c8c-9ab2-4dfa8d1310a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd907d632-e597-411a-8c82-4b0c5be89244','Forced resonance','Forced resonance is the vibration of a system, room air, or surface driven at the frequency of an external source rather than at the system''s own natural frequency. The response grows large only when the driving frequency lies near a natural (resonant) frequency, where the system readily accepts energy.','Push a swing at any rhythm and it moves a little. Push it at its natural rhythm and it swings high. Forced resonance is when an outside sound drives a room or panel, strongest near its own tuned frequency.','It describes how sustained tones excite room modes and structural resonances, setting up strong standing waves and sympathetic vibration.','A technician playing a steady 45 Hz tone hears it boom because it forces a room mode near 45 Hz; adding a bass trap damps the buildup.','Resonance',ARRAY['Modal ringing','Room modes','Standing wave','Membrane absorption']::text[],ARRAY['Confusing forced resonance with free (natural) resonance after the drive stops.','Assuming resonance needs an exact frequency match rather than proximity.','Thinking louder driving always means larger response away from a resonance.']::text[],ARRAY['A held bass note exciting a room mode.','A panel rattling only at one played frequency.','Sine-sweep testing that reveals resonant peaks.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forced resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd907d632-e597-411a-8c82-4b0c5be89244','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d907d632-e597-411a-8c82-4b0c5be89244') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d907d632-e597-411a-8c82-4b0c5be89244');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f201107-cf85-41f9-90bc-2002aa320138','Front-wall cancellation','Front-wall cancellation is a low-frequency notch, a form of speaker-boundary interference response (SBIR), caused by a reflection off the wall behind a loudspeaker combining out of phase with the direct sound. The first deep dip occurs near f = c/(4d), where d is the speaker-to-front-wall distance.','Sound from a speaker also bounces off the wall behind it. That delayed bounce can arrive out of step and cancel the direct sound. This creates a dip whose frequency depends on the wall distance.','It explains a placement-dependent bass dip so engineers can position monitors to move the notch out of the critical range.','A monitor 0.6 m from the front wall gives a first dip near f = 343/(4·0.6) ≈ 143 Hz; moving it closer raises that frequency out of the way.','Reflections',ARRAY['Floor-bounce cancellation','Listener-boundary interference response','Early reflections','Comb filtering']::text[],ARRAY['Trying to fix an SBIR notch with equalization, which cannot fill a true cancellation.','Ignoring that side and floor boundaries add their own notches.','Assuming the dip frequency is fixed regardless of speaker distance.']::text[],ARRAY['Setting monitor distance from the front wall in a studio.','Explaining a persistent low-mid dip at the mix position.','Choosing between soffit mounting and free-standing placement.']::text[],'intermediate','f_null = (2k − 1)·c / (4d),  k = 1, 2, 3, …','The first and higher cancellation frequencies equal odd multiples of the speed of sound divided by four times the distance from the loudspeaker to the wall behind it.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front-wall cancellation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f201107-cf85-41f9-90bc-2002aa320138','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f201107-cf85-41f9-90bc-2002aa320138') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f201107-cf85-41f9-90bc-2002aa320138');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5045f84-22fa-4142-9649-3e1a3d5d106c','Initial time-delay gap','The initial time-delay gap (ITDG) is the time interval between the arrival of the direct sound and the arrival of the first significant reflection at a listener. Beranek identified it as a measure related to a hall''s perceived intimacy, with smaller gaps giving a more intimate impression.','First you hear the sound straight from the stage. A moment later the first echo off a surface arrives. That short gap is the initial time-delay gap. A short gap makes a hall feel close and intimate.','It quantifies perceived acoustic intimacy in performance spaces and links room geometry to how close the sound feels.','From an impulse response an engineer reads the direct sound at 5 ms and the first reflection at 27 ms, giving an ITDG of about 22 ms in that seat.','Reflections',ARRAY['Early reflections','Live-end/dead-end design','Reverberation time','Musical clarity']::text[],ARRAY['Confusing ITDG with reverberation time; ITDG is only the gap to the first reflection.','Assuming one ITDG value describes a whole hall, though it varies by seat.','Treating a longer gap as always better; very short gaps aid intimacy.']::text[],ARRAY['Assessing intimacy in concert-hall design.','Reading an impulse response to find the first reflection.','Comparing seats in a hall for perceived closeness.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Initial time-delay gap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5045f84-22fa-4142-9649-3e1a3d5d106c','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5045f84-22fa-4142-9649-3e1a3d5d106c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5045f84-22fa-4142-9649-3e1a3d5d106c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a52b4df8-410f-4985-8423-28431e94993b','Intelligibility versus directivity','Intelligibility versus directivity is the principle that a loudspeaker''s directivity controls how much direct versus reverberant energy reaches listeners, strongly affecting speech intelligibility. Higher directivity concentrates sound onto the audience, raising the direct-to-reverberant ratio and pushing critical distance farther from the source.','A focused speaker aims sound at the listeners, not the walls. That means more clear, direct sound and less muddy echo. So a tighter pattern usually makes speech easier to understand in a live room.','It guides loudspeaker choice and aiming so speech stays intelligible in reverberant spaces by maximizing useful direct sound.','In a reverberant gym a technician swaps a wide horn for a high-directivity one, raising the direct-to-reverberant ratio and improving measured %ALcons.','Speech Intelligibility',ARRAY['Intelligibility versus reverberation','Critical distance','Direct-to-reverberant ratio','Speech transmission index']::text[],ARRAY['Assuming more output level improves intelligibility, when direct-to-reverberant ratio matters more.','Ignoring off-axis coverage while chasing high on-axis directivity.','Believing directivity is constant with frequency; it usually narrows with frequency.']::text[],ARRAY['Selecting horns for a reverberant sports hall.','Designing distributed versus point-source systems for speech.','Aiming line arrays to keep energy off reflective surfaces.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intelligibility versus directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a52b4df8-410f-4985-8423-28431e94993b','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a52b4df8-410f-4985-8423-28431e94993b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a52b4df8-410f-4985-8423-28431e94993b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '59b76301-6e6c-4bdb-b90b-9cf486f50952','Intelligibility versus noise','Intelligibility versus noise describes how background noise masks speech and degrades intelligibility, quantified largely through the signal-to-noise ratio. Intelligibility falls as noise rises, and the speech transmission index accounts for this masking as one of its degradation mechanisms.','Background noise hides parts of speech. The louder the noise compared with the talker, the more words are lost. Good sound systems keep speech well above the noise so listeners understand.','It explains why raising the speech-to-noise ratio, not just level, is essential for reliable understanding, especially in emergency announcements.','With speech at 70 dBA and noise at 60 dBA, the 10 dB signal-to-noise ratio supports good intelligibility; a technician confirms it meets STI targets.','Speech Intelligibility',ARRAY['Intelligibility versus reverberation','Speech transmission index','Signal-to-noise ratio','%ALcons']::text[],ARRAY['Assuming a very high signal-to-noise ratio keeps improving intelligibility without limit.','Measuring level but ignoring the noise spectrum, which masks unevenly.','Confusing loudness with clarity; a loud but noisy system can be unintelligible.']::text[],ARRAY['Specifying paging systems for noisy factories.','Verifying voice-alarm intelligibility under HVAC noise.','Explaining why turning up volume alone does not fix understanding.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intelligibility versus noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '59b76301-6e6c-4bdb-b90b-9cf486f50952','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='59b76301-6e6c-4bdb-b90b-9cf486f50952') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='59b76301-6e6c-4bdb-b90b-9cf486f50952');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37a27124-b57d-4ae3-8e57-b6bd154032b0','Intelligibility versus reverberation','Intelligibility versus reverberation is the principle that excessive reverberation smears speech in time, overlapping syllables and lowering intelligibility. Longer reverberation time and lower direct-to-reverberant ratio both reduce measures such as the speech transmission index and raise %ALcons.','In an echoey room, each word keeps ringing while the next begins. The sounds blur together and speech gets hard to follow. Longer echoes mean lower intelligibility.','It links reverberation control to speech clarity, guiding absorption and loudspeaker design in rooms used for the spoken word.','Peutz''s method estimates %ALcons from reverberation time and distance; a technician adds absorption to cut RT60 and lower %ALcons below 10%.','Speech Intelligibility',ARRAY['Intelligibility versus directivity','Reverberation time','Speech transmission index','%ALcons']::text[],ARRAY['Assuming reverberation always harms sound; music often benefits while speech suffers.','Treating reverberation time alone as sufficient, ignoring the direct-to-reverberant ratio.','Believing more loudspeaker power overcomes a very reverberant room.']::text[],ARRAY['Designing speech reinforcement for a reverberant church.','Setting RT60 targets for a lecture theatre.','Explaining poor announcement clarity in a train station concourse.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intelligibility versus reverberation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37a27124-b57d-4ae3-8e57-b6bd154032b0','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37a27124-b57d-4ae3-8e57-b6bd154032b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37a27124-b57d-4ae3-8e57-b6bd154032b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0fb2771a-793b-4b03-b541-c717ab0fa4f6','Listener-boundary interference response','The listener-boundary interference response is the comb-filtered frequency response at a listening position caused by reflections from nearby boundaries such as the floor, walls, and desk combining with the direct sound. Constructive and destructive interference produce a series of peaks and dips set by each reflection''s extra path length.','Surfaces near your listening spot bounce sound back to you. These bounces mix with the direct sound. Depending on timing, they add or cancel, leaving a comb of peaks and dips in the response.','It explains position-dependent coloration at the ears or microphone so engineers can predict and reduce boundary interference.','A reflection arriving with a 0.7 m extra path gives a first dip near f = 343/(2·0.7) ≈ 245 Hz; the engineer absorbs the desk and side boundaries.','Reflections',ARRAY['Floor-bounce cancellation','Front-wall cancellation','Comb filtering','Early reflections']::text[],ARRAY['Trying to equalize away comb dips that move with listener position.','Considering only one boundary when several contribute at once.','Confusing this acoustic interference with an electronic phase problem.']::text[],ARRAY['Coloration heard from a nearby mixing-desk reflection.','Predicting boundary effects at a measurement microphone.','Diagnosing why response changes as the listener leans forward.']::text[],'advanced','f_null = (2k − 1)·c / (2·Δr),  f_peak = k·c / Δr','Dips fall at odd multiples of the speed of sound over twice a reflection''s extra path length, and peaks fall at whole multiples of the speed of sound over that extra path length.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Listener-boundary interference response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0fb2771a-793b-4b03-b541-c717ab0fa4f6','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0fb2771a-793b-4b03-b541-c717ab0fa4f6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0fb2771a-793b-4b03-b541-c717ab0fa4f6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa678a1b-0ba3-4f1c-803e-8643b0d26729','Live-end/dead-end design','Live-end/dead-end (LEDE) is a control-room design approach in which the front end around the loudspeakers is made acoustically absorptive (dead) to suppress early reflections, while the rear is more reflective and diffusive (live) to return a delayed, diffuse sound field. The goal is a reflection-free zone at the mix position with a clean initial time-delay gap.','In this studio layout the front is soft and soaks up early echoes. The back is harder and scatters sound. The engineer hears clean direct sound first, then a gentle, diffuse decay from behind.','It creates a reflection-free listening zone so monitoring is accurate, with early reflections removed and later diffuse energy preserved.','A technician absorbs the front-wall and side first-reflection points and installs diffusers on the rear wall to build a live-end/dead-end control room.','Room Treatment',ARRAY['Initial time-delay gap','Early reflections','Reflection-free zone','Diffusion']::text[],ARRAY['Making the whole room dead, which removes the intended live diffuse rear field.','Placing diffusers too close to the listener to develop properly.','Assuming LEDE fixes low-frequency modal problems, which need bass trapping.']::text[],ARRAY['Designing a project or commercial mixing room.','Deciding where absorption versus diffusion should go.','Achieving a defined reflection-free zone at the console.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Live-end/dead-end design');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa678a1b-0ba3-4f1c-803e-8643b0d26729','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa678a1b-0ba3-4f1c-803e-8643b0d26729') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa678a1b-0ba3-4f1c-803e-8643b0d26729');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da54959c-13af-4d9d-aaa5-22ed077509b4','Locally reacting absorber','A locally reacting absorber is a surface whose response at any point depends only on the sound pressure at that same point, so its behavior is described by a single normal surface impedance independent of the angle of incidence. This idealization applies when sound cannot travel laterally within the absorber, as with a rigidly partitioned or thin backed layer.','This kind of absorber reacts only to the sound pressing straight on each spot. Sound cannot spread sideways inside it. That makes its behavior simple to describe with one impedance value.','It simplifies absorber modeling by allowing a single angle-independent impedance, which underpins many room-acoustics prediction methods.','An engineer models a mineral-wool panel divided into small cells as locally reacting, using one surface impedance to predict its absorption at any incidence angle.','Absorption',ARRAY['Nonlocally reacting absorber','Surface impedance','Porous absorption','Absorption coefficient']::text[],ARRAY['Assuming a thick porous layer is locally reacting when lateral wave travel makes it non-local.','Confusing surface impedance with characteristic impedance of the material.','Treating the local-reaction result as exact rather than a useful idealization.']::text[],ARRAY['Setting a boundary condition in a room-acoustics simulation.','Predicting absorption of a partitioned panel absorber.','Comparing measured and modeled absorption versus incidence angle.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Locally reacting absorber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da54959c-13af-4d9d-aaa5-22ed077509b4','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da54959c-13af-4d9d-aaa5-22ed077509b4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da54959c-13af-4d9d-aaa5-22ed077509b4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '702f04a5-7449-4e43-9ed1-d5f3c3d3dd7e','Membrane absorption','Membrane (panel) absorption uses a limp, non-porous panel spaced from a rigid wall over an air cavity, forming a mass-spring resonator that absorbs sound near its resonant frequency. The panel mass and the cavity stiffness tune the resonance, giving useful low-frequency absorption where porous absorbers are inefficient.','A thin panel sits over an air gap in front of a wall. Sound makes the panel flex like a mass on a spring. Near its tuned note it soaks up low-frequency energy well.','It targets low frequencies, controlling room modes and bass buildup that thin porous absorbers cannot handle.','For a panel of 3 kg/m² over a 50 mm air gap, f0 ≈ 60/√(3·0.05) ≈ 155 Hz; the tech tunes the gap to hit a problem mode.','Absorption',ARRAY['Panel absorbers','Helmholtz resonator','Porous absorption','Room modes']::text[],ARRAY['Expecting broadband absorption; the panel works over a limited band around resonance.','Ignoring cavity damping, so the resonance is too sharp and narrow.','Making the panel too stiff, which raises the resonance above the target.']::text[],ARRAY['Building a tuned bass trap for a control room.','Controlling a specific low-frequency room mode.','Adding low-frequency absorption behind a reflective wall finish.']::text[],'intermediate','f0 ≈ 60 / √(m · d)','The resonant frequency is about sixty divided by the square root of the panel surface mass times the air-gap depth.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Membrane absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '702f04a5-7449-4e43-9ed1-d5f3c3d3dd7e','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='702f04a5-7449-4e43-9ed1-d5f3c3d3dd7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='702f04a5-7449-4e43-9ed1-d5f3c3d3dd7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c51cf48f-e5f9-41d7-8680-eaeca6972cee','Modal degeneracy','Modal degeneracy occurs when two or more room modes share the same or nearly the same resonant frequency, most commonly when room dimensions are equal or simple integer ratios. The coincident modes reinforce each other, producing an especially strong, uneven low-frequency response.','Sometimes two different room resonances land on the same note. This happens when room dimensions match or are simple multiples. Those overlapping modes stack up and make one frequency boom badly.','It warns designers that cubic or proportionally simple rooms concentrate modal energy, worsening low-frequency unevenness.','An engineer avoids a room measuring 4 m × 4 m × 4 m because its axial modes coincide; choosing non-integer ratios spreads the modes out.','Room Modes',ARRAY['Mode clustering','Mode spacing','Modal frequency calculation','Room modes']::text[],ARRAY['Choosing equal room dimensions, which maximizes modal coincidence.','Confusing degeneracy (same frequency) with clustering (close but distinct).','Assuming absorption alone removes the peak without addressing geometry.']::text[],ARRAY['Selecting room proportions during studio design.','Explaining an extreme bass peak in a cubic room.','Comparing preferred room-ratio recommendations.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal degeneracy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c51cf48f-e5f9-41d7-8680-eaeca6972cee','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c51cf48f-e5f9-41d7-8680-eaeca6972cee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c51cf48f-e5f9-41d7-8680-eaeca6972cee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '78f57bc2-d810-4a42-a250-bf96a59a7ff3','Modal frequency calculation','Modal frequency calculation predicts the resonant frequencies of a rectangular room using the Rayleigh equation, combining integer mode numbers along the length, width, and height. It yields axial, tangential, and oblique mode frequencies from the room dimensions and the speed of sound.','A rectangular room resonates at predictable frequencies. This formula finds them from the room''s length, width, and height. Each whole-number combination gives one standing-wave frequency.','It lets designers map a room''s low-frequency modes to anticipate peaks, dips, and problem frequencies before treatment.','For a 5 m length, the first axial mode is f = (343/2)·(1/5) = 34.3 Hz; repeating for width and height reveals where bass buildup occurs.','Room Modes',ARRAY['Oblique modes','Modal degeneracy','Mode spacing','Room modes']::text[],ARRAY['Applying the rectangular formula to irregular or non-rigid rooms.','Forgetting tangential and oblique modes and counting only axial ones.','Using inconsistent units for dimensions and the speed of sound.']::text[],ARRAY['Predicting room modes when planning studio dimensions.','Locating a measured bass peak to a specific mode.','Choosing listening and speaker positions relative to modes.']::text[],'advanced','f(p,q,r) = (c/2)·√[ (p/L)² + (q/W)² + (r/H)² ]','The mode frequency equals half the speed of sound times the square root of the sum of squared ratios of each integer mode number to its room dimension.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal frequency calculation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '78f57bc2-d810-4a42-a250-bf96a59a7ff3','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='78f57bc2-d810-4a42-a250-bf96a59a7ff3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='78f57bc2-d810-4a42-a250-bf96a59a7ff3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fef65e9b-295d-4b7f-b7b6-a8b7343c3ae2','Modal region','The modal region is the low-frequency range of a room, below the Schroeder (crossover) frequency, where individual room modes are sparse, well separated, and dominate the response. Above that frequency, modes overlap densely and the field becomes statistically diffuse.','At low frequencies a room has only a few, well-spaced resonances. This range is the modal region. The Schroeder frequency marks where modes crowd together and behave like a diffuse field.','It identifies the band where wave behavior and modes govern the response, so statistical reverberation theory does not apply and modal control is needed.','For RT60 = 0.5 s and V = 100 m³, the Schroeder frequency is f ≈ 2000·√(0.5/100) ≈ 141 Hz; below it the tech treats modes individually.','Room Modes',ARRAY['Schroeder frequency','Modal density','Room modes','Mode spacing','Non-diffuse sound field']::text[],ARRAY['Applying Sabine reverberation theory below the Schroeder frequency.','Assuming the modal region has a fixed upper limit for all rooms.','Confusing the modal region boundary with a single room mode.']::text[],ARRAY['Deciding where modal treatment versus broadband absorption applies.','Interpreting a low-frequency room measurement.','Estimating the Schroeder frequency for a small studio.']::text[],'advanced','f_Schroeder ≈ 2000·√(T60 / V)','The Schroeder crossover frequency is about two thousand times the square root of the reverberation time divided by the room volume.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fef65e9b-295d-4b7f-b7b6-a8b7343c3ae2','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fef65e9b-295d-4b7f-b7b6-a8b7343c3ae2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fef65e9b-295d-4b7f-b7b6-a8b7343c3ae2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ad3ecce1-7b55-4e8c-93c1-0e671c80b4b2','Modal ringing','Modal ringing is the prolonged decay of energy stored in a lightly damped room mode after the driving sound stops, heard as a lingering tone at the mode frequency. It appears in the time domain as a slow decay and in waterfall plots as an extended low-frequency tail.','When a strong room resonance is hit, it keeps sounding after the source stops. This lingering low tone is modal ringing. It smears bass and blurs timing.','It reveals which low-frequency modes decay slowly and need damping to tighten a room''s bass response.','A waterfall plot shows a 60 Hz mode ringing far longer than its neighbors, so the engineer adds a tuned bass trap to shorten that decay.','Room Modes',ARRAY['Room modes','Forced resonance','Membrane absorption','Reverberation time']::text[],ARRAY['Judging modal ringing from frequency response alone, ignoring the decay time.','Assuming equalization shortens the ring; it lowers level but not decay.','Confusing modal ringing with electronic or driver resonance.']::text[],ARRAY['Reading a waterfall or spectrogram of a room.','Diagnosing boomy, one-note bass at the mix position.','Verifying that a bass trap has shortened low-frequency decay.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal ringing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ad3ecce1-7b55-4e8c-93c1-0e671c80b4b2','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ad3ecce1-7b55-4e8c-93c1-0e671c80b4b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ad3ecce1-7b55-4e8c-93c1-0e671c80b4b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14a998c8-3079-4ea0-a31e-95b9f37dfc6f','Mode clustering','Mode clustering is the grouping of several room modes close together in frequency, leaving gaps elsewhere in the low-frequency range. It arises from room proportions that bunch modes, producing an uneven response with peaks where modes cluster and dips where they are sparse.','Sometimes several room resonances crowd into one narrow band. Other bands are left empty. This clustering makes some bass notes boom and others sound weak.','It explains why poorly proportioned rooms have lumpy bass and guides selection of dimensions that spread modes evenly.','An engineer computes the axial modes and finds three within a few hertz, revealing a cluster; adjusting planned dimensions evens the spacing.','Room Modes',ARRAY['Mode spacing','Modal degeneracy','Modal frequency calculation','Room modes']::text[],ARRAY['Confusing clustering (close, distinct modes) with degeneracy (identical frequencies).','Assuming any absorption evens out a clustered response.','Judging room ratios by one axis instead of all three together.']::text[],ARRAY['Evaluating candidate room proportions.','Explaining uneven bass across nearby frequencies.','Comparing modal distributions of two room designs.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode clustering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14a998c8-3079-4ea0-a31e-95b9f37dfc6f','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14a998c8-3079-4ea0-a31e-95b9f37dfc6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14a998c8-3079-4ea0-a31e-95b9f37dfc6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4217f01-6236-46f8-9da8-81733c22b064','Mode spacing','Mode spacing is the frequency separation between adjacent room modes, a key indicator of low-frequency response smoothness. Even, well-distributed spacing gives a smoother response, while large gaps or tight clusters create audible peaks and dips.','Mode spacing is how far apart a room''s resonances sit in frequency. Even spacing gives smoother bass. Big gaps or crowded groups make the bass uneven.','It provides a criterion for judging and choosing room proportions to achieve the smoothest possible low-frequency response.','Listing the axial modes, an engineer checks that no gap greatly exceeds the average spacing before finalizing room dimensions.','Room Modes',ARRAY['Mode clustering','Modal degeneracy','Modal frequency calculation','Modal density']::text[],ARRAY['Optimizing spacing on one axis while ignoring cross-axis coincidences.','Assuming perfectly even spacing is achievable in a real room.','Judging spacing only from axial modes, ignoring tangential ones.']::text[],ARRAY['Applying room-ratio guidelines during design.','Assessing predicted modal distributions.','Explaining why some rooms have smoother bass than others.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode spacing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4217f01-6236-46f8-9da8-81733c22b064','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4217f01-6236-46f8-9da8-81733c22b064') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4217f01-6236-46f8-9da8-81733c22b064');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0fcd37e6-cd96-462b-b8c7-cfc9a092d787','Musical clarity','Musical clarity is the perceived distinctness of successive musical sounds, quantified by the clarity index C80, the logarithmic ratio of early (0–80 ms) to late (after 80 ms) sound energy in the impulse response, per ISO 3382-1. Higher C80 means greater clarity; lower values give a fuller, more reverberant impression.','Musical clarity is how well you hear separate notes rather than a blur. It is measured by C80. It compares the early sound energy to the later reverberant energy in the room.','It gives an objective measure of how transparent or reverberant a hall sounds for music, aiding design and evaluation.','From an impulse response, early energy is 4× the late energy, so C80 = 10·log10(4) = +6 dB, indicating a fairly clear-sounding space for music.','Clarity',ARRAY['Initial time-delay gap','Reverberation time','Definition (D50)','Early reflections']::text[],ARRAY['Confusing C80 (music, 80 ms) with C50 (speech, 50 ms).','Assuming higher clarity is always better; music needs balanced reverberance.','Reporting clarity without stating the frequency band or averaging.']::text[],ARRAY['Rating a concert hall from measurements.','Comparing clarity across seats in an auditorium.','Setting a design target for a rehearsal room.']::text[],'advanced','C80 = 10·log10( ∫₀^80ms p²(t)dt / ∫_80ms^∞ p²(t)dt )  [dB]','Clarity C80 equals ten times the base-ten log of the ratio of the sound energy in the first eighty milliseconds to the sound energy arriving after eighty milliseconds.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Musical clarity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0fcd37e6-cd96-462b-b8c7-cfc9a092d787','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0fcd37e6-cd96-462b-b8c7-cfc9a092d787') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0fcd37e6-cd96-462b-b8c7-cfc9a092d787');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8dd1db7b-4692-4aa3-b710-2aa491df2c29','Non-diffuse sound field','A non-diffuse sound field is one in which sound energy is not uniformly distributed and does not arrive equally from all directions, so the ideal assumptions of statistical room acoustics fail. It is typical below the Schroeder frequency, in strongly damped or highly directional rooms, and near sources or boundaries.','In a diffuse field, sound comes evenly from every direction. A non-diffuse field is uneven, arriving more from some directions than others. Simple reverberation formulas do not work well here.','It flags conditions where diffuse-field theory and standard reverberation equations become inaccurate, requiring wave-based or direct analysis.','Measuring reverberation in a small heavily treated room, an engineer finds position-dependent decays, confirming a non-diffuse field and treating results cautiously.','Sound Field',ARRAY['Modal region','Diffusion','Reverberation time','Critical distance']::text[],ARRAY['Applying Sabine or Eyring theory in a clearly non-diffuse field.','Assuming a single measurement position represents the whole room.','Believing all rooms become diffuse if simply made reverberant.']::text[],ARRAY['Interpreting inconsistent reverberation measurements.','Recognizing modal-dominated low-frequency behavior.','Assessing coupled or heavily damped spaces.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Non-diffuse sound field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8dd1db7b-4692-4aa3-b710-2aa491df2c29','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8dd1db7b-4692-4aa3-b710-2aa491df2c29') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8dd1db7b-4692-4aa3-b710-2aa491df2c29');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b56658c1-4df7-43e8-a374-40c96a52a17f','Nonlocally reacting absorber','A nonlocally reacting (extended-reaction) absorber is one in which sound can propagate laterally within the material, so its surface response at a point depends on the pressure field over a region and on the angle of incidence. Its behavior cannot be captured by a single angle-independent surface impedance.','In this absorber, sound can travel sideways inside the material. So its response at one spot depends on the sound nearby, not just there. Its behavior also changes with the sound''s angle.','It provides a more realistic model for thick porous layers where lateral wave propagation matters, improving absorption predictions.','An engineer models a thick unpartitioned mineral-wool slab as nonlocally reacting, using its bulk properties to predict angle-dependent absorption more accurately.','Absorption',ARRAY['Locally reacting absorber','Surface impedance','Porous absorption','Absorption coefficient']::text[],ARRAY['Forcing a single surface impedance onto a truly non-local absorber.','Assuming partitioning is unnecessary when local reaction is desired.','Ignoring incidence-angle dependence in thick porous layers.']::text[],ARRAY['Modeling absorption of a thick unpartitioned porous layer.','Choosing between local and extended-reaction assumptions in simulation.','Explaining angle-dependent absorption discrepancies.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nonlocally reacting absorber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b56658c1-4df7-43e8-a374-40c96a52a17f','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b56658c1-4df7-43e8-a374-40c96a52a17f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b56658c1-4df7-43e8-a374-40c96a52a17f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2121dfc0-4ee6-4045-a135-9ba8fae26dd8','Oblique modes','Oblique modes are room resonances involving all three pairs of surfaces at once, so all three mode numbers are nonzero. They are the most numerous but weakest of the axial, tangential, and oblique mode families, since energy reflects off all six room surfaces.','Oblique modes are standing waves that bounce between all six surfaces of a room. They are the most common type but also the weakest. They fill in the gaps between stronger modes.','They contribute to modal density and help smooth the low-frequency field, even though each individual oblique mode is weak.','When mapping modes, an engineer notes oblique modes (all mode numbers nonzero) add many weak resonances that fill between the stronger axial and tangential ones.','Room Modes',ARRAY['Modal frequency calculation','Room modes','Modal density','Mode spacing']::text[],ARRAY['Overweighting oblique modes, which are far weaker than axial modes.','Forgetting oblique modes exist when counting modal density.','Assuming all mode types have equal strength.']::text[],ARRAY['Classifying modes when analyzing a room.','Estimating modal density in the low-frequency range.','Explaining the many weak resonances between strong peaks.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oblique modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2121dfc0-4ee6-4045-a135-9ba8fae26dd8','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2121dfc0-4ee6-4045-a135-9ba8fae26dd8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2121dfc0-4ee6-4045-a135-9ba8fae26dd8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a0dca903-7e62-4852-823c-62d6deefa34e','Open-pipe modes','Open-pipe modes are the resonances of an air column open at both ends, which support a pressure node (velocity antinode) at each open end and resonate at whole-number multiples of a fundamental. The frequencies are f_n = n·c/(2L), giving a complete harmonic series.','A tube open at both ends resonates at a set of notes. The lowest fits half a wavelength in the tube. The higher ones are whole-number multiples, forming a full harmonic series.','It models the resonances of open ducts, ports, and open tubes, explaining their harmonic tuning in acoustics and instrument design.','For a 0.5 m open pipe, the fundamental is f1 = 343/(2·0.5) = 343 Hz, with overtones at 686 Hz, 1029 Hz, and so on.','Resonance',ARRAY['Standing wave','Pressure antinodes','Particle-velocity antinodes','Forced resonance']::text[],ARRAY['Confusing open-pipe tuning with a closed pipe, which gives only odd harmonics.','Ignoring the end correction that slightly lowers real pipe frequencies.','Placing a pressure antinode, rather than a node, at an open end.']::text[],ARRAY['Analyzing duct or port resonances.','Explaining harmonic series in wind instruments.','Predicting resonance of an open tube in a test.']::text[],'intermediate','f_n = n·c / (2L),  n = 1, 2, 3, …','The resonant frequencies of a pipe open at both ends equal whole-number multiples of the speed of sound divided by twice the pipe length.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Open-pipe modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a0dca903-7e62-4852-823c-62d6deefa34e','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a0dca903-7e62-4852-823c-62d6deefa34e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a0dca903-7e62-4852-823c-62d6deefa34e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd50eb3d-3c45-4864-b217-18b247975081','Panel absorbers','Panel (membrane) absorbers are resonant low-frequency absorbers consisting of a solid, non-porous panel mounted over a sealed air cavity in front of a rigid wall. The panel mass and cavity spring form a resonator tuned to absorb around f0 ≈ 60/√(m·d), with cavity damping widening the absorbed band.','A panel absorber is a stiff sheet over a sealed air gap. It vibrates and soaks up low frequencies near its tuned note. Adding damping inside broadens the range it covers.','They provide targeted low-frequency absorption to tame room modes and bass buildup that porous panels handle poorly.','For a 4 kg/m² panel over a 75 mm cavity, f0 ≈ 60/√(4·0.075) ≈ 110 Hz; the technician adds mineral wool inside to broaden absorption.','Absorption',ARRAY['Membrane absorption','Helmholtz resonator','Porous absorption','Room modes']::text[],ARRAY['Leaving the cavity undamped, giving a peaky, narrow absorber.','Not sealing the panel edges, which detunes the resonator.','Expecting one panel absorber to control the whole bass range.']::text[],ARRAY['Constructing a tuned bass trap.','Absorbing a specific low-frequency room mode.','Adding low-frequency control behind a reflective wall.']::text[],'intermediate','f0 ≈ 60 / √(m · d)','The tuning frequency is about sixty divided by the square root of the panel surface mass times the sealed air-gap depth.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Panel absorbers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd50eb3d-3c45-4864-b217-18b247975081','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd50eb3d-3c45-4864-b217-18b247975081') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd50eb3d-3c45-4864-b217-18b247975081');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6a2ad02e-59f3-4e18-a79e-b81b170495ef','Particle-velocity antinodes','Particle-velocity antinodes are the locations in a standing wave where air-particle motion is greatest and, correspondingly, sound pressure is at a minimum. In a room mode they coincide with pressure nodes and occur a quarter-wavelength from rigid boundaries.','In a standing wave, air moves most in some spots and least in others. The spots of greatest air motion are velocity antinodes. There the pressure swing is smallest.','They identify where porous absorbers work best, since porous material dissipates energy by resisting the moving air of a velocity antinode.','A technician places porous bass absorption a quarter-wavelength off the wall, at a velocity antinode, where air motion and thus absorption are greatest.','Standing Waves',ARRAY['Particle-velocity nodes','Pressure antinodes','Porous absorption','Standing wave','Room modes']::text[],ARRAY['Confusing velocity antinodes with pressure antinodes; they occur at different places.','Placing porous absorbers hard against a wall, at a velocity node.','Assuming velocity is greatest at the boundary rather than away from it.']::text[],ARRAY['Positioning porous bass traps for best effect.','Explaining why absorbers work better off the wall.','Mapping the particle-velocity pattern of a room mode.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle-velocity antinodes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6a2ad02e-59f3-4e18-a79e-b81b170495ef','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6a2ad02e-59f3-4e18-a79e-b81b170495ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6a2ad02e-59f3-4e18-a79e-b81b170495ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '239510df-8fd4-44c1-a24a-2822994e7684','Particle-velocity nodes','Particle-velocity nodes are the locations in a standing wave where air-particle motion is zero and sound pressure swings to its maximum. In a room mode they coincide with pressure antinodes and occur at rigid boundaries such as walls, floor, and ceiling.','In a standing wave, some spots have no air motion at all. These are velocity nodes. There the pressure is at its highest swing, such as right at a solid wall.','They mark where pressure-based absorbers, like membrane and Helmholtz devices, are effective, and where porous absorbers are least effective.','At a rigid wall, a velocity node with high pressure, a technician places a pressure-operated membrane trap rather than a porous one.','Standing Waves',ARRAY['Particle-velocity antinodes','Pressure antinodes','Membrane absorption','Standing wave','Room modes']::text[],ARRAY['Placing porous absorbers at a wall velocity node, where they do little.','Confusing velocity nodes with pressure nodes.','Assuming air moves fastest at a boundary.']::text[],ARRAY['Choosing pressure- versus velocity-based absorbers by location.','Explaining high sound pressure at room boundaries.','Mapping a mode''s velocity distribution for treatment.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle-velocity nodes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '239510df-8fd4-44c1-a24a-2822994e7684','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='239510df-8fd4-44c1-a24a-2822994e7684') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='239510df-8fd4-44c1-a24a-2822994e7684');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc9513e7-1858-4bf9-8efa-db052fd2f52f','Porous absorption','Porous absorption is the dissipation of sound energy as heat when air oscillates through the interconnected pores of an open-celled material such as foam, mineral wool, or fabric, driven by viscous and thermal losses. Absorption increases with material thickness and is most effective at mid and high frequencies.','Sound pushes air through the tiny holes of a soft, open material. Friction turns that motion into heat, so the sound is soaked up. Thicker material absorbs lower notes too.','It controls reverberation and reflections across the mid and high range, the workhorse mechanism of most acoustic panels.','To extend absorption downward, a technician mounts a 100 mm porous panel with a 100 mm air gap, placing more of it near a velocity antinode.','Absorption',ARRAY['Fibrous absorber','Flow resistivity','Absorption coefficient','Particle-velocity antinodes']::text[],ARRAY['Expecting thin porous panels to absorb bass effectively.','Sealing the surface with paint or film, which blocks airflow and absorption.','Ignoring flow resistivity; too high or too low both reduce performance.']::text[],ARRAY['Treating first reflections and general reverberation.','Choosing panel thickness and air-gap depth.','Comparing foam and mineral-wool absorption curves.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Porous absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc9513e7-1858-4bf9-8efa-db052fd2f52f','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc9513e7-1858-4bf9-8efa-db052fd2f52f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc9513e7-1858-4bf9-8efa-db052fd2f52f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d6b4cc4-a1da-4a2a-8e44-ae7c23191115','Pressure antinodes','Pressure antinodes are the locations in a standing wave where sound-pressure variation is greatest and air-particle velocity is at a minimum. In room modes they occur at rigid boundaries and at room corners, where multiple modes'' pressure maxima coincide.','In a standing wave, some spots have the biggest pressure swings. These are pressure antinodes. They sit at hard walls and, strongest of all, in the corners of a room.','They identify high-pressure zones, notably corners, where pressure-based bass absorbers and measurement microphones are most effective.','Because room corners are pressure antinodes for all axial modes, a technician places bass traps in the corners for maximum low-frequency absorption.','Standing Waves',ARRAY['Particle-velocity nodes','Particle-velocity antinodes','Room modes','Membrane absorption']::text[],ARRAY['Confusing pressure antinodes with velocity antinodes; they occur at different points.','Assuming pressure is lowest at boundaries, when it is highest there.','Overlooking corners, where modal pressure maxima concentrate.']::text[],ARRAY['Placing bass traps in room corners.','Choosing microphone positions for modal measurement.','Explaining why corners have the strongest bass buildup.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure antinodes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d6b4cc4-a1da-4a2a-8e44-ae7c23191115','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d6b4cc4-a1da-4a2a-8e44-ae7c23191115') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d6b4cc4-a1da-4a2a-8e44-ae7c23191115');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a5dc0a2-404d-4654-8da0-f841d575cd71','Pressure nodes','Pressure nodes are locations in a standing-wave field where the acoustic sound-pressure amplitude is minimal (ideally zero) while particle velocity is maximal. In a room mode they occur at fixed fractions of the room dimension, midway between the pressure antinodes formed at rigid boundaries.','A standing wave has still spots for pressure. At these spots the pressure barely changes. But the air is moving the fastest there. In a room they sit between the loud spots near walls.','Knowing where pressure nodes fall tells a technician where a given modal frequency is weakest and where air motion is greatest.','An engineer avoids placing a subwoofer or a pressure-sensing microphone at a mode''s pressure node, since output or pickup there is cancelled for that frequency.','Modal Behavior',ARRAY['Room modes','Resonant modes','Pressure-based absorbers','Quarter-wavelength absorber placement','Resonance decay']::text[],ARRAY['Confusing a pressure node (velocity maximum) with a velocity node (pressure maximum).','Assuming pressure is zero everywhere in the room at a modal frequency, not just at the nodal planes.','Placing a bass trap that senses pressure at a node, where it can do little work.']::text[],ARRAY['Choosing a subwoofer location to avoid modal cancellation.','Explaining why a bass note nearly disappears at one listening seat.','Positioning velocity-type absorbers where pressure nodes and velocity maxima coincide.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure nodes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a5dc0a2-404d-4654-8da0-f841d575cd71','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a5dc0a2-404d-4654-8da0-f841d575cd71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a5dc0a2-404d-4654-8da0-f841d575cd71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '115fbf23-9504-4239-9a43-2be5f1f77fc2','Pressure-based absorbers','Pressure-based absorbers are resonant devices that dissipate sound energy most effectively where acoustic pressure is high, typically at or near room boundaries. They include Helmholtz resonators and membrane (panel/diaphragmatic) absorbers, which convert pressure fluctuations into damped motion tuned to a target low-frequency band.','Some absorbers work best where pressure is high. That happens right next to hard walls. These traps use a sealed cavity or a flexing panel. They soak up a chosen low band of bass.','They target low frequencies that porous materials handle poorly, tuning absorption to specific problem modes near boundaries.','A technician mounts a tuned membrane trap flat against a wall corner, where modal pressure peaks, to tame a strong 60 Hz room resonance.','Room Treatment',ARRAY['Slat and perforated absorbers','Slotted-panel absorber','Quarter-wave absorber','Room modes','Pressure nodes']::text[],ARRAY['Expecting a pressure absorber to work at a pressure node, where pressure is low.','Confusing resonant pressure absorbers with broadband porous (velocity) absorbers.','Mistuning the cavity so the device absorbs the wrong frequency band.']::text[],ARRAY['Treating a low-frequency mode in a control room corner.','Adding tuned traps behind a monitoring position to flatten bass response.','Comparing membrane traps with porous panels for low-end control.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-based absorbers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '115fbf23-9504-4239-9a43-2be5f1f77fc2','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='115fbf23-9504-4239-9a43-2be5f1f77fc2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='115fbf23-9504-4239-9a43-2be5f1f77fc2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '70f0693d-d497-4fe9-a0be-7d86cfeef8b0','Primitive-root diffusion','Primitive-root diffusion is a Schroeder (reflection-phase-grating) diffuser design whose well depths follow a primitive-root sequence modulo a prime N, s_n = g^n mod N, where g is a primitive root of N. The sequence yields a scattered field with a notch (suppressed energy) in the specular direction, useful where the specular reflection must be reduced.','This diffuser uses a number pattern from math. The pattern comes from primitive roots of a prime. Wells of different depths follow that pattern. The result scatters sound and dips the straight-back reflection.','It scatters incident sound while deliberately weakening the mirror-like specular lobe, spreading energy into other directions.','A studio designer selects a primitive-root well pattern (for example g = 3, N = 7 giving 3,2,6,4,5,1) on a ceiling cloud to suppress a direct overhead reflection while diffusing the rest.','Diffusion',ARRAY['Quadratic-residue diffusion','Skyline diffusion','Scattering','Scattering coefficient','Spatial diffusion']::text[],ARRAY['Believing the specular notch is perfect at all frequencies; it holds near design conditions only.','Using a non-prime modulus, which breaks the sequence''s number-theoretic properties.','Confusing primitive-root with quadratic-residue sequences; they use different generators.']::text[],ARRAY['Designing a diffuser to cut a specific specular reflection.','Comparing Schroeder diffuser families for a studio ceiling.','Explaining number-theoretic diffuser design to students.']::text[],'advanced','s_n = g^n mod N','The nth well-depth index equals the primitive root g raised to the power n, taken modulo the prime N.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Primitive-root diffusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '70f0693d-d497-4fe9-a0be-7d86cfeef8b0','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='70f0693d-d497-4fe9-a0be-7d86cfeef8b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='70f0693d-d497-4fe9-a0be-7d86cfeef8b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3f0bb63-0334-4958-982d-144dd7cbf10a','Quadratic-residue diffusion','Quadratic-residue diffusion is a Schroeder phase-grating diffuser whose well-depth sequence is s_n = n^2 mod N, with N an odd prime, and physical depths d_n = (lambda_0 / 2N) * s_n for design wavelength lambda_0. Its exponentiated sequence has a flat spatial Fourier magnitude, so reflected energy spreads nearly uniformly across the scattering lobes over a design bandwidth.','A quadratic-residue diffuser uses squared numbers. It takes n squared and divides by a prime, keeping the remainder. Those remainders set the well depths. The surface then scatters sound evenly across many angles.','It breaks up strong specular reflections and spreads sound energy evenly in space, adding acoustic diffusion without heavy absorption.','For a 500 Hz design (lambda_0 = 0.686 m) with N = 7, the sequence n^2 mod 7 is 0,1,4,2,2,4,1; the deepest well is (0.686/14)x4 = 0.196 m.','Diffusion',ARRAY['Primitive-root diffusion','Skyline diffusion','Scattering coefficient','Scattering','Spatial diffusion']::text[],ARRAY['Using a non-prime N, which spoils the uniform-scattering property.','Assuming a single well width diffuses all frequencies; the useful band is bounded by well width and depth.','Neglecting that thin dividing fins are assumed rigid and lossless in the ideal model.']::text[],ARRAY['Treating the rear wall of a control room for even scattering.','Sizing well depths from a chosen design frequency.','Comparing QRD performance against a flat reflector.']::text[],'advanced','d_n = (lambda_0 / (2N)) * (n^2 mod N)','Each well depth equals the design wavelength divided by twice the prime N, multiplied by n-squared taken modulo N.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quadratic-residue diffusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3f0bb63-0334-4958-982d-144dd7cbf10a','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3f0bb63-0334-4958-982d-144dd7cbf10a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3f0bb63-0334-4958-982d-144dd7cbf10a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bbeff13a-44fb-4b64-90bb-aaf0fc2ca810','Quality factor','The quality factor Q of an acoustic resonance is the ratio of its centre (resonant) frequency f_0 to its -3 dB bandwidth, Q = f_0 / (delta f). A high Q denotes a sharp, lightly damped resonance that rings for a long time; a low Q denotes a broad, heavily damped one that decays quickly.','Quality factor tells how sharp a resonance is. Divide its centre frequency by its bandwidth. A high number means a narrow, ringing peak. A low number means a wide, quickly damped bump.','It quantifies how narrow and how long-ringing a room mode or a resonant absorber is, guiding treatment choices.','A room mode centred at 100 Hz with a -3 dB bandwidth of 5 Hz has Q = 100/5 = 20, indicating a sharp, slowly decaying resonance.','Modal Behavior',ARRAY['Resonant modes','Resonance decay','Room modes','Resonance buildup','Pressure-based absorbers']::text[],ARRAY['Confusing Q with the resonant frequency itself.','Assuming a higher Q is always better; for room modes high Q means audible ringing.','Mixing the -3 dB bandwidth definition with other bandwidth conventions.']::text[],ARRAY['Judging how audible a room mode''s ringing will be.','Specifying a resonant absorber''s selectivity.','Interpreting the width of a peak in a room''s frequency response.']::text[],'intermediate','Q = f_0 / (delta f)','The quality factor equals the resonant frequency divided by the minus three decibel bandwidth.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quality factor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bbeff13a-44fb-4b64-90bb-aaf0fc2ca810','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bbeff13a-44fb-4b64-90bb-aaf0fc2ca810') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bbeff13a-44fb-4b64-90bb-aaf0fc2ca810');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2322d332-d7cb-4c10-a959-0c871ee04a54','Quarter-wave absorber','A quarter-wave absorber is a resonant or velocity-based device whose effective depth equals one quarter of the wavelength at its target frequency, placing an air-particle-velocity maximum within the absorbing material. For a tube or airspace of depth L closed at one end, the fundamental resonance is f = c / (4L).','This absorber is a quarter of a wavelength deep. At that depth the air moves fastest. Placing damping there removes energy well. The tuned frequency is the speed of sound divided by four times the depth.','It targets a specific low or mid frequency by exploiting the velocity maximum that occurs a quarter wavelength from a rigid termination.','To absorb 100 Hz with a closed tube, depth L = c/(4f) = 343/(4x100) = 0.86 m; a shorter cavity tunes a higher frequency.','Room Treatment',ARRAY['Quarter-wavelength absorber placement','Pressure-based absorbers','Slotted-panel absorber','Pressure nodes','Slat and perforated absorbers']::text[],ARRAY['Confusing the quarter-wave (velocity) principle with pressure-based Helmholtz absorption.','Forgetting that closed-tube resonance is c/4L, not c/2L.','Ignoring end corrections and damping that shift and broaden the tuning.']::text[],ARRAY['Building a tuned tube trap for a specific bass note.','Placing porous material a quarter wavelength off a wall.','Explaining why absorber depth sets its lowest effective frequency.']::text[],'intermediate','f = c / (4L)','The fundamental frequency equals the speed of sound divided by four times the cavity depth.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-wave absorber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2322d332-d7cb-4c10-a959-0c871ee04a54','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2322d332-d7cb-4c10-a959-0c871ee04a54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2322d332-d7cb-4c10-a959-0c871ee04a54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38583800-ebbf-47d4-a648-c684bbf7fd2d','Quarter-wavelength absorber placement','Quarter-wavelength absorber placement is the practice of locating porous (velocity-type) absorption where air-particle velocity is greatest, a quarter wavelength from a rigid boundary. The offset distance for a target frequency is d = c / (4f), so a spaced or thicker absorber gains low-frequency effectiveness.','Porous absorbers work on moving air. Air moves fastest a quarter wavelength from a wall. So spacing the panel off the wall helps it catch lower notes. The gap distance is speed of sound over four times the frequency.','It improves a thin porous absorber''s low-frequency performance by moving it into the velocity maximum rather than sitting at the wall pressure maximum.','To help absorb 172 Hz, mount a porous panel d = 343/(4x172) = 0.5 m off the wall, or use an equivalent air gap behind it.','Room Treatment',ARRAY['Quarter-wave absorber','Pressure nodes','Pressure-based absorbers','Room modes','Slat and perforated absorbers']::text[],ARRAY['Mounting thin porous panels flush to the wall, where velocity (and absorption) is low for bass.','Assuming any air gap absorbs all low frequencies rather than a band near c/4d.','Confusing velocity-based placement with pressure-based resonant traps.']::text[],ARRAY['Adding an air gap behind fabric panels to extend bass absorption.','Deciding how far off the wall to float an absorber.','Explaining why absorber depth and spacing matter for the low end.']::text[],'intermediate','d = c / (4f)','The offset from the wall equals the speed of sound divided by four times the target frequency.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-wavelength absorber placement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38583800-ebbf-47d4-a648-c684bbf7fd2d','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38583800-ebbf-47d4-a648-c684bbf7fd2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38583800-ebbf-47d4-a648-c684bbf7fd2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '02aa0834-5c0d-4b16-9dc9-ca1850de846e','Rear-wall interference','Rear-wall interference is speaker-boundary (or listener-boundary) comb filtering caused by reflection from the wall behind a loudspeaker or listener combining with the direct sound. The first cancellation dip occurs where the reflected path is one half wavelength longer, giving f = c / (4d) for a source distance d from the wall.','Sound bounces off the wall behind a speaker. The echo adds to the direct sound. At some frequencies they cancel. The first dip sits at the speed of sound divided by four times the distance to the wall.','It explains the low-frequency dips and peaks (SBIR) heard when a source or listener sits a fixed distance from a hard boundary.','A monitor 0.5 m from the front wall (the boundary behind the speaker) produces a first cancellation dip near f = 343/(4x0.5) = 172 Hz, guiding either repositioning or boundary absorption.','Reflections',ARRAY['Room modes','Slapback reflection','Reflection order','Early reflections','Pressure nodes']::text[],ARRAY['Blaming a room mode for a dip that is actually boundary interference.','Assuming moving the speaker changes only volume, not the dip frequency.','Ignoring the listener''s rear wall, which causes the same effect.']::text[],ARRAY['Diagnosing a fixed bass dip in a monitoring setup.','Choosing speaker-to-wall distance during control-room setup.','Explaining speaker-boundary interference response to students.']::text[],'intermediate','f_dip = c / (4d)','The first cancellation frequency equals the speed of sound divided by four times the source-to-wall distance.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rear-wall interference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '02aa0834-5c0d-4b16-9dc9-ca1850de846e','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='02aa0834-5c0d-4b16-9dc9-ca1850de846e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='02aa0834-5c0d-4b16-9dc9-ca1850de846e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d5f0778-6495-4095-8eab-535192c80a80','Reflection density','Reflection density is the number of individual sound reflections arriving at a receiver per unit time within a room''s impulse response. It is low just after the direct sound, when discrete early reflections are separable, and increases rapidly as later reflections overlap into a dense reverberant tail.','Reflection density counts echoes arriving each second. Just after the direct sound there are only a few. As time passes, more and more arrive. They pile up into a smooth reverberant tail.','It describes how an impulse response transitions from distinct early reflections to a statistically dense, diffuse reverberant field.','An engineer inspecting a measured impulse response sees sparse spikes in the first tens of milliseconds and a dense, smooth region later, marking where reverberation begins.','Reflections',ARRAY['Reflection density growth','Reflection order','Sound-field diffuseness','Early reflections','Spatial diffusion']::text[],ARRAY['Assuming reflection density is constant over the impulse response.','Confusing high reflection density with high level; density concerns count, not loudness.','Ignoring room volume, which strongly sets how fast density grows.']::text[],ARRAY['Reading the structure of a measured room impulse response.','Designing artificial reverberation with a natural density build-up.','Explaining the boundary between early reflections and reverberation.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflection density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d5f0778-6495-4095-8eab-535192c80a80','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d5f0778-6495-4095-8eab-535192c80a80') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d5f0778-6495-4095-8eab-535192c80a80');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f411004-6b95-4e1a-a386-aaedc85f2269','Reflection density growth','Reflection density growth describes how the number of reflections per unit time increases with the square of elapsed time in a room, following dN/dt = 4*pi*c^3*t^2 / V. This quadratic growth causes discrete early reflections to merge quickly into a dense reverberant field.','The number of echoes per second grows fast. It grows with the square of time. Bigger rooms build density more slowly. This is why early echoes soon blur into smooth reverberation.','It quantifies how rapidly a room''s impulse response fills in, linking room volume and the speed of sound to the onset of a diffuse tail.','In a 100 m^3 room at t = 0.1 s, dN/dt = 4*pi*(343)^3*(0.1)^2/100 is about 5.1x10^4 reflections per second, already a dense field.','Reflections',ARRAY['Reflection density','Reflection order','Sound-field diffuseness','Reverberation time','Spatial diffusion']::text[],ARRAY['Treating growth as linear rather than proportional to t squared.','Forgetting that larger volume V slows the density build-up.','Assuming the formula gives level; it gives a reflection rate.']::text[],ARRAY['Estimating when reverberation becomes statistically diffuse.','Setting early-reflection versus late-reverb boundaries in a reverb algorithm.','Comparing small and large rooms'' impulse-response density.']::text[],'advanced','dN/dt = 4*pi*c^3*t^2 / V','The reflections arriving per second equal four pi times the cube of sound speed times time squared, divided by room volume.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflection density growth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f411004-6b95-4e1a-a386-aaedc85f2269','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f411004-6b95-4e1a-a386-aaedc85f2269') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f411004-6b95-4e1a-a386-aaedc85f2269');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3fd65c94-f68d-40b9-adda-f7d92f0438fe','Reflection order','Reflection order is the number of surface bounces a given sound path has undergone before reaching the receiver: a first-order reflection strikes one surface, a second-order reflection two, and so on. Higher-order reflections are generally weaker, more delayed, and more numerous, contributing to the diffuse reverberant field.','Reflection order counts how many walls a sound path hits. One bounce is first order. Two bounces is second order. Higher orders arrive later, quieter, and in greater numbers.','It classifies reflection paths by bounce count, helping separate strong early reflections from the many weak, late ones that form reverberation.','Using the image-source method, a technician traces first- and second-order reflection paths to find and treat the strongest early reflection points around a mix position.','Reflections',ARRAY['Reflection density','Early reflections','Slapback reflection','Rear-wall interference','Reflection density growth']::text[],ARRAY['Assuming only first-order reflections matter; higher orders build the reverberant tail.','Confusing reflection order with arrival time; order correlates with but does not equal delay.','Believing higher-order reflections are always inaudible.']::text[],ARRAY['Locating first-reflection points for absorber placement.','Running an image-source or ray-tracing acoustic model.','Explaining how reverberation is built from many reflection orders.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflection order');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3fd65c94-f68d-40b9-adda-f7d92f0438fe','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3fd65c94-f68d-40b9-adda-f7d92f0438fe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3fd65c94-f68d-40b9-adda-f7d92f0438fe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6dadf0e-46f0-4923-8c12-52e903c6de3a','Resonance buildup','Resonance buildup is the transient growth of stored acoustic energy at a resonant frequency (such as a room mode) when it is continuously excited, rising toward a steady-state level. The buildup follows an exponential approach whose time constant is longer for higher-Q, lightly damped resonances.','When you drive a resonance, energy grows over time. It does not jump to full strength at once. It rises toward a steady level. Sharp, lightly damped modes take longer to build up.','It explains why a sustained tone at a modal frequency swells in level, complementing the decay seen after the source stops.','A technician sweeping a sine tone hears certain notes swell and hang as room modes build energy, flagging frequencies that need modal treatment.','Modal Behavior',ARRAY['Resonance decay','Quality factor','Room modes','Resonant modes','Reverberation buildup']::text[],ARRAY['Assuming a resonance reaches full amplitude instantly.','Confusing buildup time with the separate decay time, though both scale with Q.','Ignoring buildup when judging steady-state modal peaks.']::text[],ARRAY['Hearing a bass note swell during a slow sine sweep.','Understanding modal ringing under sustained excitation.','Relating high Q to slow energy buildup and long decay.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonance buildup');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6dadf0e-46f0-4923-8c12-52e903c6de3a','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6dadf0e-46f0-4923-8c12-52e903c6de3a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6dadf0e-46f0-4923-8c12-52e903c6de3a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44a8e55c-79e9-4777-8da6-e2eea7d2beae','Resonance decay','Resonance decay is the exponential decrease of stored energy at a resonant frequency after excitation stops, heard as ringing at a room mode or resonant device. The decay rate is inversely related to the quality factor Q; higher-Q resonances ring longer before fading.','When the source stops, a resonance keeps ringing. Its energy fades away smoothly. Sharp, high-Q resonances ring for a long time. Well-damped ones die out quickly.','It describes the audible ringing left after a signal stops, a key symptom of untreated room modes and lightly damped resonators.','After a kick drum, a control room''s 45 Hz mode may ring for hundreds of milliseconds; adding damping lowers its Q and shortens that decay.','Modal Behavior',ARRAY['Resonance buildup','Quality factor','Room modes','Resonant modes','Reverberation time']::text[],ARRAY['Blaming a boomy, ringing bass on the source rather than modal decay.','Assuming absorption changes the modal frequency; it mainly lowers Q and shortens decay.','Confusing modal ringing with whole-room reverberation time.']::text[],ARRAY['Diagnosing boomy, lingering bass in a small room.','Measuring modal decay in a waterfall (spectral-decay) plot.','Evaluating how added bass traps shorten mode ringing.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonance decay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44a8e55c-79e9-4777-8da6-e2eea7d2beae','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44a8e55c-79e9-4777-8da6-e2eea7d2beae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44a8e55c-79e9-4777-8da6-e2eea7d2beae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ba9777a-7379-4349-91e9-d073d6d6d93f','Resonant frequency versus center frequency','The resonant frequency is the natural frequency at which a system (a room mode, resonator, or filter) stores and exchanges energy most readily, while the centre frequency is the reference frequency of a defined band, conventionally the geometric mean of its lower and upper edges (f_c = sqrt(f_1*f_2)). The two often coincide for a simple resonator but are distinct concepts.','A resonant frequency is where a system naturally rings. A centre frequency is just the middle of a chosen band. For bands, the middle is the geometric mean of the edges. The two ideas are not the same.','It distinguishes a physical resonance from the arbitrary reference frequency used to label an analysis or filter band.','An octave band centred at 1 kHz spans about 707-1414 Hz (f_c = sqrt(707x1414) = 1000 Hz); a device resonating at 1 kHz is a separate physical property.','Analysis Concepts',ARRAY['Quality factor','Resonant modes','Room modes','Resonance decay','Pressure-based absorbers']::text[],ARRAY['Assuming a filter''s centre frequency implies a physical resonance there.','Taking the centre frequency as the arithmetic mean instead of the geometric mean.','Treating resonant and centre frequency as interchangeable in all contexts.']::text[],ARRAY['Reading octave- or third-octave band analyzer labels.','Distinguishing a tuned absorber''s resonance from a graphic-EQ band.','Explaining band-centre conventions to students.']::text[],'intermediate','f_c = sqrt(f_1 * f_2)','A band centre frequency equals the square root of the product of its lower and upper edge frequencies.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonant frequency versus center frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ba9777a-7379-4349-91e9-d073d6d6d93f','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ba9777a-7379-4349-91e9-d073d6d6d93f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ba9777a-7379-4349-91e9-d073d6d6d93f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01019ff9-8165-4887-8dbd-083f3d17cd28','Resonant modes','Resonant modes are the natural standing-wave patterns of a room, each with a characteristic frequency and spatial pressure distribution set by the room geometry and boundaries. In a rectangular room they divide into axial (two surfaces), tangential (four surfaces), and oblique (six surfaces) modes.','A room has natural standing-wave patterns. Each pattern has its own frequency and shape. In a box-shaped room they come in three families. These are axial, tangential, and oblique modes.','They explain the uneven low-frequency response of a room, since energy concentrates at modal frequencies and specific locations.','A technician calculates the axial modes of a room from its dimensions to predict where bass will be strong or weak before positioning speakers and listener.','Modal Behavior',ARRAY['Room modes','Pressure nodes','Resonance decay','Quality factor','Room symmetry']::text[],ARRAY['Considering only axial modes and ignoring tangential and oblique ones.','Assuming modes matter across the full spectrum rather than mainly at low frequencies.','Confusing a mode''s frequency with its spatial pressure pattern.']::text[],ARRAY['Predicting low-frequency peaks and dips in a listening room.','Choosing room dimension ratios to spread modes evenly.','Explaining axial, tangential, and oblique mode families.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonant modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01019ff9-8165-4887-8dbd-083f3d17cd28','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01019ff9-8165-4887-8dbd-083f3d17cd28') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01019ff9-8165-4887-8dbd-083f3d17cd28');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6845569-fbc6-4613-960e-89ddbc9ab0da','Room constant','The room constant R characterises a room''s total sound absorption for steady-state analysis, defined as R = S*alpha_bar / (1 - alpha_bar), where S is total surface area and alpha_bar is the surface-averaged absorption coefficient. It sets the reverberant-field level and the critical distance at which direct and reverberant fields are equal.','The room constant sums up how absorptive a room is. It uses the total surface area and the average absorption. A bigger room constant means a quieter reverberant field. It also sets the critical distance.','It provides a single figure for predicting reverberant sound-pressure level and critical distance in steady-state room-acoustics calculations.','For S = 200 m^2 and alpha_bar = 0.2, R = 200x0.2/(1-0.2) = 50 m^2, giving a critical distance of about 0.141*sqrt(50) = 1.0 m for an omnidirectional source.','Sound Fields',ARRAY['Critical distance','Room gain','Sabine equation','Sound-field diffuseness','Reverberation time']::text[],ARRAY['Confusing the room constant R (m^2) with total absorption A = S*alpha_bar.','Using it at low frequencies where the modal field, not statistical theory, dominates.','Forgetting the (1 - alpha_bar) denominator, which matters in absorptive rooms.']::text[],ARRAY['Estimating reverberant level from a source''s power.','Calculating critical distance for microphone placement.','Comparing how added absorption raises the room constant.']::text[],'advanced','R = S*alpha_bar / (1 - alpha_bar)','The room constant equals total surface area times average absorption coefficient, divided by one minus that average coefficient.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6845569-fbc6-4613-960e-89ddbc9ab0da','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6845569-fbc6-4613-960e-89ddbc9ab0da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6845569-fbc6-4613-960e-89ddbc9ab0da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2fc91715-d271-46c1-9d47-692db70c8a3b','Room gain','Room gain (also called cabin or pressure-zone gain) is the low-frequency level boost that occurs in a small, well-sealed room at frequencies below its lowest axial mode, where the enclosure behaves as a pressure vessel rather than supporting wave motion. In such sealed spaces the response can rise on the order of 12 dB per octave as frequency falls below the modal region.','In a small sealed room, very low bass gets louder. Below the lowest mode the room acts like a sealed box. Pressure rises everywhere together. The level can climb about 12 dB per octave going down.','It explains extra deep-bass reinforcement in small sealed spaces, affecting how subwoofers and low-frequency response behave below the modal region.','In a tightly sealed control room a subwoofer''s deep output may rise steeply below the lowest mode, so a technician accounts for this boost when setting low-end level and equalization.','Sound Fields',ARRAY['Room modes','Room constant','Resonant modes','Pressure nodes','Pressure-based absorbers']::text[],ARRAY['Confusing room gain with modal peaks; room gain acts below the lowest mode.','Expecting the same boost in a leaky room, where sealing is poor.','Assuming room gain adds usable output at all low frequencies rather than only the deepest.']::text[],ARRAY['Explaining strong deep-bass lift in a small sealed room or vehicle.','Setting subwoofer level and EQ below the modal region.','Comparing sealed and leaky rooms'' low-frequency behaviour.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2fc91715-d271-46c1-9d47-692db70c8a3b','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2fc91715-d271-46c1-9d47-692db70c8a3b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2fc91715-d271-46c1-9d47-692db70c8a3b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c6097f46-addd-4e76-9573-2856ada352ec','Room modes','Room modes are the standing-wave resonances of an enclosed space, each occurring at a frequency set by the room dimensions. For a rigid rectangular room the modal frequencies are f = (c/2)*sqrt((p/Lx)^2 + (q/Ly)^2 + (r/Lz)^2), where p, q, r are non-negative integers naming the mode.','Room modes are the room''s natural bass resonances. Each depends on the room size. Some frequencies get reinforced and others cancel. This makes bass uneven from seat to seat.','They account for the uneven, position-dependent low-frequency response of rooms and guide speaker, listener, and treatment placement.','For a 5 m room length the first axial mode (1,0,0) is f = 343/(2x5) = 34.3 Hz, a frequency where that dimension reinforces bass.','Modal Behavior',ARRAY['Resonant modes','Pressure nodes','Room symmetry','Resonance decay','Room gain']::text[],ARRAY['Treating only axial modes and ignoring tangential and oblique ones.','Assuming modes can be fully removed rather than managed and damped.','Applying the rectangular formula to strongly non-rectangular rooms.']::text[],ARRAY['Predicting bass peaks and nulls in a listening room.','Selecting favourable room-dimension ratios.','Positioning subwoofer and seat to even out modal response.']::text[],'intermediate','f = (c/2)*sqrt((p/Lx)^2 + (q/Ly)^2 + (r/Lz)^2)','A modal frequency equals half the speed of sound times the root of the summed squares of each mode number over its room dimension.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c6097f46-addd-4e76-9573-2856ada352ec','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c6097f46-addd-4e76-9573-2856ada352ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c6097f46-addd-4e76-9573-2856ada352ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69907d2d-137a-4c3e-af56-e4165a464e4a','Room symmetry','Room symmetry refers to arranging a room''s boundaries, treatment, and loudspeakers symmetrically about the primary listening axis so that the two ears receive balanced early-reflection and modal energy. Left-right symmetry supports accurate stereo imaging and a stable phantom centre.','Room symmetry means the left and right sides match. The speakers and walls mirror each other around the listener. This gives each ear a balanced sound. Stereo imaging then stays centred and stable.','It ensures the reflection and modal environment is balanced left to right, which is essential for reliable stereo and surround imaging.','A technician sets up the mix position on the room''s centre line with matching side-wall distances and absorption, so a centred mono signal images precisely between the speakers.','Room Design',ARRAY['Room modes','Early reflections','Rear-wall interference','Resonant modes','Spatial diffusion']::text[],ARRAY['Placing the listening position off the centre line, skewing the stereo image.','Treating one side wall but not its mirror partner.','Assuming symmetry fixes modal problems; it balances but does not remove them.']::text[],ARRAY['Laying out a control room for accurate imaging.','Matching left and right side-wall treatment.','Diagnosing a pulled or unstable phantom centre.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room symmetry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69907d2d-137a-4c3e-af56-e4165a464e4a','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69907d2d-137a-4c3e-af56-e4165a464e4a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69907d2d-137a-4c3e-af56-e4165a464e4a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '03b2a903-112b-4465-8ea0-61cdeb5183fb','Sabine equation','The Sabine equation estimates a room''s reverberation time from its volume and total absorption: RT60 = 0.161 * V / A (SI units), where V is room volume in cubic metres and A = sum of S_i*alpha_i is total absorption in metric sabins. It assumes a diffuse sound field and relatively low average absorption.','The Sabine equation predicts how long sound lingers. It uses the room volume and its total absorption. Bigger rooms reverberate longer. More absorption shortens the decay.','It gives a quick, widely used estimate of reverberation time for room design and treatment planning.','For V = 100 m^3 and A = 20 metric sabins, RT60 = 0.161x100/20 = 0.805 s; adding absorption to raise A shortens that time.','Reverberation',ARRAY['Eyring equation','Reverberation time','Room constant','Sound-field diffuseness','Absorption coefficient']::text[],ARRAY['Using Sabine in highly absorptive rooms, where Eyring is more accurate.','Mixing SI (0.161) and imperial (0.049) constants and units.','Applying it at low frequencies dominated by discrete modes.']::text[],ARRAY['Estimating reverberation time from room size and finishes.','Specifying absorption to hit a target RT60.','Comparing predicted and measured reverberation times.']::text[],'intermediate','RT60 = 0.161 * V / A','Reverberation time equals the constant 0.161 times room volume divided by total absorption in metric sabins.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sabine equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '03b2a903-112b-4465-8ea0-61cdeb5183fb','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='03b2a903-112b-4465-8ea0-61cdeb5183fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='03b2a903-112b-4465-8ea0-61cdeb5183fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '621d690f-fa21-4d05-a23e-0e9b98cf1325','Scattering','Scattering is the redirection of incident sound by a surface or object into directions other than the single specular (mirror) angle, spreading reflected energy across many angles. It arises from surface roughness, shape, or impedance variation comparable in scale to the wavelength.','Scattering spreads a reflection in many directions. A flat wall reflects sound like a mirror. A rough or shaped surface breaks that up. The energy fans out instead of going one way.','It reduces strong specular reflections and helps create a more even, diffuse sound field without simply absorbing energy.','A technician adds a shaped or textured surface to a rear wall so a would-be specular echo is scattered, softening a distinct reflection while keeping liveliness.','Diffusion',ARRAY['Scattering coefficient','Spatial diffusion','Quadratic-residue diffusion','Sound-field diffuseness','Skyline diffusion']::text[],ARRAY['Equating scattering with absorption; scattering redistributes energy rather than removing it.','Assuming a surface scatters equally at all frequencies regardless of feature size.','Confusing scattering (energy spread) with the diffusion coefficient (spatial uniformity).']::text[],ARRAY['Breaking up a specular rear-wall reflection.','Choosing between absorption and diffusion for a live room.','Explaining how surface texture affects reflected sound.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scattering');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '621d690f-fa21-4d05-a23e-0e9b98cf1325','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='621d690f-fa21-4d05-a23e-0e9b98cf1325') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='621d690f-fa21-4d05-a23e-0e9b98cf1325');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d3eca89-f1c1-45d0-ac97-810e7a341353','Scattering coefficient','The random-incidence scattering coefficient s is the ratio of non-specularly reflected sound energy to the total reflected energy from a surface, ranging from 0 (purely specular) to 1 (all energy scattered). It is standardised for reverberation-room measurement in ISO 17497-1 and is distinct from the diffusion coefficient of ISO 17497-2.','This number rates how much a surface scatters. It is the scattered energy divided by all the reflected energy. Zero means a perfect mirror. One means all the sound is scattered away from the mirror angle.','It gives a single input value describing a surface''s scattering for room-acoustics prediction models and diffuser comparison.','If 30 percent of the reflected energy leaves the specular direction, the scattering coefficient is s = 0.3, a value fed into a ray-tracing room model.','Diffusion',ARRAY['Scattering','Spatial diffusion','Quadratic-residue diffusion','Sound-field diffuseness','Absorption coefficient']::text[],ARRAY['Confusing the scattering coefficient with the diffusion coefficient; they measure different things.','Reading it as an absorption value; scattered energy is still reflected.','Assuming one value applies at all frequencies rather than per band.']::text[],ARRAY['Supplying surface scattering data to an acoustic simulation.','Comparing diffuser products by measured scattering.','Distinguishing scattering from diffusion coefficients.']::text[],'advanced','s = E_non-specular / E_total-reflected','The scattering coefficient equals reflected energy leaving the specular direction divided by the total reflected energy.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scattering coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d3eca89-f1c1-45d0-ac97-810e7a341353','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d3eca89-f1c1-45d0-ac97-810e7a341353') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d3eca89-f1c1-45d0-ac97-810e7a341353');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d19c13e-e4f3-447f-a890-eea4a8984b55','Skyline diffusion','Skyline diffusion uses a two-dimensional array of blocks or wells of varying height, resembling a city skyline, to scatter sound in two dimensions rather than one. The heights typically follow a two-dimensional number-theoretic sequence, extending Schroeder diffuser principles to hemispherical scattering.','A skyline diffuser looks like a city of blocks. The blocks have different heights. This scatters sound in two directions at once. A one-dimensional diffuser only scatters in one plane.','It provides scattering across two dimensions, spreading reflected energy over a hemisphere instead of a single arc.','A studio fits a skyline (2D number-theoretic) panel on a ceiling cloud to diffuse reflections both front-back and side-to-side above the mix position.','Diffusion',ARRAY['Quadratic-residue diffusion','Primitive-root diffusion','Scattering','Spatial diffusion','Scattering coefficient']::text[],ARRAY['Assuming random block heights work as well as a designed sequence.','Expecting broadband diffusion beyond the range set by block size and depth.','Treating a 2D skyline as identical to a 1D well diffuser.']::text[],ARRAY['Diffusing ceiling reflections in two dimensions.','Choosing between 1D and 2D diffuser geometries.','Explaining hemispherical scattering to students.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Skyline diffusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d19c13e-e4f3-447f-a890-eea4a8984b55','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d19c13e-e4f3-447f-a890-eea4a8984b55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d19c13e-e4f3-447f-a890-eea4a8984b55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee90e3d7-7862-4d68-a192-bb5f8b987b16','Slapback reflection','A slapback reflection is a single, distinct delayed repetition of a sound produced by a strong reflection off a hard, usually parallel, surface, arriving late enough to be heard as a discrete echo rather than merging with the direct sound. In rooms it is commonly associated with delays of roughly tens of milliseconds.','Slapback is one clear echo. A hard wall bounces the sound straight back. It arrives a little late. You hear it as a distinct repeat, not part of the original.','It names the discrete single echo that hard parallel surfaces create, a defect in critical spaces though sometimes used as an effect.','A technician who hears a distinct handclap echo between two parallel hard walls adds absorption or diffusion to one surface to remove the slapback.','Reflections',ARRAY['Rear-wall interference','Reflection order','Flutter echo','Early reflections','Scattering']::text[],ARRAY['Confusing a single slapback with a repeating flutter echo.','Assuming slapback is reverberation; it is one discrete reflection.','Treating only one of two parallel walls and leaving the echo path intact.']::text[],ARRAY['Diagnosing a distinct clap echo in an untreated room.','Deciding between absorption and diffusion for parallel walls.','Using slapback deliberately as a vocal effect.']::text[],'beginner',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slapback reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee90e3d7-7862-4d68-a192-bb5f8b987b16','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee90e3d7-7862-4d68-a192-bb5f8b987b16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee90e3d7-7862-4d68-a192-bb5f8b987b16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b6867a37-9448-4a9a-a8c6-a0a6f07f5272','Slat and perforated absorbers','Slat and perforated absorbers are resonant (Helmholtz-type) absorbers formed by a slatted or perforated facing mounted over an air cavity, usually with porous fill behind it. The mass of air in the openings and the springiness of the cavity form a resonance that absorbs a tuned low-to-mid frequency band set by open area, thickness, and cavity depth.','These absorbers use a slotted or perforated front panel. Behind it is an air space, often with soft filling. The panel and cavity form a resonator. It soaks up a chosen band of lower frequencies.','They provide frequency-selective absorption in the low-to-mid range, where thin porous panels are ineffective, by resonant action.','A technician tunes the perforation percentage and cavity depth of a wood-slat panel so it absorbs a troublesome 200 Hz band while reflecting highs to keep the room lively.','Room Treatment',ARRAY['Slotted-panel absorber','Pressure-based absorbers','Quarter-wave absorber','Room modes','Quarter-wavelength absorber placement']::text[],ARRAY['Expecting broadband absorption from a resonant tuned device.','Ignoring how open area and cavity depth set the tuned frequency.','Omitting porous fill, which broadens and damps the absorption band.']::text[],ARRAY['Adding frequency-selective absorption to a live room.','Tuning a wood-slat wall to a specific problem band.','Balancing absorption and reflection for a natural sound.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slat and perforated absorbers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b6867a37-9448-4a9a-a8c6-a0a6f07f5272','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b6867a37-9448-4a9a-a8c6-a0a6f07f5272') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b6867a37-9448-4a9a-a8c6-a0a6f07f5272');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d7418f1-3185-4aeb-83ed-e5d7cdf1b895','Slotted-panel absorber','A slotted-panel absorber is a Helmholtz resonant absorber whose facing is a rigid panel cut with slots over a sealed air cavity, often with porous damping inside. The air mass in the slots resonates against the cavity compliance to absorb a tuned band, with the resonance frequency governed by slot geometry, panel thickness, and cavity depth.','A slotted-panel absorber is a rigid panel with cut slots. A sealed air space sits behind it. The air in the slots and the cavity form a resonator. It absorbs one tuned band of frequencies.','It targets a narrow low-to-mid frequency band for absorption using Helmholtz resonance, useful for taming a specific mode.','A technician sizes the slot width, spacing, and cavity depth of a slotted panel to place its resonance on a room''s boomy 120 Hz mode.','Room Treatment',ARRAY['Slat and perforated absorbers','Pressure-based absorbers','Quarter-wave absorber','Room modes','Resonant modes']::text[],ARRAY['Confusing a slotted (resonant) absorber with a broadband porous panel.','Miscalculating slot open area, which shifts the tuned frequency.','Leaving the cavity undamped, giving too narrow and peaky an absorption band.']::text[],ARRAY['Building a tuned trap for a single low-frequency mode.','Designing decorative wood facings with acoustic function.','Comparing slotted, perforated, and membrane resonant absorbers.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Slotted-panel absorber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d7418f1-3185-4aeb-83ed-e5d7cdf1b895','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d7418f1-3185-4aeb-83ed-e5d7cdf1b895') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d7418f1-3185-4aeb-83ed-e5d7cdf1b895');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ccb369bb-5d37-464a-b0bc-9d8e5f24c720','Sound-field diffuseness','Sound-field diffuseness is the degree to which acoustic energy arrives uniformly from all directions with random phase and uniform energy density throughout a space. A perfectly diffuse field is an idealisation assumed by statistical room acoustics and reverberation-room measurement standards.','A diffuse field has sound coming from everywhere equally. The energy is spread evenly through the space. The waves arrive with random timing. Real rooms only approach this ideal.','It underpins statistical reverberation theory and defines the reference condition for reverberation-room and diffusion measurements.','A technician measuring absorption in a reverberation chamber relies on a near-diffuse field, using diffusing panels and multiple positions to satisfy the assumption.','Sound Fields',ARRAY['Spatial diffusion','Scattering','Reverberation time','Sabine equation','Reflection density']::text[],ARRAY['Assuming small rooms have a diffuse field at low frequencies, where modes dominate.','Confusing diffuseness (directional uniformity) with diffusion by a surface.','Treating any reverberant space as perfectly diffuse.']::text[],ARRAY['Justifying statistical reverberation calculations.','Setting up a reverberation chamber measurement.','Explaining why very small rooms are not diffuse in the bass.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field diffuseness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ccb369bb-5d37-464a-b0bc-9d8e5f24c720','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ccb369bb-5d37-464a-b0bc-9d8e5f24c720') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ccb369bb-5d37-464a-b0bc-9d8e5f24c720');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ea4e469b-bd60-4823-b5e2-85b2a7ddfd7b','Sound-speed gradients','Sound-speed gradients are spatial variations in the speed of sound within a medium, caused chiefly by changes in air temperature (and to a lesser extent humidity and wind). Because sound bends toward regions of lower speed, these gradients refract sound paths, an effect significant over large distances and in large or non-uniform spaces.','The speed of sound changes with air temperature. Warm and cool layers make sound travel at different speeds. This bends the sound path, like light in water. The effect grows over long distances.','It explains refraction and path bending of sound through non-uniform air, affecting outdoor propagation and very large indoor spaces.','An engineer covering a large outdoor event notes that a cool evening temperature gradient bends sound downward, changing coverage compared with midday.','Propagation',ARRAY['Speed of sound','Refraction','Reflection order','Spatial diffusion','Sound-field diffuseness']::text[],ARRAY['Assuming the speed of sound is fixed regardless of temperature.','Ignoring gradients over long outdoor distances.','Confusing refraction from gradients with reflection off surfaces.']::text[],ARRAY['Planning outdoor sound coverage across a temperature gradient.','Explaining why distant sound seems louder at night.','Accounting for air conditions in large-venue propagation.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-speed gradients');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ea4e469b-bd60-4823-b5e2-85b2a7ddfd7b','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ea4e469b-bd60-4823-b5e2-85b2a7ddfd7b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ea4e469b-bd60-4823-b5e2-85b2a7ddfd7b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa594453-8161-4b70-a40d-7dea93b73ebc','Spatial diffusion','Spatial diffusion is the even spreading of reflected sound energy across space and direction, producing a smooth, enveloping reverberant field without strong directional reflections. It is achieved by scattering surfaces and by a high density of reflections arriving from many directions.','Spatial diffusion spreads reflected sound evenly around a room. No one direction is louder. The sound feels smooth and open. Rough surfaces and many echoes create it.','It creates a uniform, spacious sound field and reduces harsh directional reflections, improving listener envelopment.','A technician distributes diffusers around a room so reflected energy arrives evenly from many angles, giving a spacious sound without hot-spot reflections.','Diffusion',ARRAY['Scattering','Sound-field diffuseness','Scattering coefficient','Quadratic-residue diffusion','Reflection density']::text[],ARRAY['Confusing spatial diffusion with adding absorption; diffusion keeps energy alive.','Assuming a single diffuser panel diffuses the whole room.','Mixing spatial diffusion with the surface diffusion coefficient metric.']::text[],ARRAY['Creating an enveloping, spacious reverberant field.','Placing diffusers to avoid strong single reflections.','Explaining envelopment in concert-hall acoustics.']::text[],'intermediate',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial diffusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa594453-8161-4b70-a40d-7dea93b73ebc','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa594453-8161-4b70-a40d-7dea93b73ebc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa594453-8161-4b70-a40d-7dea93b73ebc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd9017707-2748-4aa4-89d7-538f19c6d93f','Speech clarity','Speech clarity is the perceived distinctness of speech in a room, degraded by reverberation and late reflections that mask direct sound. It is quantified by early-to-late energy ratios such as C50 (early energy up to 50 ms relative to later energy) and by the Speech Transmission Index defined in IEC 60268-16.','Speech clarity is how clearly words are heard. Too much reverberation blurs speech. Early sound helps, but late echoes hurt. Measures like C50 and the Speech Transmission Index rate it.','It rates how intelligible speech will be in a space, guiding acoustic design and sound-system tuning for talkers and announcements.','If early speech energy is three times the late energy, C50 = 10*log10(3) = 4.8 dB; higher C50 indicates clearer speech.','Intelligibility',ARRAY['Reverberation time','Early reflections','Reflection density','Sound-field diffuseness','Sabine equation']::text[],ARRAY['Assuming low reverberation alone guarantees intelligibility, ignoring background noise.','Confusing C50 (speech) with C80 (music) clarity measures.','Treating STI and C50 as identical rather than complementary metrics.']::text[],ARRAY['Assessing a lecture hall or house of worship for speech.','Tuning a paging or announcement system for intelligibility.','Comparing C50 and STI results for a room.']::text[],'advanced','C50 = 10 * log10( E(0-50 ms) / E(50 ms-inf) )','Speech clarity C50 in decibels equals ten times the base-ten log of early sound energy up to 50 ms divided by the energy arriving after 50 ms.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech clarity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd9017707-2748-4aa4-89d7-538f19c6d93f','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d9017707-2748-4aa4-89d7-538f19c6d93f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d9017707-2748-4aa4-89d7-538f19c6d93f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '40745d56-12e2-4eca-af2a-e6cbeb46fb50','Stage support','Stage support (ST) is an ISO 3382-1 objective stage-acoustic parameter that quantifies how well a platform returns early and late reflected energy to a musician. It is the level of reflected sound in a defined later time window relative to the direct sound, measured with an omnidirectional source and receiver spaced 1 m apart on the stage.','On a stage, players hear their own sound come back off nearby surfaces. Stage support measures how strong that returned sound is. A microphone sits one metre from the source. The number compares reflected energy to the direct sound.','It predicts how easily performers can hear themselves and each other, which affects ensemble playing and perceived effort on stage.','An acoustician places a source and mic 1 m apart on an empty stage; if the 20-100 ms early energy is 0.04 times the 0-10 ms direct energy, ST-early = 10 log(0.04) = -14 dB.','Room Acoustic Parameter',ARRAY['Early reflections','Initial time-delay gap','Stored energy in resonant systems','Clarity metrics','Energy decay curve']::text[],ARRAY['Forgetting the fixed 1 m source-to-receiver distance that ISO 3382-1 requires.','Confusing ST-early (20-100 ms) with the late window (100-1000 ms).','Treating a more negative ST value as always worse rather than context-dependent.']::text[],ARRAY['Assessing whether an orchestra can hear itself on a concert platform.','Comparing riser and reflector layouts during a hall commissioning survey.','Diagnosing why musicians on a large stage report poor ensemble contact.']::text[],'advanced','ST_early = 10*log10( INT_{20ms}^{100ms} p^2(t) dt / INT_{0ms}^{10ms} p^2(t) dt )','Stage support (early) is ten times the base-ten logarithm of the reflected sound energy from twenty to one hundred milliseconds divided by the direct sound energy from zero to ten milliseconds.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stage support');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '40745d56-12e2-4eca-af2a-e6cbeb46fb50','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='40745d56-12e2-4eca-af2a-e6cbeb46fb50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='40745d56-12e2-4eca-af2a-e6cbeb46fb50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f877955d-67c4-419e-9a9e-953ea09e9e6a','Standing waves','A standing wave is a stationary interference pattern formed when a sound wave reflects between opposing boundaries and superposes with itself, producing fixed pressure maxima (antinodes) and minima (nodes). In a room, standing waves occur at frequencies whose half-wavelength multiples fit the boundary spacing, creating room resonances.','When sound bounces between two walls, the reflections can line up with the outgoing wave. This makes a fixed pattern that does not travel. Some spots stay loud and others stay quiet. These trapped patterns are the room''s resonances.','Understanding standing waves explains why small rooms boost or cancel certain low frequencies at fixed locations, shaping bass response.','Between parallel walls 3.43 m apart, the lowest standing wave sits at f = c/(2L) = 343/(2 x 3.43) = 50 Hz, so a technician expects a bass peak or null there.','Wave Behavior',ARRAY['Room modes','Axial modes','Pressure antinodes','Acoustic resonance','Statistical region']::text[],ARRAY['Believing a standing wave travels; the pattern is stationary while energy still cycles.','Assuming only one standing-wave frequency exists between two surfaces, ignoring harmonics.','Confusing pressure nodes with velocity nodes, which occur at opposite locations.']::text[],ARRAY['Explaining a persistent bass boom at one seat in a small studio.','Predicting low-frequency peaks from parallel untreated walls.','Placing a subwoofer to avoid exciting a strong room resonance.']::text[],'intermediate','f_n = n*c/(2*L)','The standing-wave frequencies between two parallel surfaces equal an integer times the speed of sound divided by twice the surface spacing.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Standing waves');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f877955d-67c4-419e-9a9e-953ea09e9e6a','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f877955d-67c4-419e-9a9e-953ea09e9e6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f877955d-67c4-419e-9a9e-953ea09e9e6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81134580-f68b-477d-aff0-5bb4ebf4570b','Statistical region','The statistical region is the frequency range above the Schroeder frequency in which room modes overlap heavily and the sound field can be treated statistically as approximately diffuse rather than as discrete resonances. In this region geometric and energy-based (statistical) acoustics, such as the Sabine model, apply.','At high frequencies a room has so many resonances that they blur together. No single mode dominates. The sound field then behaves like an even, random mix. This blurred high-frequency range is the statistical region.','It marks where energy-based tools like reverberation-time formulas are valid, guiding when to model a room statistically instead of mode by mode.','For a 500 m^3 room with 1 s reverberation time, the Schroeder frequency is 2000*sqrt(1/500) = 89 Hz, so above roughly 89 Hz the room is in its statistical region.','Acoustic Regime',ARRAY['Transition between modal and geometric behavior','Diffuse-field assumptions','Modal region','Sabine equation','Room modes']::text[],ARRAY['Applying Sabine reverberation theory below the Schroeder frequency where modes are discrete.','Assuming a small room ever becomes truly diffuse at low frequencies.','Treating the Schroeder frequency as a sharp edge rather than a gradual transition.']::text[],ARRAY['Deciding whether reverberation-time formulas apply to a small control room.','Separating modal bass problems from broadband reverberation issues.','Interpreting a room''s frequency response above and below its Schroeder frequency.']::text[],'advanced','f_S = 2000 * sqrt(T60 / V)','The Schroeder frequency, marking the lower edge of the statistical region, is two thousand times the square root of reverberation time divided by room volume.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Statistical region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81134580-f68b-477d-aff0-5bb4ebf4570b','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81134580-f68b-477d-aff0-5bb4ebf4570b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81134580-f68b-477d-aff0-5bb4ebf4570b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f8df5cdf-64bc-4179-ba28-9a72771c488e','Stored energy in resonant systems','In a resonant acoustic or mechanical system, stored energy is the energy held in the oscillation, cycling between potential (compression/stiffness) and kinetic (motion/mass) forms. The ratio of stored energy to energy dissipated per radian defines the quality factor Q, so high stored energy relative to loss means sharp, long-ringing resonance.','A resonator holds energy as it vibrates. That energy swaps between motion and springiness each cycle. If little energy leaks away, the resonance is sharp and rings for a long time. The quality factor Q measures this.','It links how sharply a resonator peaks and how long it rings to the balance between energy it holds and energy it loses.','For a resonance at 100 Hz with Q = 30, the stored energy is 30 times the energy lost per radian; the technician expects a narrow peak and audible ringing.','Resonance Concept',ARRAY['Quality factor','Transient response of resonant systems','Acoustic resonance','Resonance decay','Bandwidth versus Q']::text[],ARRAY['Confusing energy stored per cycle with energy stored per radian in the Q definition.','Assuming high stored energy means high output rather than sharp, slow-decaying resonance.','Forgetting that stored energy continuously exchanges between kinetic and potential forms.']::text[],ARRAY['Explaining why a lightly damped panel absorber rings after excitation.','Relating a narrow room-mode peak to low energy loss.','Comparing damped and undamped resonators in a tuning task.']::text[],'intermediate','Q = 2*pi * (energy stored / energy dissipated per cycle) = omega * E_stored / P_loss','The quality factor equals two pi times the energy stored divided by the energy dissipated in one cycle, or angular frequency times stored energy divided by power lost.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stored energy in resonant systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f8df5cdf-64bc-4179-ba28-9a72771c488e','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f8df5cdf-64bc-4179-ba28-9a72771c488e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f8df5cdf-64bc-4179-ba28-9a72771c488e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2de990e4-25ec-4cdd-8b6d-da4d59c41f10','Surface roughness relative to wavelength','Surface roughness relative to wavelength determines whether a surface reflects sound specularly or scatters it diffusely. By the Rayleigh criterion, a surface acts acoustically smooth when its irregularity depth is small compared with the wavelength (typically less than about one-eighth of a wavelength at the incidence angle), and scatters when the depth becomes comparable to the wavelength.','A surface looks smooth or rough to sound depending on the sound''s wavelength. Bumps much smaller than the wavelength barely matter, so sound reflects cleanly. Bumps near the wavelength size scatter the sound in many directions. Low sounds have long waves, so most surfaces seem smooth to them.','It explains why a given surface scatters high frequencies but mirror-reflects low frequencies, guiding diffuser and reflector design.','At 1 kHz the wavelength is 0.343 m, so the smooth-surface limit near normal incidence is about lambda/8 = 43 mm; bumps deeper than that begin to scatter 1 kHz sound.','Scattering Concept',ARRAY['Scattering','Scattering coefficient','Diffusion coefficient','Diffuser design','Temporal diffusion']::text[],ARRAY['Assuming a physically rough surface scatters all frequencies equally.','Ignoring incidence angle, which relaxes the effective smoothness limit.','Confusing scattering (redirection) with absorption (energy loss).']::text[],ARRAY['Choosing whether a brick wall diffuses or mirror-reflects mid frequencies.','Sizing diffuser relief depth for a target scattering band.','Explaining why bass reflects specularly off a textured surface.']::text[],'advanced','surface is smooth when  h < lambda / (8*cos(theta))   (Rayleigh criterion)','A surface behaves smoothly when its roughness depth is less than the wavelength divided by eight times the cosine of the incidence angle.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface roughness relative to wavelength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2de990e4-25ec-4cdd-8b6d-da4d59c41f10','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2de990e4-25ec-4cdd-8b6d-da4d59c41f10') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2de990e4-25ec-4cdd-8b6d-da4d59c41f10');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa5dd11c-1347-4070-8df3-82b0f423c886','T10','T10 is a reverberation time derived from the decay curve evaluated over a 10 dB drop, conventionally from -5 dB to -15 dB below the steady-state level, then extrapolated to a full 60 dB decay by multiplying the measured decay time by six. It offers a fast estimate but is more sensitive to noise and non-linear decay than T20 or T30.','Reverberation time is how long sound takes to fade by sixty decibels. T10 measures only a ten-decibel part of that fade. That short slope is scaled up to a full sixty-decibel time. It is quick but easily thrown off by background noise.','It gives a rapid reverberation-time estimate when the usable decay range is limited, at the cost of higher measurement uncertainty.','If the level falls 10 dB (from -5 to -15 dB) in 0.15 s, then T10 = 6 x 0.15 = 0.9 s reverberation time.','Room Acoustic Parameter',ARRAY['T20 and T30 extrapolation','Energy decay curve','Sabine equation','Early reflections','Statistical region']::text[],ARRAY['Starting the evaluation at 0 dB instead of the -5 dB point that avoids the direct sound.','Trusting T10 when background noise contaminates the short decay range.','Forgetting to multiply the 10 dB decay time by six to reach a 60 dB value.']::text[],ARRAY['Estimating reverberation in a noisy room with limited decay headroom.','Cross-checking T20 where only a short clean decay exists.','Quick field surveys where full 30 dB decays are unavailable.']::text[],'intermediate','T10 = 6 * t(-5 dB -> -15 dB)','T10 equals six times the time taken for the decay curve to fall from five decibels to fifteen decibels below the steady-state level.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='T10');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa5dd11c-1347-4070-8df3-82b0f423c886','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa5dd11c-1347-4070-8df3-82b0f423c886') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa5dd11c-1347-4070-8df3-82b0f423c886');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2110bf02-3ead-4ef5-9a4a-42a32d4e9fa1','T20 and T30 extrapolation','T20 and T30 are reverberation times found by fitting a straight line to the decay curve over ranges of -5 to -25 dB (20 dB) and -5 to -35 dB (30 dB), then extrapolating to a full 60 dB decay by multiplying by three and by two respectively. Starting at -5 dB avoids the direct sound and the wider range reduces noise sensitivity compared with T10.','To get reverberation time, we watch how sound fades. T20 uses a twenty-decibel part of the fade and scales it up three times. T30 uses thirty decibels and scales up two times. Both start five decibels down to skip the direct sound.','They give robust reverberation-time estimates from a limited decay range while extrapolating consistently to the standard 60 dB definition.','If the decay falls 30 dB (from -5 to -35 dB) in 0.9 s, then T30 = 2 x 0.9 = 1.8 s reverberation time.','Room Acoustic Parameter',ARRAY['T10','Energy decay curve','Sabine equation','Eyring equation','Statistical region']::text[],ARRAY['Beginning the fit at 0 dB rather than -5 dB, so the direct sound biases the slope.','Using the wrong extrapolation factor: three for T20, two for T30.','Fitting into the noise floor, which flattens the decay and shortens the result.']::text[],ARRAY['Reporting reverberation time for a classroom to ISO 3382 requirements.','Comparing T20 and T30 to reveal a curved, non-linear decay.','Verifying a hall''s low-frequency reverberation against a design target.']::text[],'intermediate','T20 = 3 * t(-5->-25 dB) ;  T30 = 2 * t(-5->-35 dB)','T20 equals three times the time for a twenty-decibel decay from minus five to minus twenty-five decibels; T30 equals two times the time for a thirty-decibel decay from minus five to minus thirty-five decibels.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='T20 and T30 extrapolation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2110bf02-3ead-4ef5-9a4a-42a32d4e9fa1','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2110bf02-3ead-4ef5-9a4a-42a32d4e9fa1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2110bf02-3ead-4ef5-9a4a-42a32d4e9fa1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd4bdde94-edf0-41dd-9f5f-798500889e7d','Tangential modes','Tangential modes are room resonances formed by sound reflecting off four of a room''s six surfaces, involving two non-zero indices in the axial-tangential-oblique classification. They are generally weaker than axial modes because energy travels a longer, four-wall path with more reflection losses.','Rooms resonate in patterns. A tangential mode bounces between four walls at once. Two of its three mode numbers are non-zero. Because it hits more surfaces, it loses more energy and is weaker than a simple two-wall mode.','Classifying modes as tangential helps predict which resonances shape a room''s low-frequency response and how strongly each contributes.','In a 5 m by 4 m room, the (1,1,0) tangential mode is f = (343/2)*sqrt((1/5)^2+(1/4)^2) = 54.9 Hz.','Room Mode Type',ARRAY['Axial modes','Oblique modes','Room modes','Modal frequency calculation','Standing waves']::text[],ARRAY['Assuming tangential modes are as strong as axial modes of similar frequency.','Using only one dimension in the frequency formula instead of two non-zero indices.','Ignoring tangential modes when they cluster near an axial mode and reinforce it.']::text[],ARRAY['Building a modal map of a control room''s low end.','Explaining an unexpected resonance not matched by any axial mode.','Comparing mode strengths when planning bass-trap placement.']::text[],'advanced','f = (c/2) * sqrt( (nx/Lx)^2 + (ny/Ly)^2 )   with two non-zero indices','A tangential mode frequency equals half the speed of sound times the square root of the sum of two squared terms, each an integer divided by a room dimension.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tangential modes');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd4bdde94-edf0-41dd-9f5f-798500889e7d','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d4bdde94-edf0-41dd-9f5f-798500889e7d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d4bdde94-edf0-41dd-9f5f-798500889e7d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '15fee569-adff-40d1-8bcb-8dcd60de2bfb','Temperature-gradient refraction','Temperature-gradient refraction is the bending of sound rays caused by a vertical change in air temperature, which changes the local speed of sound with height. Because sound bends toward regions of lower speed, a temperature inversion (warmer air aloft) bends sound downward, while a normal lapse (cooler air aloft) bends it upward and forms a shadow zone.','Sound travels faster in warm air than in cold air. When air temperature changes with height, sound rays curve. They bend toward the cooler, slower air. On a warm-topped evening, sound curves back to the ground and carries far.','It explains why outdoor sound propagation varies with weather, affecting how far and how clearly sound travels over distance.','The speed of sound is c = 331.3*sqrt(1 + T/273.15), giving about 331 m/s at 0 C and 343 m/s at 20 C; a warm-over-cold inversion bends sound back down toward listeners.','Outdoor Propagation',ARRAY['Wind-gradient refraction','Sound-speed gradients','Atmospheric sound bending','Angle of incidence','Wave-based acoustics']::text[],ARRAY['Thinking sound bends toward warmer air; it actually bends toward the cooler, slower air.','Confusing refraction (gradual ray bending) with reflection off a boundary.','Assuming outdoor conditions are uniform, ignoring day-night temperature-profile changes.']::text[],ARRAY['Explaining why a distant festival is louder at night than by day.','Planning outdoor measurement conditions to limit weather bias.','Diagnosing a shadow zone where sound seems to vanish over open ground.']::text[],'intermediate','c(T) = 331.3 * sqrt(1 + T/273.15)   [T in degrees Celsius]','The speed of sound in air equals three hundred thirty-one point three metres per second times the square root of one plus the Celsius temperature divided by two hundred seventy-three point one five.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temperature-gradient refraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '15fee569-adff-40d1-8bcb-8dcd60de2bfb','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='15fee569-adff-40d1-8bcb-8dcd60de2bfb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='15fee569-adff-40d1-8bcb-8dcd60de2bfb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b31a4f5a-3b1b-407c-8238-d74fb8e4a0bc','Temporal diffusion','Temporal diffusion is the spreading of reflected sound energy over time, so that a single incident wavefront returns as a sequence of closely spaced, lower-level reflections rather than one strong specular echo. Phase-grating diffusers, such as Schroeder wells of varying depth, achieve it by imposing different time delays across the surface.','A flat wall sends sound back as one sharp reflection. A diffuser breaks that reflection into many small ones spread out in time. This softens strong echoes. The spreading of the reflection over time is temporal diffusion.','It reduces distinct echoes and coloration by smearing reflected energy in time, improving perceived spaciousness without heavy absorption.','A technician fits a Schroeder-type diffuser on a rear wall so a would-be slapback returns as a dense, low-level cluster spread over several milliseconds instead of one sharp echo.','Scattering Concept',ARRAY['Spatial diffusion','Diffuser design','Quadratic-residue diffusion','Surface roughness relative to wavelength','Slapback reflection']::text[],ARRAY['Equating diffusion with absorption; diffusion redistributes energy rather than removing it.','Assuming any bumpy surface gives useful temporal spreading at all frequencies.','Confusing temporal diffusion (time spread) with spatial diffusion (direction spread).']::text[],ARRAY['Treating a rear wall to kill slapback without deadening the room.','Improving envelopment in a listening room using phase-grating diffusers.','Explaining why a diffuser softens flutter echo between parallel walls.']::text[],'advanced',NULL,NULL,'01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temporal diffusion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b31a4f5a-3b1b-407c-8238-d74fb8e4a0bc','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b31a4f5a-3b1b-407c-8238-d74fb8e4a0bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b31a4f5a-3b1b-407c-8238-d74fb8e4a0bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'afc8ded3-80bb-4988-aef6-bc530fd1e8a2','Transient response of resonant systems','The transient response of a resonant system is its time-domain behavior when excitation starts or stops: energy builds up toward steady state and, after removal, decays exponentially at a rate set by the damping. The decay envelope follows an exponential whose time constant is proportional to the quality factor, so lightly damped resonators build and ring slowly.','When you drive a resonator, its sound does not appear instantly. It grows toward a steady level. When you stop, it fades out gradually. How fast it builds and rings depends on how much energy the system loses.','It describes how quickly resonances start and stop, which governs audible ringing, coloration, and the accuracy of transient reproduction.','For a resonance at 100 Hz with Q = 50, the decay time constant is tau = Q/(pi*f) = 50/(pi*100) = 0.159 s of audible ringing after the drive stops.','Resonance Concept',ARRAY['Stored energy in resonant systems','Quality factor','Modal ringing','Resonance decay','Resonance buildup']::text[],ARRAY['Assuming a resonator reaches full output instantly instead of building up over time.','Confusing the buildup rate with the decay rate; both scale with Q but are separate phases.','Ignoring that higher Q means longer ringing and slower settling.']::text[],ARRAY['Explaining audible ringing after a bass note in an untreated room.','Relating a sharp modal peak to a long decay tail.','Assessing how a resonant absorber colors transient material.']::text[],'advanced','p(t) proportional to exp(-t/tau) ,  tau = Q/(pi*f)','After excitation stops, the resonant amplitude decays exponentially with a time constant equal to the quality factor divided by pi times the resonant frequency.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transient response of resonant systems');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'afc8ded3-80bb-4988-aef6-bc530fd1e8a2','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='afc8ded3-80bb-4988-aef6-bc530fd1e8a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='afc8ded3-80bb-4988-aef6-bc530fd1e8a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6eeae32f-37a1-48ea-b5a6-bbb9df778bc3','Transition between modal and geometric behavior','The transition between modal and geometric behavior is the frequency range around the Schroeder frequency where a room''s response changes from discrete, widely spaced resonances (modal region) to a dense overlap of modes treatable by geometric and statistical acoustics. Below it, individual modes dominate; above it, ray-based and energy models apply.','At low frequencies a room shows separate resonances. At high frequencies these blur into a smooth response. The change happens around a frequency set by the room''s size and reverberation. Below it, think modes; above it, think rays and energy.','It tells the technician which modeling approach is valid at a given frequency, preventing misuse of modal or statistical methods outside their range.','For a 500 m^3 room with 1 s reverberation time, the transition sits near the Schroeder frequency 2000*sqrt(1/500) = 89 Hz; treat bass below modally and mids above geometrically.','Acoustic Regime',ARRAY['Statistical region','Modal region','Room modes','Sabine equation','Wave-based acoustics']::text[],ARRAY['Treating the Schroeder frequency as a hard boundary rather than a gradual transition.','Applying ray-tracing or Sabine theory to the modal region below the transition.','Assuming large and small rooms transition at the same frequency.']::text[],ARRAY['Choosing modal analysis versus ray tracing for a room simulation.','Explaining why bass needs different treatment than mid frequencies.','Deciding where discrete room-mode control gives way to broadband treatment.']::text[],'advanced','f_S = 2000 * sqrt(T60 / V)','The transition (Schroeder) frequency is two thousand times the square root of the reverberation time divided by the room volume.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transition between modal and geometric behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6eeae32f-37a1-48ea-b5a6-bbb9df778bc3','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6eeae32f-37a1-48ea-b5a6-bbb9df778bc3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6eeae32f-37a1-48ea-b5a6-bbb9df778bc3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1fd4e95b-376c-4871-9983-40e1cd3d592b','Velocity-based absorbers','Velocity-based absorbers are porous or fibrous materials that dissipate sound by friction as air particles move through them, so they work best where particle velocity is high. Because particle velocity is greatest a quarter wavelength from a rigid boundary and zero at the boundary, such absorbers are most effective when spaced away from the wall or made thick relative to the wavelength.','Porous absorbers turn sound into heat as air moves through their fibres. They work where air is moving fastest. Air moves fastest a quarter wavelength out from a hard wall. So mounting the absorber off the wall boosts its low-frequency grip.','They convert sound energy to heat through airflow resistance, providing broadband mid-and-high-frequency absorption in rooms.','At 100 Hz the wavelength is 3.43 m, so peak particle velocity is a quarter wavelength out, 0.86 m from the wall; an air gap there improves low-frequency absorption.','Absorber Type',ARRAY['Porous absorption','Pressure-based absorbers','Air-gap effects behind absorbers','Quarter-wavelength absorber placement','Fibrous absorber']::text[],ARRAY['Mounting a thin porous panel flat on the wall where particle velocity is near zero for bass.','Confusing velocity-based porous absorbers with pressure-based membrane or panel absorbers.','Expecting a thin absorber to control low frequencies without depth or an air gap.']::text[],ARRAY['Adding an air gap behind fabric-wrapped panels to extend low-frequency absorption.','Choosing porous treatment for broadband mid-high control.','Explaining why corner-mounted thick absorbers outperform thin wall panels at bass.']::text[],'intermediate','velocity maximum at  d = lambda/4  from a rigid wall','Particle velocity, and thus porous-absorber effectiveness, peaks at a distance of one quarter wavelength from a rigid reflecting wall.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Velocity-based absorbers');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1fd4e95b-376c-4871-9983-40e1cd3d592b','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1fd4e95b-376c-4871-9983-40e1cd3d592b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1fd4e95b-376c-4871-9983-40e1cd3d592b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1200ea8b-4a83-474f-ac74-c261f230fbb6','Wave-based acoustics','Wave-based acoustics models sound by solving the acoustic wave equation (or its frequency-domain Helmholtz form) with boundary conditions, capturing interference, diffraction, and resonance exactly. It is most important at low frequencies and in small rooms where wavelengths are comparable to room dimensions, unlike geometric acoustics which ignores wave phenomena.','Wave-based methods treat sound as a full wave, not simple rays. They solve the equations that govern how pressure changes in space and time. This captures interference, bending, and resonance. It matters most for low frequencies in small rooms.','It provides accurate low-frequency room predictions, including modes and diffraction, that ray-based methods cannot reproduce.','An engineer runs a finite-element or FDTD solver of the wave equation to predict a small studio''s modal response below its Schroeder frequency, where ray methods fail.','Modeling Approach',ARRAY['Room modes','Modal region','Transition between modal and geometric behavior','Standing waves','Statistical region']::text[],ARRAY['Applying geometric ray methods at low frequencies where wave effects dominate.','Assuming wave-based simulation is needed at all frequencies, ignoring its cost at high frequencies.','Neglecting accurate boundary impedance, which strongly affects wave-based results.']::text[],ARRAY['Simulating a control room''s low-frequency modes before construction.','Predicting diffraction around a barrier or console edge.','Choosing wave-based over ray-based modeling below the Schroeder frequency.']::text[],'advanced','Laplacian(p) = (1/c^2) * d^2p/dt^2   ;  Helmholtz: Laplacian(p) + k^2 p = 0','The acoustic wave equation sets the spatial Laplacian of pressure equal to one over the speed of sound squared times the second time derivative of pressure; the Helmholtz form adds the wavenumber-squared term in the frequency domain.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave-based acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1200ea8b-4a83-474f-ac74-c261f230fbb6','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1200ea8b-4a83-474f-ac74-c261f230fbb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1200ea8b-4a83-474f-ac74-c261f230fbb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a17b6afa-019c-41e8-86d1-50bf3a8b2ad1','Wind-gradient refraction','Wind-gradient refraction is the bending of sound rays caused by wind speed increasing with height, which changes the effective speed of sound along the propagation direction. Downwind, the effective speed rises with height so sound bends downward and carries far; upwind, it bends upward, forming an acoustic shadow zone.','Wind usually blows faster higher up. This adds to or subtracts from the sound''s speed along its path. Going downwind, sound curves back toward the ground and travels far. Going upwind, it curves up and leaves a quiet shadow near the ground.','It explains the directional asymmetry of outdoor sound propagation, so listeners downwind hear more than those upwind.','The effective sound speed is c_eff = c + u(z)*cos(phi); downwind (phi = 0) the wind adds to c and increases with height, bending sound down toward distant listeners.','Outdoor Propagation',ARRAY['Temperature-gradient refraction','Sound-speed gradients','Atmospheric sound bending','Wave-based acoustics','Angle of incidence']::text[],ARRAY['Assuming wind blows sound like a breeze rather than bending rays via a speed gradient.','Forgetting the strong upwind-versus-downwind asymmetry it creates.','Confusing wind-gradient refraction with temperature-gradient refraction, though both can act together.']::text[],ARRAY['Explaining why an outdoor concert is louder downwind than upwind.','Planning noise measurements to account for wind direction.','Diagnosing an upwind shadow zone where sound seems to disappear.']::text[],'intermediate','c_eff(z) = c + u(z)*cos(phi)','The effective sound speed at a given height equals the still-air sound speed plus the wind speed at that height times the cosine of the angle between the wind and the sound direction.','01e593be-e5ac-4f41-b22b-a546319f81d8' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wind-gradient refraction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a17b6afa-019c-41e8-86d1-50bf3a8b2ad1','01e593be-e5ac-4f41-b22b-a546319f81d8',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a17b6afa-019c-41e8-86d1-50bf3a8b2ad1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a17b6afa-019c-41e8-86d1-50bf3a8b2ad1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f7c8aed-a3da-4369-9bf0-1d07d4b3db20','Acoustic absorption coefficient','The acoustic absorption coefficient (alpha) is the fraction of incident sound energy that a surface or material removes from the reflected field rather than returning it. It ranges from 0 (perfectly reflective) to 1 (perfectly absorptive) and generally varies with frequency and angle of incidence.','This number tells how much sound a surface soaks up. A value of 0 means all sound bounces back. A value of 1 means all sound is absorbed. Soft, thick materials have higher numbers.','It quantifies how effectively a material converts incident sound energy to heat, letting designers predict reflections and reverberation.','If a panel returns 30 percent of the energy that strikes it, alpha = 1 - 0.30 = 0.70, so it absorbs 70 percent of the incident sound.','Absorption',ARRAY['Acoustic absorptivity','Acoustic reflectivity','Acoustic transmissivity','Acoustic impedance mismatch']::text[],ARRAY['Believing the coefficient is a single fixed value rather than one that changes with frequency.','Thinking a coefficient above 1 (from lab edge effects) means more than all energy was absorbed.','Confusing the absorption coefficient with the noise reduction coefficient (a single averaged figure).']::text[],ARRAY['Selecting wall treatment to hit a target reverberation time.','Reading a manufacturer''s per-octave absorption data table.','Modelling a room in acoustic prediction software.']::text[],'beginner','alpha = W_abs / W_inc = 1 - |R|^2','The absorption coefficient equals absorbed sound power divided by incident sound power, or one minus the energy fraction reflected.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic absorption coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f7c8aed-a3da-4369-9bf0-1d07d4b3db20','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f7c8aed-a3da-4369-9bf0-1d07d4b3db20') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f7c8aed-a3da-4369-9bf0-1d07d4b3db20');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4cb6195a-4925-41c6-9fc1-c72d54057fae','Acoustic absorptivity','Acoustic absorptivity is the intrinsic property of a material or surface describing the fraction of incident sound energy it absorbs. It is numerically the absorption coefficient, expressed as a value between 0 and 1 that depends on frequency, incidence angle, and mounting.','Absorptivity describes how good a material is at taking in sound. It is the same idea as the absorption coefficient. A high value means the material traps most of the sound. Low values mean sound bounces off.','It expresses a material''s inherent sound-soaking ability so surfaces can be compared independently of a specific room.','A curtain with an absorptivity of 0.5 at 500 Hz absorbs half of the mid-frequency energy that reaches it.','Absorption',ARRAY['Acoustic absorption coefficient','Acoustic reflectivity','Acoustic transmissivity','Acoustic extinction']::text[],ARRAY['Treating absorptivity and reflectivity as unrelated when they sum with transmissivity to one.','Assuming a material''s absorptivity is constant across all frequencies.','Confusing an intrinsic property with a whole-room absorption figure in sabins.']::text[],ARRAY['Comparing two foam types on a datasheet.','Explaining why a bare concrete room sounds live.','Estimating treatment needed for a reflective space.']::text[],'beginner','a = W_abs / W_inc','Absorptivity equals the absorbed sound power divided by the incident sound power at a surface.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic absorptivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4cb6195a-4925-41c6-9fc1-c72d54057fae','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4cb6195a-4925-41c6-9fc1-c72d54057fae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4cb6195a-4925-41c6-9fc1-c72d54057fae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38d9483b-1e8d-4100-ac43-2e3f08bd8b09','Acoustic analogy','An acoustic analogy is a mathematical reformulation of the fluid equations of motion into an exact inhomogeneous wave equation whose source term represents sound generation, most famously Lighthill''s analogy for aerodynamically generated noise. The rearrangement treats the true flow as an equivalent acoustic source radiating into a uniform medium at rest.','This method rewrites the equations of moving air as a wave equation. One side looks like normal sound spreading out. The other side acts like a source that creates the sound. Engineers use it to study noise from jets and fans.','It lets engineers predict sound radiated by turbulent or moving fluids by separating true wave propagation from the flow features that act as sources.','A technician studying fan or jet noise applies Lighthill''s analogy to link measured turbulence quantities to the far-field sound they radiate.','Aeroacoustics',ARRAY['Acoustic field','Acoustic velocity potential','Acoustic energy flux','Acoustic intensity']::text[],ARRAY['Assuming the analogy is an approximation when Lighthill''s equation is an exact rearrangement.','Thinking the source term is independent of the sound field it generates.','Believing it applies only to jets rather than any flow-generated sound.']::text[],ARRAY['Predicting noise from an HVAC fan.','Analysing aircraft engine jet noise.','Modelling airflow noise in a duct or vent.']::text[],'advanced','d^2(rho'')/dt^2 - c0^2 * laplacian(rho'') = d^2(T_ij)/(dx_i dx_j)','The second time derivative of density fluctuation minus the sound speed squared times its Laplacian equals the double spatial derivative of the Lighthill stress tensor.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic analogy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38d9483b-1e8d-4100-ac43-2e3f08bd8b09','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38d9483b-1e8d-4100-ac43-2e3f08bd8b09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38d9483b-1e8d-4100-ac43-2e3f08bd8b09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f74011a1-6a60-46aa-9438-6a3213e889a2','Acoustic aperture','An acoustic aperture is an opening or radiating area through which sound passes or is emitted, such as a port, slot, or the mouth of a horn. Its behaviour is governed by the ratio of aperture size to wavelength, which sets how strongly sound diffracts and how directional the radiation becomes.','An acoustic aperture is a gap or opening that sound passes through. Its size compared to the sound''s wavelength matters most. Small openings spread sound widely. Large openings send sound in a tighter beam.','It describes the opening that controls how sound enters, exits, or spreads from a device or barrier.','A technician notes that a loudspeaker port acts as an aperture, so when its width is small next to the wavelength, low frequencies radiate almost omnidirectionally.','Radiation & Diffraction',ARRAY['Acoustic wavelength','Acoustic field','Boundary spacing and cancellation','Acoustic wavenumber']::text[],ARRAY['Assuming a small opening keeps a beam narrow when it actually spreads sound.','Ignoring that diffraction depends on aperture size relative to wavelength, not absolute size.','Treating an aperture as frequency-independent.']::text[],ARRAY['Designing a bass-reflex loudspeaker port.','Predicting sound leakage through a gap in a barrier.','Understanding the throat and mouth of a horn.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic aperture');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f74011a1-6a60-46aa-9438-6a3213e889a2','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f74011a1-6a60-46aa-9438-6a3213e889a2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f74011a1-6a60-46aa-9438-6a3213e889a2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ed79e697-fbf1-4e15-ae56-fa5e6f0ffaf2','Acoustic energy density','Acoustic energy density is the acoustic energy stored per unit volume of the medium, comprising kinetic energy of particle motion and potential energy of compression. For a plane progressive wave its time-averaged value equals the mean-square sound pressure divided by the product of density and sound speed squared.','This measures how much sound energy fits in a given volume of air. It combines the energy of moving air particles and squeezed air. Louder sound packs more energy into each cubic metre. It is measured in joules per cubic metre.','It expresses how much acoustic energy a region of the sound field holds, linking pressure to energy content.','For a plane wave with 1 Pa rms pressure in air, w = (1)^2 / (1.21 x 343^2) = about 7.0 x 10^-6 J/m^3.','Energy & Intensity',ARRAY['Acoustic intensity','Acoustic energy flux','Acoustic power density','Acoustic momentum']::text[],ARRAY['Counting only kinetic or only potential energy instead of both.','Confusing energy density (per volume) with intensity (per area).','Applying the simple plane-wave formula inside a reactive near field.']::text[],ARRAY['Relating a diffuse-field pressure level to stored energy.','Deriving intensity from energy density and sound speed.','Analysing energy build-up in a reverberant room.']::text[],'intermediate','w = p_rms^2 / (rho0 * c^2)','The time-averaged energy density of a plane wave equals mean-square sound pressure divided by density times the square of the sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic energy density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ed79e697-fbf1-4e15-ae56-fa5e6f0ffaf2','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ed79e697-fbf1-4e15-ae56-fa5e6f0ffaf2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ed79e697-fbf1-4e15-ae56-fa5e6f0ffaf2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd93338b5-603f-4993-bcbf-db807f3ed168','Acoustic energy flux','Acoustic energy flux is the rate at which acoustic energy passes through a surface, obtained by integrating sound intensity over that surface. Integrated over a closed surface around a source it equals the radiated sound power, measured in watts.','This is how fast sound energy flows across a surface. It adds up the intensity over the whole area. Across a surface wrapping a source, it equals the total sound power. It is measured in watts.','It links local intensity to the total acoustic power crossing or leaving a boundary.','If a plane wave carries an intensity of 2.4 x 10^-3 W/m^2 through a 2 m^2 window, the energy flux is about 4.8 x 10^-3 W.','Energy & Intensity',ARRAY['Acoustic intensity','Acoustic energy density','Acoustic power density','Acoustic field']::text[],ARRAY['Confusing energy flux (through a surface) with energy density (in a volume).','Forgetting that only the intensity component normal to the surface contributes.','Assuming flux is uniform over a surface in a complex field.']::text[],ARRAY['Measuring radiated power with an intensity probe over a scan surface.','Estimating sound power escaping through an opening.','Verifying a source''s rated acoustic output.']::text[],'intermediate','P = integral over S of I . dS','Acoustic energy flux equals the surface integral of the sound intensity component normal to the surface.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic energy flux');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd93338b5-603f-4993-bcbf-db807f3ed168','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d93338b5-603f-4993-bcbf-db807f3ed168') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d93338b5-603f-4993-bcbf-db807f3ed168');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4ef01ee-c71c-40cd-9cf4-5a5a8e14b88e','Acoustic extinction','Acoustic extinction is the progressive removal of energy from a sound wave as it travels through a medium, combining true absorption (conversion to heat) and scattering out of the beam. Its intensity decays exponentially with distance according to an extinction coefficient.','As sound travels through a material, it gets weaker. Some energy turns to heat, and some scatters away. Together this loss is called extinction. The sound fades faster over longer distances.','It describes total energy loss along a propagation path, useful when both absorption and scattering matter.','With an extinction coefficient of 0.01 per metre, intensity after 100 m falls to I0 x e^-1, about 37 percent of the starting value.','Propagation Loss',ARRAY['Acoustic absorptivity','Boundary-layer attenuation','Acoustic intensity','Acoustic transmissivity']::text[],ARRAY['Assuming extinction is only absorption and ignoring scattering.','Treating the decay as linear rather than exponential with distance.','Confusing the extinction coefficient (per metre) with a decibel loss figure.']::text[],ARRAY['Modelling sound loss through fog or a porous medium.','Explaining why high frequencies fade faster over distance.','Analysing ultrasound attenuation in tissue or fluids.']::text[],'advanced','I(x) = I0 * exp(-mu * x)','Intensity at distance x equals the starting intensity times e raised to minus the extinction coefficient times distance.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic extinction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4ef01ee-c71c-40cd-9cf4-5a5a8e14b88e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4ef01ee-c71c-40cd-9cf4-5a5a8e14b88e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4ef01ee-c71c-40cd-9cf4-5a5a8e14b88e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a053a7d4-6530-42d4-9de9-0c0fc65eea4f','Acoustic field','An acoustic field is the region of a medium in which sound waves are present, fully described at each point by sound pressure and particle velocity as functions of position and time. Characteristic regions include the near field, far field, free field, and diffuse field.','An acoustic field is any space filled with sound. At every point it has a pressure and a motion of the air. Engineers describe it using these values over space and time. Different zones behave in different ways.','It provides the framework for describing where and how sound exists so measurements and predictions can be made.','A technician placing a measurement microphone checks whether it sits in the free field or too close to a source, in the reactive near field.','Sound Field',ARRAY['Acoustic velocity potential','Acoustic intensity','Acoustic energy density','Acoustic aperture']::text[],ARRAY['Assuming intensity equals pressure over impedance everywhere, which fails in the near field.','Measuring in a reflective space and treating it as free field.','Confusing the diffuse field with the free field.']::text[],ARRAY['Choosing a microphone position for a level measurement.','Distinguishing near-field from far-field loudspeaker behaviour.','Setting up an anechoic or reverberation test.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a053a7d4-6530-42d4-9de9-0c0fc65eea4f','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a053a7d4-6530-42d4-9de9-0c0fc65eea4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a053a7d4-6530-42d4-9de9-0c0fc65eea4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e12d9a5-1305-4452-9aaa-46fb6b2faff7','Acoustic impedance mismatch','An acoustic impedance mismatch is a difference in characteristic (specific) acoustic impedance between two media or regions, which causes partial reflection of a sound wave at their boundary. The larger the mismatch, the greater the fraction of energy reflected rather than transmitted.','Every material resists sound in its own way. When two materials differ a lot, sound bounces at their boundary. A big difference means most sound reflects. A close match lets sound pass through easily.','It explains why sound reflects at boundaries and governs how much energy transfers between media.','At an air-to-water boundary, impedance jumps from about 415 to 1.48 million rayls, so the pressure reflection coefficient is near 1 and almost all energy reflects.','Impedance',ARRAY['Acoustic reflectivity','Acoustic transmissivity','Acoustic resistance','Acoustic absorption coefficient']::text[],ARRAY['Thinking sound passes easily from air into a solid or liquid.','Confusing specific acoustic impedance (rho c) with acoustic impedance (pressure over volume velocity).','Assuming reflection depends on density alone, not impedance.']::text[],ARRAY['Explaining why underwater sound barely enters air.','Designing an impedance-matching horn or waveguide.','Understanding coupling losses at a transducer face.']::text[],'intermediate','R = (Z2 - Z1) / (Z2 + Z1)','The pressure reflection coefficient equals the difference of the two impedances divided by their sum.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic impedance mismatch');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e12d9a5-1305-4452-9aaa-46fb6b2faff7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e12d9a5-1305-4452-9aaa-46fb6b2faff7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e12d9a5-1305-4452-9aaa-46fb6b2faff7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5736dc24-7b2b-4c3e-8063-d73e3e33fa9b','Acoustic intensity','Acoustic intensity is the time-averaged rate of acoustic energy flow per unit area in the direction of propagation, equal to the time average of the product of sound pressure and particle velocity. It is a vector quantity measured in watts per square metre, with a reference of 1 pW/m^2 (10^-12 W/m^2).','Intensity measures how much sound power flows through each square metre. It multiplies pressure by the motion of the air. It also has a direction. It is measured in watts per square metre.','It describes the strength and direction of sound energy flow, forming the basis for sound-power measurement.','For a plane wave with 1 Pa rms pressure in air, I = p_rms^2 / (rho0 c) = 1 / 415 = about 2.4 x 10^-3 W/m^2.','Energy & Intensity',ARRAY['Acoustic energy flux','Acoustic energy density','Acoustic power density','Acoustic impedance mismatch']::text[],ARRAY['Confusing intensity (a vector) with sound pressure (a scalar).','Using I = p^2/(rho c) in the near field, where pressure and velocity are out of phase.','Mixing the intensity reference (1 pW/m^2) with the pressure reference (20 uPa).']::text[],ARRAY['Mapping energy flow with a two-microphone intensity probe.','Determining a machine''s sound power on a factory floor.','Locating a noise source by intensity direction.']::text[],'intermediate','I = <p * u>  ; plane wave: I = p_rms^2 / (rho0 * c)','Intensity is the time average of sound pressure times particle velocity; for a plane wave it equals mean-square pressure divided by density times sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5736dc24-7b2b-4c3e-8063-d73e3e33fa9b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5736dc24-7b2b-4c3e-8063-d73e3e33fa9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5736dc24-7b2b-4c3e-8063-d73e3e33fa9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2073cf7e-a037-49a1-8284-4932de535044','Acoustic momentum','Acoustic momentum is the linear momentum transported by a sound wave, whose time-averaged density for a plane travelling wave equals the acoustic energy density divided by the sound speed. Its transfer to an absorbing or reflecting surface manifests as acoustic radiation pressure.','A sound wave carries a small push in its direction of travel. This push is its momentum. When sound hits and is absorbed by a surface, it presses on it. That gentle steady force is called radiation pressure.','It explains the small steady forces sound exerts, underlying radiation pressure and acoustic levitation.','A technician relates the momentum density of a plane wave to its energy: g = w / c, so 7 x 10^-6 J/m^3 in air gives about 2 x 10^-8 kg/(m^2 s).','Energy & Intensity',ARRAY['Acoustic energy density','Acoustic intensity','Acoustic energy flux','Acoustic field']::text[],ARRAY['Assuming a sound wave carries no momentum because average particle displacement is zero.','Confusing the steady radiation pressure with the oscillating acoustic pressure.','Treating radiation pressure as large; it is a small second-order effect.']::text[],ARRAY['Explaining acoustic levitation of small particles.','Understanding forces in high-intensity ultrasound.','Discussing why sound exerts a steady push on a target.']::text[],'advanced','g = w / c','The time-averaged momentum density of a plane wave equals its acoustic energy density divided by the sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic momentum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2073cf7e-a037-49a1-8284-4932de535044','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2073cf7e-a037-49a1-8284-4932de535044') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2073cf7e-a037-49a1-8284-4932de535044');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a4eeb62-89c0-4c33-9237-09d710143976','Acoustic path-length difference','Acoustic path-length difference is the difference in distance travelled by two sound paths arriving at the same point, which sets their relative time delay and phase difference. When the difference equals half a wavelength the arrivals are out of phase and cancel; at a whole wavelength they add.','Sound can reach a point by two routes of different length. The gap in length delays one arrival. At certain gaps the two sounds cancel out. At others they reinforce, causing peaks and dips.','It explains interference effects such as comb filtering from a direct sound and its reflection.','A 0.343 m path difference delays one arrival by 1 ms; the first cancellation occurs at f = c/(2 x 0.343) = 500 Hz.','Interference',ARRAY['Boundary spacing and cancellation','Acoustic wavelength','Acoustic wavenumber','Acoustic field']::text[],ARRAY['Confusing path-length difference with total path length.','Assuming cancellation occurs at a whole wavelength instead of a half wavelength.','Ignoring that the effect repeats across many frequencies (comb filtering).']::text[],ARRAY['Diagnosing comb filtering between two microphones on one source.','Aligning delay between a main and a fill loudspeaker.','Explaining floor-bounce dips in a measurement.']::text[],'intermediate','delta_phi = (2*pi/lambda) * delta_d ; delta_t = delta_d / c','The phase difference equals two pi over the wavelength times the path-length difference, and the time delay equals the path-length difference divided by sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic path-length difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a4eeb62-89c0-4c33-9237-09d710143976','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a4eeb62-89c0-4c33-9237-09d710143976') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a4eeb62-89c0-4c33-9237-09d710143976');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44a53dac-932e-45ad-870a-c3a7fc0b0355','Acoustic power density','Acoustic power density is the acoustic power carried per unit area of a wavefront, numerically equal to the magnitude of the sound intensity and expressed in watts per square metre. It describes how concentrated the sound-power flow is across the area it passes through.','This is how much sound power passes through each square metre. It is the same size as the intensity magnitude. A tighter beam packs more power into each square metre. It is measured in watts per square metre.','It expresses how concentrated sound-power flow is over an area, useful for exposure and radiation analysis.','A plane wave of 1 Pa rms in air carries a power density of p_rms^2/(rho0 c) = about 2.4 x 10^-3 W/m^2 through the wavefront.','Energy & Intensity',ARRAY['Acoustic intensity','Acoustic energy flux','Acoustic energy density','Acoustic momentum']::text[],ARRAY['Confusing power density (per area) with energy density (per volume).','Assuming the term always means power per unit volume dissipated, a different usage.','Forgetting it, like intensity, is a directional quantity in a wavefront.']::text[],ARRAY['Assessing the intensity of a focused ultrasound beam.','Comparing radiated concentration from different sources.','Estimating power crossing a defined area.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic power density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44a53dac-932e-45ad-870a-c3a7fc0b0355','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44a53dac-932e-45ad-870a-c3a7fc0b0355') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44a53dac-932e-45ad-870a-c3a7fc0b0355');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fdcf9df3-e8c3-47b1-a4e2-ef9cdeead830','Acoustic reflectivity','Acoustic reflectivity is the fraction of incident sound energy reflected from a boundary, equal to the squared magnitude of the pressure reflection coefficient. It is set by the impedance mismatch between the two media and, with absorptivity and transmissivity, accounts for all incident energy.','Reflectivity is the share of sound energy that bounces off a surface. A hard, mismatched surface reflects most of the sound. It depends on how the two materials differ. Together with what is absorbed and passed through, it adds to all the incoming sound.','It quantifies how much sound a boundary sends back, shaping echoes and reverberation.','If the second medium has three times the impedance of the first, energy reflectivity = ((3-1)/(3+1))^2 = 0.25, so 25 percent of the energy reflects.','Reflection',ARRAY['Acoustic absorption coefficient','Acoustic transmissivity','Acoustic impedance mismatch','Acoustic absorptivity']::text[],ARRAY['Confusing the energy reflectivity with the pressure reflection coefficient (its square root).','Forgetting reflectivity varies with frequency and incidence angle.','Assuming a rigid surface has zero absorption, so reflectivity is exactly one.']::text[],ARRAY['Predicting strength of a wall reflection.','Explaining flutter echo between hard parallel surfaces.','Choosing between reflective and diffusive treatment.']::text[],'intermediate','r = |(Z2 - Z1)/(Z2 + Z1)|^2','Energy reflectivity equals the squared magnitude of the impedance difference divided by the impedance sum.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic reflectivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fdcf9df3-e8c3-47b1-a4e2-ef9cdeead830','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fdcf9df3-e8c3-47b1-a4e2-ef9cdeead830') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fdcf9df3-e8c3-47b1-a4e2-ef9cdeead830');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23b99647-2c92-4f1b-ad60-a9b118b89814','Acoustic refractive index','The acoustic refractive index is the ratio of a reference sound speed to the local sound speed in a medium, governing how much a sound ray bends when it crosses regions of differing speed. Following Snell''s law, sound bends toward regions of lower sound speed.','Sound travels at different speeds in different conditions. The refractive index compares a reference speed to the local speed. When speed changes, sound rays bend. This is why sound curves in temperature or wind layers.','It quantifies how sound speed variations bend sound paths, explaining refraction outdoors and underwater.','If sound speeds up from 343 to 355 m/s in a warmer layer, the index there is n = 343/355 = 0.966, and rays bend away from that faster layer.','Refraction',ARRAY['Acoustic impedance mismatch','Acoustic wavelength','Acoustic field','Acoustic wavenumber']::text[],ARRAY['Borrowing the optics rule that higher index means slower speed but forgetting the reference definition.','Assuming sound always travels straight over long distances.','Ignoring wind and temperature gradients that create the index variation.']::text[],ARRAY['Explaining why sound carries far on a cold night.','Understanding sound channels in the ocean.','Predicting outdoor sound bending over a stadium.']::text[],'advanced','n = c0 / c','The acoustic refractive index equals a reference sound speed divided by the local sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic refractive index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23b99647-2c92-4f1b-ad60-a9b118b89814','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23b99647-2c92-4f1b-ad60-a9b118b89814') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23b99647-2c92-4f1b-ad60-a9b118b89814');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c471cde4-fcfa-430e-9526-d052fa7cefa9','Acoustic resistance','Acoustic resistance is the real, in-phase part of acoustic impedance, equal to the component of sound pressure that is in phase with the volume velocity divided by that volume velocity. It represents energy actually dissipated or radiated, measured in acoustic ohms (Pa s/m^3).','Acoustic resistance is the part of a system''s opposition to sound that loses energy. It links pressure to the flow of air through an opening. Unlike stored energy, this part is used up. It is measured in acoustic ohms.','It captures the energy-dissipating part of acoustic impedance, important for absorbers and radiators.','A technician models a porous panel or a small vent as an acoustic resistance, since it converts sound to heat rather than storing it.','Impedance',ARRAY['Acoustic impedance mismatch','Acoustic absorptivity','Acoustic reactance','Acoustic field']::text[],ARRAY['Confusing acoustic resistance with acoustic reactance (the out-of-phase, energy-storing part).','Mixing up specific acoustic resistance (per area) with acoustic resistance (per volume velocity).','Assuming resistance is frequency-independent when it often is not.']::text[],ARRAY['Modelling a loudspeaker port''s losses.','Designing a resistive acoustic absorber.','Analysing a microphone''s acoustic network.']::text[],'advanced','R_a = Re(Z_a)','Acoustic resistance is the real part of the acoustic impedance, the in-phase pressure per unit volume velocity.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic resistance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c471cde4-fcfa-430e-9526-d052fa7cefa9','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c471cde4-fcfa-430e-9526-d052fa7cefa9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c471cde4-fcfa-430e-9526-d052fa7cefa9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '560823d8-cf03-41c7-a5b8-607dc541553e','Acoustic singularity','An acoustic singularity is a point in a sound field where a field quantity becomes infinite or undefined, such as the source point of an idealized point (monopole) source where the modelled pressure diverges, or a phase singularity (acoustic vortex) where amplitude vanishes and phase is undefined. Such points arise mathematically in solutions of the wave equation and its Green''s functions.','An acoustic singularity is a special point in a sound field. There a value blows up or has no clear meaning. One example is an ideal point source, where the model gives infinite pressure. Another is a swirl point where the sound cancels and its timing is undefined.','It marks points where idealized models break down or where sound develops special structure, guiding careful analysis.','When modelling a small source as a point, a technician avoids evaluating the field exactly at the singular source point, where the formula diverges.','Field Theory',ARRAY['Acoustic field','Acoustic velocity potential','Acoustic aperture','Acoustic energy density']::text[],ARRAY['Treating the infinite value at a point source as physically real rather than a modelling artefact.','Assuming a phase singularity means a fault instead of a zero-amplitude vortex point.','Evaluating a Green''s function at its own source point.']::text[],ARRAY['Modelling a compact source as an ideal point.','Analysing acoustic vortices in structured sound fields.','Handling divergences in boundary-element simulations.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic singularity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '560823d8-cf03-41c7-a5b8-607dc541553e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='560823d8-cf03-41c7-a5b8-607dc541553e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='560823d8-cf03-41c7-a5b8-607dc541553e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '767e0911-6ad8-483f-82eb-b55f00604c95','Acoustic transmissivity','Acoustic transmissivity is the fraction of incident sound energy transmitted through a boundary or partition, denoted by the transmission coefficient tau. It relates directly to sound transmission loss, which equals ten times the base-ten logarithm of one over tau.','Transmissivity is the share of sound energy that passes through a wall or partition. A small value means the wall blocks most sound. It connects directly to how many decibels a wall stops. Heavy, sealed walls have low transmissivity.','It quantifies how much sound gets through a barrier, underpinning sound insulation ratings.','A partition with tau = 0.001 has transmission loss TL = 10 log10(1/0.001) = 30 dB.','Transmission',ARRAY['Acoustic reflectivity','Acoustic absorption coefficient','Acoustic impedance mismatch','Acoustic absorptivity']::text[],ARRAY['Confusing transmissivity with transmission loss (its logarithmic form).','Assuming a small hole barely matters when leaks dominate transmission.','Forgetting transmissivity is strongly frequency-dependent.']::text[],ARRAY['Rating a wall''s sound insulation.','Explaining why sealing gaps improves isolation.','Comparing partition designs for a studio.']::text[],'intermediate','TL = 10 * log10(1 / tau)','Sound transmission loss equals ten times the base-ten logarithm of one divided by the transmission coefficient.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic transmissivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '767e0911-6ad8-483f-82eb-b55f00604c95','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='767e0911-6ad8-483f-82eb-b55f00604c95') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='767e0911-6ad8-483f-82eb-b55f00604c95');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e66fe0e-661a-42a9-a463-619f81b4f18c','Acoustic tunneling','Acoustic tunneling is the transmission of sound energy through a region that would normally forbid propagation, such as a band gap of a phononic crystal or a thin barrier, carried by evanescent (non-propagating) waves. It is the acoustic analogue of quantum-mechanical tunneling and appears in phononic crystals and acoustic metamaterials.','Sometimes sound crosses a zone that should block it. It leaks through as a fading, non-travelling wave. This mirrors how particles tunnel through barriers in quantum physics. Engineers see it in specially structured materials.','It explains how sound can leak through nominally blocking structures, informing metamaterial and barrier design.','A technician testing a phononic-crystal barrier may measure small transmission inside its stop band, evidence of evanescent-wave tunneling.','Metamaterials',ARRAY['Acoustic transmissivity','Acoustic impedance mismatch','Acoustic extinction','Acoustic wavenumber']::text[],ARRAY['Assuming a band gap blocks sound perfectly with no leakage.','Confusing the evanescent tunneling wave with an ordinary propagating wave.','Expecting tunneling transmission to be large rather than a small residual.']::text[],ARRAY['Characterising a phononic-crystal sound barrier.','Studying leakage through a metamaterial stop band.','Demonstrating the wave analogy to quantum tunneling.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic tunneling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e66fe0e-661a-42a9-a463-619f81b4f18c','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e66fe0e-661a-42a9-a463-619f81b4f18c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e66fe0e-661a-42a9-a463-619f81b4f18c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7257827-b4a3-4cb1-80a3-7712315bcde8','Acoustic velocity potential','The acoustic velocity potential is a scalar function whose spatial gradient gives the particle velocity and whose time derivative (times minus the density) gives the sound pressure, valid for irrotational acoustic fields. It offers a single convenient variable from which both pressure and velocity can be derived.','The velocity potential is one helper quantity for sound fields. Its slope in space gives how fast the air moves. Its change in time gives the sound pressure. Using it, engineers track a whole field with one function.','It simplifies acoustic analysis by letting both pressure and particle velocity come from one scalar field.','A technician modelling radiation solves for the velocity potential, then takes its gradient for particle velocity and its time derivative for pressure.','Field Theory',ARRAY['Acoustic field','Acoustic intensity','Acoustic wavenumber','Acoustic singularity']::text[],ARRAY['Applying it where the field is rotational, which violates its assumption.','Forgetting the density factor and sign linking it to pressure.','Confusing the velocity potential with the particle velocity itself.']::text[],ARRAY['Deriving radiation from a vibrating surface.','Setting up a boundary-value acoustic problem.','Relating source motion to radiated pressure.']::text[],'advanced','u = grad(phi) ; p = -rho0 * d(phi)/dt','Particle velocity is the gradient of the velocity potential, and sound pressure is minus the density times the potential''s time derivative.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic velocity potential');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7257827-b4a3-4cb1-80a3-7712315bcde8','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7257827-b4a3-4cb1-80a3-7712315bcde8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7257827-b4a3-4cb1-80a3-7712315bcde8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4a15e4a-41b9-49ca-a2c9-d9a8be5aa6f5','Acoustic wavelength','The acoustic wavelength is the spatial distance over which a sound wave completes one full cycle, equal to the sound speed divided by the frequency. In air at about 20 C it ranges from roughly 17 m at 20 Hz to about 17 mm at 20 kHz.','Wavelength is the length of one full sound wave in space. It equals the speed of sound divided by the frequency. Low notes have long waves. High notes have short waves.','It sets the physical scale of a sound, determining diffraction, room modes, and directivity.','A 1000 Hz tone in air has a wavelength of lambda = 343/1000 = 0.343 m, about the width of a small loudspeaker.','Wave Properties',ARRAY['Acoustic wavenumber','Angular wavenumber','Acoustic path-length difference','Acoustic aperture']::text[],ARRAY['Forgetting wavelength depends on the medium''s sound speed, not just frequency.','Assuming wavelength is fixed when temperature changes the sound speed.','Confusing wavelength (space) with period (time).']::text[],ARRAY['Sizing an absorber or diffuser against a target frequency.','Predicting room modes from room dimensions.','Judging whether a source radiates omnidirectionally.']::text[],'beginner','lambda = c / f','Wavelength equals the speed of sound divided by the frequency.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic wavelength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4a15e4a-41b9-49ca-a2c9-d9a8be5aa6f5','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4a15e4a-41b9-49ca-a2c9-d9a8be5aa6f5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4a15e4a-41b9-49ca-a2c9-d9a8be5aa6f5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24d50de3-8cc7-49a3-8327-3ec90217987a','Acoustic wavenumber','The acoustic wavenumber is the spatial rate of phase change of a sound wave, in acoustics conventionally the angular wavenumber k = 2*pi/lambda = omega/c, expressed in radians per metre. A related quantity, the repetency, equals 1/lambda in cycles per metre.','The wavenumber tells how many wave cycles fit in a given distance. In acoustics it is usually written as two pi divided by the wavelength. It rises with frequency. It is a handy way to describe wave size.','It provides a compact spatial-frequency measure used throughout wave equations and radiation formulas.','For a 1000 Hz tone in air, lambda = 0.343 m, so k = 2*pi/0.343 = about 18.3 rad/m.','Wave Properties',ARRAY['Angular wavenumber','Acoustic wavelength','Acoustic field','Acoustic velocity potential']::text[],ARRAY['Mixing the angular wavenumber (2 pi/lambda) with the repetency (1/lambda).','Forgetting the units are radians per metre in the acoustic convention.','Confusing wavenumber with angular frequency omega.']::text[],ARRAY['Writing the plane-wave phase term k x.','Computing the ka value for a radiating source.','Setting up a wave-equation solution.']::text[],'intermediate','k = 2*pi/lambda = omega/c','The acoustic (angular) wavenumber equals two pi divided by the wavelength, which also equals angular frequency divided by sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic wavenumber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24d50de3-8cc7-49a3-8327-3ec90217987a','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24d50de3-8cc7-49a3-8327-3ec90217987a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24d50de3-8cc7-49a3-8327-3ec90217987a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9242972f-c9f4-4af6-8e61-cf30f73557df','Angular wavenumber','The angular wavenumber is the number of radians of phase per unit length of a wave, defined as k = 2*pi/lambda and measured in radians per metre. It is the form of wavenumber used in acoustic wave equations and is distinguished from the repetency, 1/lambda, given in cycles per metre.','The angular wavenumber counts radians of phase per metre. It equals two pi divided by the wavelength. Short waves give a large value. It is the version used in most acoustic equations.','It expresses spatial phase change in radians so it fits directly into sinusoidal wave equations.','A wave of 0.343 m wavelength has k = 2*pi/0.343 = about 18.3 rad/m, used in the phase term of its equation.','Wave Properties',ARRAY['Acoustic wavenumber','Acoustic wavelength','Acoustic field','Acoustic velocity potential']::text[],ARRAY['Confusing the angular wavenumber (radians/m) with the repetency (cycles/m).','Dropping the factor of two pi when converting from wavelength.','Mixing it up with angular frequency, which is per unit time.']::text[],ARRAY['Forming the phase of a travelling-wave expression.','Relating spatial and temporal frequency through the sound speed.','Analysing standing-wave patterns.']::text[],'intermediate','k = 2*pi/lambda','The angular wavenumber equals two pi divided by the wavelength.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Angular wavenumber');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9242972f-c9f4-4af6-8e61-cf30f73557df','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9242972f-c9f4-4af6-8e61-cf30f73557df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9242972f-c9f4-4af6-8e61-cf30f73557df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a337246-91f6-43b2-b77a-f7d244737813','Anti-resonance','Anti-resonance is a frequency at which a driven system''s response reaches a minimum because its reactive elements combine to present a very high driving-point impedance (low mobility). It falls between resonances and represents strong opposition to motion at the drive point.','At an anti-resonance a system barely responds to a driving force. Its internal parts push back strongly at that frequency. It sits between the easy resonant frequencies. There, motion at the drive point is very small.','It identifies frequencies where a system resists being driven, shaping instrument and transducer behaviour.','A technician measuring a loudspeaker or pickup impedance sees anti-resonance as a dip in output or a peak in impedance between resonant peaks.','Resonance',ARRAY['Acoustic resistance','Acoustic impedance mismatch','Acoustic field','Audible spectrum']::text[],ARRAY['Confusing anti-resonance with resonance, which is the opposite (a response peak).','Assuming high impedance always means high output rather than low motion.','Overlooking that anti-resonances alternate with resonances in a system.']::text[],ARRAY['Interpreting a loudspeaker impedance curve.','Explaining dead spots on a stringed instrument.','Tuning a mechanical system away from a driving frequency.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Anti-resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a337246-91f6-43b2-b77a-f7d244737813','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a337246-91f6-43b2-b77a-f7d244737813') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a337246-91f6-43b2-b77a-f7d244737813');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d70002c-b72a-40d7-acbc-115e0a0b3689','Audible spectrum','The audible spectrum is the nominal range of sound frequencies a healthy young human can hear, conventionally taken as 20 Hz to 20 kHz. The upper limit falls with age and noise exposure, and sensitivity varies strongly with frequency and level.','The audible spectrum is the range of pitches people can hear. It runs from about 20 Hz to 20,000 Hz. The top limit drops as we age. We hear middle pitches more easily than very low or very high ones.','It defines the frequency range that audio equipment and hearing studies must cover.','A technician sets a system''s frequency response to cover 20 Hz to 20 kHz so it reproduces the full audible range.','Hearing',ARRAY['Acoustic wavelength','Brilliance','Bass ratio','Acoustic field']::text[],ARRAY['UNSAFE: Assuming very low or very high sounds are safe at high levels just because they seem quiet; intense infrasound and ultrasound can still harm.','Treating 20 Hz to 20 kHz as exact for every listener rather than a nominal range.','Believing hearing sensitivity is flat across the range.']::text[],ARRAY['Specifying the bandwidth of a playback system.','Explaining age-related loss of high-frequency hearing.','Interpreting an audiogram against the nominal range.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audible spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d70002c-b72a-40d7-acbc-115e0a0b3689','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d70002c-b72a-40d7-acbc-115e0a0b3689') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d70002c-b72a-40d7-acbc-115e0a0b3689');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '359771db-a92f-4477-a692-338d94e16fe6','Bass ratio','Bass ratio is a room-acoustics metric of low-frequency warmth, defined as the average reverberation time in the 125 Hz and 250 Hz octave bands divided by the average in the 500 Hz and 1000 Hz bands. Values somewhat above one indicate a warm hall with relatively strong bass reverberation.','Bass ratio measures how warm a room sounds. It compares low-frequency echo time to mid-frequency echo time. A value above one means the bass rings longer. That warmth is often preferred in concert halls.','It gives a single number describing a hall''s low-frequency warmth relative to the mids.','With reverberation times 2.4, 2.2, 2.0 and 1.9 s at 125, 250, 500 and 1000 Hz, BR = (2.4+2.2)/(2.0+1.9) = 1.18.','Room Acoustics',ARRAY['Brilliance','Audible spectrum','Binaural quality index','Acoustic absorption coefficient']::text[],ARRAY['Using single frequencies instead of octave-band reverberation times.','Assuming a higher bass ratio is always better regardless of music type.','Confusing bass ratio with the treble ratio used for brilliance.']::text[],ARRAY['Assessing warmth when tuning a concert hall.','Comparing measured halls in acoustic surveys.','Setting reverberation targets across frequency bands.']::text[],'intermediate','BR = (T_125 + T_250) / (T_500 + T_1000)','Bass ratio equals the sum of the 125 and 250 Hz reverberation times divided by the sum of the 500 and 1000 Hz reverberation times.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bass ratio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '359771db-a92f-4477-a692-338d94e16fe6','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='359771db-a92f-4477-a692-338d94e16fe6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='359771db-a92f-4477-a692-338d94e16fe6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e82a356f-0ec7-48cc-808f-96d85825051f','Binaural quality index','The binaural quality index (BQI) is a concert-hall measure of apparent source width and spaciousness, defined as one minus the early interaural cross-correlation coefficient averaged over the 500, 1000, and 2000 Hz octave bands. Higher values indicate greater dissimilarity between the ears'' signals and a wider, more enveloping sound.','This index measures how wide and spacious a hall sounds. It compares the early sound reaching each ear. When the two ear signals differ more, the value is higher. Higher values usually mean a better, more enveloping sound.','It rates a hall''s spatial impression from binaural measurements, correlating with listener preference.','A technician measures the early interaural cross-correlation with a head-and-torso microphone; if the averaged value is 0.35, BQI = 1 - 0.35 = 0.65.','Room Acoustics',ARRAY['Bass ratio','Brilliance','Acoustic field','Audible spectrum']::text[],ARRAY['Forgetting BQI uses the early part of the response, not the full impulse response.','Confusing a high correlation (narrow image) with a high index (wide image).','Using the wrong octave bands instead of 500, 1000, and 2000 Hz.']::text[],ARRAY['Evaluating spaciousness in a concert-hall survey.','Comparing seat positions for apparent source width.','Validating an acoustic design against listener preference.']::text[],'advanced','BQI = 1 - IACC_E3','The binaural quality index equals one minus the early interaural cross-correlation coefficient averaged over the 500, 1000, and 2000 Hz octave bands.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural quality index');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e82a356f-0ec7-48cc-808f-96d85825051f','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e82a356f-0ec7-48cc-808f-96d85825051f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e82a356f-0ec7-48cc-808f-96d85825051f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '617f1c4a-e776-4816-b84d-2cbffbc4d790','Boundary spacing and cancellation','Boundary spacing and cancellation refers to speaker-boundary interference, where sound reflected from a nearby surface combines with the direct sound and produces frequency-dependent reinforcement and cancellation (comb filtering). The lowest cancellation occurs when the extra reflected path equals half a wavelength, set by the source''s distance from the boundary.','A speaker near a wall or floor sends sound two ways. The direct sound and the reflection meet at the listener. At some frequencies they cancel, causing dips. The spacing to the surface sets where these dips fall.','It explains the tonal dips caused by nearby surfaces and guides loudspeaker placement.','For a source 0.5 m from a boundary, the first cancellation is near f = c/(4d) = 343/(4 x 0.5) = about 172 Hz.','Interference',ARRAY['Acoustic path-length difference','Acoustic reflectivity','Acoustic field','Acoustic wavelength']::text[],ARRAY['Assuming moving a speaker slightly cannot change its low-frequency response.','Confusing the reinforcement peaks with the cancellation dips.','Treating the effect as one dip rather than a repeating comb pattern.']::text[],ARRAY['Positioning studio monitors away from walls.','Diagnosing a bass dip from floor bounce.','Choosing subwoofer placement in a room.']::text[],'intermediate','f_null = c / (4 * d)','The first cancellation frequency equals the speed of sound divided by four times the source-to-boundary distance.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary spacing and cancellation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '617f1c4a-e776-4816-b84d-2cbffbc4d790','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='617f1c4a-e776-4816-b84d-2cbffbc4d790') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='617f1c4a-e776-4816-b84d-2cbffbc4d790');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a228655e-b63a-47a6-9878-a951f5c1c32b','Boundary-layer attenuation','Boundary-layer attenuation is the extra loss of sound energy near a rigid boundary, such as the wall of a tube or duct, caused by viscous friction and thermal conduction within the thin acoustic boundary layer. The loss per unit length increases with the square root of frequency and is greater in narrower channels.','Near a hard wall, moving air rubs and loses heat. This drains energy from sound in tubes and ducts. The effect grows in narrow pipes. It also rises as frequency increases.','It accounts for wall losses that damp sound in tubes, ducts, and small passages beyond bulk absorption.','A technician modelling a narrow tube or a woodwind bore adds boundary-layer loss, which scales with the square root of frequency and inversely with tube radius.','Propagation Loss',ARRAY['Acoustic extinction','Acoustic resistance','Acoustic field','Acoustic intensity']::text[],ARRAY['Ignoring wall losses and assuming sound travels loss-free in a tube.','Assuming the loss is frequency-independent instead of rising with the square root of frequency.','Overlooking that narrow channels lose far more energy than wide ones.']::text[],ARRAY['Modelling attenuation in a narrow acoustic tube.','Explaining damping in woodwind and organ pipes.','Analysing losses in small ports and ducts.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary-layer attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a228655e-b63a-47a6-9878-a951f5c1c32b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a228655e-b63a-47a6-9878-a951f5c1c32b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a228655e-b63a-47a6-9878-a951f5c1c32b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '206faa64-db72-4609-a97f-1ce0c6590ae8','Brilliance','Brilliance is the perceived brightness and clarity of a room''s sound, associated with strong reverberation at high frequencies relative to the mid-range. It is often quantified by a treble ratio comparing high-band reverberation times to mid-band values.','Brilliance is a bright, clear, ringing quality in a room''s sound. It comes from strong high-frequency echo. Too little makes a room sound dull. Too much makes it harsh and brittle.','It describes the treble character of a hall, balancing warmth to keep sound clear rather than dull or harsh.','A technician judges brilliance from a treble ratio, such as (T_2000 + T_4000) divided by (T_500 + T_1000), where higher values indicate a brighter hall.','Room Acoustics',ARRAY['Bass ratio','Binaural quality index','Audible spectrum','Acoustic absorption coefficient']::text[],ARRAY['Confusing brilliance with loudness rather than high-frequency reverberation.','Assuming more brilliance is always better; excess sounds harsh.','Treating brilliance as the opposite of warmth rather than a complementary balance.']::text[],ARRAY['Judging the treble character of a concert hall.','Balancing warmth and brilliance during acoustic tuning.','Diagnosing a dull-sounding room lacking high-frequency reverberation.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Brilliance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '206faa64-db72-4609-a97f-1ce0c6590ae8','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='206faa64-db72-4609-a97f-1ce0c6590ae8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='206faa64-db72-4609-a97f-1ce0c6590ae8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '236df65b-cb96-4bb6-bd89-e78202177238','Bulk acoustic wave','A bulk acoustic wave is an elastic wave that travels through the interior volume of a solid or fluid medium, rather than along a surface or within a thin guided layer. It may be longitudinal (compressional) or transverse (shear), with a speed fixed by the medium''s elastic moduli and density.','A bulk sound wave moves through the whole body of a material. It does not cling to the surface. It can push and pull along its path or shake side to side. Its speed depends on how stiff and heavy the material is.','It distinguishes waves that travel through a medium''s volume from surface or guided waves, which matters for transducers, filters, and material testing.','An ultrasonic thickness gauge sends a bulk longitudinal wave into steel (c approximately 5900 m/s) and times its echo; bulk-acoustic-wave (BAW) resonators use these waves in piezoelectric films for radio-frequency filtering.','Wave Types',ARRAY['Compression wave','Guided-wave propagation','Characteristic impedance','Evanescent wave','Bulk density']::text[],ARRAY['Confusing bulk waves with surface (Rayleigh) waves.','Assuming every bulk wave is longitudinal, forgetting shear waves in solids.','Thinking bulk-wave speed depends on frequency in a nondispersive medium.']::text[],ARRAY['Ultrasonic testing of a metal weld.','Specifying a BAW radio-frequency filter.','Measuring the sound speed in a fluid.']::text[],'intermediate','c = sqrt(C/rho)','A bulk-wave speed equals the square root of the relevant elastic modulus divided by the density.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bulk acoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '236df65b-cb96-4bb6-bd89-e78202177238','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='236df65b-cb96-4bb6-bd89-e78202177238') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='236df65b-cb96-4bb6-bd89-e78202177238');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73d4ce3c-6d08-4571-9d50-212523e98c4e','Bulk density','Bulk density is the mass of a material per unit of its total occupied volume, including any internal pores or air voids. In acoustics it is the density (rho) that combines with wave speed to set characteristic impedance and to govern how a medium stores and transports acoustic energy.','Bulk density is mass divided by the whole volume a material fills. It counts the pores and gaps inside. Air is light and has low density. Steel is heavy and dense. This value helps set how sound moves through a material.','It supplies the density term in nearly every acoustic relation, linking a material''s makeup to its acoustic behavior.','Dry air at 20 degrees C has rho approximately 1.204 kg/m^3; with c approximately 343 m/s the characteristic impedance rho*c is about 413 Pa*s/m.','Material Properties',ARRAY['Characteristic impedance','Compression wave','Bulk acoustic wave','Complex stiffness','Energy absorption coefficient']::text[],ARRAY['Confusing bulk density with skeletal (material) density that excludes pores.','Forgetting that gas density changes with temperature and pressure.','Using volume mass density where a per-area surface mass is required.']::text[],ARRAY['Computing rho*c for a microphone calibration.','Selecting a porous absorber material.','Correcting air density for altitude or temperature.']::text[],'beginner','rho = m/V','Density equals mass divided by the total volume the material occupies.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bulk density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73d4ce3c-6d08-4571-9d50-212523e98c4e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73d4ce3c-6d08-4571-9d50-212523e98c4e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73d4ce3c-6d08-4571-9d50-212523e98c4e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23107dfa-d417-4b0d-ade5-e704cd4858b1','Characteristic impedance','The characteristic (specific acoustic) impedance of a medium is the product of its density and sound speed, z0 = rho*c, equal to the ratio of acoustic pressure to particle velocity for a plane progressive wave. It controls how much sound reflects and transmits at a boundary between two media.','Every material resists sound in its own way. Characteristic impedance is density times sound speed. It links pressure and motion in a traveling wave. A big mismatch between two materials causes strong reflections.','It predicts reflection and transmission at interfaces and sets the reference for matching sources, media, and loads.','Air is about 413 rayl and water about 1.48 Mrayl; that huge mismatch is why little airborne sound enters water. For air, z0 = rho*c = 1.204 * 343 approximately 413 Pa*s/m.','Acoustic Impedance',ARRAY['Bulk density','Compression wave','Critical angle','Energy absorption coefficient','Bulk acoustic wave']::text[],ARRAY['Confusing specific acoustic impedance (rho*c) with acoustic impedance (pressure over volume velocity).','Assuming it varies with frequency for a plane wave in a lossless fluid.','Mixing MKS rayls with CGS rayls.']::text[],ARRAY['Matching an ultrasound transducer to tissue.','Predicting reflection at a wall surface.','Designing a transmission-line loudspeaker.']::text[],'intermediate','z0 = rho*c','Characteristic impedance equals the medium''s density multiplied by its sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Characteristic impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23107dfa-d417-4b0d-ade5-e704cd4858b1','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23107dfa-d417-4b0d-ade5-e704cd4858b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23107dfa-d417-4b0d-ade5-e704cd4858b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac6fd5b3-f44b-4aad-8269-b184de6368f9','Complex stiffness','Complex stiffness represents a material''s dynamic stiffness as a complex number, k* = k(1 + i*eta), where the real part is the elastic (storage) stiffness and the imaginary part encodes damping. The loss factor eta measures the energy dissipated per cycle relative to the energy stored.','Real materials both spring back and lose energy as they flex. Complex stiffness bundles both into one number. The real part is the springiness. The extra part stands for damping. The loss factor says how much energy turns to heat.','It lets vibration and structure-borne-sound models capture damping and phase lag without tracking every microscopic loss.','Adding a damping treatment might raise a panel''s loss factor eta from about 0.01 to 0.1, cutting resonant vibration roughly tenfold; the equation of motion uses k* = k(1 + i*eta).','Material Properties',ARRAY['Critical frequency','Compression wave','Characteristic impedance','Eigenmode','Half-wave resonance']::text[],ARRAY['Treating the loss factor as constant when it often varies with frequency.','Confusing loss factor eta with damping ratio zeta (eta is about 2*zeta at resonance).','Ignoring the imaginary part and under-predicting damping.']::text[],ARRAY['Modeling a constrained-layer damped panel.','Finite-element vibroacoustic analysis.','Specifying a viscoelastic damping material.']::text[],'advanced','k* = k(1 + i*eta)','Complex stiffness is the elastic stiffness times one plus the loss factor multiplied by the imaginary unit.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex stiffness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac6fd5b3-f44b-4aad-8269-b184de6368f9','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac6fd5b3-f44b-4aad-8269-b184de6368f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac6fd5b3-f44b-4aad-8269-b184de6368f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5953f626-d08c-4064-89c4-c2f62184d9b3','Compression wave','A compression (longitudinal) wave is one in which particle motion is parallel to the direction of propagation, producing alternating regions of compression and rarefaction. Sound in fluids such as air and water propagates only as compression waves.','In a compression wave the medium is squeezed and stretched along the travel direction. Air molecules bunch up, then spread out. Sound in air and water works this way. It is also called a longitudinal wave.','It describes how ordinary sound carries energy through fluids and along solids, the basis of all airborne audio.','In air the speed is c = sqrt(K/rho) approximately 343 m/s at 20 degrees C; a 1 kHz tone then has a wavelength of about 0.343 m.','Wave Types',ARRAY['Bulk acoustic wave','Guided-wave propagation','Half-wavelength relationships','Characteristic impedance','Bulk density']::text[],ARRAY['Calling a compression wave a transverse wave.','Thinking air can support shear (transverse) waves.','Confusing particle velocity with the wave (phase) speed.']::text[],ARRAY['Explaining basic sound propagation.','Ultrasound imaging in tissue.','Computing wavelength for a subwoofer.']::text[],'beginner','c = sqrt(K/rho)','In a fluid, compression-wave speed equals the square root of the bulk modulus divided by the density.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compression wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5953f626-d08c-4064-89c4-c2f62184d9b3','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5953f626-d08c-4064-89c4-c2f62184d9b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5953f626-d08c-4064-89c4-c2f62184d9b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '975bbfaa-b9d1-4eae-be30-43977da33e69','Critical angle','The critical angle is the angle of incidence at a boundary beyond which an acoustic wave undergoes total internal reflection, arising when sound travels toward a faster medium. Snell''s law gives sin(theta_c) = c1/c2, defined only when the second medium is faster (c2 > c1).','Sound bends when it crosses between materials. If it heads into a faster material, a special angle exists. Past that angle no sound gets through. It all reflects back. This angle is the critical angle.','It marks the onset of total reflection, important for how sound is trapped, channeled, or reflected at material boundaries.','From air (343 m/s) toward water (1480 m/s), sin(theta_c) = 343/1480, so theta_c approximately 13.4 degrees; beyond it airborne sound is fully reflected.','Reflection & Refraction',ARRAY['Characteristic impedance','Grazing incidence','Evanescent wave','Guided-wave propagation','Compression wave']::text[],ARRAY['Applying it when sound enters a slower medium (no critical angle exists then).','Confusing angle measured from the normal with angle from the surface.','Forgetting an evanescent wave still exists beyond the critical angle.']::text[],ARRAY['Underwater-to-air sound transmission.','Setting an ultrasonic wedge transducer angle.','Sound trapped in a warm surface layer of air or water.']::text[],'intermediate','sin(theta_c) = c1/c2','The sine of the critical angle equals the speed in the first medium divided by the speed in the faster second medium.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical angle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '975bbfaa-b9d1-4eae-be30-43977da33e69','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='975bbfaa-b9d1-4eae-be30-43977da33e69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='975bbfaa-b9d1-4eae-be30-43977da33e69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4fb8d00-5c30-4c3d-ab05-2cb5edf0b881','Critical frequency','The critical (coincidence) frequency of a panel is the lowest frequency at which its bending wavelength equals the airborne acoustic wavelength, so grazing sound couples efficiently and the transmission loss dips. For a homogeneous plate it is approximated by f_c = c^2 / (1.8 * c_L * h).','A panel bends in waves when sound hits it. At one special frequency those bends match the sound in air. There the panel leaks sound badly. That frequency is the critical or coincidence frequency. Thin, stiff panels push it higher.','It predicts the frequency where a wall or panel loses isolation, guiding material and thickness choices for soundproofing.','A 6 mm (about 1/4 inch) aluminum plate has a critical frequency near 2000 Hz; f_c = c^2/(1.8*c_L*h) with c=343, c_L approximately 5200 m/s, h=0.0064 m gives about 1960 Hz.','Sound Transmission',ARRAY['Half-wave resonance','Complex stiffness','Eigenmode','Compression wave','Characteristic impedance']::text[],ARRAY['Confusing the coincidence dip with the mass-law region of transmission loss.','Assuming a heavier panel always isolates better regardless of coincidence.','Ignoring that panel thickness sets the critical frequency.']::text[],ARRAY['Designing a partition wall for isolation.','Diagnosing a dip in a wall''s sound-transmission-class curve.','Choosing glazing thickness for a studio window.']::text[],'advanced','f_c = c^2 / (1.8 * c_L * h)','The critical frequency equals the square of the sound speed in air divided by 1.8 times the panel''s longitudinal wave speed times its thickness.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4fb8d00-5c30-4c3d-ab05-2cb5edf0b881','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4fb8d00-5c30-4c3d-ab05-2cb5edf0b881') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4fb8d00-5c30-4c3d-ab05-2cb5edf0b881');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2158a2b-11fd-4ed3-a3db-dde6879191a3','Cylindrical spreading loss','Cylindrical spreading loss is the reduction in sound level as energy from a line source spreads over a cylindrical wavefront, so intensity falls as 1/r and the level drops about 3 dB per doubling of distance. It applies when a source behaves like a line or when propagation is confined between two parallel boundaries.','Some sources act like a long line, not a point. Their sound spreads out in a widening cylinder. The level then drops three decibels each time distance doubles. This is a slower fall-off than a point source gives.','It models how line sources or channel-confined propagation lose level with distance, distinct from spherical spreading.','A long line array or busy highway follows cylindrical spreading: moving from 10 m to 20 m drops the level about 3 dB, from delta_L = 10*log10(r2/r1).','Sound Propagation',ARRAY['Far-field approximation','Driver spacing and lobing','Effective radiating size','Fraunhofer region','Compression wave']::text[],ARRAY['Applying the point-source 6 dB rule to a line source.','Forgetting cylindrical spreading only holds within a finite line''s near field.','Confusing intensity falling as 1/r with pressure falling as 1/sqrt(r).']::text[],ARRAY['Predicting line-array coverage in a venue.','Modeling highway or railway noise.','Sound propagation in a shallow duct or channel.']::text[],'intermediate','delta_L = 10*log10(r2/r1)','For a line source, the level drop equals ten times the base-ten logarithm of the ratio of the two distances, giving about 3 dB per doubling.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cylindrical spreading loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2158a2b-11fd-4ed3-a3db-dde6879191a3','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2158a2b-11fd-4ed3-a3db-dde6879191a3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2158a2b-11fd-4ed3-a3db-dde6879191a3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd53c0e10-659e-40b3-89e9-bd7dcd1a4395','Diffraction around obstacles','Diffraction around obstacles is the bending of sound waves into the shadow region behind a barrier or object, allowing sound to reach points not on a straight line from the source. The effect is strongest when the obstacle is small compared with the wavelength and weakens as the obstacle grows large relative to lambda.','Sound can bend around edges and objects. It does not simply stop at a barrier. Low, long-wavelength sounds bend the most. High, short-wavelength sounds are blocked better. This bending is called diffraction.','It explains why barriers work poorly at low frequencies and how sound leaks around obstacles, key to barrier and enclosure design.','A highway barrier blocks high frequencies well but low bass bends over the top; its screening scales with the Fresnel number N = 2*delta/lambda, where delta is the extra path over the barrier.','Wave Behavior',ARRAY['Grazing incidence','Critical angle','Effective radiating size','Frequency-dependent directionality','Evanescent wave']::text[],ARRAY['Thinking a barrier blocks all frequencies equally.','Assuming a solid wall casts a perfectly silent shadow.','Confusing diffraction with simple reflection.']::text[],ARRAY['Designing a highway noise barrier.','Managing loudspeaker-cabinet edge diffraction.','Hearing sound around a corner or doorway.']::text[],'intermediate','N = 2*delta/lambda','The Fresnel number equals twice the extra path length over the barrier divided by the wavelength.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffraction around obstacles');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd53c0e10-659e-40b3-89e9-bd7dcd1a4395','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d53c0e10-659e-40b3-89e9-bd7dcd1a4395') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d53c0e10-659e-40b3-89e9-bd7dcd1a4395');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f764a4ff-758f-4ab7-9465-72da0f3ccc95','Distance-to-phase conversion','Distance-to-phase conversion expresses a propagation path length as an equivalent phase shift for a given frequency, phi = 2*pi*d/lambda = 2*pi*f*d/c. It quantifies how far a wavefront''s phase advances over a travel distance.','A sound takes time to travel a distance. That travel shows up as a phase shift. One full wavelength of path equals 360 degrees. So distance and phase are two views of the same delay. Higher frequencies gain phase faster.','It underlies delay alignment, interference prediction, and array steering by tying physical spacing to phase relationships.','At 1 kHz (lambda approximately 0.343 m), a 0.1715 m path (half a wavelength) gives phi = 2*pi*0.1715/0.343 = pi radians (180 degrees), a full polarity flip.','Phase & Interference',ARRAY['Half-wavelength relationships','Driver spacing and lobing','Half-wave resonance','Compression wave','Frequency-dependent directionality']::text[],ARRAY['Forgetting phase depends on frequency, not distance alone.','Mixing degrees and radians in the calculation.','Ignoring that phase wraps around every 360 degrees.']::text[],ARRAY['Time-aligning a subwoofer with the main speakers.','Predicting comb filtering from reflections.','Steering a beamforming microphone array.']::text[],'intermediate','phi = 2*pi*f*d/c','Phase shift equals two pi times frequency times distance divided by the sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distance-to-phase conversion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f764a4ff-758f-4ab7-9465-72da0f3ccc95','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f764a4ff-758f-4ab7-9465-72da0f3ccc95') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f764a4ff-758f-4ab7-9465-72da0f3ccc95');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8abc4cf-5e88-4b91-aedd-6991a3a810f9','Distributed Helmholtz resonator','A distributed Helmholtz resonator is an array of Helmholtz-type resonant cells, typically a perforated panel over an air cavity, that provides tuned low-frequency absorption spread across a surface rather than in a single lumped device. Each cell resonates near f = (c/(2*pi)) * sqrt(A/(V*L'')).','A Helmholtz resonator is a cavity with a neck, like blowing across a bottle. Spreading many of them over a surface makes a panel absorber. It soaks up a chosen low frequency. A perforated panel over an air space is a common form.','It delivers targeted low-frequency absorption over a wall or ceiling area where single resonators would be impractical.','A perforated-panel absorber is tuned with f = (c/(2*pi))*sqrt(A/(V*L'')); designers set hole size, spacing, and cavity depth to place the peak on a room mode, such as 100 Hz.','Absorption',ARRAY['Energy absorption coefficient','Eigenmode','Half-wave resonance','Distributed-parameter model','Complex stiffness']::text[],ARRAY['Using the single-neck lumped formula where end corrections and distribution matter.','Forgetting the neck end correction (L'' is longer than the physical neck).','Expecting broadband absorption from a sharply tuned resonator.']::text[],ARRAY['Taming a room mode with a perforated-panel absorber.','Tuning a bass trap to a specific frequency.','Designing a reactive duct silencer.']::text[],'advanced','f = (c/(2*pi)) * sqrt(A/(V*L''))','The resonance frequency equals the sound speed over two pi, times the square root of the neck area divided by the cavity volume times the effective neck length.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distributed Helmholtz resonator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8abc4cf-5e88-4b91-aedd-6991a3a810f9','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8abc4cf-5e88-4b91-aedd-6991a3a810f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8abc4cf-5e88-4b91-aedd-6991a3a810f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ba4a5e2-10a5-4b2e-b832-3f2e200ee8f2','Distributed-parameter model','A distributed-parameter model treats an acoustic or vibrating system as having its mass, stiffness, and compliance spread continuously through space, described by partial differential equations rather than concentrated into discrete lumped elements. It is required when the system''s dimensions are not small compared with the wavelength.','Some systems are small next to the wavelength, so we treat them as single lumps. When they grow large, that shortcut fails. Then we model the properties as spread out in space. This is a distributed-parameter model. It uses wave equations, not simple lumps.','It provides accurate modeling of pipes, panels, and rooms where wave effects and standing waves cannot be ignored.','A small loudspeaker cavity can be lumped at low frequency, but a long transmission line must be modeled as distributed once its length exceeds roughly a tenth of the wavelength.','Modeling',ARRAY['Distributed Helmholtz resonator','Eigenmode','Element order','Guided-wave propagation','Helmholtz equation']::text[],ARRAY['Using a lumped model above its valid frequency range.','Ignoring standing waves inside a supposedly small cavity.','Assuming lumped and distributed models agree near resonance.']::text[],ARRAY['Designing a transmission-line loudspeaker enclosure.','Analyzing acoustics in a long HVAC duct.','Choosing between a lumped and a wave-based model.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Distributed-parameter model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ba4a5e2-10a5-4b2e-b832-3f2e200ee8f2','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ba4a5e2-10a5-4b2e-b832-3f2e200ee8f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ba4a5e2-10a5-4b2e-b832-3f2e200ee8f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a55a5cc6-040d-47ea-a61e-9ae9e0eddcc7','Driver spacing and lobing','Driver spacing and lobing describes how the distance between two radiating loudspeaker drivers creates constructive and destructive interference lobes in the radiation pattern once the spacing approaches or exceeds a wavelength. Wider spacing yields more and narrower lobes and can create off-axis nulls near the crossover frequency.','Two speakers close together add up cleanly. As their spacing nears one wavelength, their outputs interfere. This carves the sound into lobes and dead spots. The pattern gets messy off to the sides. This is lobing.','It explains coverage irregularity in multi-driver systems and sets spacing limits for line arrays and crossovers.','To limit strong lobing, keep center-to-center spacing below about one wavelength at the crossover; at 2 kHz (lambda approximately 0.17 m) drivers should sit within roughly 0.17 m. Grating-style lobes appear where sin(theta) = m*lambda/d.','Radiation Pattern',ARRAY['Effective radiating size','Frequency-dependent directionality','Half-wavelength relationships','Distance-to-phase conversion','Cylindrical spreading loss']::text[],ARRAY['Ignoring vertical lobing at the crossover frequency.','Blaming lobing on the crossover electronics rather than geometry.','Thinking closer spacing always worsens the pattern (it usually helps).']::text[],ARRAY['Setting line-array element spacing.','Designing an MTM (D''Appolito) crossover.','Arraying multiple subwoofers.']::text[],'advanced','sin(theta) = m*lambda/d','Interference lobes point at angles whose sine equals an integer times the wavelength divided by the driver spacing.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Driver spacing and lobing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a55a5cc6-040d-47ea-a61e-9ae9e0eddcc7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a55a5cc6-040d-47ea-a61e-9ae9e0eddcc7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a55a5cc6-040d-47ea-a61e-9ae9e0eddcc7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54e19bc1-3af5-49a6-b6a9-381ad9ae3502','Effective radiating size','Effective radiating size is the acoustically relevant dimension of a source relative to wavelength, commonly captured by the parameter ka (wavenumber times radius). When ka is much less than 1 the source radiates nearly omnidirectionally; when ka is much greater than 1 it becomes directional and beams.','A source seems small or large depending on the wavelength. The measure is ka, its size against the wavelength. When it is small, sound spreads everywhere. When it is large, sound beams forward. So one speaker is wide at bass and narrow at treble.','It predicts directivity and beaming from a source''s size-to-wavelength ratio, central to loudspeaker and microphone design.','A 0.3 m loudspeaker (radius 0.15 m) reaches ka approximately 1 near 360 Hz; below that it is nearly omnidirectional and above it begins to beam. Here ka = 2*pi*f*a/c.','Radiation Pattern',ARRAY['Frequency-dependent directionality','Driver spacing and lobing','Far-field approximation','Fraunhofer region','Diffraction around obstacles']::text[],ARRAY['Assuming a small driver stays omnidirectional at every frequency.','Confusing physical size with the effective (ka) size.','Ignoring how a baffle changes the radiation pattern.']::text[],ARRAY['Choosing a tweeter for wide dispersion.','Predicting woofer beaming at high frequency.','Judging a microphone''s directivity.']::text[],'intermediate','ka = 2*pi*f*a/c','The size parameter equals two pi times frequency times the source radius divided by the sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Effective radiating size');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54e19bc1-3af5-49a6-b6a9-381ad9ae3502','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54e19bc1-3af5-49a6-b6a9-381ad9ae3502') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54e19bc1-3af5-49a6-b6a9-381ad9ae3502');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60ca3740-54fa-4054-a8ab-6e8a5b53eb01','Eigenmode','An eigenmode (normal mode) is a natural standing-wave pattern of a bounded acoustic system, each with its own eigenfrequency and spatial shape. In a rigid rectangular room the modal frequencies are f = (c/2) * sqrt((nx/Lx)^2 + (ny/Ly)^2 + (nz/Lz)^2).','A closed space rings at certain natural frequencies. Each has its own standing-wave shape. These are eigenmodes, or room modes. At those frequencies sound piles up in some spots and cancels in others. The room''s size sets which frequencies occur.','It explains uneven low-frequency response in rooms and the resonances of enclosures, pipes, and instruments.','A 5 x 4 x 3 m room''s lowest axial mode is f = (343/2)/5 = 34.3 Hz; the full formula f = (c/2)*sqrt(...) maps every problem mode.','Resonance & Modes',ARRAY['Half-wave resonance','Distributed Helmholtz resonator','Complex stiffness','Helmholtz equation','Distributed-parameter model']::text[],ARRAY['Confusing axial, tangential, and oblique modes.','Thinking absorption removes a mode''s frequency rather than damping it.','Ignoring modes because the room subjectively sounds fine.']::text[],ARRAY['Treating bass problems in a control room.','Sizing a listening room to spread modes.','Analyzing an instrument body''s resonances.']::text[],'advanced','f = (c/2) * sqrt((nx/Lx)^2 + (ny/Ly)^2 + (nz/Lz)^2)','A rectangular-room mode frequency equals half the sound speed times the square root of the summed squares of each mode number divided by that dimension.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eigenmode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60ca3740-54fa-4054-a8ab-6e8a5b53eb01','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60ca3740-54fa-4054-a8ab-6e8a5b53eb01') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60ca3740-54fa-4054-a8ab-6e8a5b53eb01');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da50998b-d597-4a86-9f9d-2ef6eeb8cd9c','Element order','In numerical acoustics (finite element and boundary element methods), element order is the polynomial degree of the shape functions used to interpolate the acoustic field within each mesh element. Higher-order elements represent field variation more accurately per element, allowing a coarser mesh for a given accuracy.','Computers solve sound problems by splitting space into small pieces. Inside each piece the field is guessed with a math curve. Element order is how curved that guess can be. Higher order fits the wave with fewer pieces. It costs more per piece, though.','It controls the trade-off between accuracy and computational cost in acoustic simulation meshes.','A common rule needs several elements per wavelength: linear elements often need about ten per wavelength, while quadratic (order-2) elements allow fewer, cutting mesh size at high frequency.','Numerical Methods',ARRAY['Distributed-parameter model','Helmholtz equation','Eigenmode','Frequency-response function','Guided-wave propagation']::text[],ARRAY['Confusing element order with mesh density (element count).','Using too few elements per wavelength and getting dispersion error.','Assuming higher order is always cheaper overall.']::text[],ARRAY['Setting up a finite-element acoustic model.','Running a boundary-element radiation study.','Balancing accuracy against solver runtime.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Element order');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da50998b-d597-4a86-9f9d-2ef6eeb8cd9c','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da50998b-d597-4a86-9f9d-2ef6eeb8cd9c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da50998b-d597-4a86-9f9d-2ef6eeb8cd9c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7a39c9de-861c-40cc-a256-32359886dbd9','Energy absorption coefficient','The energy absorption coefficient (alpha) is the fraction of incident sound energy not reflected by a surface, ranging from 0 for a perfect reflector to 1 for total absorption. It equals one minus the energy reflection coefficient, alpha = 1 - |R|^2.','When sound hits a surface, some bounces back and some is absorbed. The absorption coefficient is the share taken in. Zero means a perfect sound mirror. One means nothing reflects. It usually changes with frequency.','It quantifies how much sound a material soaks up, the core input for reverberation and room-treatment calculations.','Heavy drapery might have alpha approximately 0.6 at 500 Hz; this value feeds Sabine''s equation to set the reverberation time. Here alpha = 1 - |R|^2 = absorbed energy divided by incident energy.','Absorption',ARRAY['Distributed Helmholtz resonator','Characteristic impedance','Eigenmode','Grazing incidence','Compression wave']::text[],ARRAY['Confusing absorption (energy lost at a surface) with transmission (energy passing through).','Thinking alpha can never exceed 1 (Sabine values can, from edge effects).','Using a single alpha value across all frequencies.']::text[],ARRAY['Designing for a target reverberation time.','Comparing acoustic treatment panels.','Specifying a material''s noise-reduction coefficient.']::text[],'beginner','alpha = 1 - |R|^2','The absorption coefficient equals one minus the squared magnitude of the pressure reflection coefficient.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Energy absorption coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7a39c9de-861c-40cc-a256-32359886dbd9','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7a39c9de-861c-40cc-a256-32359886dbd9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7a39c9de-861c-40cc-a256-32359886dbd9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f70c1b07-b342-43e8-b9c3-ba7b74242a91','Evanescent wave','An evanescent wave is a near-field disturbance whose amplitude decays exponentially with distance and which carries no net energy away from its source or interface. It appears beyond a critical angle, near sources smaller than a wavelength, and below a waveguide''s cutoff frequency.','Some waves do not travel outward. Instead they cling near a surface or source and fade fast. Their strength drops off steeply with distance. They store energy rather than radiate it. These are evanescent waves.','It explains near-field behavior, sub-wavelength detail, and why energy is trapped rather than radiated in certain conditions.','Near a small source or below a duct''s cutoff, the field is evanescent, decaying as exp(-alpha*x); near-field acoustic holography exploits it to image sub-wavelength detail.','Wave Behavior',ARRAY['Critical angle','Guided-wave propagation','Far-field approximation','Fresnel region','Effective radiating size']::text[],ARRAY['Thinking evanescent waves carry energy outward.','Confusing evanescent near-field decay with ordinary spreading loss.','Ignoring evanescent components in near-field measurements.']::text[],ARRAY['Near-field acoustic holography imaging.','Duct behavior below the cutoff frequency.','Total internal reflection beyond the critical angle.']::text[],'advanced','p(x) proportional to exp(-alpha*x)','The pressure amplitude of an evanescent wave falls off exponentially with distance.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Evanescent wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f70c1b07-b342-43e8-b9c3-ba7b74242a91','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f70c1b07-b342-43e8-b9c3-ba7b74242a91') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f70c1b07-b342-43e8-b9c3-ba7b74242a91');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d103607-2a58-4c29-8ea0-e28279522151','Far-field approximation','The far-field approximation applies at distances large compared with both the wavelength and the source size, where the wavefront is effectively planar, the level falls 6 dB per distance doubling for a point source, and the radiation pattern no longer changes shape with distance. It requires roughly r much greater than lambda and r much greater than D^2/lambda.','Far from a source the sound settles into a simple form. The wavefront looks flat and the pattern stops changing. Level then drops six decibels each time distance doubles. You must be many wavelengths and source-sizes away. This is the far field.','It lets engineers use simple point-source math and stable polar patterns for measurement and prediction.','To measure a 0.3 m loudspeaker at 1 kHz (lambda approximately 0.34 m), stay beyond about r = 2*D^2/lambda approximately 0.53 m and several wavelengths; 1 to 2 m is safely far field.','Sound Propagation',ARRAY['Fraunhofer region','Fresnel region','Effective radiating size','Cylindrical spreading loss','Frequency-dependent directionality']::text[],ARRAY['Measuring too close and collecting near-field errors.','Assuming the 6 dB-per-doubling rule holds in the near field.','Forgetting the criterion depends on both wavelength and source size.']::text[],ARRAY['Measuring a loudspeaker''s frequency response.','Placing a measurement microphone.','Predicting sound level at the audience.']::text[],'intermediate','r >> 2*D^2/lambda','The far field begins where distance is much greater than twice the source size squared divided by the wavelength (and much greater than a wavelength).','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field approximation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d103607-2a58-4c29-8ea0-e28279522151','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d103607-2a58-4c29-8ea0-e28279522151') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d103607-2a58-4c29-8ea0-e28279522151');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9c0fb39-520b-4d48-9e19-63089745033c','Finite-amplitude acoustics','Finite-amplitude (nonlinear) acoustics studies sound waves whose amplitude is large enough that the linear approximation fails, so effects such as waveform steepening, harmonic generation, and shock formation appear. It governs high-intensity sound where the acoustic pressure is not small compared with ambient pressure.','Quiet sound follows simple linear rules. Very loud sound breaks those rules. The wave steepens and grows extra harmonics. It can even form a shock. This large-amplitude behavior is finite-amplitude acoustics.','It describes high-intensity phenomena in sirens, sonic booms, medical ultrasound, and loud horns where linear theory is inadequate.','In high-intensity ultrasound or a loud horn a pure tone steepens and spawns harmonics; a shock forms after a discontinuity distance set by the Mach number and the nonlinearity parameter B/A.','Nonlinear Acoustics',ARRAY['Compression wave','Bulk acoustic wave','Half-wavelength relationships','Characteristic impedance','Guided-wave propagation']::text[],ARRAY['Applying linear superposition to very loud sound.','Ignoring self-generated harmonics at high intensity.','Assuming sound-pressure level scales linearly with drive at high levels.']::text[],ARRAY['High-intensity focused ultrasound therapy.','Studying sonic-boom propagation.','Designing a parametric (ultrasonic) loudspeaker.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite-amplitude acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9c0fb39-520b-4d48-9e19-63089745033c','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9c0fb39-520b-4d48-9e19-63089745033c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9c0fb39-520b-4d48-9e19-63089745033c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a522137d-8b51-4e23-8517-aaedb454b7dc','Fraunhofer region','The Fraunhofer region is the far-field zone of a radiating aperture, beyond the Rayleigh distance r > 2*D^2/lambda, where the beam pattern is fully formed and independent of distance and the wavefront is essentially planar. The angular directivity there is the Fourier transform of the aperture''s source distribution.','Far from a large source the beam takes its final shape. Its pattern no longer changes with distance. This far zone is the Fraunhofer region. You reach it past the Rayleigh distance, about two source-widths squared over the wavelength.','It defines where a source''s polar or beam pattern is valid and stable for measurement and design.','For a 1 m array at 1 kHz (lambda approximately 0.34 m), the Fraunhofer region begins near r = 2*D^2/lambda approximately 5.8 m; polar plots are only meaningful beyond that.','Sound Propagation',ARRAY['Fresnel region','Far-field approximation','Effective radiating size','Frequency-dependent directionality','Cylindrical spreading loss']::text[],ARRAY['Measuring a large array''s polar pattern while still in the Fresnel region.','Confusing Fraunhofer (far) with Fresnel (near).','Ignoring that the boundary distance moves with frequency.']::text[],ARRAY['Far-field measurement of a line array.','Antenna-style beam-pattern analysis.','Anechoic polar testing of a loudspeaker.']::text[],'advanced','r > 2*D^2/lambda','The Fraunhofer (far-field) region lies beyond the Rayleigh distance, twice the aperture size squared divided by the wavelength.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fraunhofer region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a522137d-8b51-4e23-8517-aaedb454b7dc','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a522137d-8b51-4e23-8517-aaedb454b7dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a522137d-8b51-4e23-8517-aaedb454b7dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd435224e-38ff-411e-9041-d687cc1f34c4','Frequency-dependent directionality','Frequency-dependent directionality is the tendency of a source or receiver to radiate or pick up sound more selectively as frequency rises, because directivity depends on size relative to wavelength (ka). Low frequencies spread widely while high frequencies beam.','A speaker spreads bass in all directions. It focuses treble into a narrow beam. So its coverage narrows as pitch rises. Microphones behave the same way. This change of pattern with pitch is frequency-dependent directionality.','It explains why coverage and tone change with listener position and motivates constant-directivity designs.','A dome tweeter is wide at 2 kHz but beams at 16 kHz; waveguides and arrays hold a more constant angle. The directivity index rises with ka = 2*pi*f*a/c.','Radiation Pattern',ARRAY['Effective radiating size','Driver spacing and lobing','Far-field approximation','Diffraction around obstacles','Fraunhofer region']::text[],ARRAY['Expecting flat on-axis response to mean even off-axis coverage.','Ignoring high-frequency beaming when aiming speakers.','Assuming a microphone''s polar pattern is frequency-independent.']::text[],ARRAY['Aiming a PA system for even coverage.','Choosing a constant-directivity horn.','Judging off-axis coloration of a microphone.']::text[],'intermediate','ka = 2*pi*f*a/c','Directivity grows with the size parameter ka, which is two pi times frequency times the radius divided by the sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-dependent directionality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd435224e-38ff-411e-9041-d687cc1f34c4','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d435224e-38ff-411e-9041-d687cc1f34c4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d435224e-38ff-411e-9041-d687cc1f34c4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b9a8337-92ee-474b-9691-f7b4920735de','Frequency-response function','A frequency-response function (FRF) is the complex ratio of a system''s output to its input as a function of frequency, H(f) = Y(f)/X(f), giving both magnitude (gain) and phase versus frequency. It fully characterizes a linear time-invariant system''s steady-state behavior.','Feed a system many frequencies and watch what comes out. The frequency-response function compares output to input at each one. It shows both level and phase change. It tells how a room, filter, or speaker shapes sound. It holds only for linear systems.','It provides a complete, measurable description of how a device or space alters signals, the basis of audio measurement and equalization.','Dual-channel analyzers compute H(f) = Y(f)/X(f) from an FFT ratio to measure a loudspeaker or room; the magnitude gives the response curve and the phase reveals delay.','Measurement',ARRAY['Frequency-dependent directionality','Distance-to-phase conversion','Eigenmode','Element order','Half-wavelength relationships']::text[],ARRAY['Confusing the magnitude-only curve with the full complex FRF.','Applying an FRF to a nonlinear system.','Trusting a measured FRF without checking coherence.']::text[],ARRAY['Measuring room response with a dual-FFT analyzer.','Quality-control testing of a loudspeaker.','Aligning and equalizing a sound system.']::text[],'intermediate','H(f) = Y(f)/X(f)','The frequency-response function equals the output spectrum divided by the input spectrum at each frequency.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-response function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b9a8337-92ee-474b-9691-f7b4920735de','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b9a8337-92ee-474b-9691-f7b4920735de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b9a8337-92ee-474b-9691-f7b4920735de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bee95c3c-6dea-4701-be5a-6b9c3249bcf9','Fresnel region','The Fresnel region is the radiating near-field zone of an aperture, closer than the Rayleigh distance r < 2*D^2/lambda, where the wavefront is curved and the beam pattern varies with distance. Interference among aperture contributions causes on-axis level fluctuations there.','Close to a large source the sound field is complicated. The pattern keeps changing as you move nearer or farther. Levels can ripple up and down along the axis. This near zone is the Fresnel region. It ends at the Rayleigh distance.','It warns where measurements and level predictions are unreliable because the beam pattern is not yet formed.','Within a line array''s Fresnel region the level may fall only about 3 dB per doubling and on-axis nulls appear; the region extends out to r = 2*D^2/lambda.','Sound Propagation',ARRAY['Fraunhofer region','Far-field approximation','Evanescent wave','Effective radiating size','Cylindrical spreading loss']::text[],ARRAY['Measuring in the Fresnel region and calling it far-field data.','Expecting a smooth 6 dB-per-doubling drop there.','Confusing Fresnel (near) with Fraunhofer (far).']::text[],ARRAY['Near-field coverage of a tall line array.','Avoiding near-field measurement error.','Analyzing a large flat-panel radiator.']::text[],'advanced','r < 2*D^2/lambda','The Fresnel (near-field) region lies within the Rayleigh distance, twice the aperture size squared divided by the wavelength.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fresnel region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bee95c3c-6dea-4701-be5a-6b9c3249bcf9','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bee95c3c-6dea-4701-be5a-6b9c3249bcf9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bee95c3c-6dea-4701-be5a-6b9c3249bcf9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f87e146-8786-43b3-b3d1-210a3e29a084','Geometrical acoustics','Geometrical (ray) acoustics is a high-frequency approximation that treats sound as traveling along rays and ignores diffraction, valid when the wavelength is small compared with the dimensions of obstacles and the room. It underlies ray-tracing prediction of reflections and reverberation.','When wavelengths are small, sound acts like light rays. It travels in straight lines and bounces cleanly. This ray picture ignores bending around edges. It works well at high frequencies in large rooms. It fails for long bass wavelengths.','It enables simple ray-tracing prediction of reflections, echoes, and coverage in large spaces.','Auralization software ray-traces a concert hall''s early reflections; the method is trusted above the Schroeder frequency, where the wavelength is small versus the room size.','Modeling',ARRAY['Eigenmode','Diffraction around obstacles','Distributed-parameter model','Grazing incidence','Frequency-dependent directionality']::text[],ARRAY['Applying ray acoustics at low frequencies where diffraction dominates.','Ignoring diffraction at barrier and wall edges.','Assuming rays capture modal (standing-wave) behavior.']::text[],ARRAY['Ray-tracing a concert hall.','Designing coverage in a large stadium.','Predicting echoes in a big space.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Geometrical acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f87e146-8786-43b3-b3d1-210a3e29a084','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f87e146-8786-43b3-b3d1-210a3e29a084') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f87e146-8786-43b3-b3d1-210a3e29a084');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92969065-a7f7-4ba7-bc52-541d4763074e','Grazing incidence','Grazing incidence is sound arriving at a surface at nearly 90 degrees from the normal, traveling almost parallel to the surface. It maximizes path-length interference between direct and reflected sound and is a reference condition for ground-effect dips and for measurement-microphone orientation.','Sound can hit a surface almost side-on, skimming along it. This is grazing incidence. Direct and reflected sound then arrive close together and interfere. Over ground this causes cancellation dips. Some microphones are aimed this way on purpose.','It defines a key geometry for outdoor ground effect, barrier performance, and microphone incidence behavior.','Sound over grass shows a ground-effect dip at grazing incidence; a measurement microphone used at grazing (90-degree) incidence minimizes high-frequency pressure buildup at its diaphragm.','Reflection & Refraction',ARRAY['Critical angle','Diffraction around obstacles','Energy absorption coefficient','Geometrical acoustics','Evanescent wave']::text[],ARRAY['Measuring the angle from the surface instead of from the normal.','Assuming grazing sound simply reflects with no interference.','Ignoring ground-effect cancellation on grazing outdoor paths.']::text[],ARRAY['Outdoor sound propagation over the ground.','Grazing paths across a noise barrier.','Orienting a measurement microphone.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grazing incidence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92969065-a7f7-4ba7-bc52-541d4763074e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92969065-a7f7-4ba7-bc52-541d4763074e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92969065-a7f7-4ba7-bc52-541d4763074e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ccc8691f-738a-4cf8-a1a7-0ee7655ce6df','Guided-wave propagation','Guided-wave propagation is the confinement and channeling of acoustic waves within a bounded structure such as a duct, pipe, or plate, where the boundaries constrain the field into discrete modes. Each mode has a cutoff frequency below which it cannot propagate and instead decays evanescently.','A duct or pipe can channel sound along its length. The walls trap the wave inside. Only certain patterns, called modes, can travel. Each mode has a lowest frequency it needs. Below that it fades out instead of moving.','It describes how sound travels in ducts, pipes, and panels, essential for HVAC noise, wind instruments, and ultrasonic testing.','In a rigid duct only the plane-wave mode travels below the first cutoff f = c/(2a) for a duct of width a; above it, higher-order modes appear and complicate silencer design.','Wave Propagation',ARRAY['Evanescent wave','Distributed-parameter model','Half-wave resonance','Eigenmode','Bulk acoustic wave']::text[],ARRAY['Assuming every frequency propagates freely in a duct.','Ignoring higher-order modes above the cutoff frequency.','Confusing guided modes with free-field plane waves.']::text[],ARRAY['Designing an HVAC duct silencer.','Modeling a wind instrument''s bore.','Using Lamb waves in nondestructive testing.']::text[],'advanced','f_cutoff = c/(2a)','The first higher-mode cutoff frequency in a rigid duct equals the sound speed divided by twice the duct width.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Guided-wave propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ccc8691f-738a-4cf8-a1a7-0ee7655ce6df','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ccc8691f-738a-4cf8-a1a7-0ee7655ce6df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ccc8691f-738a-4cf8-a1a7-0ee7655ce6df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6286dca2-b576-413f-8b28-a9fa619d4828','Half-wave resonance','Half-wave resonance occurs in a system such as a tube open at both ends (or closed at both ends) whose fundamental standing wave fits one half wavelength in its length, giving f = c/(2L). Overtones occur at all integer multiples of the fundamental.','A pipe open at both ends rings when half a wave fits its length. Its lowest note is sound speed over twice the length. The overtones are whole-number multiples of that note. A pipe closed at both ends behaves the same way.','It sets the fundamental and harmonic series for open pipes, transmission lines, and both-ends-fixed resonators.','A 0.5 m open-open tube resonates at f = 343/(2*0.5) = 343 Hz, with overtones at 686 Hz, 1029 Hz, and so on.','Resonance & Modes',ARRAY['Half-wavelength relationships','Eigenmode','Guided-wave propagation','Critical frequency','Distributed Helmholtz resonator']::text[],ARRAY['Confusing an open-open (half-wave) tube with an open-closed (quarter-wave) tube.','Forgetting the open-end length correction.','Expecting only odd harmonics (that is the quarter-wave case).']::text[],ARRAY['Tuning a flute or open organ pipe.','Designing a transmission-line loudspeaker.','Standing waves along a room dimension.']::text[],'intermediate','f_n = n*c/(2L)','The resonance frequencies equal an integer times the sound speed divided by twice the length.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Half-wave resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6286dca2-b576-413f-8b28-a9fa619d4828','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6286dca2-b576-413f-8b28-a9fa619d4828') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6286dca2-b576-413f-8b28-a9fa619d4828');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1890f6c-c262-4574-890f-1cc957ff3e82','Half-wavelength relationships','Half-wavelength relationships describe the acoustic consequences of a path or spacing equal to half a wavelength, which corresponds to a 180-degree phase shift and drives cancellations, standing-wave nodes, and destructive interference. They recur in room dimensions, microphone spacing, and comb filtering.','Half a wavelength of path means a 180-degree phase flip. Two signals can then cancel each other. This spacing sets standing-wave dead spots and comb-filter dips. It shows up in room sizes and microphone placement. Knowing it helps avoid cancellations.','It provides a quick rule linking spacing to cancellation, used to predict nulls and place sources and microphones.','Two microphones a half wavelength apart on one source cancel that frequency; at 500 Hz, half a wavelength is about 0.343 m, so 0.34 m spacing nulls 500 Hz. Here lambda/2 = c/(2f).','Phase & Interference',ARRAY['Distance-to-phase conversion','Half-wave resonance','Driver spacing and lobing','Eigenmode','Compression wave']::text[],ARRAY['Forgetting the relationship is specific to one frequency.','Confusing half-wavelength cancellation with full-wavelength reinforcement.','Ignoring it when spacing microphones or speakers.']::text[],ARRAY['Avoiding comb filtering between two sources.','Predicting room standing-wave nulls.','Applying the 3-to-1 microphone rule.']::text[],'beginner','lambda/2 = c/(2f)','Half a wavelength equals the sound speed divided by twice the frequency.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Half-wavelength relationships');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1890f6c-c262-4574-890f-1cc957ff3e82','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1890f6c-c262-4574-890f-1cc957ff3e82') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1890f6c-c262-4574-890f-1cc957ff3e82');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e14f3ac-3cac-419b-87c5-3000078889c7','Helmholtz equation','The Helmholtz equation is the time-independent (frequency-domain) form of the wave equation, laplacian(p) + k^2*p = 0, obtained by assuming a time-harmonic pressure, where k = omega/c is the wavenumber. It governs steady-state sound fields and underpins most acoustic modeling.','The wave equation describes sound changing in space and time. Assume one steady frequency and time drops out. What remains links the field''s curvature to its wavelength. That is the Helmholtz equation. Most sound-field math starts here.','It provides the master equation for steady-state acoustic fields, underlying modes, radiation, and numerical acoustics.','Finite-element and boundary-element solvers discretize laplacian(p) + k^2*p = 0 to predict room modes or radiation; with k = 2*pi*f/c, at 1 kHz k is about 18.3 rad/m.','Wave Equations',ARRAY['Eigenmode','Distributed-parameter model','Element order','Guided-wave propagation','Evanescent wave']::text[],ARRAY['Confusing the Helmholtz equation with the Helmholtz resonator.','Forgetting it assumes a single frequency.','Dropping the k^2 term.']::text[],ARRAY['Setting up a finite-element or boundary-element acoustic solve.','Deriving a room''s modal frequencies.','Solving a source-radiation problem.']::text[],'advanced','laplacian(p) + k^2*p = 0','The Laplacian of the complex pressure plus the wavenumber squared times the pressure equals zero.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Helmholtz equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e14f3ac-3cac-419b-87c5-3000078889c7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e14f3ac-3cac-419b-87c5-3000078889c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e14f3ac-3cac-419b-87c5-3000078889c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '841ada14-461f-464e-a3c5-d5684cc7c6dc','Homogeneous wave equation','The homogeneous acoustic wave equation is the source-free linear partial differential equation that governs small-amplitude sound pressure in a lossless, uniform fluid. It sets the Laplacian of the pressure equal to the second time derivative of the pressure divided by the square of the sound speed.','This equation describes how sound spreads through still air. It applies where no source is adding energy. It links how pressure bends in space to how fast it changes in time. The sound speed ties the two together.','It provides the basic mathematical model from which plane waves, spherical waves, and room modes are derived when no source is present in the region.','For c = 343 m/s, a plane-wave solution p = A·cos(kx − ωt) fits only when ω/k = c; at 1000 Hz the wavenumber is k = 2πf/c ≈ 18.3 rad/m and wavelength ≈ 0.343 m.','Wave Theory',ARRAY['Inhomogeneous wave equation','Linear acoustics','Impedance boundary condition','Natural frequency','Modal behavior']::text[],ARRAY['Assuming it holds for large-amplitude sound, where nonlinear terms matter.','Forgetting it describes only source-free regions.','Confusing the propagation speed c with particle velocity.']::text[],ARRAY['Deriving plane-wave behaviour for a duct or free field.','Setting up a room-mode analysis away from sources.','Explaining why frequency and wavelength are linked by sound speed.']::text[],'advanced','∇²p − (1/c²)·∂²p/∂t² = 0','The spatial Laplacian of acoustic pressure equals one divided by the square of the sound speed, times the second time derivative of pressure.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Homogeneous wave equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '841ada14-461f-464e-a3c5-d5684cc7c6dc','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='841ada14-461f-464e-a3c5-d5684cc7c6dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='841ada14-461f-464e-a3c5-d5684cc7c6dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db202609-38c1-48e7-b02c-a3c149400036','Impedance boundary condition','An impedance boundary condition specifies a surface by the ratio of acoustic pressure to normal particle velocity at that surface, rather than fixing pressure or velocity alone. This complex specific acoustic impedance sets how much sound the boundary reflects and absorbs.','This rule describes a wall by how it responds to sound. It links the pressure at the wall to the air motion into it. A hard wall lets no air move through. A soft or absorbing wall allows some motion.','It lets acoustic models represent real absorbing or reactive surfaces with a single impedance value instead of idealised rigid or pressure-release limits.','A rigid wall has infinite surface impedance, so normal particle velocity is zero; a perfectly absorbing surface matches the air, with specific impedance equal to ρ₀c ≈ 415 rayl in air at 20 °C.','Wave Theory',ARRAY['Homogeneous wave equation','Intensity reflection coefficient','Mean absorption coefficient','Linear acoustics','Leaky wave']::text[],ARRAY['Treating surface impedance as purely real when it usually has a reactive part.','Assuming every hard-looking surface is perfectly rigid.','Confusing specific acoustic impedance with characteristic impedance ρ₀c.']::text[],ARRAY['Modelling an absorptive room boundary in a simulation.','Specifying a reflective versus absorbing surface for a mode study.','Relating a surface impedance to its absorption coefficient.']::text[],'advanced','Z_s = p / u_n','The surface acoustic impedance equals the acoustic pressure at the surface divided by the particle velocity normal to that surface.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impedance boundary condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db202609-38c1-48e7-b02c-a3c149400036','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db202609-38c1-48e7-b02c-a3c149400036') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db202609-38c1-48e7-b02c-a3c149400036');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68415ba5-4f01-4370-bf6a-ee9df1306952','Infrasonics','Infrasonics refers to acoustic energy at frequencies below the nominal lower limit of human hearing, conventionally taken as below about 20 Hz. Such sound can be perceived as vibration or pressure rather than clear tone, and it propagates with very long wavelengths.','Infrasound is sound pitched below what people can hear. It sits under about 20 hertz. You may feel it as vibration rather than hear it. Its waves are very long. Wind, machines, and large sources make it.','The term marks the low-frequency band where normal hearing fails, which matters for measurement, environmental noise, and building or machinery vibration.','A technician chasing a 12 Hz rumble uses a microphone and analyser rated for infrasound, since standard meters and small monitors roll off well before that frequency.','Frequency Range',ARRAY['Instantaneous sound pressure','Natural frequency','Modal behavior','Monaural hearing']::text[],ARRAY['Assuming a sharp 20 Hz cutoff, when hearing thresholds vary between people.','Believing infrasound cannot affect people because it is inaudible.','Trying to measure it with gear that rolls off in the low bass.']::text[],ARRAY['Investigating a felt but unheard rumble in a venue.','Assessing HVAC or ventilation noise complaints.','Choosing instrumentation for very low-frequency measurement.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68415ba5-4f01-4370-bf6a-ee9df1306952','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68415ba5-4f01-4370-bf6a-ee9df1306952') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68415ba5-4f01-4370-bf6a-ee9df1306952');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77f5d168-6467-4e92-a397-ce340b57ef6f','Inhomogeneous wave equation','The inhomogeneous acoustic wave equation is the wave equation with a non-zero right-hand side representing acoustic sources within the region. The source term drives the pressure field, so its solutions describe radiation from mass injection, applied forces, or other excitation.','This is the wave equation with a source added. The extra term stands for something making sound. It could be a pulsing volume or a force. Its solutions show how a source radiates into space.','It models sound generation and radiation, letting engineers predict the field produced by a loudspeaker, pulsating body, or other driven source.','A technician treats a small pulsating source as a simple (monopole) source term q(r,t); the radiated pressure then falls with distance following the inverse-distance spreading of the free-field solution.','Wave Theory',ARRAY['Homogeneous wave equation','Near-field approximation','Linear acoustics','Impedance boundary condition']::text[],ARRAY['Ignoring the source term and treating a driven region as source-free.','Confusing the source strength with the resulting pressure.','Assuming free-space solutions apply when boundaries reflect energy back.']::text[],ARRAY['Predicting radiation from a modelled loudspeaker source.','Analysing sound produced by a vibrating panel.','Setting up a source in an acoustic simulation.']::text[],'advanced','∇²p − (1/c²)·∂²p/∂t² = −q(r,t)','The Laplacian of pressure minus one over sound speed squared times the second time derivative of pressure equals the negative of a source distribution term.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inhomogeneous wave equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77f5d168-6467-4e92-a397-ce340b57ef6f','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77f5d168-6467-4e92-a397-ce340b57ef6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77f5d168-6467-4e92-a397-ce340b57ef6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60675a48-3f2c-48bc-82d4-f6de76365f2e','Insertion loss','Insertion loss is the reduction in sound level at a receiver caused by inserting an element such as a barrier, enclosure, silencer, or duct lining into the sound path. It is the level measured before insertion minus the level measured after, in decibels.','Insertion loss shows how much a device quiets sound. You measure the level before adding it. Then you measure again with it in place. The drop in decibels is the insertion loss.','It quantifies how effective a treatment or device is at a listener position, capturing real installed performance rather than a material property alone.','If a receiver reads 85 dB before a silencer and 62 dB after it is fitted, the insertion loss is 85 − 62 = 23 dB at that measurement band.','Noise Control',ARRAY['Mean absorption coefficient','Intensity reflection coefficient','Impedance boundary condition']::text[],ARRAY['Confusing insertion loss with transmission loss, which is a partition property.','Ignoring that insertion loss depends on the geometry and receiver position.','Reporting a single number without stating the frequency band.']::text[],ARRAY['Rating a duct silencer in an HVAC system.','Assessing a noise barrier at a listener location.','Comparing enclosure designs for a noisy machine.']::text[],'intermediate','IL = L_p,before − L_p,after','Insertion loss equals the sound pressure level at the receiver before inserting the element, minus the level at the same point after insertion.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Insertion loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60675a48-3f2c-48bc-82d4-f6de76365f2e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60675a48-3f2c-48bc-82d4-f6de76365f2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60675a48-3f2c-48bc-82d4-f6de76365f2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0809da5e-a30e-4be1-b08b-f8ad60425a56','Instantaneous sound pressure','Instantaneous sound pressure is the momentary difference between the total pressure at a point and the ambient static pressure, at a given instant of time. It is the fluctuating acoustic component whose amplitude and sign vary continuously as a wave passes.','Sound rides on top of the steady air pressure. Instantaneous sound pressure is that small extra part right now. It rises and falls as the wave moves by. It can be positive or negative.','It is the fundamental time-domain acoustic quantity from which levels, RMS values, and energy measures are derived.','A technician viewing a microphone signal on an oscilloscope reads the instantaneous sound pressure directly; squaring and time-averaging it yields the mean-square value used for sound pressure level.','Acoustic Quantities',ARRAY['Kinetic energy density','Infrasonics','Homogeneous wave equation','Intensity reflection coefficient']::text[],ARRAY['Confusing instantaneous pressure with the RMS or peak value.','Forgetting to subtract the static ambient pressure.','Reporting a single instant as if it were a level.']::text[],ARRAY['Reading a raw microphone waveform on a scope.','Explaining how RMS level comes from the pressure signal.','Distinguishing peak from continuous pressure values.']::text[],'beginner','p(t) = P_total(t) − P₀','Instantaneous sound pressure equals the total instantaneous pressure at a point minus the ambient static pressure.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Instantaneous sound pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0809da5e-a30e-4be1-b08b-f8ad60425a56','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0809da5e-a30e-4be1-b08b-f8ad60425a56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0809da5e-a30e-4be1-b08b-f8ad60425a56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6dee45c1-ff55-4f69-a205-0c3a60ec2e47','Integrated impulse-response method','The integrated impulse-response method obtains a sound-energy decay curve by integrating the squared room impulse response backward in time, following Schroeder. The resulting smooth decay curve is used to derive reverberation time and related room-acoustic parameters.','This method measures how a room''s echo dies away. It starts from the room''s impulse response. It squares that signal and adds it up from the end backward. The smooth curve that results gives the reverberation time.','It yields a stable, repeatable decay curve from a single measurement, avoiding the run-to-run scatter of the interrupted-noise method.','A technician captures a room impulse response with a swept sine, then applies Schroeder backward integration E(t) = ∫ from t to ∞ of p²(τ) dτ and reads T20 or T30 from the decay slope.','Room Measurement',ARRAY['Interrupted-noise method','Mean absorption coefficient','Modal behavior','Late lateral sound level']::text[],ARRAY['Confusing this method with directly recording decaying noise.','Integrating forward instead of backward in time.','Failing to truncate or compensate the impulse-response noise tail.']::text[],ARRAY['Measuring reverberation time in a performance space.','Deriving clarity and decay parameters from one impulse response.','Comparing decay results with the interrupted-noise method.']::text[],'advanced','E(t) = ∫_t^∞ p²(τ) dτ','The decay energy at time t equals the integral of the squared impulse response from that time out to infinity.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Integrated impulse-response method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6dee45c1-ff55-4f69-a205-0c3a60ec2e47','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6dee45c1-ff55-4f69-a205-0c3a60ec2e47') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6dee45c1-ff55-4f69-a205-0c3a60ec2e47');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e6aca8a2-bbc9-4362-9472-eee1eacea0c3','Intensity reflection coefficient','The intensity reflection coefficient is the fraction of incident sound intensity reflected at a boundary between two media. For normal incidence it equals the squared magnitude of the pressure reflection coefficient, which depends on the two characteristic acoustic impedances.','When sound hits a boundary, some energy bounces back. This number is the fraction that reflects. It depends on how the two materials differ in impedance. A big mismatch reflects almost everything.','It tells how much acoustic energy is returned versus transmitted at an interface, which underlies reflection, absorption, and transmission calculations.','At an air-to-water interface at normal incidence, with Z₁ ≈ 415 rayl and Z₂ ≈ 1.48×10⁶ rayl, R_I = ((Z₂ − Z₁)/(Z₂ + Z₁))² ≈ 0.999, so nearly all sound reflects.','Wave Theory',ARRAY['Impedance boundary condition','Mean absorption coefficient','Mode conversion','Insertion loss']::text[],ARRAY['Confusing the intensity coefficient with the pressure coefficient (one is the square of the other).','Using the normal-incidence form at oblique angles.','Forgetting that reflected plus transmitted intensity fractions sum to one for a lossless interface.']::text[],ARRAY['Estimating reflection at a boundary between two media.','Explaining why sound barely enters water from air.','Relating impedance mismatch to absorption at a surface.']::text[],'advanced','R_I = ((Z₂ − Z₁)/(Z₂ + Z₁))²','At normal incidence the intensity reflection coefficient equals the square of the difference of the two characteristic impedances divided by their sum.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity reflection coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e6aca8a2-bbc9-4362-9472-eee1eacea0c3','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e6aca8a2-bbc9-4362-9472-eee1eacea0c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e6aca8a2-bbc9-4362-9472-eee1eacea0c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '416e6749-506e-4c8b-9be4-0ebead30a522','Internal resonance','Internal resonance is a nonlinear condition in which two or more natural modes of a system have frequencies in a simple integer ratio, allowing strong energy exchange between them. It is a resonance among the modes themselves rather than with an external drive.','A vibrating body has many natural modes. Sometimes their frequencies line up in whole-number ratios. Then energy can pass strongly from one mode to another. We call this coupling internal resonance.','It explains how energy fed into one mode can appear in another, producing rich or unexpected vibration in strings, plates, shells, and structural elements.','An instrument builder who finds a body mode near twice another mode''s frequency expects internal resonance, so driving the lower mode can pump energy into the higher one.','Nonlinear Vibration',ARRAY['Natural frequency','Mode coupling','Modal behavior','Mode shape']::text[],ARRAY['Confusing internal resonance with ordinary forced resonance from an external source.','Assuming modes never exchange energy in a linear model.','Overlooking the required integer frequency ratio between modes.']::text[],ARRAY['Explaining odd tonal behaviour in a musical instrument body.','Analysing energy transfer between structural modes.','Studying nonlinear response of plates or shells.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Internal resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '416e6749-506e-4c8b-9be4-0ebead30a522','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='416e6749-506e-4c8b-9be4-0ebead30a522') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='416e6749-506e-4c8b-9be4-0ebead30a522');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95e0973c-83e6-496b-b339-02aec4d5955e','Interrupted-noise method','The interrupted-noise method measures reverberation by exciting a room with broadband or band-limited noise, then abruptly stopping the source and directly recording the decay of sound pressure level. Reverberation time is found from the slope of the recorded decay.','This method fills a room with steady noise. Then the noise is switched off suddenly. A meter records how the level fades. The fade rate gives the reverberation time. Several runs are averaged.','It provides a straightforward decay measurement using noise and a level recorder, long the classic technique before impulse-response processing.','A technician plays pink noise, cuts it, and reads T30 from the −5 dB to −35 dB portion of the decay, averaging several stops because each decay differs slightly.','Room Measurement',ARRAY['Integrated impulse-response method','Mean absorption coefficient','Modal behavior','Late lateral sound level']::text[],ARRAY['Reading the reverberation from too small a decay range above the noise floor.','Not averaging enough decays, so scatter biases the result.','Assuming a single stop gives a repeatable decay curve.']::text[],ARRAY['Measuring reverberation time with noise and a sound level meter.','Cross-checking impulse-response results in a hall.','Field-testing reverberation where impulse gear is unavailable.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interrupted-noise method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95e0973c-83e6-496b-b339-02aec4d5955e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95e0973c-83e6-496b-b339-02aec4d5955e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95e0973c-83e6-496b-b339-02aec4d5955e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc9fca20-efb4-4418-b24a-2571a30b05a5','Kinetic energy density','Kinetic energy density is the acoustic kinetic energy per unit volume in a sound field, arising from the motion of the fluid particles. It equals one half the fluid density times the square of the particle velocity.','Moving air in a sound wave carries energy. Kinetic energy density is that motion energy per unit volume. It grows with the square of particle speed. It pairs with the potential energy stored in pressure.','It is one of the two parts of acoustic energy density and is central to describing energy storage and flow in a sound field.','For air with ρ₀ = 1.21 kg/m³ and a particle velocity of 0.001 m/s, the instantaneous kinetic energy density is ½·1.21·(0.001)² ≈ 6.05×10⁻⁷ J/m³.','Acoustic Quantities',ARRAY['Instantaneous sound pressure','Homogeneous wave equation','Near-field approximation','Linear acoustics']::text[],ARRAY['Confusing particle velocity with the wave propagation speed c.','Forgetting kinetic energy density pairs with potential (pressure) energy density.','Mixing instantaneous and time-averaged values.']::text[],ARRAY['Analysing energy balance in a standing-wave field.','Relating particle velocity to stored acoustic energy.','Comparing kinetic and potential energy in a room mode.']::text[],'advanced','w_k = ½·ρ₀·u²','Kinetic energy density equals one half the equilibrium fluid density times the square of the particle velocity.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kinetic energy density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc9fca20-efb4-4418-b24a-2571a30b05a5','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc9fca20-efb4-4418-b24a-2571a30b05a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc9fca20-efb4-4418-b24a-2571a30b05a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eadf6ca3-edd8-47c5-9c04-53aef28f6a9b','Lamb wave','A Lamb wave is a guided elastic wave that propagates in a solid plate whose thickness is comparable to the wavelength, bounded by two free surfaces. It exists in symmetric and antisymmetric modes whose velocities depend on frequency and plate thickness, making Lamb waves dispersive.','A Lamb wave travels along a thin plate. The plate''s two surfaces guide it. It comes in symmetric and bending forms. Its speed changes with frequency and plate thickness. This makes it a dispersive wave.','Lamb waves let a single transducer inspect large plate-like structures, because the guided wave carries energy over long distances within the plate.','An inspector launches an antisymmetric (A0) Lamb mode along a metal panel and reads reflected arrivals to locate a crack, choosing the frequency-thickness product from the plate''s dispersion curves.','Elastic Waves',ARRAY['Love wave','Leaky wave','Mode conversion','Mode shape','Linear acoustics']::text[],ARRAY['Treating Lamb waves as non-dispersive, so ignoring how speed varies with frequency.','Confusing plate-guided Lamb waves with surface Rayleigh waves on a half-space.','Forgetting that multiple modes can propagate at once.']::text[],ARRAY['Ultrasonic inspection of plates and pipe walls.','Structural health monitoring of aircraft skin.','Selecting a guided-wave mode for defect detection.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lamb wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eadf6ca3-edd8-47c5-9c04-53aef28f6a9b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eadf6ca3-edd8-47c5-9c04-53aef28f6a9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eadf6ca3-edd8-47c5-9c04-53aef28f6a9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d3e0d4a-ee6b-4450-8e38-65c0af49166c','Late lateral sound level','Late lateral sound level is a room-acoustic parameter that quantifies the strength of late sound arriving from the sides of a listener, relative to the sound of the source measured at 10 m in a free field. It is computed from a figure-of-eight microphone impulse response integrated from 80 ms onward.','In a hall, late sound arrives from the sides. This parameter measures how strong that side sound is. It uses a figure-of-eight microphone facing the source''s null. Late energy after 80 milliseconds is compared to the source at 10 metres.','It gauges listener envelopment, the sense of being surrounded by sound, which is an important quality of concert-hall acoustics.','A technician measures the impulse response with a figure-of-eight microphone (its null toward the source), integrates the late lateral energy from 80 ms, and references it to an omnidirectional 10 m free-field measurement using the ISO 3382-1 formula.','Room Measurement',ARRAY['Integrated impulse-response method','Interrupted-noise method','Modal behavior','Mean absorption coefficient']::text[],ARRAY['Confusing late lateral level with the early lateral energy fraction.','Misorienting the figure-of-eight microphone relative to the source.','Forgetting the 80 ms lower integration limit for late energy.']::text[],ARRAY['Assessing envelopment in a concert hall.','Comparing seat positions for spatial impression.','Reporting ISO 3382-1 spatial parameters for a venue.']::text[],'advanced','L_J = 10·lg[ ∫_{0.080}^{∞} p_L²(t) dt / ∫_{0}^{∞} p_10²(t) dt ]  dB','Late lateral sound level equals ten times the base-ten logarithm of the late lateral squared pressure integrated from 80 milliseconds, divided by the squared source pressure at 10 metres integrated over all time.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Late lateral sound level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d3e0d4a-ee6b-4450-8e38-65c0af49166c','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d3e0d4a-ee6b-4450-8e38-65c0af49166c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d3e0d4a-ee6b-4450-8e38-65c0af49166c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '16b8fe0c-5af7-4e82-a7e5-3707dc7c5e51','Leaky wave','A leaky wave is a guided or surface elastic wave that continuously radiates energy into an adjoining medium as it propagates, so its amplitude decays along the path. Leaky Lamb and leaky Rayleigh waves occur when a solid is loaded by a fluid that carries energy away.','A leaky wave travels along a surface but loses energy as it goes. It leaks sound into the neighbouring material. A plate in water is one example. The wave fades as it radiates outward.','Leaky waves explain energy loss from fluid-loaded structures and underpin methods that detect leaks or measure material properties through the radiated field.','An inspector using immersion ultrasonics observes a leaky Lamb wave whose amplitude drops along a submerged plate, because energy radiates into the surrounding water at the coincidence angle.','Elastic Waves',ARRAY['Lamb wave','Love wave','Mode conversion','Impedance boundary condition']::text[],ARRAY['Assuming a fluid-loaded guided wave is lossless.','Confusing leakage radiation with material damping.','Ignoring the radiation angle set by the wave and fluid speeds.']::text[],ARRAY['Immersion ultrasonic testing of plates.','Measuring material properties from radiated leaky waves.','Explaining attenuation of surface waves on fluid-loaded solids.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Leaky wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '16b8fe0c-5af7-4e82-a7e5-3707dc7c5e51','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='16b8fe0c-5af7-4e82-a7e5-3707dc7c5e51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='16b8fe0c-5af7-4e82-a7e5-3707dc7c5e51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf2624ec-e968-45eb-817f-64d6205d3abe','Linear acoustics','Linear acoustics is the branch of acoustics that treats sound as a small perturbation of the medium, so the governing equations are linearised and pressure disturbances add by superposition. It is valid when acoustic amplitudes are small compared with the ambient pressure and density.','Linear acoustics treats sound as a small ripple. The ripple is tiny next to the steady pressure. Under this rule, waves simply add together. Most everyday sound behaves this way. Very loud sound does not.','It provides the tractable framework, based on superposition, that underlies nearly all standard analysis of waves, rooms, and transducers.','A technician relying on superposition to add two signals or predict interference is using linear acoustics, valid because normal sound pressures are far below atmospheric pressure.','Wave Theory',ARRAY['Homogeneous wave equation','Inhomogeneous wave equation','Kinetic energy density','Impedance boundary condition']::text[],ARRAY['Applying superposition to very high-amplitude sound where nonlinear effects appear.','Assuming the medium is always linear regardless of level.','Confusing linear acoustics with linear frequency response of a device.']::text[],ARRAY['Adding signals and predicting interference patterns.','Justifying standard room and duct analysis.','Marking the boundary where nonlinear acoustics takes over.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf2624ec-e968-45eb-817f-64d6205d3abe','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf2624ec-e968-45eb-817f-64d6205d3abe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf2624ec-e968-45eb-817f-64d6205d3abe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73cc2ebd-264d-41c4-b504-05f0dc6fb01c','Loudspeaker spacing and interference','Loudspeaker spacing and interference concerns how the distance between two or more loudspeakers reproducing the same signal creates position-dependent constructive and destructive interference. Path-length differences produce comb filtering and lobing that vary the frequency response across the coverage area.','Two speakers playing the same signal overlap in the air. Their sound adds in some spots and cancels in others. This depends on the path-length difference. The result is uneven response across the room. Spacing controls the pattern.','Understanding this guides loudspeaker placement so coverage is even and comb-filtering dips are minimised in the audience area.','A technician spacing two subwoofers keeps their separation small relative to the wavelength to avoid deep cancellation, since two sources one wavelength apart cancel where their path difference is half a wavelength.','Sound Reinforcement',ARRAY['Microphone spacing and phase interaction','Intensity reflection coefficient','Modal behavior','Near-field approximation']::text[],ARRAY['Assuming two speakers always add 6 dB everywhere, ignoring cancellation zones.','Forgetting that comb-filter spacing depends on frequency and geometry.','Spacing sources far apart at low frequency and creating cancellation.']::text[],ARRAY['Placing multiple loudspeakers for even coverage.','Diagnosing tonal changes as a listener moves.','Arranging subwoofers to avoid low-frequency cancellation.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudspeaker spacing and interference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73cc2ebd-264d-41c4-b504-05f0dc6fb01c','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73cc2ebd-264d-41c4-b504-05f0dc6fb01c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73cc2ebd-264d-41c4-b504-05f0dc6fb01c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b0b36965-6d36-485d-9f29-a26464c030e2','Love wave','A Love wave is a horizontally polarised shear surface wave that propagates in a layered elastic medium, where a lower-speed surface layer overlies a faster half-space. Its particle motion is transverse and parallel to the surface, and it is dispersive.','A Love wave travels along the surface of layered ground. It shakes side to side, flat along the surface. It needs a slower top layer over faster rock. Its speed changes with frequency. Earthquakes produce them.','Love waves describe part of the surface-wave energy in layered media, important in seismology and in guided-wave testing of coated or layered solids.','A geophysicist identifies a Love wave by its purely horizontal, surface-parallel shaking on seismograph traces, distinguishing it from the rolling motion of a Rayleigh wave.','Elastic Waves',ARRAY['Lamb wave','Leaky wave','Mode conversion','Mode shape']::text[],ARRAY['Confusing horizontally polarised Love waves with vertically rolling Rayleigh waves.','Assuming Love waves exist without a slower surface layer.','Treating them as non-dispersive.']::text[],ARRAY['Interpreting surface-wave arrivals in seismology.','Analysing guided waves in layered or coated solids.','Distinguishing surface-wave types by their polarisation.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Love wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b0b36965-6d36-485d-9f29-a26464c030e2','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b0b36965-6d36-485d-9f29-a26464c030e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b0b36965-6d36-485d-9f29-a26464c030e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee9413ab-0ba9-4ffc-907c-cf093d197cc1','Lumped-element approximation','The lumped-element approximation treats an acoustic component as a discrete element with a single value of mass, compliance, or resistance, valid when the component is much smaller than the acoustic wavelength. Under this condition the pressure and velocity can be taken as uniform across the element.','When a part is much smaller than the wavelength, sound acts on it all at once. We can then treat it as one lump. It becomes a single mass, spring, or resistance. This simplifies the analysis greatly.','It reduces distributed acoustic systems to simple circuit-like models, making devices such as Helmholtz resonators and small enclosures easy to analyse.','A technician modelling a small ported enclosure treats the port air as a lumped mass and the box air as a lumped spring, valid because both are far smaller than the bass wavelength.','Acoustic Modelling',ARRAY['Natural frequency','Mass-controlled region','Near-field approximation','Impedance boundary condition']::text[],ARRAY['Applying it when the element is comparable to or larger than the wavelength.','Ignoring the high-frequency limit where wave effects appear.','Assuming uniform pressure across a large component.']::text[],ARRAY['Modelling a Helmholtz resonator or small port.','Designing a compact loudspeaker enclosure.','Deciding when a component is acoustically ''small''.']::text[],'intermediate','L ≪ λ','The lumped-element approximation holds when the largest dimension of the component is much smaller than the acoustic wavelength.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lumped-element approximation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee9413ab-0ba9-4ffc-907c-cf093d197cc1','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee9413ab-0ba9-4ffc-907c-cf093d197cc1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee9413ab-0ba9-4ffc-907c-cf093d197cc1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30391361-c42c-40a7-afe2-a5e83aed9f0f','Mass-controlled region','The mass-controlled region is the frequency range, above a system''s resonance, where its response is dominated by inertial mass rather than stiffness or damping. In this range the mechanical reactance rises with frequency and displacement falls at roughly 12 dB per octave for a driven force.','Above resonance, mass rules a system''s response. Its inertia resists motion more as frequency rises. Stiffness matters less here. For a fixed force, motion drops steeply with frequency. This band is the mass-controlled region.','Identifying it explains how loudspeaker diaphragms, panels, and partitions behave above resonance, guiding design of transducers and sound-insulating structures.','A technician notes that a loudspeaker cone above its free-air resonance operates mass-controlled, giving the flat on-axis pressure response that piston sources produce in that band.','Vibration Behaviour',ARRAY['Natural frequency','Lumped-element approximation','Modal behavior','Mean absorption coefficient']::text[],ARRAY['Confusing the mass-controlled region with the stiffness-controlled region below resonance.','Assuming displacement is flat with frequency when it actually falls.','Ignoring damping''s role near the resonance itself.']::text[],ARRAY['Explaining a loudspeaker''s response above resonance.','Analysing panel transmission loss in its mass-law band.','Distinguishing stiffness-, damping-, and mass-controlled behaviour.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mass-controlled region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30391361-c42c-40a7-afe2-a5e83aed9f0f','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30391361-c42c-40a7-afe2-a5e83aed9f0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30391361-c42c-40a7-afe2-a5e83aed9f0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '448c9f12-dd09-40df-9545-980cf2d29d6e','Mean absorption coefficient','The mean absorption coefficient is the surface-area-weighted average of the absorption coefficients of all boundaries enclosing a room. It represents the fraction of incident sound energy absorbed per reflection, averaged over the whole enclosing surface.','A room has many surfaces, each absorbing sound differently. The mean absorption coefficient averages them by area. It gives one number for the whole room. Bigger surfaces count more. It feeds reverberation calculations.','It condenses a room''s varied surfaces into a single value used in Sabine and related reverberation-time formulas.','For a room with 100 m² at α = 0.1 and 50 m² at α = 0.5, the mean absorption coefficient is (100·0.1 + 50·0.5)/150 = 35/150 ≈ 0.23.','Room Acoustics',ARRAY['Intensity reflection coefficient','Integrated impulse-response method','Interrupted-noise method','Impedance boundary condition']::text[],ARRAY['Averaging coefficients without weighting by surface area.','Confusing the mean coefficient with total absorption in sabins.','Ignoring frequency dependence of each surface''s absorption.']::text[],ARRAY['Estimating reverberation time from surface data.','Comparing treatment options for a room.','Reporting a single absorption figure for an enclosure.']::text[],'intermediate','ᾱ = (Σ Sᵢ·αᵢ) / (Σ Sᵢ)','The mean absorption coefficient equals the sum over all surfaces of each area times its absorption coefficient, divided by the total surface area.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mean absorption coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '448c9f12-dd09-40df-9545-980cf2d29d6e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='448c9f12-dd09-40df-9545-980cf2d29d6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='448c9f12-dd09-40df-9545-980cf2d29d6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1854fb2-d89a-4ec3-acd5-830b134932be','Microphone spacing and phase interaction','Microphone spacing and phase interaction describes how the distance between two microphones capturing the same source causes time-of-arrival differences that create phase-dependent summation. When their signals are mixed, path-length differences produce comb filtering that colours the combined response.','Two microphones catch a source at slightly different times. Mixed together, their signals add and cancel by frequency. This comb filtering colours the sound. Spacing sets the pattern. The 3:1 rule helps avoid the worst of it.','It guides microphone placement so that combined signals do not suffer audible comb filtering from phase cancellation.','Following the 3-to-1 rule, a technician keeps the distance between two microphones at least three times each microphone''s distance to its source, so leakage arrives low enough to limit comb filtering.','Recording Technique',ARRAY['Loudspeaker spacing and interference','Modal behavior','Near-field approximation','Intensity reflection coefficient']::text[],ARRAY['Ignoring the 3:1 spacing guideline and getting hollow, phasey sound.','Assuming two microphones always sum cleanly.','Confusing comb filtering with equipment frequency-response errors.']::text[],ARRAY['Placing multiple microphones on a drum kit or ensemble.','Diagnosing thin, phasey sound after mixing microphones.','Setting spot and main microphone distances in a session.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone spacing and phase interaction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1854fb2-d89a-4ec3-acd5-830b134932be','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1854fb2-d89a-4ec3-acd5-830b134932be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1854fb2-d89a-4ec3-acd5-830b134932be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '051b956c-dd46-4383-ac32-bf622a5d18f8','Modal behavior','Modal behavior is the tendency of a bounded acoustic or vibrating system to respond most strongly at its natural modes, each a standing-wave pattern with a characteristic frequency and shape. In rooms it produces uneven low-frequency response as modes reinforce and cancel at different positions.','A room or object has natural standing-wave patterns. Each pattern has its own frequency and shape. Sound builds up at these modes. Low frequencies in small rooms behave this way. Response then varies from seat to seat.','Recognising modal behavior explains uneven bass and resonances, guiding room treatment, loudspeaker placement, and listening-position choices.','A technician hearing one bass note boom in a control room maps the room modes, then moves the subwoofer and seat away from that mode''s pressure extremes to even the response.','Modal Behavior',ARRAY['Modal spacing','Mode shape','Natural frequency','Mode coupling','Mean absorption coefficient']::text[],ARRAY['Assuming modes matter equally at all frequencies rather than mainly in the low end.','Treating room response as position-independent.','Confusing a single resonance with the full set of room modes.']::text[],ARRAY['Diagnosing boomy bass in a small studio.','Choosing loudspeaker and listener positions.','Planning low-frequency room treatment.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '051b956c-dd46-4383-ac32-bf622a5d18f8','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='051b956c-dd46-4383-ac32-bf622a5d18f8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='051b956c-dd46-4383-ac32-bf622a5d18f8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2bc2bf0c-2ea6-46d9-a633-dceb6c734f0b','Modal spacing','Modal spacing is the frequency separation between adjacent room modes. It is wide and uneven at low frequencies, where individual modes stand out, and becomes dense at higher frequencies, above the Schroeder frequency, where modes overlap into a statistical field.','Room modes sit at certain frequencies. Modal spacing is the gap between neighbouring ones. At low frequencies these gaps are wide. Single modes then dominate. Higher up, modes crowd together and blur into an even field.','It indicates where a room''s response is dominated by isolated resonances versus a dense, diffuse field, marking the transition set by the Schroeder frequency.','For a room of volume 100 m³ and reverberation time 0.5 s, the Schroeder frequency f ≈ 2000·√(0.5/100) ≈ 141 Hz; below it modal spacing is wide and problem modes dominate.','Modal Behavior',ARRAY['Modal behavior','Mode shape','Natural frequency','Mode coupling']::text[],ARRAY['Assuming even modal spacing at low frequencies, where it is actually irregular.','Ignoring the Schroeder frequency dividing modal and diffuse regions.','Confusing modal spacing with modal bandwidth.']::text[],ARRAY['Assessing low-frequency evenness in a room design.','Locating problem modes below the Schroeder frequency.','Deciding where statistical acoustics begins to apply.']::text[],'advanced','f_S ≈ 2000·√(T/V)','The Schroeder frequency, marking the upper end of wide modal spacing, is about two thousand times the square root of reverberation time divided by room volume.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal spacing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2bc2bf0c-2ea6-46d9-a633-dceb6c734f0b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2bc2bf0c-2ea6-46d9-a633-dceb6c734f0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2bc2bf0c-2ea6-46d9-a633-dceb6c734f0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32263c0e-a7ce-4b52-99d1-0c4f01bde80c','Mode conversion','Mode conversion is the transformation of one type of elastic wave into another at a boundary or discontinuity, such as a longitudinal wave partly becoming a shear wave upon oblique reflection or refraction. It arises because the boundary conditions couple different wave polarisations.','An elastic wave can change type at a boundary. A pressure wave may turn partly into a shear wave. This happens at angled reflections in solids. The boundary links the wave types. This change is mode conversion.','It explains extra wave arrivals and energy sharing at interfaces, which both aid and complicate ultrasonic testing and seismic interpretation.','An inspector sending an angled longitudinal wave into steel generates a refracted shear wave by mode conversion, and uses that shear wave for angle-beam flaw detection.','Elastic Waves',ARRAY['Lamb wave','Love wave','Leaky wave','Intensity reflection coefficient','Mode coupling']::text[],ARRAY['Assuming a wave keeps its type at every boundary.','Ignoring converted arrivals when interpreting ultrasonic signals.','Expecting mode conversion at normal incidence, where it is absent for isotropic solids.']::text[],ARRAY['Angle-beam ultrasonic inspection of welds.','Interpreting seismic reflections in layered media.','Explaining unexpected echoes in a solid.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode conversion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32263c0e-a7ce-4b52-99d1-0c4f01bde80c','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32263c0e-a7ce-4b52-99d1-0c4f01bde80c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32263c0e-a7ce-4b52-99d1-0c4f01bde80c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d175f7b-85cf-4f0a-b52b-98e0622fb31e','Mode coupling','Mode coupling is the exchange of energy between distinct modes of a system caused by an interaction that links them, such as a shared boundary, imperfection, or nonlinearity. Coupled modes no longer vibrate independently, so energy fed into one can appear in another.','Ideally, each mode vibrates on its own. Sometimes a link ties two modes together. Then energy passes between them. A flaw, boundary, or nonlinear effect can cause this. The modes share their vibration.','It explains why real systems do not behave as sets of independent resonators, affecting instrument tone, structural response, and waveguide performance.','A technician analysing a guitar body finds that two nearby modes couple through the bridge, so exciting one plate mode also drives the other, spreading the radiated energy.','Vibration Behaviour',ARRAY['Mode shape','Modal behavior','Internal resonance','Natural frequency','Mode conversion']::text[],ARRAY['Assuming modes are always independent and orthogonal in a real structure.','Confusing mode coupling with mode conversion between wave types.','Overlooking coupling introduced by damping or boundaries.']::text[],ARRAY['Analysing coupled plate modes in an instrument.','Studying energy transfer in a mechanical structure.','Explaining beating between two close resonances.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode coupling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d175f7b-85cf-4f0a-b52b-98e0622fb31e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d175f7b-85cf-4f0a-b52b-98e0622fb31e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d175f7b-85cf-4f0a-b52b-98e0622fb31e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd50d53dd-3623-4b00-9cb5-63214ca9ecf7','Mode shape','A mode shape is the spatial pattern of displacement or pressure associated with a single natural mode of a vibrating system, showing where the amplitude is greatest and where nodes of zero amplitude lie. Each mode shape is paired with its own natural frequency.','Each natural mode has a fixed pattern of motion. The mode shape shows that pattern in space. It marks the loud areas and the still nodes. Every mode shape goes with one natural frequency.','Mode shapes reveal where a structure or air volume moves most, guiding where to drive, damp, or sense a given mode.','A technician sprinkles particles on a vibrating plate to reveal a mode shape''s nodal lines, then places damping at the antinodes where motion is greatest to control that mode.','Vibration Behaviour',ARRAY['Mode coupling','Modal behavior','Natural frequency','Modal spacing','Internal resonance']::text[],ARRAY['Confusing a mode shape (spatial pattern) with a mode''s frequency.','Assuming nodes are dead everywhere, when they are still only for that mode.','Expecting one shape to describe all frequencies.']::text[],ARRAY['Mapping nodal lines on a vibrating plate.','Deciding where to place sensors or dampers for a mode.','Interpreting a modal analysis of a structure.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode shape');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd50d53dd-3623-4b00-9cb5-63214ca9ecf7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d50d53dd-3623-4b00-9cb5-63214ca9ecf7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d50d53dd-3623-4b00-9cb5-63214ca9ecf7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bbf4f62e-962b-4d35-b04f-3668d6c346b7','Molecular relaxation','Molecular relaxation is a sound-absorption mechanism in gases in which acoustic energy is temporarily stored in the internal vibrational states of molecules and returned with a time delay. In air this vibrational relaxation of oxygen and nitrogen, strongly dependent on humidity, dominates atmospheric absorption at higher audio frequencies.','Air molecules can store a little sound energy inside them. They release it slightly later, out of step. This lag removes energy from the wave. Oxygen and nitrogen do this in air. Humidity strongly changes the effect.','It explains why high frequencies fade faster over distance outdoors and underlies standardised calculations of atmospheric sound absorption.','A technician predicting long-throw system loss uses ISO 9613-1 to add molecular-relaxation absorption, which cuts high frequencies far more than lows over hundreds of metres, and varies with temperature and humidity.','Sound Propagation',ARRAY['Linear acoustics','Kinetic energy density','Intensity reflection coefficient','Homogeneous wave equation']::text[],ARRAY['Ignoring humidity, which strongly changes atmospheric absorption.','Assuming absorption is uniform across frequency rather than rising with it.','Confusing molecular relaxation loss with simple geometric spreading.']::text[],ARRAY['Predicting high-frequency loss over long distances outdoors.','Applying ISO 9613-1 atmospheric absorption in system design.','Explaining why distant sound sounds dull.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Molecular relaxation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bbf4f62e-962b-4d35-b04f-3668d6c346b7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bbf4f62e-962b-4d35-b04f-3668d6c346b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bbf4f62e-962b-4d35-b04f-3668d6c346b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db44a921-37a2-414b-8fcf-70a4fa5bf93e','Monaural hearing','Monaural hearing is hearing that uses input from a single ear, in contrast to binaural hearing which combines both ears. It lacks the interaural time and level differences that support accurate horizontal localisation, though spectral cues still give limited directional information.','Monaural hearing uses just one ear. It misses the comparison between two ears. That comparison normally helps locate sounds left or right. So placing sounds is harder with one ear. Some cues from the ear''s shape still help.','The concept clarifies what is lost without two-ear comparison, informing hearing assessment, mixing choices, and single-microphone monaural recording.','A technician checking a mono mix or a single-earpiece feed evaluates monaural cues, remembering that left-right localisation relies on binaural differences that a single ear cannot provide.','Psychoacoustics',ARRAY['Infrasonics','Loudspeaker spacing and interference','Microphone spacing and phase interaction']::text[],ARRAY['Assuming one ear can localise horizontally as well as two.','Confusing monaural (one ear) with monophonic (single-channel) audio.','Ignoring the spectral cues that still aid monaural direction sense.']::text[],ARRAY['Evaluating a single-earpiece communication feed.','Discussing localisation loss with single-sided hearing.','Comparing mono and stereo listening cues.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Monaural hearing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db44a921-37a2-414b-8fcf-70a4fa5bf93e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db44a921-37a2-414b-8fcf-70a4fa5bf93e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db44a921-37a2-414b-8fcf-70a4fa5bf93e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd209dc01-6e1c-4648-8317-a94e1626411a','Natural frequency','A natural frequency is a frequency at which a system tends to oscillate freely after an initial disturbance, in the absence of continuous forcing or damping. For a simple mass-spring system it is set by the ratio of stiffness to mass.','Every springy object has favourite frequencies to vibrate at. A natural frequency is one of these. Give it a push and it rings there. More stiffness raises it. More mass lowers it.','It predicts where a system resonates, which matters for instrument tuning, loudspeaker design, and avoiding unwanted structural resonances.','For a mass of 0.25 kg on a spring of stiffness 1000 N/m, the natural frequency is f = (1/2π)·√(k/m) = (1/2π)·√(1000/0.25) ≈ 10.1 Hz.','Vibration Behaviour',ARRAY['Mode shape','Modal behavior','Mass-controlled region','Lumped-element approximation','Internal resonance']::text[],ARRAY['Confusing natural frequency with the forced (driving) frequency.','Forgetting that damping slightly lowers the damped natural frequency.','Assuming a complex system has only one natural frequency.']::text[],ARRAY['Predicting a loudspeaker''s free-air resonance.','Tuning a resonant structure or instrument.','Avoiding a structural resonance near an excitation frequency.']::text[],'intermediate','f_n = (1/2π)·√(k/m)','The natural frequency equals one over two pi times the square root of the stiffness divided by the mass.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Natural frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd209dc01-6e1c-4648-8317-a94e1626411a','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d209dc01-6e1c-4648-8317-a94e1626411a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d209dc01-6e1c-4648-8317-a94e1626411a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fafc55a2-3b60-4def-b3e7-52855d741272','Near-field approximation','The near-field approximation describes the sound field close to a source, where reactive energy and complex interference dominate and the simple inverse-distance level decay of the far field does not yet hold. In this region pressure and particle velocity are not in phase and the pattern varies rapidly with position.','Close to a source the sound field is messy. Pressure and air motion fall out of step here. Level does not drop by a clean rule with distance. Small position changes alter it a lot. This is the near field.','It warns where far-field assumptions fail, which matters for microphone placement, source measurement, and interpreting level-versus-distance behaviour.','A technician measuring a loudspeaker''s response steps back into the far field, beyond the near-field region, because near the source the response varies sharply and does not follow the inverse-square level drop.','Sound Propagation',ARRAY['Kinetic energy density','Lumped-element approximation','Loudspeaker spacing and interference','Instantaneous sound pressure']::text[],ARRAY['Applying the far-field inverse-square rule too close to a source.','Assuming pressure and particle velocity stay in phase near a source.','Measuring a source''s response inside its near field.']::text[],ARRAY['Choosing a measurement distance for a loudspeaker.','Explaining why close-mic level does not follow inverse-square.','Interpreting rapid response changes near a source.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field approximation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fafc55a2-3b60-4def-b3e7-52855d741272','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fafc55a2-3b60-4def-b3e7-52855d741272') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fafc55a2-3b60-4def-b3e7-52855d741272');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd396d65-695c-43c6-9ab0-854e1497ee46','Nitrogen relaxation','Nitrogen relaxation is the vibrational relaxation of nitrogen molecules in air, in which acoustic compression briefly stores energy in molecular vibration and releases it out of phase, absorbing sound. Its characteristic nitrogen relaxation frequency f_rN, defined in ISO 9613-1, is strongly humidity-dependent and governs atmospheric absorption in the low-frequency range.','Air is mostly nitrogen. Sound waves squeeze these molecules and make them vibrate. That vibration lags behind the wave. The lag turns sound energy into heat. This effect is strongest at low frequencies. It changes a lot with humidity.','It explains part of how the atmosphere soaks up sound energy, especially at lower frequencies, and is a term in outdoor sound-absorption models.','Predicting outdoor low-frequency loss with ISO 9613-1: at reference pressure, 20 C, and 1% water-vapour molar concentration, f_rN is about 9 + 280*1 = 289 Hz, so absorption peaks near that region.','Atmospheric Absorption',ARRAY['Oxygen relaxation','Propagation loss','Physical acoustics','Relationship among frequency, wavelength, and sound speed']::text[],ARRAY['Assuming air absorption depends only on distance, not on humidity and temperature.','Confusing nitrogen relaxation, which dominates low frequencies, with oxygen relaxation at higher frequencies.','Treating the relaxation frequency as fixed instead of humidity-dependent.']::text[],ARRAY['Modeling long-range low-frequency propagation for an outdoor concert.','Estimating environmental noise from a distant industrial source.','Correcting outdoor measurements for atmospheric absorption.']::text[],'advanced','f_rN = (p_a/p_r)*(T/T_0)^(-1/2)*(9 + 280*h*exp(-4.170*[(T/T_0)^(-1/3) - 1]))','The nitrogen relaxation frequency scales with air pressure and temperature and rises with the molar water-vapour concentration h.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nitrogen relaxation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd396d65-695c-43c6-9ab0-854e1497ee46','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd396d65-695c-43c6-9ab0-854e1497ee46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd396d65-695c-43c6-9ab0-854e1497ee46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8acf04fa-481f-4ced-8524-7c55ab70d5b6','Nodal plane','A nodal plane is a flat surface within a vibrating medium or standing-wave field on which the acoustic variable (typically pressure or particle displacement) stays at zero, or minimum, amplitude at all times. It is the two-dimensional analogue of a node in a one-dimensional standing wave.','In a standing wave, some spots never move. A line of such spots forms a nodal line. A whole flat surface of them is a nodal plane. There, the sound quantity stays near zero.','It marks where a standing-wave field has no motion or no pressure change, helping identify mode shapes in rooms, plates, and enclosures.','Mapping a room mode: a technician finds a low-frequency pressure minimum along a plane midway between two walls, then avoids placing a measurement microphone there.','Standing Waves',ARRAY['Nodal line','Standing wave','Resonant frequency','Quarter-wave resonance']::text[],ARRAY['Confusing a pressure nodal plane with a velocity nodal plane; they sit a quarter-wavelength apart.','Assuming a node means zero energy, when energy is simply stored elsewhere in the field.','Expecting nodal planes only in one dimension rather than across surfaces.']::text[],ARRAY['Locating pressure minima when analyzing room modes.','Studying vibration patterns of a loudspeaker cone or panel.','Positioning microphones to avoid or capture standing-wave nulls.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nodal plane');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8acf04fa-481f-4ced-8524-7c55ab70d5b6','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8acf04fa-481f-4ced-8524-7c55ab70d5b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8acf04fa-481f-4ced-8524-7c55ab70d5b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a25530b-f5ed-46b3-bcf0-44e44c18cd39','Normal-incidence absorption','Normal-incidence absorption is the fraction of incident sound power absorbed by a surface when a plane wave strikes it perpendicularly (at 0 degrees). The normal-incidence absorption coefficient equals one minus the squared magnitude of the pressure reflection coefficient, and is measured in an impedance (Kundt) tube per ISO 10534.','Send a sound wave straight at a surface. Some sound bounces back. The rest is absorbed. Normal-incidence absorption is that absorbed share. It is measured with a straight tube test.','It quantifies how well a material absorbs sound arriving head-on, giving a repeatable lab value for comparing absorbers.','Impedance-tube test: if the measured pressure reflection coefficient magnitude is 0.5, the normal-incidence absorption coefficient is 1 - 0.5^2 = 0.75.','Sound Absorption',ARRAY['Random-incidence absorption','Normal-incidence impedance','Pressure reflection coefficient','Reference sound pressure']::text[],ARRAY['Confusing normal-incidence absorption with the higher random-incidence (Sabine) value.','Assuming a tube value predicts real-room performance without angle correction.','Forgetting that the coefficient is power-based, so it uses the squared reflection magnitude.']::text[],ARRAY['Comparing acoustic foams in an impedance-tube test.','Validating a porous absorber design at specific frequencies.','Deriving surface impedance from a tube measurement.']::text[],'intermediate','alpha_0 = 1 - |R|^2','Normal-incidence absorption equals one minus the squared magnitude of the pressure reflection coefficient.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Normal-incidence absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a25530b-f5ed-46b3-bcf0-44e44c18cd39','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a25530b-f5ed-46b3-bcf0-44e44c18cd39') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a25530b-f5ed-46b3-bcf0-44e44c18cd39');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4cee698-b895-4611-a4c3-b1daba1f3ce7','Normal-incidence impedance','Normal-incidence specific acoustic impedance is the complex ratio of sound pressure to normal particle velocity at a surface when a plane wave arrives perpendicularly. It characterizes the surface''s acoustic response and links directly to its reflection coefficient and absorption.','At a surface, sound has pressure and motion. Their ratio is the surface impedance. Measured for a straight-on wave, it is the normal-incidence impedance. It tells how the surface reacts to sound.','It fully describes how a surface reflects and absorbs a perpendicular wave, and is the quantity extracted from impedance-tube tests.','From tube data: with surface impedance Zs and air impedance Z0, the reflection coefficient is R = (Zs - Z0)/(Zs + Z0); if Zs = 3*Z0, then R = 2/4 = 0.5.','Acoustic Impedance',ARRAY['Normal-incidence absorption','Pressure reflection coefficient','Radiation boundary condition','Propagation constant']::text[],ARRAY['Dropping the imaginary part and treating impedance as purely real.','Confusing specific acoustic impedance with the characteristic impedance of air.','Assuming normal-incidence impedance predicts oblique-incidence behavior directly.']::text[],ARRAY['Extracting material impedance from an impedance-tube measurement.','Feeding surface impedance into a room-acoustics simulation.','Designing a matched absorber for perpendicular incidence.']::text[],'advanced','Z_s = p/u_n ;  R = (Z_s - Z_0)/(Z_s + Z_0)','Normal-incidence surface impedance is pressure divided by normal particle velocity; the reflection coefficient follows from it and the air impedance.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Normal-incidence impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4cee698-b895-4611-a4c3-b1daba1f3ce7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4cee698-b895-4611-a4c3-b1daba1f3ce7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4cee698-b895-4611-a4c3-b1daba1f3ce7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8d98c90-dc16-4b7e-a69f-b2902353a755','Object size relative to wavelength','Object size relative to wavelength is the ratio of an obstacle''s characteristic dimension to the acoustic wavelength, often expressed as ka = 2*pi*a/lambda. It governs whether sound reflects, scatters, or diffracts around the object: large objects (ka >> 1) reflect and shadow, while small objects (ka << 1) let sound diffract around them.','How sound meets an object depends on size. Compare the object to the wavelength. If the object is much bigger, sound bounces and casts a shadow. If it is much smaller, sound bends around it.','It predicts the acoustic regime, reflection, scattering, or diffraction, so technicians know whether an object blocks or is bypassed by sound.','A 0.1 m object at 100 Hz (wavelength 3.43 m) has ka = 2*pi*0.05/3.43 = 0.09, so bass diffracts around it; at 10 kHz (wavelength 0.034 m) ka is about 9, so highs reflect and shadow.','Diffraction & Scattering',ARRAY['Diffraction','Rayleigh wave','Paraxial approximation','Ray acoustics']::text[],ARRAY['Assuming a barrier blocks all frequencies equally, ignoring bass diffraction.','Forgetting that the same object behaves differently across the audio band.','Mixing up radius and diameter when computing ka.']::text[],ARRAY['Predicting whether a noise barrier stops low-frequency traffic noise.','Judging how a microphone body shadows high frequencies.','Deciding if a small diffuser scatters or is bypassed by long wavelengths.']::text[],'intermediate','ka = 2*pi*a/lambda','The size parameter is the wavenumber times the object radius, equal to two pi times the radius divided by the wavelength.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Object size relative to wavelength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8d98c90-dc16-4b7e-a69f-b2902353a755','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8d98c90-dc16-4b7e-a69f-b2902353a755') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8d98c90-dc16-4b7e-a69f-b2902353a755');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b77c8d79-5179-4f75-8c65-d29247129538','Orbital angular momentum of sound','Orbital angular momentum (OAM) of sound is angular momentum carried by an acoustic vortex whose wavefront spirals helically around a central axis, with a pressure phase that varies as exp(i*m*phi). The integer m is the topological charge; on the axis the phases cancel, giving a phase singularity and zero pressure amplitude there.','Some sound beams twist like a corkscrew. The wavefront spirals around a center line. This spin of the wave carries orbital angular momentum. Right on the center line, the pressure drops to zero.','It provides an extra property of sound beyond pressure and frequency, useful for contactless particle manipulation and for encoding multiple channels of information.','A first-order vortex (m = 1) completes one full 2*pi phase turn around the axis per wavelength; doubling to m = 2 doubles the twist and the carried orbital angular momentum.','Wave Physics',ARRAY['Phase singularity','Nodal plane','Physical acoustics','Propagation constant']::text[],ARRAY['Confusing orbital angular momentum (spiral wavefront) with spin angular momentum (local circular motion).','Expecting pressure at the beam center, where the phase singularity forces zero amplitude.','Assuming the topological charge can be non-integer for a stable single vortex.']::text[],ARRAY['Contactless rotation or trapping of small objects with an acoustic vortex.','Encoding data on twisted sound beams for multiplexed communication.','Studying helical wavefields generated by phased transducer arrays.']::text[],'advanced','p(r,phi,z) ∝ exp(i*m*phi)','An acoustic vortex has a pressure phase that advances as the topological charge times the azimuthal angle, giving m full turns around the axis.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Orbital angular momentum of sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b77c8d79-5179-4f75-8c65-d29247129538','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b77c8d79-5179-4f75-8c65-d29247129538') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b77c8d79-5179-4f75-8c65-d29247129538');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2f5def9-ec65-4cf6-b372-2d266e3e1ff1','Overtone','An overtone is any resonant frequency of a vibrating system above its fundamental (lowest) frequency. In a harmonic system the first overtone is the second harmonic, so overtone numbering is offset by one from harmonic numbering.','A note is not one pure tone. It has a lowest pitch, the fundamental. Above it sit extra tones. These higher tones are overtones. They shape the sound''s color, or timbre.','Overtones give an instrument or voice its characteristic timbre and are central to how we distinguish sound sources at the same pitch.','For a string tuned to 100 Hz, the first overtone is the second harmonic at 200 Hz, the second overtone is 300 Hz, and so on.','Harmonics & Timbre',ARRAY['Harmonics','Resonant frequency','Quarter-wave resonance','Standing wave']::text[],ARRAY['Assuming the first overtone equals the first harmonic; the first overtone is the second harmonic.','Believing all overtones are exact integer multiples; real instruments can be inharmonic.','Confusing overtone content (timbre) with loudness.']::text[],ARRAY['Explaining why a violin and flute at the same pitch sound different.','Tuning an instrument by listening to overtone beating.','Analyzing a spectrum to identify an instrument''s harmonic series.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Overtone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2f5def9-ec65-4cf6-b372-2d266e3e1ff1','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2f5def9-ec65-4cf6-b372-2d266e3e1ff1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2f5def9-ec65-4cf6-b372-2d266e3e1ff1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab1f9954-beec-4b39-a2a4-251278109068','Oxygen relaxation','Oxygen relaxation is the vibrational relaxation of oxygen molecules in air that absorbs acoustic energy, characterized by the oxygen relaxation frequency f_rO defined in ISO 9613-1. It dominates atmospheric absorption at higher audio and ultrasonic frequencies and depends strongly on humidity.','Air contains oxygen molecules. Sound makes them vibrate and store energy. That energy comes back out of step with the wave. So sound is absorbed. This effect is strongest at high frequencies.','It explains much of the high-frequency loss of sound in air and is a key term in outdoor sound-absorption calculations.','By ISO 9613-1, at reference pressure and 1% water-vapour molar concentration, f_rO is about 24 + 4.04e4*(0.02+1)/(0.391+1) = ~29.6 kHz, so oxygen absorption peaks in the ultrasonic region there.','Atmospheric Absorption',ARRAY['Nitrogen relaxation','Propagation loss','Physical acoustics','Relationship among frequency, wavelength, and sound speed']::text[],ARRAY['Confusing oxygen relaxation (high frequencies) with nitrogen relaxation (low frequencies).','Assuming dry air absorbs the same as humid air; the relaxation frequency shifts with humidity.','Ignoring temperature and pressure scaling of the relaxation frequency.']::text[],ARRAY['Predicting high-frequency air loss over long outdoor distances.','Correcting ultrasonic measurements for atmospheric absorption.','Modeling treble roll-off at a large open-air venue.']::text[],'advanced','f_rO = (p_a/p_r)*(24 + 4.04e4*h*(0.02 + h)/(0.391 + h))','The oxygen relaxation frequency scales with air pressure and increases with the molar water-vapour concentration h.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oxygen relaxation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab1f9954-beec-4b39-a2a4-251278109068','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab1f9954-beec-4b39-a2a4-251278109068') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab1f9954-beec-4b39-a2a4-251278109068');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ad63824-827a-40a4-ae07-a571156a25f9','Paraxial approximation','The paraxial approximation treats sound as propagating in a narrow cone close to a principal axis, so that angles are small and sin(theta) approx theta, cos(theta) approx 1. It reduces the full wave equation to the simpler parabolic (one-way) equation used for beam propagation.','Imagine a sound beam aimed straight ahead. Its rays stay near the center line. Their angles are small. This lets us simplify the math. Curved wave paths become easier to compute.','It simplifies beam and wave modeling for narrow, forward-directed sound, trading exactness for a tractable parabolic equation.','For a beam within 5 degrees (0.087 rad) of axis, sin(0.087) = 0.0872 and cos(0.087) = 0.996, so replacing them with theta and 1 introduces well under 1% error.','Wave Modeling',ARRAY['Ray acoustics','Propagation constant','Object size relative to wavelength','Radiating near field']::text[],ARRAY['Applying it to wide-angle or strongly diverging fields where small-angle assumptions fail.','Forgetting it is a one-way model that neglects backscatter.','Assuming it is exact rather than a small-angle approximation.']::text[],ARRAY['Modeling a focused ultrasound beam near its axis.','Simulating long-range sound channels with a parabolic-equation solver.','Approximating a directional loudspeaker''s forward beam.']::text[],'advanced','sin(theta) ≈ theta,  cos(theta) ≈ 1  (theta << 1)','For small angles from the axis, the sine of the angle is approximately the angle itself and the cosine is approximately one.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Paraxial approximation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ad63824-827a-40a4-ae07-a571156a25f9','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ad63824-827a-40a4-ae07-a571156a25f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ad63824-827a-40a4-ae07-a571156a25f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a39be261-3df1-4d80-b54a-abd584d77f09','Peak particle velocity','Peak particle velocity is the maximum instantaneous speed of the medium''s particles as they oscillate about their rest position in a sound field. For a sinusoidal signal it equals the square root of two times the root-mean-square particle velocity, and for a plane progressive wave it relates to pressure by u = p/(rho*c).','Sound makes air particles vibrate back and forth. Their speed changes over each cycle. The highest speed reached is the peak particle velocity. It is not the same as the speed of sound.','It quantifies how fast the medium actually moves, distinct from wave speed, and links pressure to motion in a sound field.','In a plane wave in air (rho*c approx 415 Pa*s/m), a peak pressure of 1 Pa gives peak particle velocity u = 1/415 = 2.4 mm/s.','Acoustic Field Quantity',ARRAY['Potential energy density','Radiation pressure','Normal-incidence impedance','RMS SPL']::text[],ARRAY['Confusing particle velocity with the speed of sound; particles barely move.','Mixing peak and RMS values when reporting particle velocity.','Applying the plane-wave relation u = p/(rho*c) in the near field where it fails.']::text[],ARRAY['Assessing diaphragm or medium motion near a high-output source.','Relating measured pressure to particle velocity in a plane wave.','Characterizing intense fields for nonlinear or safety analysis.']::text[],'intermediate','u_peak = sqrt(2)*u_rms ;  u = p/(rho*c) (plane wave)','Peak particle velocity is root two times the RMS particle velocity; in a plane wave particle velocity equals pressure divided by the characteristic impedance.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak particle velocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a39be261-3df1-4d80-b54a-abd584d77f09','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a39be261-3df1-4d80-b54a-abd584d77f09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a39be261-3df1-4d80-b54a-abd584d77f09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '603d3fdc-94e9-4ce1-948a-3224c84d459d','Phase singularity','A phase singularity is a point or line in a wave field where the amplitude is exactly zero and the phase is therefore undefined, with phase circulating by an integer multiple of 2*pi around it. In acoustics these singularities form the dark cores of vortex beams and the intersections of nodal surfaces.','In a wave, phase tells you where you are in the cycle. But where the amplitude hits zero, phase has no value. That spot is a phase singularity. Around it, phase wraps a full turn.','It identifies the zero-amplitude cores in complex sound fields and underlies the structure of acoustic vortices and dislocations.','Circling a first-order vortex core once, the phase accumulates exactly 2*pi (topological charge m = 1); the pressure amplitude at the core is zero.','Wave Physics',ARRAY['Orbital angular momentum of sound','Nodal plane','Physical acoustics','Propagation constant']::text[],ARRAY['Assuming phase is always defined; at a zero-amplitude point it is not.','Confusing a phase singularity (a point/line null) with a broad pressure minimum.','Expecting non-integer phase circulation around a stable singularity.']::text[],ARRAY['Locating the dark core of an acoustic vortex beam.','Analyzing interference fields with wavefront dislocations.','Designing metasurfaces that generate twisted sound.']::text[],'advanced','∮ grad(phase)·dl = 2*pi*m','Integrating the phase gradient once around a singularity gives two pi times an integer, the topological charge.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase singularity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '603d3fdc-94e9-4ce1-948a-3224c84d459d','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='603d3fdc-94e9-4ce1-948a-3224c84d459d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='603d3fdc-94e9-4ce1-948a-3224c84d459d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e02e5106-6add-4714-8cb2-0f9b2ff38261','Physical acoustics','Physical acoustics is the branch of acoustics concerned with the fundamental physics of sound and vibration in matter, including wave propagation, absorption, scattering, nonlinear effects, and the interaction of sound with the structure of gases, liquids, and solids. It underpins applied fields such as room, underwater, and ultrasonic acoustics.','Physical acoustics studies how sound really works. It covers how waves travel, fade, and bend. It also covers how sound interacts with materials. It is the science base for all applied acoustics.','It provides the theoretical foundation, wave physics and material interaction, on which practical acoustic engineering is built.','A technician draws on physical acoustics to understand why a material absorbs highs but not lows, or why sound bends over a hill on a cool night.','Acoustics Discipline',ARRAY['Ray acoustics','Propagation constant','Radiation pressure','Object size relative to wavelength']::text[],ARRAY['Treating physical acoustics as only theory with no practical relevance.','Confusing it with psychoacoustics, which studies perception.','Assuming it covers only audible sound, not ultrasound or infrasound.']::text[],ARRAY['Explaining the science behind a material''s absorption behavior.','Grounding an ultrasonic or underwater application in wave theory.','Relating measured propagation effects to underlying physics.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Physical acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e02e5106-6add-4714-8cb2-0f9b2ff38261','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e02e5106-6add-4714-8cb2-0f9b2ff38261') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e02e5106-6add-4714-8cb2-0f9b2ff38261');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b538e60f-a42f-4e93-8f7f-0420cf79cf07','Potential energy density','Acoustic potential energy density is the energy stored per unit volume in the compression of the medium by a sound field, equal to p^2/(2*rho*c^2) for the instantaneous pressure. It is the compressional counterpart of kinetic energy density, and their sum gives the total acoustic energy density.','A sound wave squeezes the air. That squeeze stores energy, like a spring. Potential energy density is that stored energy per unit volume. It depends on the pressure. Motion stores the other half.','It quantifies the energy held in compression of the medium, needed for energy-balance and intensity calculations.','In air (rho = 1.21, c = 343, so rho*c^2 approx 1.42e5 Pa) a pressure of 1 Pa gives potential energy density 1^2/(2*1.42e5) = 3.5e-6 J/m^3.','Acoustic Energy',ARRAY['Peak particle velocity','Radiation pressure','Reference sound pressure','Propagation loss']::text[],ARRAY['Forgetting the factor of two, or the rho*c^2 in the denominator.','Confusing energy density (per volume) with intensity (per area per time).','Assuming potential and kinetic densities are equal at every instant; only their averages match in a plane wave.']::text[],ARRAY['Computing total acoustic energy in a reverberant room.','Relating pressure to stored energy in energy-balance models.','Deriving sound intensity from field quantities.']::text[],'advanced','w_pot = p^2/(2*rho*c^2)','Acoustic potential energy density equals the instantaneous pressure squared divided by twice the density times the sound speed squared.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Potential energy density');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b538e60f-a42f-4e93-8f7f-0420cf79cf07','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b538e60f-a42f-4e93-8f7f-0420cf79cf07') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b538e60f-a42f-4e93-8f7f-0420cf79cf07');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9297016-263c-4723-9638-451ea52da037','Pressure reflection coefficient','The pressure reflection coefficient is the complex ratio of the reflected sound-pressure amplitude to the incident sound-pressure amplitude at a boundary. For normal incidence between media it equals (Z2 - Z1)/(Z2 + Z1), where Z is characteristic impedance; its magnitude and phase set how much sound is returned and with what phase shift.','Sound hits a boundary and part bounces back. The pressure reflection coefficient compares the reflected pressure to the incoming pressure. It depends on the impedance change. A big impedance jump reflects more sound.','It measures how strongly a boundary reflects sound, and connects impedance mismatch to reflection and absorption.','At an air-to-water boundary (Z_air approx 415, Z_water approx 1.48e6 Pa*s/m), R = (1.48e6 - 415)/(1.48e6 + 415) approx 0.9994, so almost all sound reflects.','Reflection',ARRAY['Normal-incidence impedance','Normal-incidence absorption','Radiation boundary condition','Propagation constant']::text[],ARRAY['Ignoring the phase of R and using only its magnitude.','Confusing the pressure reflection coefficient with the power (intensity) reflection coefficient, its squared magnitude.','Swapping the order of the impedances, which flips the sign.']::text[],ARRAY['Predicting reflection at a boundary between two materials.','Deriving absorption from measured reflection in an impedance tube.','Analyzing why sound barely crosses the air-water interface.']::text[],'intermediate','R = (Z_2 - Z_1)/(Z_2 + Z_1)','The pressure reflection coefficient at normal incidence is the difference of the two characteristic impedances divided by their sum.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure reflection coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9297016-263c-4723-9638-451ea52da037','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9297016-263c-4723-9638-451ea52da037') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9297016-263c-4723-9638-451ea52da037');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e05ecc8-3c1d-4c2c-a7f4-a4edd8bde04b','Pressure turbulence','Pressure turbulence refers to random, fluctuating pressure fields produced by turbulent flow, such as wind or air moving over a microphone, which are not radiating sound but can contaminate acoustic measurements. These near-field, convected pressure fluctuations are distinct from propagating acoustic pressure.','Moving air is often messy and swirling. This creates random pressure changes. That is pressure turbulence. It is not true sound, but a microphone still hears it. Wind noise is a common example.','It names the non-acoustic, flow-driven pressure noise that corrupts measurements, so it can be recognized and reduced.','Using a windscreen or foam on an outdoor microphone reduces turbulent pressure fluctuations that would otherwise swamp low-frequency readings.','Measurement Noise',ARRAY['Propagation loss','Reference sound pressure','RMS SPL','Physical acoustics']::text[],ARRAY['Mistaking wind-induced pressure fluctuations for real low-frequency sound.','Assuming a windscreen removes all turbulent noise rather than reducing it.','Confusing convected, non-radiating pressure with propagating acoustic pressure.']::text[],ARRAY['Diagnosing wind noise on an outdoor recording.','Choosing windscreens for environmental noise measurements.','Separating flow noise from true source levels in flow-duct testing.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure turbulence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e05ecc8-3c1d-4c2c-a7f4-a4edd8bde04b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e05ecc8-3c1d-4c2c-a7f4-a4edd8bde04b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e05ecc8-3c1d-4c2c-a7f4-a4edd8bde04b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '079ef798-b8e8-4fa4-9479-9db7afb00530','Propagation constant','The propagation constant is a complex quantity, gamma = alpha + j*beta, describing how a harmonic wave changes as it travels: its real part alpha is the attenuation constant (amplitude decay per unit length) and its imaginary part beta is the phase constant (phase change per unit length, equal to the wavenumber k = omega/c in a lossless medium).','As a wave travels, two things happen. It loses amplitude, and its phase advances. The propagation constant captures both in one number. Its real part is loss. Its imaginary part is phase change.','It compactly describes both attenuation and phase progression of a traveling wave, essential for modeling ducts, transmission lines, and lossy media.','In a lossless medium at 1 kHz with c = 343 m/s, alpha = 0 and beta = k = 2*pi*1000/343 = 18.3 rad/m, so gamma = j*18.3 per metre.','Wave Propagation',ARRAY['Propagation loss','Relationship among frequency, wavelength, and sound speed','Normal-incidence impedance','Paraxial approximation']::text[],ARRAY['Confusing the attenuation constant (real part) with the phase constant (imaginary part).','Assuming the propagation constant is purely imaginary even in lossy media.','Mixing up angular frequency and ordinary frequency when computing beta.']::text[],ARRAY['Modeling attenuation and phase in a lined duct.','Characterizing wave travel through a lossy porous material.','Relating wavenumber to frequency in propagation calculations.']::text[],'advanced','gamma = alpha + j*beta,  beta = k = omega/c','The propagation constant is the attenuation constant plus j times the phase constant, where the phase constant equals the wavenumber, angular frequency over sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Propagation constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '079ef798-b8e8-4fa4-9479-9db7afb00530','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='079ef798-b8e8-4fa4-9479-9db7afb00530') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='079ef798-b8e8-4fa4-9479-9db7afb00530');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7063b60c-b56c-4630-995f-d038e1c5769e','Propagation loss','Propagation loss (transmission loss in propagation) is the total reduction in sound level between a reference point near the source and a distant point, combining geometric spreading, atmospheric or medium absorption, and boundary and refraction effects. It is usually expressed in decibels.','Sound gets quieter as it travels. Part is simple spreading out. Part is the medium soaking up energy. Together these give the propagation loss. It is measured in decibels.','It quantifies how much weaker sound becomes over distance, combining spreading and absorption for range and coverage predictions.','For free-field spreading, doubling distance from a point source loses 6 dB; adding, say, 2 dB of air absorption over that span gives about 8 dB total propagation loss.','Attenuation',ARRAY['Propagation constant','Oxygen relaxation','Nitrogen relaxation','Relationship among frequency, wavelength, and sound speed']::text[],ARRAY['Assuming only spreading matters and ignoring atmospheric absorption at high frequencies.','Applying the 6 dB per distance-doubling rule to line sources, which spread differently.','Neglecting ground and refraction effects outdoors.']::text[],ARRAY['Predicting SPL at an audience far from the stage.','Estimating environmental noise levels at a distant receiver.','Setting up delay towers to compensate for distance loss.']::text[],'intermediate','PL = 20*log10(r/r_0) + a*r (spreading + absorption)','Propagation loss is twenty times the log of the distance ratio for spherical spreading, plus the absorption coefficient times distance.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Propagation loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7063b60c-b56c-4630-995f-d038e1c5769e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7063b60c-b56c-4630-995f-d038e1c5769e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7063b60c-b56c-4630-995f-d038e1c5769e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c5ef2e7-6588-463c-ad81-3675c521632a','Quarter-wave resonance','Quarter-wave resonance is the fundamental resonance of a tube or cavity closed at one end and open at the other, occurring when the length equals one quarter of the wavelength. The closed end forms a pressure antinode and the open end a pressure node, giving a fundamental frequency of f = c/(4L).','Think of a tube closed at one end. It rings loudest at a certain pitch. That pitch has a wavelength four times the tube length. This is quarter-wave resonance. Blowing across a test tube behaves the same way.','It sets the resonant pitch of one-end-closed pipes and is the basis of quarter-wave tubes used as tuned absorbers and resonators.','A tube 0.5 m long, closed at one end, resonates at f = 343/(4*0.5) = 171.5 Hz.','Resonance',ARRAY['Resonant frequency','Quarter-wavelength relationships','Overtone','Nodal plane']::text[],ARRAY['Using the open-open tube formula f = c/(2L) for a closed-open tube.','Forgetting the end correction, which slightly lowers the true frequency.','Assuming a closed-open tube produces all harmonics; it produces only odd ones.']::text[],ARRAY['Tuning a quarter-wave tube trap to absorb a room mode.','Predicting the resonance of a closed-end pipe or duct.','Designing a Helmholtz-like resonator element.']::text[],'intermediate','f = c/(4*L)','The quarter-wave fundamental frequency equals the sound speed divided by four times the tube length.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-wave resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c5ef2e7-6588-463c-ad81-3675c521632a','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c5ef2e7-6588-463c-ad81-3675c521632a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c5ef2e7-6588-463c-ad81-3675c521632a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4834dd37-9c34-41d8-a9e3-6ba975a66b79','Quarter-wavelength relationships','Quarter-wavelength relationships describe acoustic effects that occur when a path length or spacing equals one quarter of the wavelength, producing a 90-degree phase shift one way and 180 degrees round trip. They govern first cancellation dips from reflections, quarter-wave impedance transformers, and quarter-wave tuned absorbers.','A quarter wavelength is a key distance in acoustics. Travel it twice and the wave flips phase. This causes cancellations and tuned effects. It explains reflection dips and quarter-wave traps.','It captures why quarter-wavelength spacings cause cancellations and enable tuned impedance-matching and absorption.','A floor reflection with a path difference of a quarter wavelength at 500 Hz (wavelength 0.686 m) needs an extra path of 0.172 m, giving a first cancellation notch there.','Wavelength Effects',ARRAY['Quarter-wave resonance','Relationship among frequency, wavelength, and sound speed','Nodal plane','Pressure reflection coefficient']::text[],ARRAY['Forgetting that the phase inverts over the round trip, not the one-way path.','Assuming the effect is broadband; it is frequency-specific.','Ignoring reflection phase shifts that modify the simple quarter-wave rule.']::text[],ARRAY['Diagnosing a comb-filter notch from a floor or wall reflection.','Designing a quarter-wave absorber for a specific frequency.','Matching impedances with a quarter-wave transformer section.']::text[],'intermediate','d = lambda/4 = c/(4*f)','A quarter-wavelength distance equals the wavelength divided by four, or the sound speed divided by four times the frequency.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-wavelength relationships');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4834dd37-9c34-41d8-a9e3-6ba975a66b79','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4834dd37-9c34-41d8-a9e3-6ba975a66b79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4834dd37-9c34-41d8-a9e3-6ba975a66b79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e443f5f-8bc5-4178-92d5-06a8109ebcb0','RMS SPL','RMS SPL is the sound pressure level computed from the root-mean-square (RMS) sound pressure, expressed in decibels as 20*log10(p_rms/p_0) with the reference p_0 = 20 micropascals in air. RMS is the standard averaging used for SPL because it corresponds to the acoustic power of the signal.','Sound pressure rises and falls quickly. We need one steady number for its size. RMS gives that average. Turned into decibels, it is the RMS sound pressure level. This is the usual way SPL is stated.','It provides the standard, power-related measure of sound level, so meters and specifications report a consistent value.','An RMS pressure of 0.2 Pa gives SPL = 20*log10(0.2/20e-6) = 20*log10(10000) = 80 dB.','Sound Level',ARRAY['Reference sound pressure','Peak particle velocity','Propagation loss','Random-incidence absorption']::text[],ARRAY['Reporting peak pressure as if it were RMS, overstating the level.','Forgetting the 20 micropascal reference, which anchors the decibel scale.','UNSAFE: Assuming a moderate RMS SPL is safe while ignoring high crest-factor peaks and long exposure that can still damage hearing.']::text[],ARRAY['Reading a sound level meter set to RMS.','Comparing measured SPL against exposure limits.','Specifying an output level for a loudspeaker.']::text[],'beginner','L_p = 20*log10(p_rms/p_0),  p_0 = 20 uPa','RMS sound pressure level is twenty times the base-ten log of the RMS pressure divided by the 20-micropascal reference pressure.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RMS SPL');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e443f5f-8bc5-4178-92d5-06a8109ebcb0','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e443f5f-8bc5-4178-92d5-06a8109ebcb0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e443f5f-8bc5-4178-92d5-06a8109ebcb0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42c2ea77-bca9-48f7-8b44-c57160d54ee5','Radiating near field','The radiating near field (Fresnel region) is the zone close to a finite sound source, beyond the reactive near field, where the radiated field is still forming: pressure and particle velocity are not yet in phase and the wavefronts have not settled into simple spherical spreading. It lies between the reactive near field and the far field.','Near a sound source, the field is complicated. Waves have not settled into a clean pattern yet. Pressure and motion are out of step. This zone is the radiating near field. Farther out, it becomes the far field.','It marks the transition region where source measurements are unreliable, warning technicians to measure in the far field.','For a source of largest dimension D, the far field roughly begins beyond about D^2/lambda; inside that distance a measurement mic sits in the radiating near field and reads inconsistently.','Sound Field Region',ARRAY['Reactive near field','Radiation boundary condition','Peak particle velocity','Physical acoustics']::text[],ARRAY['Measuring source level in the near field and assuming it equals the far-field value.','Confusing the radiating near field with the reactive (evanescent) near field.','Assuming inverse-square spreading holds inside the near field.']::text[],ARRAY['Deciding how far from a loudspeaker to place a measurement microphone.','Interpreting inconsistent SPL readings close to a large source.','Planning array measurements at a proper far-field distance.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiating near field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42c2ea77-bca9-48f7-8b44-c57160d54ee5','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42c2ea77-bca9-48f7-8b44-c57160d54ee5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42c2ea77-bca9-48f7-8b44-c57160d54ee5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8665bbc-d35c-4544-ab6d-41e75c740b3b','Radiation boundary condition','The radiation (Sommerfeld) boundary condition is the physical requirement that, far from a source, acoustic energy only travels outward and no waves arrive from infinity. Mathematically, the field must behave as an outgoing wave, expressed as the limit of r*(dp/dr + j*k*p) approaching zero as r grows large.','A source sends sound outward into open space. Nothing should come back in from far away. That rule is the radiation boundary condition. It ensures only outgoing waves in the solution. It keeps physics realistic.','It selects the physically correct outgoing-wave solution and is essential for well-posed radiation and scattering problems.','In simulations, an engineer imposes this condition (or a numerical absorbing boundary that mimics it) so a modeled source radiates outward without spurious incoming reflections.','Boundary Condition',ARRAY['Radiating near field','Normal-incidence impedance','Pressure reflection coefficient','Propagation constant']::text[],ARRAY['Ignoring it and getting non-physical solutions with incoming waves.','Confusing the mathematical radiation condition with a physical absorbing material.','Assuming a truncated simulation grid satisfies it without a special boundary treatment.']::text[],ARRAY['Setting outer boundaries in a free-field radiation simulation.','Formulating a scattering problem in unbounded space.','Justifying an absorbing boundary in a numerical model.']::text[],'advanced','lim_{r->inf} r*(dp/dr + j*k*p) = 0','Far from the source, the radius times the sum of the radial pressure gradient and j times the wavenumber times pressure must approach zero.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation boundary condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8665bbc-d35c-4544-ab6d-41e75c740b3b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8665bbc-d35c-4544-ab6d-41e75c740b3b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8665bbc-d35c-4544-ab6d-41e75c740b3b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'da1a5e78-8b88-4b55-9cb6-6fdcd8cddcf2','Radiation pressure','Acoustic radiation pressure is the steady (time-averaged) pressure a sound field exerts on an object or interface, arising from the nonlinear momentum transported by the wave. For a plane traveling wave fully absorbed at a surface it equals the time-averaged energy density, or the intensity divided by the sound speed.','A sound wave carries momentum. When it pushes on a surface, a small steady force appears. This is radiation pressure. It is a second-order, nonlinear effect. It can move tiny objects.','It explains the steady force sound exerts, used in acoustic levitation, particle trapping, and radiation-force measurements.','For an absorbed plane wave of intensity I = 10 W/m^2 in air (c = 343 m/s), radiation pressure P = I/c = 10/343 = 0.029 Pa.','Nonlinear Acoustics',ARRAY['Potential energy density','Orbital angular momentum of sound','Peak particle velocity','Physical acoustics']::text[],ARRAY['Confusing steady radiation pressure with the oscillating acoustic pressure of the wave.','Treating it as a linear effect; it is a second-order, nonlinear quantity.','Using the absorbing-surface formula for a perfectly reflecting surface, which doubles the value.']::text[],ARRAY['Levitating or trapping small particles with focused ultrasound.','Measuring ultrasonic power with a radiation-force balance.','Explaining acoustic streaming and steady forces in intense fields.']::text[],'advanced','P_rad = <E> = I/c (plane wave, fully absorbed)','For a fully absorbed plane wave, radiation pressure equals the time-averaged energy density, or equivalently the sound intensity divided by the sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Radiation pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'da1a5e78-8b88-4b55-9cb6-6fdcd8cddcf2','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='da1a5e78-8b88-4b55-9cb6-6fdcd8cddcf2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='da1a5e78-8b88-4b55-9cb6-6fdcd8cddcf2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec8607da-31fb-41a1-817c-671052936624','Random-incidence absorption','Random-incidence absorption is the sound absorption of a surface averaged over all angles of incidence in a diffuse field, as measured in a reverberation chamber per ISO 354. Its coefficient (the Sabine absorption coefficient) is generally higher than the normal-incidence value and can slightly exceed one due to edge and diffraction effects.','In a real room, sound hits surfaces from all directions. Random-incidence absorption averages over all those angles. It is measured in a reverberation chamber. This is the value used for room design.','It gives the practical, diffuse-field absorption figure used in reverberation-time and room-treatment calculations.','A published Sabine coefficient of 0.85 at 1 kHz means a diffuse field loses about 85% of the sound power striking that surface per reflection.','Sound Absorption',ARRAY['Normal-incidence absorption','Propagation loss','Reference sound pressure','Normal-incidence impedance']::text[],ARRAY['Confusing the higher Sabine value with the lower normal-incidence coefficient.','Being surprised that a Sabine coefficient can exceed 1 due to edge diffraction.','Applying a single-number rating without checking the frequency band.']::text[],ARRAY['Selecting absorber ratings for a reverberation-time calculation.','Comparing acoustic panels using ISO 354 chamber data.','Predicting a room''s diffuse-field decay after treatment.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random-incidence absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec8607da-31fb-41a1-817c-671052936624','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec8607da-31fb-41a1-817c-671052936624') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec8607da-31fb-41a1-817c-671052936624');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9264d35-4468-47f3-a1e4-9430ef2b5ee5','Ray acoustics','Ray acoustics (geometrical acoustics) models sound propagation as rays that travel along paths perpendicular to the wavefronts, valid in the high-frequency limit where wavelengths are small compared with obstacles and gradients. It handles reflection and refraction well but neglects diffraction and interference.','Ray acoustics treats sound like beams of light. Sound travels in straight rays. Rays reflect and bend at surfaces. This works well for short wavelengths. It ignores bending around edges.','It gives a fast, intuitive way to trace reflections and refraction for high frequencies, as in room-acoustics ray tracing.','In room modeling, a technician traces rays from a loudspeaker, reflecting them off walls to estimate early reflection paths and coverage.','Wave Modeling',ARRAY['Paraxial approximation','Object size relative to wavelength','Physical acoustics','Propagation constant']::text[],ARRAY['Applying ray methods at low frequencies where diffraction dominates.','Forgetting that ray tracing ignores interference and wave phase.','Assuming rays capture sound bending around large obstacles.']::text[],ARRAY['Ray-tracing early reflections in a concert-hall model.','Estimating sound refraction through temperature gradients outdoors.','Predicting high-frequency coverage from a source.']::text[],'intermediate','|grad(tau)|^2 = 1/c^2 (eikonal equation)','In the high-frequency limit, the squared gradient of the travel-time function equals one over the sound speed squared, defining ray paths.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ray acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9264d35-4468-47f3-a1e4-9430ef2b5ee5','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9264d35-4468-47f3-a1e4-9430ef2b5ee5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9264d35-4468-47f3-a1e4-9430ef2b5ee5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8583cebf-e5a9-4dbc-9727-6080ea76fea7','Rayleigh wave','A Rayleigh wave is a surface acoustic wave that travels along the free boundary of a solid, with particle motion tracing a retrograde ellipse that combines longitudinal and vertical shear components and decays with depth. Its speed is slightly below the solid''s shear-wave speed, roughly 0.87 to 0.95 times it depending on Poisson''s ratio.','Some waves travel along a solid''s surface. A Rayleigh wave is one of these. Particles move in small ellipses near the surface. The motion fades with depth. Earthquakes produce these waves.','It describes energy guided along a solid surface, important in seismology, ultrasonic testing, and surface-acoustic-wave devices.','In steel (shear speed about 3200 m/s), the Rayleigh-wave speed is roughly 0.92 times that, near 2950 m/s.','Surface Waves',ARRAY['Object size relative to wavelength','Propagation constant','Physical acoustics','Ray acoustics']::text[],ARRAY['Confusing a surface Rayleigh wave with a bulk longitudinal or shear wave.','Assuming it penetrates deeply; its amplitude decays within about one wavelength of the surface.','Treating particle motion as linear rather than elliptical and retrograde.']::text[],ARRAY['Surface-crack detection in ultrasonic non-destructive testing.','Analyzing surface-acoustic-wave (SAW) filter behavior.','Interpreting ground motion in seismology.']::text[],'advanced','c_R ≈ (0.87 + 1.12*nu)/(1 + nu) * c_s','The Rayleigh-wave speed is approximately the factor 0.87 plus 1.12 times Poisson''s ratio, divided by one plus Poisson''s ratio, times the shear-wave speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rayleigh wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8583cebf-e5a9-4dbc-9727-6080ea76fea7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8583cebf-e5a9-4dbc-9727-6080ea76fea7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8583cebf-e5a9-4dbc-9727-6080ea76fea7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2cd83d89-1555-421c-8b1b-84756fb4a6b0','Reactive near field','The reactive near field is the region immediately adjacent to a sound source where pressure and particle velocity are largely out of phase, energy oscillates back and forth without net radiation, and evanescent (non-propagating) components dominate. It lies closer to the source than the radiating near field.','Very close to a source, energy sloshes in and out. It does not all radiate away. Pressure and motion are out of step here. This is the reactive near field. It fades quickly with distance.','It identifies the innermost zone where stored, non-radiating energy dominates, cautioning against measurements taken there.','Within roughly a fraction of a wavelength (about lambda/(2*pi)) of a small source, a probe sits in the reactive near field and reads mostly non-radiating field, not true output.','Sound Field Region',ARRAY['Radiating near field','Radiation boundary condition','Peak particle velocity','Normal-incidence impedance']::text[],ARRAY['Confusing the reactive near field with the radiating near field.','Measuring output very close to a source and mistaking stored energy for radiation.','Assuming pressure and velocity are in phase near a source.']::text[],ARRAY['Understanding why a mic pressed against a driver reads unreliably.','Interpreting probe measurements near a small source.','Explaining strong non-radiating fields close to a vibrating surface.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reactive near field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2cd83d89-1555-421c-8b1b-84756fb4a6b0','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2cd83d89-1555-421c-8b1b-84756fb4a6b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2cd83d89-1555-421c-8b1b-84756fb4a6b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a49d8607-4f7e-4861-8a6f-f6100cfc071e','Reference sound pressure','The reference sound pressure is the standardized pressure against which sound pressure level is defined: 20 micropascals (2e-5 Pa) in air and 1 micropascal in water. It corresponds roughly to the quietest sound a healthy young human can hear at 1 kHz in air and anchors the decibel SPL scale.','Decibels compare a sound to a fixed baseline. That baseline is the reference sound pressure. In air it is 20 micropascals. It is about the softest sound a person can hear. In water it is 1 micropascal.','It provides the fixed anchor for the decibel SPL scale, so levels are comparable across instruments and studies.','Because SPL = 20*log10(p_rms/p_0), a pressure equal to the reference (20 uPa) gives 0 dB SPL.','Reference Quantity',ARRAY['RMS SPL','Propagation loss','Random-incidence absorption','Physical acoustics']::text[],ARRAY['Using the air reference (20 uPa) for underwater sound, where 1 uPa applies.','Forgetting that 0 dB SPL is not zero pressure, just the reference level.','Confusing the pressure reference with power or intensity references.']::text[],ARRAY['Calibrating and interpreting a sound level meter reading.','Reporting SPL consistently across measurements.','Distinguishing airborne and underwater decibel scales.']::text[],'beginner','p_0 = 20 uPa (air),  p_0 = 1 uPa (water)','The reference sound pressure is twenty micropascals in air and one micropascal in water, used as the denominator in the sound pressure level formula.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference sound pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a49d8607-4f7e-4861-8a6f-f6100cfc071e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a49d8607-4f7e-4861-8a6f-f6100cfc071e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a49d8607-4f7e-4861-8a6f-f6100cfc071e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a34d7309-80bf-4cb0-bb18-33c633a7058f','Relationship among frequency, wavelength, and sound speed','The relationship among frequency, wavelength, and sound speed states that the speed of sound equals frequency times wavelength (c = f*lambda). For a fixed medium the sound speed is essentially constant, so wavelength is inversely proportional to frequency.','Sound speed, frequency, and wavelength are linked. Speed equals frequency times wavelength. In a given medium, the speed is fixed. So higher frequencies have shorter wavelengths. Lower frequencies have longer ones.','It is the basic wave equation tying pitch to physical size, letting technicians convert between frequency and wavelength.','In air at c = 343 m/s, a 1000 Hz tone has wavelength lambda = c/f = 343/1000 = 0.343 m.','Wave Fundamentals',ARRAY['Propagation constant','Object size relative to wavelength','Quarter-wavelength relationships','Resonant frequency']::text[],ARRAY['Assuming the sound speed changes with frequency in air; it is essentially constant (nondispersive).','Using the speed of sound in air for calculations in water or solids.','Confusing frequency (pitch) with wavelength (physical length).']::text[],ARRAY['Converting a frequency to a wavelength for room-mode or spacing calculations.','Choosing driver spacing relative to wavelength in an array.','Estimating the size of an absorber for a target frequency.']::text[],'beginner','c = f*lambda,  lambda = c/f','Sound speed equals frequency times wavelength, so wavelength equals sound speed divided by frequency.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Relationship among frequency, wavelength, and sound speed');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a34d7309-80bf-4cb0-bb18-33c633a7058f','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a34d7309-80bf-4cb0-bb18-33c633a7058f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a34d7309-80bf-4cb0-bb18-33c633a7058f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3414154b-2f8d-4d78-be6a-24bc2e21033e','Resonant frequency','A resonant frequency is a frequency at which a system naturally oscillates with maximum amplitude for a given drive, because energy stored in mass (or inertia) and stiffness (or compliance) exchanges most efficiently. For a simple mass-spring system it is f = (1/(2*pi))*sqrt(k/m).','Every object has favorite frequencies to vibrate at. Drive it there and it responds strongly. That is a resonant frequency. A pushed swing timed right is a good example. Rooms and instruments have them too.','It identifies where a system responds most strongly, key to tuning instruments, resonators, absorbers, and diagnosing problem room modes.','A mass-spring system with stiffness k = 1000 N/m and mass m = 0.25 kg resonates at f = (1/(2*pi))*sqrt(1000/0.25) = (1/(2*pi))*63.2 = 10.1 Hz.','Resonance',ARRAY['Quarter-wave resonance','Overtone','Nodal plane','Relationship among frequency, wavelength, and sound speed']::text[],ARRAY['Assuming a system has only one resonant frequency; most have many.','Confusing resonant frequency with the driving frequency.','Ignoring damping, which lowers and broadens the resonance peak.']::text[],ARRAY['Identifying and treating a problem room mode.','Tuning a resonator or absorber to a target frequency.','Explaining why a structure rattles at a specific pitch.']::text[],'beginner','f_0 = (1/(2*pi))*sqrt(k/m)','The resonant frequency of a mass-spring system is one over two pi times the square root of the stiffness divided by the mass.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonant frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3414154b-2f8d-4d78-be6a-24bc2e21033e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3414154b-2f8d-4d78-be6a-24bc2e21033e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3414154b-2f8d-4d78-be6a-24bc2e21033e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9082df5c-d202-4053-b942-a4eac3062ef8','Reverse-time integration','Reverse-time (Schroeder backward) integration is a method that computes a room''s smooth energy-decay curve by integrating the squared impulse response from a late time backward to the point of interest. The decay curve at time t equals the remaining acoustic energy from t to infinity, which removes the random fluctuations seen when a single decay is measured directly.','A room''s echo tail is bumpy and hard to read. This trick adds up the sound energy starting from the end and working back. The result is a smooth decay line. Engineers use that line to read reverberation time.','It turns one noisy measured impulse response into a smooth, repeatable decay curve so reverberation time can be read reliably.','After capturing a room impulse response, a technician squares it and integrates backward; fitting a line from -5 dB to -35 dB on the resulting curve gives T30, doubled to report reverberation time.','Measurement Method',ARRAY['Root-mean-square sound pressure','Strength','Sound energy']::text[],ARRAY['Integrating forward in time instead of backward, which reproduces the noisy decay.','Including the noise floor tail in the integral, which flattens the curve and shortens the apparent decay.','Assuming the method needs many averaged decays; one impulse response is enough.']::text[],ARRAY['Deriving T30 from a swept-sine room measurement.','Comparing seat-to-seat decay in a concert hall.','Checking reverberation after installing acoustic treatment.']::text[],'advanced','E(t) = ∫_t^∞ p²(τ) dτ','The energy-decay curve at time t equals the integral of the squared impulse-response pressure from t to infinity.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverse-time integration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9082df5c-d202-4053-b942-a4eac3062ef8','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9082df5c-d202-4053-b942-a4eac3062ef8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9082df5c-d202-4053-b942-a4eac3062ef8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11dff361-767a-4db1-8e2d-6ade1e3f2228','Root-mean-square sound pressure','Root-mean-square (RMS) sound pressure is the square root of the time-averaged square of the instantaneous sound pressure over a stated interval. It is the standard amplitude measure used to compute sound pressure level and acoustic intensity because it relates directly to the energy carried by the wave.','Sound pressure swings above and below the still-air value. Its simple average is near zero, so that is useless. RMS squares the values first, averages them, then takes the square root. This gives one steady number that tracks the sound''s power.','It provides a single energy-based amplitude value that stays meaningful for both steady tones and complex signals, forming the basis of decibel levels.','For a pure tone with peak pressure 1 Pa, the RMS pressure is 1/√2 ≈ 0.707 Pa; referencing 20 µPa gives a level of 20·log10(0.707/20e-6) ≈ 91 dB SPL.','Acoustic Quantity',ARRAY['Sound pressure','Sound energy','Specific acoustic impedance']::text[],ARRAY['Confusing RMS with peak amplitude; for a sine they differ by a factor of √2.','Using too short an averaging time for low-frequency or fluctuating signals.','Assuming peak-to-RMS ratio is always 3 dB; it depends on the waveform (crest factor).']::text[],ARRAY['Calibrating a sound level meter.','Reporting SPL of a mixed program signal.','Setting gain structure from measured RMS levels.']::text[],'intermediate','p_rms = √( (1/T) ∫_0^T p²(t) dt )','RMS sound pressure equals the square root of the mean, over the averaging time, of the squared instantaneous sound pressure.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Root-mean-square sound pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11dff361-767a-4db1-8e2d-6ade1e3f2228','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11dff361-767a-4db1-8e2d-6ade1e3f2228') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11dff361-767a-4db1-8e2d-6ade1e3f2228');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba8db6d8-c36d-4c82-86ec-7abe3a14a391','STearly','STearly (early stage support) is a stage-acoustics parameter defined in ISO 3382-1 as the level ratio, in decibels, of energy arriving 20 to 100 ms after the direct sound to the direct-sound energy in the first 10 ms, measured 1 m from an omnidirectional source on an unoccupied stage. It quantifies how well early reflections from the stage enclosure support a musician''s ability to hear their own instrument.','On a stage, players need to hear themselves and nearby sound. STearly measures the early reflected sound from the stage walls and ceiling. It compares that early energy to the direct sound. A higher value means the stage gives the player good, quick support.','It rates how strongly a stage enclosure returns early reflections to a performer, a key factor in ensemble playing and self-monitoring.','An acoustician places a source and microphone 1 m apart on stage; if the 20-100 ms energy is about -12 dB relative to the direct sound, STearly is about -12 dB, near the typical range for good orchestral stages.','Room Acoustic Parameter',ARRAY['STlate','Strength','Reverse-time integration']::text[],ARRAY['Using a distance other than the specified 1 m, which invalidates the value.','Confusing stage support with clarity or strength measured in the audience area.','Ignoring that the measurement requires an unoccupied stage per the standard.']::text[],ARRAY['Assessing musician support in a new concert-hall stage design.','Comparing stage shells for an orchestra.','Diagnosing complaints that players cannot hear each other.']::text[],'advanced','ST_early = 10·log10( ∫_20ms^100ms p²(t) dt / ∫_0^10ms p²(t) dt )','Early stage support is ten times the base-ten logarithm of the energy between 20 and 100 ms divided by the energy in the first 10 ms.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='STearly');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba8db6d8-c36d-4c82-86ec-7abe3a14a391','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba8db6d8-c36d-4c82-86ec-7abe3a14a391') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba8db6d8-c36d-4c82-86ec-7abe3a14a391');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8805aa7e-25ef-4d34-9480-42927ad95039','STlate','STlate (late stage support) is the ISO 3382-1 stage parameter giving the decibel ratio of energy arriving 100 to 1000 ms after the direct sound to the direct-sound energy in the first 10 ms, measured 1 m from an omnidirectional source on stage. It reflects the contribution of the hall''s later reverberant sound to a performer''s sense of reverberance and blend.','STlate measures the later, more reverberant sound a player hears on stage. It looks at energy from 100 to 1000 milliseconds. It compares that to the direct sound. This shows how much the whole room''s reverberation reaches back to the musician.','It describes how much late reverberant energy from the hall returns to performers, shaping their impression of the room''s liveness.','With the same 1 m source-receiver setup as STearly, the technician integrates the 100-1000 ms window; a value near -14 dB indicates a moderately reverberant return to the stage.','Room Acoustic Parameter',ARRAY['STearly','Strength','Reverse-time integration']::text[],ARRAY['Overlapping the early window; the late window must start at 100 ms.','Assuming higher STlate is always better; excess late energy can muddy ensemble timing.','Measuring with the audience present, contrary to the standard''s unoccupied condition.']::text[],ARRAY['Evaluating perceived reverberance on an orchestral stage.','Balancing early versus late support in a hall design.','Documenting stage acoustics for a venue report.']::text[],'advanced','ST_late = 10·log10( ∫_100ms^1000ms p²(t) dt / ∫_0^10ms p²(t) dt )','Late stage support is ten times the base-ten logarithm of the energy between 100 and 1000 ms divided by the energy in the first 10 ms.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='STlate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8805aa7e-25ef-4d34-9480-42927ad95039','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8805aa7e-25ef-4d34-9480-42927ad95039') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8805aa7e-25ef-4d34-9480-42927ad95039');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30059915-f2db-489c-a9c6-7af2ba35598b','Scalar potential','In linear acoustics the scalar (velocity) potential is a single scalar function whose spatial gradient gives the particle velocity and whose time derivative gives the sound pressure. Because acoustic motion in an ideal fluid is irrotational, the whole field can be derived from this one potential, simplifying wave analysis.','A sound field has pressure and air motion at every point. Tracking both everywhere is a lot of work. The scalar potential is one field that contains both. You take its slope to get air motion. You take its time change to get pressure.','It reduces a vector velocity field and a pressure field to one scalar function, making the wave equation and boundary problems easier to solve.','A modeler solving radiation from a vibrating surface computes the velocity potential, then obtains pressure as p = -ρ₀ ∂φ/∂t and particle velocity as u = ∇φ at any field point.','Theory / Field Variable',ARRAY['Sound pressure','Sound field','Scholte wave']::text[],ARRAY['Mixing sign conventions; some texts define u = -∇φ, so pressure sign must match.','Assuming a scalar potential exists in a rotational (vortical) flow, where it does not.','Confusing the velocity potential with the pressure field itself.']::text[],ARRAY['Deriving radiation from a baffled piston.','Setting up a boundary-element acoustic model.','Teaching the acoustic wave equation from first principles.']::text[],'advanced','u = ∇φ ,  p = -ρ₀ ∂φ/∂t','Particle velocity equals the gradient of the potential; sound pressure equals minus the fluid density times the time derivative of the potential.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scalar potential');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30059915-f2db-489c-a9c6-7af2ba35598b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30059915-f2db-489c-a9c6-7af2ba35598b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30059915-f2db-489c-a9c6-7af2ba35598b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0eda6c22-f7f5-44ff-96d8-960d9e6a7b0d','Scholte wave','A Scholte wave is an interface wave that travels along the boundary between a fluid and a solid, with its energy concentrated at the interface and decaying exponentially into both media. Its speed is slightly below the sound speed of the fluid, and it is important in ocean-bottom and ultrasonic sensing.','Where water meets the seabed, a special wave can run along the surface between them. It is called a Scholte wave. Most of its motion stays near the boundary. It fades quickly as you move away from that surface into either material.','It describes guided energy trapped at a fluid-solid interface, which matters for seabed characterization and non-destructive testing.','A geophysicist analyzing ocean-bottom seismometer data identifies the slow, interface-bound Scholte arrival to estimate the shear properties of soft seabed sediments.','Wave Type',ARRAY['Stoneley wave','Shear wave','Surface acoustic wave','Scalar potential']::text[],ARRAY['Confusing a Scholte wave (fluid-solid) with a Stoneley wave (solid-solid).','Assuming it travels faster than the fluid sound speed; it is slightly slower.','Treating it as a bulk wave rather than an interface-bound wave.']::text[],ARRAY['Characterizing soft seabed sediments from ocean-bottom recordings.','Ultrasonic testing across a liquid-metal boundary.','Studying guided waves in underwater acoustics.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scholte wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0eda6c22-f7f5-44ff-96d8-960d9e6a7b0d','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0eda6c22-f7f5-44ff-96d8-960d9e6a7b0d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0eda6c22-f7f5-44ff-96d8-960d9e6a7b0d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44eba295-408d-4092-82a9-f276b6c2f4a0','Self-demodulation','Self-demodulation is a nonlinear effect in which an intense, amplitude-modulated high-frequency (primary) sound beam progressively generates a low-frequency signal as it propagates, because the medium responds nonlinearly to the beam''s envelope. It is the mechanism behind the parametric acoustic array, and the recovered low-frequency waveform is proportional to the second time derivative of the squared modulation envelope.','Send a strong, high-pitched beam that carries a slow envelope. As it moves through air or water, the medium reacts unevenly. This slowly creates a new low-pitched sound from the envelope. The effect needs no loudspeaker for the low tone; the medium makes it.','It lets a small high-frequency source create a highly directional low-frequency beam, the basis of parametric loudspeakers and sonar.','An audio-spotlight designer amplitude-modulates an ultrasonic carrier so self-demodulation reproduces the audible program along a narrow beam, aiming sound at one listener without spreading it across a room.','Nonlinear Effect',ARRAY['Thermoviscous loss','Sound pressure','Sonic']::text[],ARRAY['Assuming the low frequency is radiated directly by the source rather than generated in the medium.','Ignoring that high primary intensity is required for measurable output.','Expecting high efficiency; parametric conversion is inherently low.']::text[],ARRAY['Designing a directional ''audio spotlight'' loudspeaker.','Parametric sub-bottom profiling sonar.','Demonstrating nonlinear acoustics in a lab.']::text[],'advanced','p_demod ∝ ∂²/∂t² [ E²(t) ]','The demodulated low-frequency pressure is proportional to the second time derivative of the square of the primary-beam modulation envelope.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Self-demodulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44eba295-408d-4092-82a9-f276b6c2f4a0','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44eba295-408d-4092-82a9-f276b6c2f4a0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44eba295-408d-4092-82a9-f276b6c2f4a0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a16a214-dec3-4b04-aa48-abf17c0ad4d0','Shadow zones','A shadow zone is a region into which sound cannot penetrate along direct ray paths because refraction from a sound-speed gradient, or diffraction around an obstacle, bends energy away from it. Sound levels there are much lower than geometric spreading alone would predict, though weak diffracted or scattered energy may still arrive.','Sometimes sound bends away from an area and leaves it quiet. This can happen when the speed of sound changes with height or depth. It can also happen behind a large barrier. That quiet area is a shadow zone. A little sound still leaks in.','It identifies regions of unexpectedly low sound level created by refraction or obstruction, important for predicting coverage and detection ranges.','A sonar operator accounts for a shadow zone below a downward-refracting layer, knowing a submarine there may be undetectable despite being within nominal range.','Propagation Effect',ARRAY['Sound-speed gradient','Total internal reflection','Spherical spreading loss']::text[],ARRAY['Assuming a shadow zone is perfectly silent; diffracted energy still enters.','Confusing refractive shadow zones with simple distance-based level loss.','Forgetting that shadow-zone geometry changes with the sound-speed profile.']::text[],ARRAY['Predicting sonar detection gaps in the ocean.','Estimating outdoor noise behind a barrier or hill.','Modeling atmospheric sound propagation under a temperature inversion.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shadow zones');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a16a214-dec3-4b04-aa48-abf17c0ad4d0','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a16a214-dec3-4b04-aa48-abf17c0ad4d0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a16a214-dec3-4b04-aa48-abf17c0ad4d0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81bffc58-b660-4dba-8019-5840abcb2a74','Shear wave','A shear (transverse) wave is an elastic wave in which particle motion is perpendicular to the direction of propagation, restored by a material''s shear stiffness. It travels only in media that resist shear, so it exists in solids but not in ideal (inviscid) fluids, and it moves slower than the compressional wave in the same solid.','In a solid, you can shake particles side to side as a wave moves forward. That is a shear wave. It needs a material that resists twisting or sliding. Solids do; still air and water basically do not. So shear waves travel in solids only.','It represents the transverse mode of elastic-wave energy in solids, essential in seismology, ultrasonics, and structure-borne sound.','For steel with shear modulus 79 GPa and density 7850 kg/m³, the shear-wave speed is √(79e9/7850) ≈ 3170 m/s, well below its ~5900 m/s compressional speed.','Wave Type',ARRAY['Surface acoustic wave','Stoneley wave','Scholte wave','Total internal reflection']::text[],ARRAY['Believing shear waves travel in air or water; ideal fluids support only compressional waves.','Assuming shear waves are faster than compressional waves; they are slower.','Confusing particle motion direction: shear is transverse, not longitudinal.']::text[],ARRAY['Ultrasonic flaw detection in metal parts.','Analyzing structure-borne vibration in buildings.','Interpreting seismic S-wave arrivals.']::text[],'intermediate','c_s = √(G/ρ)','Shear-wave speed equals the square root of the shear modulus divided by the material density.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shear wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81bffc58-b660-4dba-8019-5840abcb2a74','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81bffc58-b660-4dba-8019-5840abcb2a74') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81bffc58-b660-4dba-8019-5840abcb2a74');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7daeb22-29e4-43ce-9c7c-a973d5670607','Sommerfeld radiation condition','The Sommerfeld radiation condition is a mathematical requirement imposed at infinity that selects physically meaningful outgoing-wave solutions of the Helmholtz equation and excludes waves converging from infinity. In three dimensions it states that r times the difference between the radial derivative of the pressure and ik times the pressure tends to zero as the radius grows without bound.','When you solve for radiated sound in open space, the math allows two answers. One spreads outward; the other flows inward from far away. The inward one is not physical. This condition throws it out. It forces the solution to only carry energy outward.','It guarantees a unique, physically correct solution for exterior radiation and scattering problems by enforcing purely outgoing energy at large distances.','When setting up a boundary-element model of a radiating source, an engineer relies on the free-space Green''s function, which already satisfies this condition so no spurious incoming waves appear.','Theory / Boundary Condition',ARRAY['Scalar potential','Sound field','Spherical spreading loss']::text[],ARRAY['Getting the sign wrong; it depends on the assumed e^(-iωt) versus e^(+iωt) time convention.','Applying it to interior (bounded) problems where it is not needed.','Confusing this analytic condition with a numerical absorbing boundary.']::text[],ARRAY['Formulating exterior scattering problems.','Justifying free-space Green''s functions in radiation theory.','Setting far-field conditions in acoustic solvers.']::text[],'advanced','lim_{r→∞} r ( ∂p/∂r − i k p ) = 0','As distance grows without limit, the radius times the radial pressure derivative minus i times the wavenumber times pressure approaches zero.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sommerfeld radiation condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7daeb22-29e4-43ce-9c7c-a973d5670607','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7daeb22-29e4-43ce-9c7c-a973d5670607') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7daeb22-29e4-43ce-9c7c-a973d5670607');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11ed3f56-b9e0-4d1c-9bb8-b4c0eea050df','Sonic','''Sonic'' is an adjective meaning of or relating to sound, and in fluid dynamics specifically pertaining to a flow speed equal to the local speed of sound (Mach 1). In acoustics it commonly denotes the audible regime, bounded by ''infrasonic'' (below human hearing) and ''ultrasonic'' (above it); the related term ''subsonic'' instead refers to a flow slower than Mach 1.','''Sonic'' simply means having to do with sound. In airflow, it can mean moving at the speed of sound. In audio, it often means the range people can hear. It sits between infrasonic below and ultrasonic above.','It provides a general adjective for sound-related quantities and marks the audible or speed-of-sound regime in a family of related terms.','A technician labels a 1 kHz test tone as sonic (audible), reserving ''ultrasonic'' for a 40 kHz transducer signal that lies above the roughly 20 kHz upper limit of hearing.','Terminology',ARRAY['Sound energy','Sound field','Self-demodulation']::text[],ARRAY['Using ''sonic'' to mean loud; it refers to sound or the speed of sound, not level.','Confusing ''supersonic'' (faster than sound) with ''ultrasonic'' (above hearing).','Assuming ''sonic'' always means audible; in aerodynamics it means Mach 1.']::text[],ARRAY['Distinguishing sonic from ultrasonic test signals.','Describing sonic-range measurement microphones.','Explaining audio frequency bands to students.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11ed3f56-b9e0-4d1c-9bb8-b4c0eea050df','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11ed3f56-b9e0-4d1c-9bb8-b4c0eea050df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11ed3f56-b9e0-4d1c-9bb8-b4c0eea050df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f8290615-0212-4560-be18-db462273ed87','Sound energy','Sound energy is the additional energy a medium carries because of the presence of a sound wave, made up of the kinetic energy of moving particles and the potential energy of elastic compression. Its concentration is described by the sound energy density, and its flow per unit area by acoustic intensity.','A sound wave adds energy to the air or water it passes through. Part is motion energy from particles moving. Part is spring energy stored in the squeeze and stretch. Together these make up the sound energy in the field.','It quantifies the energy content of a sound field, underpinning measures such as energy density, intensity, and reverberant decay.','In a plane wave with RMS pressure 0.707 Pa in air (ρc ≈ 413 rayl, c ≈ 343 m/s), the energy density is p_rms²/(ρc²) ≈ 0.707²/(1.21×343²) ≈ 3.5×10⁻⁶ J/m³.','Acoustic Quantity',ARRAY['Sound pressure','Root-mean-square sound pressure','Sound field','Strength']::text[],ARRAY['Confusing sound energy density (J/m³) with intensity (W/m²), which is energy flow.','Forgetting the potential-energy term and counting only particle motion.','Assuming energy density and pressure are linearly related; it scales with pressure squared.']::text[],ARRAY['Estimating reverberant energy build-up in a room.','Relating intensity to energy density in a diffuse field.','Teaching kinetic and potential parts of an acoustic wave.']::text[],'intermediate','w = p_rms² / (ρ₀ c²)','For a plane progressive wave the time-averaged sound energy density equals the mean-square pressure divided by the density times the sound speed squared.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound energy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f8290615-0212-4560-be18-db462273ed87','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f8290615-0212-4560-be18-db462273ed87') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f8290615-0212-4560-be18-db462273ed87');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56e6d344-8f9c-40e8-b5a2-8da222c3d1f1','Sound field','A sound field is a region of a medium in which sound waves are present, fully described at each point by the sound pressure and the particle velocity as functions of time. Characteristic idealizations include the free field, where waves radiate without reflections, and the diffuse field, where energy arrives equally from all directions.','A sound field is any space filled with sound waves. At every point you can note the pressure and the tiny air motion. Some fields are open with no echoes. Others are full of sound coming from all sides at once.','It provides the spatial framework for describing how sound is distributed and behaves throughout a region, guiding measurement and modeling choices.','A technician measuring a loudspeaker chooses an anechoic (free-field) space so only direct sound is captured, avoiding the diffuse-field reflections of a normal room.','Fundamental Concept',ARRAY['Sound pressure','Sound energy','Spatial variance','Scalar potential']::text[],ARRAY['Assuming any room provides a free field; reflections create a mixed or diffuse field.','Describing a field by pressure alone and ignoring particle velocity.','Treating near-field and far-field regions as identical.']::text[],ARRAY['Selecting free-field versus diffuse-field microphone calibration.','Mapping SPL distribution across a listening area.','Defining measurement conditions in an acoustic test.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56e6d344-8f9c-40e8-b5a2-8da222c3d1f1','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56e6d344-8f9c-40e8-b5a2-8da222c3d1f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56e6d344-8f9c-40e8-b5a2-8da222c3d1f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d76f967-01a1-4b4d-8d3b-094150a6c854','Sound pressure','Sound pressure is the local, instantaneous deviation of pressure from the ambient static pressure caused by a sound wave, expressed in pascals. It is the quantity a microphone transduces, and its RMS value referenced to 20 µPa in air defines sound pressure level.','Still air has a steady background pressure. A sound wave makes tiny fast changes above and below it. That small change is the sound pressure. A microphone senses exactly this change and turns it into a signal.','It is the primary field variable of airborne acoustics and the basis for level, intensity, and impedance measurements.','A measurement microphone reading an RMS sound pressure of 2 Pa reports a level of 20·log10(2/20e-6) = 100 dB SPL relative to the 20 µPa reference.','Acoustic Quantity',ARRAY['Root-mean-square sound pressure','Sound energy','Specific acoustic impedance','Sound field']::text[],ARRAY['Confusing the small sound pressure with the large ambient static pressure.','Reporting instantaneous rather than RMS pressure when computing SPL.','Using the wrong reference; air uses 20 µPa, water uses 1 µPa.']::text[],ARRAY['Calibrating a microphone with a pistonphone.','Computing SPL from a measured pressure.','Explaining what a diaphragm actually senses.']::text[],'beginner','p(t) = P(t) − P₀','Sound pressure is the total instantaneous pressure minus the ambient static pressure.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d76f967-01a1-4b4d-8d3b-094150a6c854','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d76f967-01a1-4b4d-8d3b-094150a6c854') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d76f967-01a1-4b4d-8d3b-094150a6c854');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75309272-9e19-44f5-9bdc-e11f4d3d7f24','Sound-speed gradient','A sound-speed gradient is the rate at which the speed of sound changes with position in a medium, most often with depth in the ocean or height in the atmosphere. Its sign and magnitude bend sound rays toward regions of lower speed, controlling refraction, ducting, and shadow-zone formation.','The speed of sound is not the same everywhere. It changes with depth in water or height in air. The sound-speed gradient measures how fast it changes. This change bends sound rays and decides where sound goes.','It drives refraction of sound in the ocean and atmosphere, determining propagation paths, channels, and quiet shadow zones.','An analyst reading a profile where sound speed rises by 15 m/s over 500 m of depth computes a gradient of 0.03 s⁻¹, then predicts rays bending upward toward the slower shallow water.','Propagation Parameter',ARRAY['Shadow zones','Total internal reflection','Spherical spreading loss']::text[],ARRAY['Assuming rays bend toward higher sound speed; they bend toward lower speed.','Ignoring the sign, which decides upward versus downward refraction.','Treating the ocean or atmosphere as uniform, missing ducting effects.']::text[],ARRAY['Predicting sonar ray paths from a sound-speed profile.','Explaining a surface duct or deep sound channel.','Modeling daytime versus nighttime outdoor sound propagation.']::text[],'intermediate','g = dc/dz','The sound-speed gradient is the derivative of sound speed with respect to position (typically depth or height).','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-speed gradient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75309272-9e19-44f5-9bdc-e11f4d3d7f24','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75309272-9e19-44f5-9bdc-e11f4d3d7f24') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75309272-9e19-44f5-9bdc-e11f4d3d7f24');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5528a522-17a0-430e-8383-e7a4f9a19514','Spatial hearing','Spatial hearing is the auditory system''s ability to determine the direction, distance, and spatial extent of sound sources using binaural and monaural cues. Key cues include interaural time and level differences between the ears and the direction-dependent spectral shaping imposed by the head and outer ears.','Spatial hearing is how we tell where a sound comes from. Our two ears get the sound at slightly different times and loudness. The shape of the head and ears also colors the sound by direction. The brain reads these clues to place the source.','It explains how listeners localize sources and perceive an acoustic scene, underpinning stereo, surround, and binaural audio design.','A binaural-audio engineer applies head-related transfer functions so headphone playback recreates the interaural and spectral cues that let a listener perceive a source above and behind them.','Psychoacoustics',ARRAY['Sound field','Spatial variance','Sound pressure']::text[],ARRAY['Assuming level difference alone locates sound; timing and spectral cues matter too.','Ignoring front-back confusion that arises without spectral (pinna) cues.','Treating distance perception as identical to direction perception.']::text[],ARRAY['Designing binaural headphone rendering.','Explaining stereo image and panning.','Diagnosing localization problems in a surround setup.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial hearing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5528a522-17a0-430e-8383-e7a4f9a19514','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5528a522-17a0-430e-8383-e7a4f9a19514') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5528a522-17a0-430e-8383-e7a4f9a19514');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b89040f-a8c5-4ac1-947e-59dcfa108de2','Spatial variance','Spatial variance is the variation of an acoustic quantity, such as sound pressure level or frequency response, from one location to another within a sound field. In sound-system design it describes how coverage and tonal balance change across the audience area, and reducing it is a central goal of system optimization.','Sound is rarely the same everywhere in a room. Level and tone change from seat to seat. Spatial variance measures how much they change across the space. Good system design keeps this variation small so every seat sounds alike.','It quantifies how uniform a sound field is across space, a key metric for even loudspeaker coverage and consistent audience experience.','A system engineer measures response at several seats and finds high-frequency level dropping 8 dB from front to back; adding delayed fill loudspeakers reduces this spatial variance.','System Design',ARRAY['Sound field','Spherical spreading loss','Spatial hearing']::text[],ARRAY['Optimizing a single measurement position and ignoring variation across the audience.','Confusing spatial variance (position to position) with frequency-response ripple at one point.','Assuming more loudspeakers always reduce variance; poor aiming can worsen it.']::text[],ARRAY['Tuning a line array for even coverage.','Comparing seat-to-seat response in a venue.','Deciding where to add delay or fill loudspeakers.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial variance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b89040f-a8c5-4ac1-947e-59dcfa108de2','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b89040f-a8c5-4ac1-947e-59dcfa108de2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b89040f-a8c5-4ac1-947e-59dcfa108de2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3a38ad39-78d7-40cb-9dbb-e5a7901d870b','Specific acoustic impedance','Specific acoustic impedance is the complex ratio of sound pressure to particle velocity at a point in a medium, measured in pascal-seconds per metre (rayls). For a plane progressive wave it reduces to the real characteristic impedance, the product of the medium''s density and sound speed.','At a point in a sound field, pressure pushes and particles move. Specific acoustic impedance compares the pressure to that motion. In a simple traveling wave it equals density times sound speed. It tells how the medium opposes the flow of sound.','It characterizes how a medium or wave couples pressure to motion, governing reflection, transmission, and matching between media.','For air at 20 °C with density 1.21 kg/m³ and sound speed 343 m/s, the characteristic impedance is 1.21 × 343 ≈ 415 rayls, the value used in intensity and matching calculations.','Acoustic Quantity',ARRAY['Surface impedance','Transfer impedance','Sound pressure','Total internal reflection']::text[],ARRAY['Confusing specific acoustic impedance (per unit area) with acoustic impedance (pressure over volume velocity).','Assuming it is always real; away from a plane wave it is complex.','Mixing up rayls with the different mechanical or acoustic ohm units.']::text[],ARRAY['Computing reflection at an interface between two media.','Matching a horn or transducer to air.','Relating intensity to pressure in a plane wave.']::text[],'intermediate','z = p / u ;  plane wave: z = ρ₀ c','Specific acoustic impedance is sound pressure divided by particle velocity; for a plane wave it equals density times sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Specific acoustic impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3a38ad39-78d7-40cb-9dbb-e5a7901d870b','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3a38ad39-78d7-40cb-9dbb-e5a7901d870b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3a38ad39-78d7-40cb-9dbb-e5a7901d870b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7dfe1a2-4efa-4109-91bc-a8557c1195a9','Spherical spreading loss','Spherical spreading loss is the reduction in sound level with distance that occurs when energy from a point source radiates outward over an expanding spherical wavefront in free space. Because intensity falls as the inverse square of range, the level decreases by about 6 dB for each doubling of distance.','A point source sends sound out in all directions like an expanding balloon. The same energy spreads over a bigger and bigger surface. So the sound gets weaker with distance. It drops about 6 decibels each time the distance doubles.','It provides the baseline geometric attenuation of a free-field point source, used to estimate levels versus distance before adding absorption.','A source producing 100 dB at 1 m loses 20·log10(100/1) = 40 dB by 100 m under spherical spreading, giving roughly 60 dB at that range in free field.','Propagation Effect',ARRAY['Spatial variance','Shadow zones','Sound-speed gradient','Sound energy']::text[],ARRAY['Using 3 dB per distance doubling; that is cylindrical, not spherical spreading.','Applying free-field spreading inside a reverberant room.','Forgetting that atmospheric or medium absorption adds further loss.']::text[],ARRAY['Estimating outdoor sound level versus distance.','Setting up a sonar range budget.','Predicting SPL falloff from a point source outdoors.']::text[],'beginner','TL = 20·log10(r / r₀)','Transmission loss from spherical spreading is twenty times the base-ten logarithm of the range divided by a reference range.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical spreading loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7dfe1a2-4efa-4109-91bc-a8557c1195a9','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7dfe1a2-4efa-4109-91bc-a8557c1195a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7dfe1a2-4efa-4109-91bc-a8557c1195a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8276b756-04d6-477e-99ba-71245ceb7069','Stiffness-controlled region','The stiffness-controlled (compliance-controlled) region is the frequency range, below a driven system''s resonance, where its response is dominated by the restoring stiffness rather than mass or damping. In this region the reactance is that of the compliance, and displacement amplitude is nearly independent of frequency for a constant driving force.','Every vibrating device has a resonance frequency. Below it, the springiness of the system rules its behavior. This is the stiffness-controlled region. Here the motion depends mainly on how stiff the system is, not its weight.','It identifies the low-frequency behavior of transducers and mechanical systems, explaining why response below resonance is set by compliance.','A microphone designer notes that below the diaphragm resonance the capsule works in its stiffness-controlled region, giving a flat pressure response that suits a measurement microphone.','Transducer Behavior',ARRAY['Transition region','Surface impedance','Specific acoustic impedance']::text[],ARRAY['Confusing the stiffness-controlled (below resonance) with the mass-controlled (above resonance) region.','Assuming velocity is constant; it is displacement that is roughly flat here.','Overlooking that damping still limits response right at resonance.']::text[],ARRAY['Explaining a measurement microphone''s flat low-frequency response.','Analyzing a loudspeaker below its fundamental resonance.','Designing a mechanical suspension for a transducer.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stiffness-controlled region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8276b756-04d6-477e-99ba-71245ceb7069','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8276b756-04d6-477e-99ba-71245ceb7069') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8276b756-04d6-477e-99ba-71245ceb7069');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a02a9c87-a857-4784-9f47-8082baad1739','Stoneley wave','A Stoneley wave is an interface wave that propagates along the bonded boundary between two solid half-spaces, with amplitude decaying away from the interface into both solids. It exists only for a limited range of material property combinations and is the solid-solid counterpart of the fluid-solid Scholte wave.','Where two solids are firmly joined, a wave can travel along the seam between them. It is called a Stoneley wave. Its motion is strongest at the join. It fades as you move into either solid. It only forms for certain material pairs.','It describes guided energy trapped at a solid-solid interface, relevant to bonded structures, geophysics, and borehole acoustics.','A well-logging analyst interprets borehole Stoneley-wave data, whose speed and attenuation reveal formation permeability around the boreholewall.','Wave Type',ARRAY['Scholte wave','Shear wave','Surface acoustic wave']::text[],ARRAY['Confusing a Stoneley wave (solid-solid) with a Scholte wave (fluid-solid).','Assuming it always exists; it requires specific property combinations.','Treating it as a bulk wave rather than an interface-guided wave.']::text[],ARRAY['Interpreting borehole acoustic logs.','Testing the quality of a bonded solid interface.','Studying interface waves in seismology.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stoneley wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a02a9c87-a857-4784-9f47-8082baad1739','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a02a9c87-a857-4784-9f47-8082baad1739') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a02a9c87-a857-4784-9f47-8082baad1739');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '00f2c8f6-bb22-4500-944c-f34764ece3dd','Strength','Sound strength (G) is an ISO 3382-1 room-acoustic parameter giving the decibel ratio of the total sound energy of a room impulse response at a listener position to the energy that the same omnidirectional source would produce at 10 m in a free field. It measures how much a room amplifies a source relative to open air.','A room makes a source sound louder than it would outdoors. Strength puts a number on that boost. It compares the total energy at a seat to the energy the same source gives at 10 metres outside. A higher value means a louder, more supportive room.','It rates the loudness a hall adds to a source, helping compare venues and predict how well a seat is served acoustically.','An acoustician normalizes a measured impulse response to a calibrated 10 m free-field reference; if the seat energy is 4 dB higher, G is +4 dB, typical of a supportive concert hall.','Room Acoustic Parameter',ARRAY['STearly','STlate','Reverse-time integration','Sound energy']::text[],ARRAY['Skipping the required free-field calibration of the source at 10 m.','Confusing strength (a level ratio) with reverberation time (a decay rate).','Assuming higher strength always means better; it can indicate excess loudness.']::text[],ARRAY['Comparing loudness support across concert halls.','Documenting acoustic quality at multiple seats.','Verifying coverage after a hall renovation.']::text[],'advanced','G = 10·log10( ∫_0^∞ p²(t) dt / ∫_0^∞ p_10²(t) dt )','Strength is ten times the base-ten logarithm of the room impulse-response energy divided by the free-field energy of the same source at 10 metres.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '00f2c8f6-bb22-4500-944c-f34764ece3dd','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='00f2c8f6-bb22-4500-944c-f34764ece3dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='00f2c8f6-bb22-4500-944c-f34764ece3dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f7f700c-61fc-44d6-97d8-2abe9702cbd5','Surface acoustic wave','A surface acoustic wave (SAW) is an elastic wave guided along the free surface of a solid, with particle motion confined to roughly one wavelength of depth and decaying into the bulk. The classic Rayleigh-type SAW combines longitudinal and shear motion in a retrograde elliptical path and is widely exploited in electronic filters and sensors.','A surface acoustic wave runs along the top of a solid. Its motion stays near the surface and fades with depth. It carries energy like a ripple on the ground. Tiny versions of these waves power many radio filters and sensors.','It describes surface-guided elastic energy used both to study materials and to build compact signal-processing devices.','An RF engineer uses a piezoelectric SAW filter, where interdigital electrodes launch a surface wave whose transit sets a precise passband for a mobile-phone front end.','Wave Type',ARRAY['Shear wave','Stoneley wave','Scholte wave','Surface impedance']::text[],ARRAY['Assuming SAW energy penetrates deep into the solid; it stays within about a wavelength.','Confusing a Rayleigh surface wave with a bulk shear wave.','Overlooking that surface waves are slower than the bulk waves in the same solid.']::text[],ARRAY['Designing a SAW bandpass filter for radio.','Non-destructive surface inspection of components.','Building SAW-based gas or strain sensors.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface acoustic wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f7f700c-61fc-44d6-97d8-2abe9702cbd5','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f7f700c-61fc-44d6-97d8-2abe9702cbd5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f7f700c-61fc-44d6-97d8-2abe9702cbd5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd81a9cd6-9a63-47a1-a164-63ab4795ddd1','Surface impedance','Surface (acoustic) impedance is the complex ratio of the sound pressure at a boundary to the resulting normal component of particle velocity into that boundary. It characterizes how a surface reflects and absorbs sound, and is directly linked to the surface''s absorption coefficient and reflection factor.','When sound hits a wall, the surface pushes back in its own way. Surface impedance compares the pressure at the wall to the air motion into it. This number tells how much sound the surface reflects or soaks up.','It describes the acoustic boundary condition of a material, enabling prediction of absorption, reflection, and room response.','Using an impedance tube per ISO 10534, a technician measures a panel''s surface impedance and converts it to an absorption coefficient for use in room-acoustic modeling.','Acoustic Quantity',ARRAY['Specific acoustic impedance','Transfer impedance','Stiffness-controlled region']::text[],ARRAY['Ignoring the phase; surface impedance is complex, not a single real number.','Using the tangential instead of the normal velocity component.','Confusing surface impedance with the absorption coefficient it helps compute.']::text[],ARRAY['Measuring absorber performance in an impedance tube.','Setting boundary conditions in a room-acoustics simulation.','Specifying acoustic treatment for a studio wall.']::text[],'advanced','Z_s = p / u_n','Surface impedance is the sound pressure at the boundary divided by the normal particle velocity into the boundary.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Surface impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd81a9cd6-9a63-47a1-a164-63ab4795ddd1','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d81a9cd6-9a63-47a1-a164-63ab4795ddd1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d81a9cd6-9a63-47a1-a164-63ab4795ddd1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6beff891-34f6-4b15-a8b4-7d6e88cf6c26','Thermal attenuation','Thermal attenuation is the loss of acoustic energy caused by heat conduction between the warmer compressions and cooler rarefactions of a sound wave, which irreversibly converts wave energy to heat. It is one of the two classical absorption mechanisms, the other being viscous loss, and together they make classical absorption rise with the square of frequency.','A sound wave heats the air where it squeezes and cools it where it stretches. Heat then leaks from warm to cool spots. That leaked heat is lost from the wave. This steady loss is called thermal attenuation.','It accounts for part of the frequency-dependent absorption of sound in fluids, important at high frequencies and over long paths.','An ultrasonic engineer includes thermal attenuation, alongside viscous loss, when predicting how quickly a megahertz beam weakens over centimetres in water.','Attenuation Mechanism',ARRAY['Thermoviscous loss','Spherical spreading loss','Sound energy']::text[],ARRAY['Assuming all absorption is viscous; heat conduction also contributes.','Neglecting its strong rise with frequency, roughly as frequency squared.','Confusing this molecular loss with geometric spreading loss.']::text[],ARRAY['Modeling high-frequency ultrasound absorption.','Estimating long-range atmospheric high-frequency loss.','Explaining why treble fades faster over distance.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6beff891-34f6-4b15-a8b4-7d6e88cf6c26','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6beff891-34f6-4b15-a8b4-7d6e88cf6c26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6beff891-34f6-4b15-a8b4-7d6e88cf6c26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cb866dfd-bd0a-4a70-b3e9-9e8d82d4cbaf','Thermoviscous loss','Thermoviscous loss is the combined classical absorption of sound arising from the fluid''s shear viscosity and its thermal conductivity, described by the Stokes-Kirchhoff theory. The resulting classical absorption coefficient increases with the square of frequency and sets a lower bound on attenuation before molecular relaxation is added.','As sound moves through a fluid, two effects steal energy. One is the fluid''s internal friction. The other is heat leaking between hot and cold parts of the wave. Together these are thermoviscous loss. They grow quickly as pitch rises.','It gives the baseline physical absorption of sound in a fluid from viscosity and heat conduction, foundational for attenuation modeling.','When modeling a 5 MHz medical ultrasound beam, an engineer starts from the thermoviscous (classical) absorption, which scales as frequency squared, before adding tissue-specific relaxation losses.','Attenuation Mechanism',ARRAY['Thermal attenuation','Self-demodulation','Sound energy']::text[],ARRAY['Assuming classical loss explains all real absorption; molecular relaxation often dominates in air.','Forgetting the strong frequency-squared dependence.','Treating viscous and thermal contributions as unrelated rather than combined.']::text[],ARRAY['Predicting ultrasound attenuation in water or tissue.','Setting the absorption floor in a propagation model.','Explaining frequency-dependent high-frequency loss.']::text[],'advanced','α_class ∝ f²','The classical thermoviscous absorption coefficient is proportional to the square of frequency.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermoviscous loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cb866dfd-bd0a-4a70-b3e9-9e8d82d4cbaf','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cb866dfd-bd0a-4a70-b3e9-9e8d82d4cbaf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cb866dfd-bd0a-4a70-b3e9-9e8d82d4cbaf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8596a185-5cdc-4f65-be43-101099c57a41','Total internal reflection','Total internal reflection occurs when a sound wave in a slower medium strikes a boundary with a faster medium at an angle beyond the critical angle, so all the energy is reflected and none is transmitted as a propagating wave. The critical angle is set by Snell''s law from the ratio of the two sound speeds.','When sound goes from a slow medium toward a faster one, it bends away from the boundary. Past a certain angle it cannot cross at all. Instead it fully bounces back. This is total internal reflection.','It explains how sound can be fully trapped at an interface, underpinning waveguides, ducts, and ocean sound channels.','For sound going from water (1500 m/s) toward a faster seabed (1800 m/s), the critical angle is arcsin(1500/1800) ≈ 56°; beyond it the bottom reflects sound almost perfectly.','Propagation Effect',ARRAY['Sound-speed gradient','Shadow zones','Specific acoustic impedance']::text[],ARRAY['Applying it when the second medium is slower; total internal reflection needs a faster medium beyond.','Measuring the angle from the surface instead of from the normal.','Assuming any large angle reflects fully; it must exceed the critical angle.']::text[],ARRAY['Explaining strong seabed reflection in shallow-water sonar.','Understanding sound trapping in an ocean sound channel.','Analyzing reflection at a fast solid interface.']::text[],'intermediate','sin θ_c = c₁ / c₂  (c₂ > c₁)','The critical angle''s sine equals the ratio of the slower medium''s sound speed to the faster medium''s sound speed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Total internal reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8596a185-5cdc-4f65-be43-101099c57a41','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8596a185-5cdc-4f65-be43-101099c57a41') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8596a185-5cdc-4f65-be43-101099c57a41');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20078416-e3a8-45ff-a0b0-e6bcc28df45d','Transfer impedance','Acoustic transfer impedance is the complex ratio of the sound pressure produced at one point in a system to the volume velocity applied at a different point, expressed in acoustic ohms. Being a cross-quantity between two locations, it characterizes how a source at one port drives a response at another and appears in the two-port description of acoustic networks.','Push sound in at one place and it creates pressure somewhere else. Transfer impedance links those two spots. It divides the pressure at the second place by the flow pushed in at the first. It shows how one point drives another.','It relates a driving source at one location to the acoustic response at another, key to modeling ducts, mufflers, and coupled acoustic systems.','An exhaust-system engineer measures a muffler''s transfer impedance between inlet and outlet ports to predict how source pulsations translate into tailpipe sound pressure.','Acoustic Quantity',ARRAY['Specific acoustic impedance','Surface impedance','Sound pressure']::text[],ARRAY['Confusing acoustic transfer impedance with a shielded-cable''s electromagnetic transfer impedance.','Using velocity where volume velocity is required, giving wrong units.','Treating it as a single-point (driving-point) impedance rather than a cross-point ratio.']::text[],ARRAY['Modeling a muffler or duct as a two-port network.','Characterizing coupling between chambers in an acoustic system.','Predicting response of a coupled loudspeaker enclosure.']::text[],'advanced','Z_T = p₂ / U₁','Transfer impedance is the sound pressure at a second point divided by the volume velocity applied at a first point.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20078416-e3a8-45ff-a0b0-e6bcc28df45d','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20078416-e3a8-45ff-a0b0-e6bcc28df45d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20078416-e3a8-45ff-a0b0-e6bcc28df45d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff6ed721-a838-493d-94c9-37f744f1022e','Transformation acoustics','Transformation acoustics is a design method that applies coordinate transformations to the acoustic wave equation to prescribe the material properties needed to steer sound along desired paths. It is the acoustic analogue of transformation optics and underlies designs such as acoustic cloaks, lenses, and beam benders realized with metamaterials.','Transformation acoustics is a math recipe for guiding sound. You imagine bending the space that sound travels through. The recipe then tells you what strange materials would bend real sound the same way. Engineers use it to design sound cloaks and lenses.','It provides a systematic way to design acoustic metamaterials that route, hide, or focus sound by mapping desired wave paths to material requirements.','A metamaterial designer uses transformation acoustics to specify the anisotropic density profile of a shell that guides sound around an object, making it acoustically ''cloaked''.','Design Method',ARRAY['Scalar potential','Sound field','Surface impedance']::text[],ARRAY['Assuming the required materials are ordinary; they are usually anisotropic metamaterials.','Confusing the design mathematics with a physical wave phenomenon.','Expecting perfect broadband cloaking; real designs are band-limited and lossy.']::text[],ARRAY['Designing an acoustic cloak.','Engineering a flat acoustic lens.','Researching sound-steering metamaterials.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transformation acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff6ed721-a838-493d-94c9-37f744f1022e','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff6ed721-a838-493d-94c9-37f744f1022e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff6ed721-a838-493d-94c9-37f744f1022e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b16491c-3c1e-4d50-ad59-c5c656f02629','Transition region','In the response of a driven mechanical or acoustic system, the transition region is the frequency band around the fundamental resonance where behavior shifts from stiffness (compliance) control below resonance to mass control above it. Near resonance the reactive stiffness and mass terms cancel, so damping (resistance) governs the response and the amplitude peaks.','Below resonance, a device is ruled by its springiness. Above resonance, its weight takes over. In between lies the transition region, right around resonance. Here springiness and weight nearly cancel. Damping then controls how big the peak gets.','It marks the crossover in a transducer''s behavior between stiffness- and mass-controlled regimes, where resonance and damping shape the response.','A loudspeaker designer adds mechanical damping in the transition region around the driver''s resonance to tame the response peak before the mass-controlled range above it.','Transducer Behavior',ARRAY['Stiffness-controlled region','Specific acoustic impedance','Surface impedance']::text[],ARRAY['Assuming the peak height is fixed; damping in this region sets the amplitude.','Confusing the transition region with the far-below-resonance stiffness region.','Ignoring that stiffness and mass reactances cancel only near resonance.']::text[],ARRAY['Damping a loudspeaker''s fundamental resonance.','Analyzing a microphone capsule near its resonance.','Explaining the crossover between compliance and mass control.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transition region');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b16491c-3c1e-4d50-ad59-c5c656f02629','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b16491c-3c1e-4d50-ad59-c5c656f02629') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b16491c-3c1e-4d50-ad59-c5c656f02629');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '75dd9ada-6b2f-486c-abcd-a2e61129501d','Ts','Centre time (Ts) is an ISO 3382-1 objective room-acoustic parameter equal to the time of the centre of gravity of the squared impulse response. It gives a single value, in seconds, that grows with more reverberant conditions and shrinks when early energy dominates, without needing an arbitrary early/late boundary.','Centre time is the balance point in time of a room''s sound energy. A short value means most sound arrives early and clearly. A long value means the energy spreads out over time. It uses one number, so you avoid picking a cutoff.','It summarises the balance between clarity and reverberance in one continuous number, avoiding the fixed 50 or 80 ms split that clarity ratios require.','From a measured impulse response an engineer computes Ts; a speech-friendly room might give about 70 ms, while a reverberant concert hall can exceed 150 ms.','Room Acoustic Parameter',ARRAY['Clarity metrics','Reverberation time','Early reflections','Energy decay curve','Impulse response']::text[],ARRAY['Assuming Ts needs a fixed early/late boundary the way C50 or C80 do.','Reporting Ts in milliseconds while labelling it seconds, or the reverse.','Thinking a higher centre time is always worse, ignoring the room''s purpose.']::text[],ARRAY['Rating speech intelligibility in a lecture hall from measured impulse responses.','Comparing acoustics before and after treatment in a multipurpose auditorium.','Cross-checking clarity ratios during an ISO 3382-1 acoustic survey.']::text[],'advanced','Ts = ( INT_0^inf t * p^2(t) dt ) / ( INT_0^inf p^2(t) dt )','Centre time is the energy-weighted average arrival time: integrate time multiplied by squared sound pressure, then divide by the integral of squared sound pressure.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ts');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '75dd9ada-6b2f-486c-abcd-a2e61129501d','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='75dd9ada-6b2f-486c-abcd-a2e61129501d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='75dd9ada-6b2f-486c-abcd-a2e61129501d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41e53c50-0556-409e-8a2d-4e765f436d06','Turbulence ingestion noise','Turbulence ingestion noise is aerodynamic sound produced when a rotor, fan, or propeller draws in turbulent inflow and its blades successively encounter, or ''chop'', the incoming eddies. The resulting unsteady blade loading radiates mainly broadband noise, with quasi-tonal peaks (''haystacks'') clustered around the blade-passing frequency and its harmonics.','A fan or propeller pulls in swirling, gusty air. Its blades slice through those gusts one after another. This makes the blade forces flicker, which radiates sound. The sound is mostly broadband, with humps near the blade-passing rate.','The concept explains a major source of fan, propeller, and drone noise, and guides quieter inlet and blade designs.','An engineer recording a cooling fan or drone hears rising broadband noise with ''haystack'' bumps; smoothing the inflow or adding an inlet screen reduces it.','Aeroacoustic Source',ARRAY['Aeroacoustics','Broadband noise','Blade-passing frequency','Unsteady blade loading','Turbulent flow']::text[],ARRAY['Confusing it with tonal blade-passing noise from steady, undisturbed inflow.','Assuming it is purely tonal, when it is mainly broadband with haystack peaks.','Ignoring that upstream turbulence, not blade shape alone, drives this noise.']::text[],ARRAY['Diagnosing extra noise from a ducted cooling fan drawing turbulent air.','Analysing drone or UAV propeller noise during hover.','Assessing HVAC fan noise where inlet turbulence is present.']::text[],'advanced',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Turbulence ingestion noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41e53c50-0556-409e-8a2d-4e765f436d06','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41e53c50-0556-409e-8a2d-4e765f436d06') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41e53c50-0556-409e-8a2d-4e765f436d06');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1694d03d-8c2c-4dee-a17e-49aa060fb5aa','Ultrasonics','Ultrasonics is the study and use of acoustic waves at frequencies above about 20 kHz, the nominal upper limit of human hearing. These waves obey the same physics as audible sound but, because of their short wavelengths, are highly directional and are absorbed rapidly in air.','Ultrasound is sound pitched too high for people to hear. It begins above about 20 kilohertz. It follows the same rules as ordinary sound. Its short waves travel in tight beams and fade quickly in air.','It underlies applications such as medical imaging, cleaning, distance sensing, and non-destructive testing, where short wavelengths give fine spatial detail.','A technician using a 40 kHz ultrasonic leak detector hears nothing directly; the device shifts the inaudible signal down into the audible range.','Frequency Range',ARRAY['Frequency','Wavelength','Underwater acoustics','Viscous attenuation','Wave acoustics']::text[],ARRAY['Assuming ultrasound is a different kind of wave rather than just higher-frequency sound.','Thinking ultrasound carries far in air; high-frequency air absorption is severe.','Confusing ultrasonic frequency with loudness or intensity.']::text[],ARRAY['Using an ultrasonic detector to locate compressed-air or gas leaks.','Understanding why some pest deterrents use inaudible tones.','Explaining ultrasonic cleaning of studio connectors and small parts.']::text[],'beginner',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1694d03d-8c2c-4dee-a17e-49aa060fb5aa','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1694d03d-8c2c-4dee-a17e-49aa060fb5aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1694d03d-8c2c-4dee-a17e-49aa060fb5aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9f330d9a-1197-4db8-8ffa-de85097177ca','Underwater acoustics','Underwater acoustics (hydroacoustics) is the study of the generation, propagation, and reception of sound in water and other liquids. Because water is far denser and less compressible than air, sound travels at roughly 1500 m/s in seawater, and sound levels are referenced to 1 micropascal rather than the 20 micropascals used in air.','Underwater acoustics is the science of sound in water. Sound moves through water much faster than through air. It also carries over very long distances. Its level is measured against a different reference pressure than in air.','It provides the basis for sonar, marine communication, navigation, and the monitoring of ocean life and noise.','An engineer logging ship noise reports levels in dB re 1 micropascal; the same physical pressure yields a much larger decibel number than it would in air.','Acoustics Field',ARRAY['Wave impedance','Speed of sound','Ultrasonics','Wave acoustics','Sound intensity level']::text[],ARRAY['Using the airborne reference of 20 micropascals when reporting underwater levels.','Assuming the sound speed in water equals the air value of about 343 m/s.','Directly comparing air and water decibel figures without noting the different references.']::text[],ARRAY['Measuring vessel or pile-driving noise for environmental permits.','Setting up a hydrophone to record marine mammal sounds.','Explaining why sonar ranges far exceed anything possible in air.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Underwater acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9f330d9a-1197-4db8-8ffa-de85097177ca','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9f330d9a-1197-4db8-8ffa-de85097177ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9f330d9a-1197-4db8-8ffa-de85097177ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eacf1611-2723-4c2a-92cb-d5752b1ad37f','Viscous attenuation','Viscous attenuation is the loss of acoustic energy as sound travels through a fluid, caused by the fluid''s shear viscosity converting organised wave motion into heat. It is one part of ''classical'' absorption; the amplitude absorption coefficient it contributes rises with the square of frequency, so high frequencies are damped far more strongly than low ones.','As sound moves through air or water, friction inside the fluid steals energy. This friction comes from the fluid''s stickiness, called viscosity. The lost energy turns into heat. High notes fade much faster than low notes.','It explains part of why distant sound loses its highs and why high-frequency and ultrasonic waves have short usable ranges.','Because loss grows with frequency squared, a 10 kHz tone suffers roughly 100 times the viscous loss per metre of a 1 kHz tone, so highs disappear over distance.','Sound Propagation',ARRAY['Ultrasonics','Wave equation','Speed of sound','Atmospheric absorption','Underwater acoustics']::text[],ARRAY['Confusing viscous loss with the spreading loss of the inverse-square law.','Forgetting that absorption grows with frequency squared, not linearly.','Ignoring thermal conduction, which adds to classical absorption alongside viscosity.']::text[],ARRAY['Explaining why distant thunder sounds dull and low.','Predicting the short range of ultrasonic sensors in air.','Modelling high-frequency loss in long-throw outdoor sound systems.']::text[],'advanced','alpha = (2 * eta * omega^2) / (3 * rho * c^3)','The viscous amplitude absorption coefficient equals two times the shear viscosity times the angular frequency squared, divided by three times the fluid density times the speed of sound cubed.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Viscous attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eacf1611-2723-4c2a-92cb-d5752b1ad37f','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eacf1611-2723-4c2a-92cb-d5752b1ad37f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eacf1611-2723-4c2a-92cb-d5752b1ad37f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ad840cff-d968-4cd9-aeaa-e779bcbe0fc6','Wave acoustics','Wave acoustics is the branch of acoustics that treats sound explicitly as waves governed by the wave equation, so that phase, interference, diffraction, and resonance are fully represented. It contrasts with geometric (ray) acoustics, which ignores wavelength and is only accurate when wavelengths are small compared with objects and room dimensions.','Wave acoustics studies sound as true waves. It tracks how waves add, cancel, bend, and resonate. This matters most at low frequencies with long waves. Ray-based methods, by contrast, ignore these wave effects.','It provides the accurate physical model needed to predict low-frequency behaviour, room modes, and diffraction that ray methods miss.','To predict bass modes in a small control room, an engineer relies on wave-based modelling rather than ray tracing, which fails when wavelengths rival room size.','Modelling Approach',ARRAY['Wave equation','Why wavelength affects room behavior','Standing wave','Diffraction','Wave impedance']::text[],ARRAY['Applying ray tracing at low frequencies, where wave effects dominate.','Assuming wave and geometric acoustics always give the same answer.','Forgetting that wave methods become costly at high frequencies with tiny wavelengths.']::text[],ARRAY['Modelling low-frequency modes in a small studio or vocal booth.','Predicting diffraction of sound around a barrier or console.','Choosing between wave and ray simulation for a room design.']::text[],'intermediate',NULL,NULL,'cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave acoustics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ad840cff-d968-4cd9-aeaa-e779bcbe0fc6','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ad840cff-d968-4cd9-aeaa-e779bcbe0fc6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ad840cff-d968-4cd9-aeaa-e779bcbe0fc6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83ebb4a9-33e2-44a6-943d-2cf124b11e45','Wave equation','The acoustic wave equation is the partial differential equation that governs how small sound-pressure disturbances propagate through a fluid. In its linear, lossless form it states that the Laplacian of the pressure equals the second time-derivative of the pressure divided by the square of the sound speed.','The wave equation is the master rule for how sound spreads. It links how pressure varies in space to how it changes in time. The speed of sound sets that connection. Almost all sound behaviour follows from it.','It is the foundation from which sound speed, wavelength, impedance, room modes, and radiation are all derived.','Acoustic modelling software solves the wave equation numerically to predict how a room or loudspeaker will behave before anything is built.','Governing Equation',ARRAY['Wave acoustics','Wave impedance','Speed of sound','Standing wave','Why wavelength affects room behavior']::text[],ARRAY['Forgetting that the linear form assumes small amplitudes and no losses.','Mixing up the roles of the spatial and time derivatives.','Thinking it applies only to air, when it holds in any fluid with the right sound speed.']::text[],ARRAY['Understanding how simulation tools predict room acoustics.','Deriving why wavelength equals speed divided by frequency.','Explaining loudspeaker radiation from first principles.']::text[],'advanced','laplacian(p) = (1 / c^2) * d^2p/dt^2','The spatial Laplacian of the sound pressure equals one over the sound speed squared, times the second time-derivative of the sound pressure.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave equation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83ebb4a9-33e2-44a6-943d-2cf124b11e45','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83ebb4a9-33e2-44a6-943d-2cf124b11e45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83ebb4a9-33e2-44a6-943d-2cf124b11e45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9a9697f-2e3e-4397-8bb9-238943b7f852','Wave impedance','Wave impedance (specific acoustic impedance) is the ratio of acoustic pressure to particle velocity at a point in a sound field. For a plane progressive wave in a lossless fluid it is real and equals the characteristic impedance, the product of density and sound speed, about 413 Pa*s/m (rayls) for air at 20 degrees Celsius.','Wave impedance compares sound pressure to how fast the air particles move. For a simple travelling wave it depends only on the medium. For air it is about 413 rayls. It controls how sound reflects at a boundary.','It determines how much sound reflects or passes through when a wave meets a boundary between media of different impedance.','For air, density times sound speed gives 1.204 kg/m^3 * 343 m/s = about 413 Pa*s/m; water is roughly 3600 times higher, so most airborne sound reflects off water.','Acoustic Property',ARRAY['Wave equation','Wave acoustics','Speed of sound','Sound intensity level','Underwater acoustics']::text[],ARRAY['Confusing specific acoustic impedance with acoustic impedance, which also includes area.','Assuming the impedance is complex for a plane progressive wave, when it is real.','Forgetting that impedance shifts with temperature through density and sound speed.']::text[],ARRAY['Explaining why airborne sound barely couples into water.','Understanding reflection at a wall or air-to-material boundary.','Matching a horn to air for efficient loudspeaker radiation.']::text[],'advanced','z = p / u = rho_0 * c   (plane progressive wave)','Wave impedance is sound pressure divided by particle velocity; for a plane progressive wave it equals the fluid density times the speed of sound.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave impedance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9a9697f-2e3e-4397-8bb9-238943b7f852','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9a9697f-2e3e-4397-8bb9-238943b7f852') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9a9697f-2e3e-4397-8bb9-238943b7f852');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67c67bf6-b169-4a27-86d1-e23721a1bbaa','Why low frequencies have long wavelengths','This principle follows from the relation wavelength = sound speed / frequency: because the speed of sound is essentially fixed in a given medium, wavelength is inversely proportional to frequency. Low-frequency (bass) tones therefore span metres, while high-frequency tones span only centimetres.','Wavelength equals sound speed divided by frequency. Sound speed barely changes within one room. So lower notes must have longer waves. A 20 hertz bass tone stretches about 17 metres. A 10 kilohertz tone is only a few centimetres.','It explains why bass is hard to localise and hard to absorb, which shapes how rooms and loudspeakers handle low frequencies.','At 20 degrees Celsius (c = 343 m/s), a 40 Hz kick fundamental has a wavelength of 343/40 = about 8.6 m, far larger than most rooms, so it excites room modes.','Wave Principle',ARRAY['Wave equation','Why wavelength affects room behavior','Speed of sound','Wavelength','Standing wave']::text[],ARRAY['Thinking louder bass has a longer wavelength; loudness does not change wavelength.','Assuming wavelength depends on the source rather than on the medium and frequency.','Forgetting that sound speed, and therefore wavelength, shifts with temperature.']::text[],ARRAY['Explaining why subwoofer placement is so room-dependent.','Understanding why bass traps must be physically deep.','Predicting which frequencies will excite a room''s length mode.']::text[],'beginner','lambda = c / f','Wavelength equals the speed of sound divided by the frequency.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Why low frequencies have long wavelengths');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67c67bf6-b169-4a27-86d1-e23721a1bbaa','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67c67bf6-b169-4a27-86d1-e23721a1bbaa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67c67bf6-b169-4a27-86d1-e23721a1bbaa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e5cbf5b-0be6-453c-b012-8a1c04909ef7','Why wavelength affects room behavior','How sound behaves in a room depends on how its wavelength compares with the room''s dimensions and surface features. When wavelengths are comparable to or larger than room dimensions, discrete standing-wave modes and strong diffraction dominate; when wavelengths are much smaller, sound behaves more like rays that reflect and can be treated statistically.','A room reacts to sound based on how the wavelength compares to its size. Long bass waves fit the room like organ pipes and create modes. Short high waves act more like light rays. So bass and treble misbehave in very different ways.','It explains why low and high frequencies need different acoustic treatment and why small rooms struggle most with bass.','In a 3 m long room the first axial mode is 343/(2*3) = about 57 Hz, forming a strong standing wave, while a 3 kHz tone (wavelength 0.11 m) simply reflects.','Wave Principle',ARRAY['Why low frequencies have long wavelengths','Wave acoustics','Standing wave','Room modes','Wave equation']::text[],ARRAY['Treating every frequency with the same absorber thickness.','Assuming ray-and-reflection thinking works for bass, where modes dominate instead.','Thinking a bigger room removes modes rather than lowering their frequencies.']::text[],ARRAY['Deciding treatment for a small mixing room''s bass problems.','Explaining why thin foam absorbs highs but not lows.','Predicting standing-wave frequencies from room dimensions.']::text[],'intermediate','f = n * c / (2 * L)','The axial room-mode frequencies equal an integer times the speed of sound, divided by twice the room dimension along that axis.','cf8ef23a-a16a-4291-82ce-756e9ae1bd36' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Why wavelength affects room behavior');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e5cbf5b-0be6-453c-b012-8a1c04909ef7','cf8ef23a-a16a-4291-82ce-756e9ae1bd36',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e5cbf5b-0be6-453c-b012-8a1c04909ef7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e5cbf5b-0be6-453c-b012-8a1c04909ef7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ddc0f5fb-547d-44fa-a8b2-8e90642a52f9','Acoustic contrast control','Acoustic contrast control (ACC) is a sound-zone method that computes loudspeaker-array filters to maximize the ratio of acoustic energy in a wanted (bright) zone to that in an unwanted (dark) zone. The optimal weights are the eigenvector of a spatial correlation problem that yields the greatest energy contrast between the two regions.','This method makes one seat loud while a nearby seat stays quiet. It uses many speakers driven by special filters. The filters push most energy into the wanted spot. They leave very little sound in the quiet spot.','It creates personal listening zones so different people can hear different content, or silence, from the same set of loudspeakers.','If the bright zone holds 1.0 Pa^2 mean-square pressure and the dark zone holds 0.01 Pa^2, the contrast is 100, or 20 dB.','Spatial audio',ARRAY['Beamformed sonar','Binaural synthesis','Ambisonics','Array gain']::text[],ARRAY['Assuming high energy contrast also means good sound quality in the bright zone; timbre can still be poor.','Believing the dark zone is truly silent rather than just strongly attenuated.','Forgetting that contrast falls apart when the room or listener geometry changes.']::text[],ARRAY['Designing a car cabin where driver and passenger hear different audio.','Building a museum exhibit that keeps sound local to one display.','Comparing acoustic contrast control against pressure-matching for a sound-zone system.']::text[],'advanced','AC = ( (1/N_b) * sum|p_b|^2 ) / ( (1/N_d) * sum|p_d|^2 )','Acoustic contrast equals the mean squared sound pressure over the bright-zone points divided by the mean squared sound pressure over the dark-zone points.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic contrast control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ddc0f5fb-547d-44fa-a8b2-8e90642a52f9','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ddc0f5fb-547d-44fa-a8b2-8e90642a52f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ddc0f5fb-547d-44fa-a8b2-8e90642a52f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd20e29c3-c914-4fea-bf54-2d99f8cc572d','Acoustic matching layer','An acoustic matching layer is a thin layer bonded to the radiating face of a transducer whose acoustic impedance is intermediate between the piezoelectric element and the load medium. A single quarter-wavelength layer of impedance equal to the geometric mean of the two media minimizes reflection and improves energy transfer and bandwidth.','This is a thin coating on the front of an ultrasound probe. The crystal and the body have very different densities. The layer sits between them to ease the mismatch. It lets more sound cross the boundary instead of bouncing back.','It reduces the large impedance mismatch between a stiff piezoelectric element and a softer load such as water or tissue, raising sensitivity and bandwidth.','For a piezo element of 30 MRayl and water of 1.5 MRayl, an ideal single layer has impedance sqrt(30 x 1.5) = 6.7 MRayl and is one quarter-wavelength thick.','Ultrasonic transducer',ARRAY['Backing layer','CMUT','Axial resolution']::text[],ARRAY['Thinking the layer should match the element''s impedance rather than the geometric mean of element and load.','Using a half-wavelength instead of a quarter-wavelength thickness.','Ignoring that the ideal impedance and thickness are frequency dependent.']::text[],ARRAY['Selecting a probe for imaging through water versus tissue.','Designing a broadband high-frequency ultrasonic transducer.','Diagnosing weak signal output traced to a delaminated front layer.']::text[],'intermediate','Z_m = sqrt(Z_1 * Z_2),  t = lambda_m / 4','The matching-layer impedance equals the square root of the product of the element and load impedances, and its thickness is one quarter of the wavelength in the layer.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic matching layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd20e29c3-c914-4fea-bf54-2d99f8cc572d','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d20e29c3-c914-4fea-bf54-2d99f8cc572d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d20e29c3-c914-4fea-bf54-2d99f8cc572d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66705bca-c478-4618-97b7-ef62eb023668','Acoustic radiation-force impulse','Acoustic radiation-force impulse (ARFI) is an ultrasound technique that uses a short, focused high-intensity push pulse to displace tissue by acoustic radiation force, then tracks the resulting micron-scale displacement or shear-wave speed to infer tissue stiffness. It underlies point shear-wave elastography and ARFI imaging.','A strong, brief ultrasound push nudges tissue a tiny amount. Softer tissue moves more than stiff tissue. The probe watches how far and how fast it moves. This reveals how stiff the tissue is.','It measures tissue stiffness without a needle, helping detect conditions such as liver fibrosis or suspicious lesions.','The body force per unit volume from the push beam is F = 2*alpha*I/c; with alpha = 5 Np/m, I = 1000 W/m^2 and c = 1540 m/s, F is about 6.5 N/m^3.','Ultrasound imaging',ARRAY['Continuous-wave Doppler','Axial resolution','Acoustic matching layer','Cavitation noise']::text[],ARRAY['Confusing tissue displacement with the much larger displacement of the probe itself.','Assuming stiffness maps to a single disease when many factors change tissue elasticity.','UNSAFE: Ignoring thermal and mechanical index limits; push pulses raise time-averaged intensity and can heat tissue if output safety limits are exceeded.']::text[],ARRAY['Estimating liver stiffness to stage fibrosis.','Characterizing a breast lesion as soft or hard.','Comparing point shear-wave elastography against strain elastography.']::text[],'advanced','F = 2*alpha*I/c','The radiation body force per unit volume equals twice the absorption coefficient times the acoustic intensity, divided by the sound speed.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic radiation-force impulse');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66705bca-c478-4618-97b7-ef62eb023668','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66705bca-c478-4618-97b7-ef62eb023668') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66705bca-c478-4618-97b7-ef62eb023668');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf9b301a-cb4c-4c10-b8d9-46ee341b56a4','Acoustic-emission sensor','An acoustic-emission (AE) sensor is a piezoelectric transducer that detects the transient elastic stress waves released when a material undergoes crack growth, plastic deformation, or similar sudden energy release. Because it listens passively for high-frequency bursts (typically tens of kHz to about 1 MHz), it is used for structural monitoring rather than active pulsing.','This sensor listens for tiny cracking sounds inside a material. When metal or concrete starts to fail, it snaps and sends out waves. The sensor picks up these bursts. Engineers use them to catch damage early.','It enables passive, continuous monitoring of structures so growing defects can be caught before they become failures.','A technician mounts AE sensors on a pressure vessel and watches for a rising burst rate during a proof-load test to locate active flaws.','NDT sensor',ARRAY['Cavitation noise','Backing layer','Acoustic matching layer','CMUT']::text[],ARRAY['Treating acoustic emission as an active pulse-echo test rather than passive listening.','Ignoring background noise sources such as friction or fluid flow that mimic real emissions.','Assuming one sensor can locate a source without an array for triangulation.']::text[],ARRAY['Monitoring a pressure vessel during a hydrostatic proof test.','Watching a bridge or storage tank for fatigue-crack activity.','Detecting leak-related turbulence in a pipeline.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic-emission sensor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf9b301a-cb4c-4c10-b8d9-46ee341b56a4','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf9b301a-cb4c-4c10-b8d9-46ee341b56a4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf9b301a-cb4c-4c10-b8d9-46ee341b56a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9f44fd1e-7bdc-47c0-9e68-597cf75348ef','Active sonar','Active sonar detects and locates underwater targets by transmitting an acoustic pulse and processing the echo returned from the target. Its performance is governed by the active sonar equation, which balances source level, two-way transmission loss, target strength, noise, array gain, and a detection threshold.','Active sonar sends out a sound ping. The ping bounces off objects and comes back. The system times and measures the echo. This tells the range and bearing of the target.','It provides range and bearing to targets that make little noise of their own, at the cost of revealing the transmitter''s presence.','With SL = 220, two-way TL = 140, TS = 15, NL = 60, AG = 20 and DT = 10 (all dB), signal excess = 220 - 140 + 15 - (60 - 20) - 10 = 45 dB, so detection is likely.','Sonar',ARRAY['Beamformed sonar','Array gain','Ambient-noise level','Bottom bounce','Convergence zone']::text[],ARRAY['Counting transmission loss only once instead of twice for the outbound and return paths.','Confusing target strength (an echo property) with source level (a transmit property).','Assuming a stronger ping always helps, ignoring reverberation that also grows with source level.']::text[],ARRAY['Estimating detection range against a small, quiet target.','Choosing active versus passive sonar when stealth matters.','Analyzing why reverberation, not noise, limits detection in shallow water.']::text[],'intermediate','SE = SL - 2*TL + TS - (NL - AG) - DT','Signal excess equals source level minus two-way transmission loss plus target strength, minus the noise level reduced by array gain, minus the detection threshold.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Active sonar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9f44fd1e-7bdc-47c0-9e68-597cf75348ef','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9f44fd1e-7bdc-47c0-9e68-597cf75348ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9f44fd1e-7bdc-47c0-9e68-597cf75348ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb2c4194-cbf3-4657-a511-c62fe4fc257e','Ambient-noise level','Ambient-noise level is the background acoustic pressure level in the sea, excluding the sonar''s own signal and self-noise, expressed as a level in dB relative to 1 microPascal (dB re 1 uPa), often as a spectrum level in dB re 1 uPa^2/Hz. Its spectrum, summarized by the Wenz curves, is shaped by turbulence, shipping, wind and waves, and biological sources.','This is the constant background sound in the ocean. It comes from waves, wind, distant ships and sea life. Sonar has to hear a target over this noise. Its loudness is given against a very small pressure reference.','It sets the noise term in the sonar equation and thus the floor a signal must exceed to be detected.','A sound pressure of 10 uPa gives a level of 20*log10(10/1) = 20 dB re 1 uPa; the Wenz curves show typical deep-sea spectrum levels near 30 to 70 dB re 1 uPa^2/Hz across the band.','Underwater noise',ARRAY['Active sonar','Beamformed sonar','Array gain','Cavitation noise']::text[],ARRAY['Quoting an underwater level in dB without stating the 1 microPascal reference used in water.','Comparing underwater dB directly to airborne dB (re 20 uPa), which differ by about 62 dB in reference plus impedance effects.','Confusing broadband level with spectrum level (per hertz) when reading the Wenz curves.']::text[],ARRAY['Predicting sonar detection range in heavy versus light shipping traffic.','Assessing wind-driven noise before a passive listening survey.','Reporting a measured spectrum against the Wenz curves.']::text[],'intermediate',NULL,NULL,'f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambient-noise level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb2c4194-cbf3-4657-a511-c62fe4fc257e','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb2c4194-cbf3-4657-a511-c62fe4fc257e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb2c4194-cbf3-4657-a511-c62fe4fc257e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7676430-10a3-4ff9-bb6e-83802a32b0c0','Ambisonic normalization','Ambisonic normalization is the convention that scales the spherical-harmonic components of an Ambisonic signal set. Common schemes are SN3D (Schmidt semi-normalized) and N3D (fully or orthonormalized), which differ by a per-order factor; the AmbiX exchange format uses ACN channel ordering with SN3D normalization.','Ambisonics stores sound as a set of related channels. Each channel needs a size convention so decoders read it right. SN3D and N3D are two such conventions. They differ by a fixed scaling for each channel.','It makes encoders, effects, and decoders agree on channel gains so an Ambisonic scene plays back correctly.','To convert an SN3D component of order n to N3D, multiply by sqrt(2n+1); for a first-order (n=1) component this factor is sqrt(3) = 1.732.','Spatial audio',ARRAY['Ambisonics','Ambisonic order','Binaural synthesis','Acoustic contrast control']::text[],ARRAY['Mixing SN3D and N3D signals in one chain, which corrupts the reconstructed sound field.','Confusing normalization (channel gains) with channel ordering (ACN versus Furse-Malham).','Assuming legacy B-format (FuMa) can be dropped straight into an AmbiX (ACN/SN3D) tool.']::text[],ARRAY['Importing a field recording into a decoder that expects AmbiX.','Converting a legacy first-order B-format file to the AmbiX standard.','Debugging why an Ambisonic scene sounds unbalanced after mixing tools.']::text[],'advanced','Y_N3D(n,m) = sqrt(2n+1) * Y_SN3D(n,m)','A fully normalized (N3D) component of order n equals the square root of two n plus one, times the corresponding semi-normalized (SN3D) component.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambisonic normalization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7676430-10a3-4ff9-bb6e-83802a32b0c0','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7676430-10a3-4ff9-bb6e-83802a32b0c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7676430-10a3-4ff9-bb6e-83802a32b0c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ee4f696-8f1a-487f-b66f-83376f367164','Ambisonic order','Ambisonic order is the highest spherical-harmonic order N used to represent a sound field, setting the angular (spatial) resolution of the encoding. A full-sphere (3D) Ambisonic signal of order N requires (N+1)^2 channels, while a horizontal-only (2D) representation requires 2N+1.','Ambisonic order says how detailed the surround image is. A higher order paints direction more sharply. But it needs many more channels. First order is coarse; higher orders are crisp.','It trades spatial sharpness against channel count and processing cost when capturing or synthesizing a 3D sound field.','A third-order 3D scene needs (3+1)^2 = 16 channels; first order needs (1+1)^2 = 4 channels (W, X, Y, Z).','Spatial audio',ARRAY['Ambisonics','Ambisonic normalization','Binaural synthesis','Acoustic contrast control']::text[],ARRAY['Using the 2D channel count (2N+1) when a full-sphere (3D) system needs (N+1)^2.','Believing higher order helps everywhere, when the sweet spot still shrinks with frequency.','Confusing order with the number of loudspeakers, which are chosen separately.']::text[],ARRAY['Choosing microphone-array order for a VR field recording.','Sizing a decoder and channel budget for a dome of loudspeakers.','Explaining why a first-order recording localizes less sharply than a higher-order one.']::text[],'intermediate','K_3D = (N+1)^2 ,  K_2D = 2N+1','The number of channels for a full-sphere Ambisonic signal is N plus one, squared; for horizontal-only it is two N plus one.','f9526f78-48bb-4873-8c05-4910bd24cfbd' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambisonic order');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ee4f696-8f1a-487f-b66f-83376f367164','f9526f78-48bb-4873-8c05-4910bd24cfbd',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ee4f696-8f1a-487f-b66f-83376f367164') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ee4f696-8f1a-487f-b66f-83376f367164');
